INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(4, 'Audio Services', 'av-services-audio-services', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n\n    <!-- Primary Meta Tags -->\n    <title>Audio Services | Professional Sound Production & AV Audio Solutions | MiHi</title>\n    <meta name=\"title\" content=\"Audio Services | Professional Sound Production & AV Audio Solutions | MiHi\">\n    <meta name=\"description\"\n        content=\"Professional audio services: line arrays, distributed sound systems, wireless audio & sound engineering for corporate events, concerts, galas & weddings. Expert AV support nationwide.\">\n    <meta name=\"keywords\"\n        content=\"audio services, sound production, AV audio, line arrays, distributed sound, wireless audio, event sound systems, professional audio, sound engineering, AV production, corporate events audio, concert sound, event audio solutions, sound reinforcement, audio equipment rental\">\n    <meta name=\"author\" content=\"MiHi Entertainment\">\n    <meta name=\"robots\" content=\"index, follow\">\n    <meta name=\"language\" content=\"English\">\n    <meta name=\"revisit-after\" content=\"7 days\">\n    <meta name=\"theme-color\" content=\"#FF4F4F\">\n    <meta name=\"format-detection\" content=\"telephone=yes\">\n    <link rel=\"canonical\" href=\"https://www.mihientertainment.com/av-services/audio-services.html\">\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n\n    <!-- Additional SEO Meta Tags -->\n    <meta name=\"geo.region\" content=\"US\">\n    <meta name=\"geo.placename\" content=\"United States\">\n    <meta name=\"ICBM\" content=\"39.8283, -98.5795\">\n\n    <!-- Open Graph / Facebook -->\n    <meta property=\"og:type\" content=\"website\">\n    <meta property=\"og:url\" content=\"https://www.mihientertainment.com/av-services/audio-services.html\">\n    <meta property=\"og:title\"\n        content=\"Audio Services & Sound Production | Professional AV Audio Solutions | MiHi Entertainment\">\n    <meta property=\"og:description\"\n        content=\"Professional audio services and sound production for events. Line arrays, distributed sound systems, wireless audio solutions, and expert AV support.\">\n    <meta property=\"og:image\" content=\"https://www.mihientertainment.com/assets/images/audivis/hero.jpg\">\n    <meta property=\"og:image:width\" content=\"1200\">\n    <meta property=\"og:image:height\" content=\"630\">\n    <meta property=\"og:site_name\" content=\"MiHi Entertainment\">\n    <meta property=\"og:locale\" content=\"en_US\">\n\n    <!-- Twitter -->\n    <meta property=\"twitter:card\" content=\"summary_large_image\">\n    <meta property=\"twitter:url\" content=\"https://www.mihientertainment.com/av-services/audio-services.html\">\n    <meta property=\"twitter:title\"\n        content=\"Audio Services & Sound Production | Professional AV Audio Solutions | MiHi Entertainment\">\n    <meta property=\"twitter:description\"\n        content=\"Professional audio services and sound production for events. Line arrays, distributed sound systems, wireless audio solutions, and expert AV support.\">\n    <meta property=\"twitter:image\" content=\"https://www.mihientertainment.com/assets/images/audivis/hero.jpg\">\n\n    <!-- Structured Data - Service -->\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"Service\",\n      \"serviceType\": \"Audio Services & Sound Production\",\n      \"name\": \"Audio Services\",\n      \"description\": \"Professional audio services and sound production for events. Line arrays, distributed sound systems, wireless audio solutions, and expert AV support for conferences, galas, concerts, corporate events, and brand activations.\",\n      \"provider\": {\n        \"@type\": \"LocalBusiness\",\n        \"@id\": \"https://www.mihientertainment.com/#organization\",\n        \"name\": \"MiHi Entertainment\",\n        \"url\": \"https://www.mihientertainment.com\",\n        \"description\": \"Professional event audio services and sound production company specializing in line arrays, distributed sound systems, wireless audio, and sound engineering for events nationwide.\",\n        \"foundingDate\": \"2010\",\n        \"numberOfEmployees\": {\n          \"@type\": \"QuantitativeValue\",\n          \"value\": \"50-200\"\n        },\n        \"priceRange\": \"$$-$$$\"\n      },\n      \"serviceArea\": {\n        \"@type\": \"Country\",\n        \"name\": \"United States\"\n      },\n      \"areaServed\": {\n        \"@type\": \"Country\",\n        \"name\": \"United States\"\n      },\n      \"audience\": {\n        \"@type\": \"Audience\",\n        \"audienceType\": \"Event Planners, Corporate Event Organizers, Wedding Planners, Concert Producers, Brand Activation Managers\"\n      },\n      \"hasOfferCatalog\": {\n        \"@type\": \"OfferCatalog\",\n        \"name\": \"Audio Services\",\n        \"itemListElement\": [\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Line Array Sound Systems\",\n              \"description\": \"Professional line array speakers for large venues and events\"\n            }\n          },\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Distributed Sound Systems\",\n              \"description\": \"Evenly distributed audio coverage for events of all sizes\"\n            }\n          },\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Wireless Audio Solutions\",\n              \"description\": \"Wireless microphones and audio systems for events\"\n            }\n          },\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Audio Engineering Services\",\n              \"description\": \"Expert sound engineering and on-site audio support for conferences, galas, concerts, corporate events, and brand activations\"\n            }\n          }\n        ]\n      }\n    }\n    </script>\n\n    <!-- Structured Data - BreadcrumbList -->\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"BreadcrumbList\",\n      \"itemListElement\": [\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 1,\n          \"name\": \"Home\",\n          \"item\": \"https://www.mihientertainment.com\"\n        },\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 2,\n          \"name\": \"AV Services\",\n          \"item\": \"https://www.mihientertainment.com/av-production.html\"\n        },\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 3,\n          \"name\": \"Audio Services\",\n          \"item\": \"https://www.mihientertainment.com/av-services/audio-services.html\"\n        }\n      ]\n    }\n    </script>\n\n    <!-- Structured Data - Organization -->\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"Organization\",\n      \"name\": \"MiHi Entertainment\",\n      \"url\": \"https://www.mihientertainment.com\",\n      \"logo\": \"https://www.mihientertainment.com/assets/images/logo.png\",\n      \"description\": \"MiHi Entertainment provides professional audio services, sound production, line arrays, distributed sound systems, and wireless audio solutions for corporate events, concerts, galas, and weddings.\",\n      \"sameAs\": [\n        \"https://www.facebook.com/mihientertainment\",\n        \"https://www.instagram.com/mihientertainment\",\n        \"https://www.linkedin.com/company/mihientertainment\"\n      ],\n      \"contactPoint\": {\n        \"@type\": \"ContactPoint\",\n        \"telephone\": \"+1-XXX-XXX-XXXX\",\n        \"contactType\": \"Customer Service\",\n        \"email\": \"info@mihientertainment.com\",\n        \"availableLanguage\": \"English\"\n      },\n      \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"addressCountry\": \"US\"\n      },\n      \"areaServed\": {\n        \"@type\": \"Country\",\n        \"name\": \"United States\"\n      }\n    }\n    </script>\n\n    <!-- Structured Data - WebPage -->\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"WebPage\",\n      \"name\": \"Audio Services | Professional Sound Production & AV Audio Solutions\",\n      \"description\": \"Professional audio services: line arrays, distributed sound systems, wireless audio & sound engineering for corporate events, concerts, galas & weddings. Expert AV support nationwide.\",\n      \"url\": \"https://www.mihientertainment.com/av-services/audio-services.html\",\n      \"inLanguage\": \"en-US\",\n      \"isPartOf\": {\n        \"@type\": \"WebSite\",\n        \"name\": \"MiHi Entertainment\",\n        \"url\": \"https://www.mihientertainment.com\"\n      },\n      \"primaryImageOfPage\": {\n        \"@type\": \"ImageObject\",\n        \"url\": \"https://www.mihientertainment.com/assets/images/audivis/hero.jpg\",\n        \"width\": 1200,\n        \"height\": 630\n      },\n      \"breadcrumb\": {\n        \"@type\": \"BreadcrumbList\",\n        \"itemListElement\": [\n          {\n            \"@type\": \"ListItem\",\n            \"position\": 1,\n            \"name\": \"Home\",\n            \"item\": \"https://www.mihientertainment.com\"\n          },\n          {\n            \"@type\": \"ListItem\",\n            \"position\": 2,\n            \"name\": \"AV Services\",\n            \"item\": \"https://www.mihientertainment.com/av-production.html\"\n          },\n          {\n            \"@type\": \"ListItem\",\n            \"position\": 3,\n            \"name\": \"Audio Services\",\n            \"item\": \"https://www.mihientertainment.com/av-services/audio-services.html\"\n          }\n        ]\n      },\n      \"mainEntity\": {\n        \"@type\": \"Service\",\n        \"serviceType\": \"Audio Services & Sound Production\",\n        \"provider\": {\n          \"@type\": \"LocalBusiness\",\n          \"name\": \"MiHi Entertainment\"\n        }\n      }\n    }\n    </script>\n\n    <!-- Structured Data - FAQPage (for Google Featured Snippets) -->\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"FAQPage\",\n      \"mainEntity\": [\n        {\n          \"@type\": \"Question\",\n          \"name\": \"What types of audio services do you provide for events?\",\n          \"acceptedAnswer\": {\n            \"@type\": \"Answer\",\n            \"text\": \"We provide comprehensive audio services including line array sound systems for large venues, distributed sound systems for even coverage, wireless audio solutions with wireless microphones, professional sound engineering, and on-site audio support for conferences, corporate events, concerts, galas, weddings, and brand activations.\"\n          }\n        },\n        {\n          \"@type\": \"Question\",\n          \"name\": \"Do you offer wireless audio solutions for events?\",\n          \"acceptedAnswer\": {\n            \"@type\": \"Answer\",\n            \"text\": \"Yes, we offer professional wireless audio solutions including wireless microphones, wireless audio systems, and distributed sound systems that provide crystal-clear audio coverage throughout your event space without cables, perfect for presentations, speeches, and performances.\"\n          }\n        },\n        {\n          \"@type\": \"Question\",\n          \"name\": \"What is a line array sound system?\",\n          \"acceptedAnswer\": {\n            \"@type\": \"Answer\",\n            \"text\": \"A line array sound system is a professional audio setup consisting of multiple speaker cabinets arranged in a vertical array. These systems provide exceptional sound quality, even coverage, and clarity for large venues, concerts, and corporate events, ensuring every guest hears crystal-clear audio.\"\n          }\n        },\n        {\n          \"@type\": \"Question\",\n          \"name\": \"Do you provide audio services for corporate events and meetings?\",\n          \"acceptedAnswer\": {\n            \"@type\": \"Answer\",\n            \"text\": \"Yes, we specialize in professional audio services for corporate events, conferences, and meetings. Our services include distributed sound systems, wireless microphones for presentations, line arrays for large corporate gatherings, and expert sound engineering to ensure clear audio for speeches, presentations, and performances.\"\n          }\n        },\n        {\n          \"@type\": \"Question\",\n          \"name\": \"What audio equipment is included in your rental services?\",\n          \"acceptedAnswer\": {\n            \"@type\": \"Answer\",\n            \"text\": \"Our audio equipment rental includes professional sound systems (line arrays, distributed speakers, wireless microphones), mixing consoles, amplifiers, audio processors, monitoring systems, and all necessary cables and accessories. Our expert sound engineers handle setup, testing, and live event support.\"\n          }\n        }\n      ]\n    }\n    </script>\n\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <!-- Brand Guide Typography: Azo Sans Font Family -->\n    <link rel=\"stylesheet\" href=\"https://code.jquery.com/ui/1.13.2/themes/ui-lightness/jquery-ui.css\">\n    <script src=\"https://code.jquery.com/jquery-3.6.0.min.js\"></script>\n    <script src=\"https://code.jquery.com/ui/1.13.2/jquery-ui.min.js\"></script>\n    <style>\n        /* Azo Sans Font Face Declarations */\n        @font-face {\n            font-family: \'Azo Sans\';\n            src: url(\'../../assets/fonts/AzoSans-Regular.woff2\') format(\'woff2\'),\n                url(\'../../assets/fonts/AzoSans-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        @font-face {\n            font-family: \'Azo Sans Uber\';\n            src: url(\'../../assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\'),\n                url(\'../../assets/fonts/AzoSansUber-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        /* Protect navigation from page styles - ensure navigation.js styles are preserved */\n        header.bg-white.shadow-lg.fixed {\n            z-index: 50 !important;\n            position: fixed !important;\n            top: 0 !important;\n            left: 0 !important;\n            right: 0 !important;\n        }\n\n        header.bg-white.shadow-lg.fixed nav a:not(.btn-primary) {\n            background: transparent !important;\n            background-color: transparent !important;\n            background-image: none !important;\n            padding: 0 !important;\n            border-radius: 0 !important;\n            box-shadow: none !important;\n            display: inline !important;\n            white-space: normal !important;\n            min-height: auto !important;\n            min-width: auto !important;\n        }\n\n        /* Ensure Events dropdown menu displays correctly */\n        header .group>div[class*=\"grid\"] {\n            display: grid !important;\n        }\n\n        header .group .grid-cols-2 {\n            grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n            display: grid !important;\n            gap: 1rem !important;\n        }\n\n        header .group .space-y-3 {\n            display: flex !important;\n            flex-direction: column !important;\n            gap: 0.75rem !important;\n        }\n\n        header .group .space-y-3>a {\n            display: block !important;\n            width: 100% !important;\n            text-align: left !important;\n            line-height: 1.5 !important;\n        }\n\n        header .group .space-y-3>a span {\n            display: block !important;\n            line-height: 1.4 !important;\n        }\n\n        header .group .space-y-3>a span.font-medium {\n            display: block !important;\n            margin-bottom: 0.25rem !important;\n            font-weight: 600 !important;\n        }\n\n        header .group .space-y-3>a span.text-xs {\n            display: block !important;\n            margin-top: 0 !important;\n            line-height: 1.3 !important;\n        }\n\n        /* Fix floating text in Events dropdown */\n        header .group .absolute {\n            position: absolute !important;\n        }\n\n        header .group .absolute>div {\n            position: relative !important;\n        }\n\n        header .group .absolute .p-6 {\n            padding: 1.5rem !important;\n        }\n\n        header .group .absolute .grid {\n            align-items: start !important;\n        }\n\n        header .group .absolute .space-y-3>a {\n            position: relative !important;\n            float: none !important;\n            clear: both !important;\n        }\n\n        /* Ensure Events dropdown text doesn\'t float - proper alignment */\n        header .group .absolute a {\n            display: block !important;\n            width: 100% !important;\n            text-align: left !important;\n            float: none !important;\n            clear: none !important;\n        }\n\n        header .group .absolute a br {\n            display: block !important;\n            content: \"\" !important;\n            margin-top: 0.25rem !important;\n        }\n\n        header .group .absolute .grid>div {\n            display: flex !important;\n            flex-direction: column !important;\n            align-items: stretch !important;\n        }\n\n        header .group .absolute .grid>div>a {\n            align-self: stretch !important;\n        }\n\n        /* Protect mobile navigation menu from page styles */\n        #mobile-menu-overlay {\n            z-index: 9999 !important;\n        }\n\n        #mobile-menu {\n            display: flex !important;\n            flex-direction: column !important;\n            height: 100% !important;\n            overflow: hidden !important;\n        }\n\n        #mobile-menu .flex.flex-col.h-full {\n            display: flex !important;\n            flex-direction: column !important;\n            height: 100% !important;\n        }\n\n        #mobile-menu .flex-1.overflow-y-auto {\n            flex: 1 1 0% !important;\n            overflow-y: auto !important;\n        }\n\n        #mobile-menu .space-y-3>div {\n            display: block !important;\n        }\n\n        #mobile-menu .mobile-menu-toggle {\n            display: flex !important;\n            align-items: center !important;\n            justify-content: space-between !important;\n            width: 100% !important;\n        }\n\n        #mobile-menu .mobile-menu-toggle svg {\n            display: block !important;\n        }\n\n        #mobile-menu [id$=\"-content\"] {\n            display: block !important;\n        }\n\n        #mobile-menu [id$=\"-content\"].hidden {\n            display: none !important;\n        }\n\n        #mobile-menu .space-y-1>a,\n        #mobile-menu .space-y-4>div {\n            display: block !important;\n        }\n\n        #mobile-menu a {\n            display: block !important;\n            text-decoration: none !important;\n        }\n\n        #mobile-menu button {\n            display: flex !important;\n            cursor: pointer !important;\n            background: transparent !important;\n            border: none !important;\n        }\n\n        /* Ensure mobile menu sections are properly arranged */\n        #mobile-menu .px-5.py-6 {\n            padding-left: 1.25rem !important;\n            padding-right: 1.25rem !important;\n            padding-top: 1.5rem !important;\n            padding-bottom: 1.5rem !important;\n        }\n\n        #mobile-menu .space-y-3 {\n            display: flex !important;\n            flex-direction: column !important;\n            gap: 0.75rem !important;\n        }\n\n        /* Ensure Events section items are properly arranged */\n        #mobile-menu #events-content {\n            display: block !important;\n        }\n\n        #mobile-menu #events-content.hidden {\n            display: none !important;\n        }\n\n        #mobile-menu #events-content .px-5.pb-4 {\n            padding-left: 1.25rem !important;\n            padding-right: 1.25rem !important;\n            padding-bottom: 1rem !important;\n        }\n\n        #mobile-menu #events-content .space-y-1 {\n            display: flex !important;\n            flex-direction: column !important;\n            gap: 0.25rem !important;\n        }\n\n        #mobile-menu #events-content .space-y-1>a {\n            display: block !important;\n            width: 100% !important;\n            padding: 0.625rem 0.75rem !important;\n            margin: 0 !important;\n        }\n\n        /* Ensure mobile menu buttons and links maintain proper layout */\n        #mobile-menu .flex.items-center.gap-3 {\n            display: flex !important;\n            align-items: center !important;\n            gap: 0.75rem !important;\n        }\n\n        #mobile-menu .w-full.flex.items-center.justify-between {\n            display: flex !important;\n            align-items: center !important;\n            justify-content: space-between !important;\n            width: 100% !important;\n        }\n\n        /* Fix text cropping and ensure all menu items are fully visible */\n        #mobile-menu * {\n            box-sizing: border-box !important;\n        }\n\n        #mobile-menu {\n            overflow-x: hidden !important;\n            overflow-y: auto !important;\n        }\n\n        #mobile-menu .mobile-menu-toggle {\n            white-space: nowrap !important;\n            overflow: visible !important;\n            text-overflow: clip !important;\n        }\n\n        #mobile-menu .mobile-menu-toggle span {\n            white-space: normal !important;\n            word-wrap: break-word !important;\n            overflow-wrap: break-word !important;\n            overflow: visible !important;\n            text-overflow: clip !important;\n            max-width: 100% !important;\n        }\n\n        #mobile-menu a {\n            white-space: normal !important;\n            word-wrap: break-word !important;\n            overflow-wrap: break-word !important;\n            overflow: visible !important;\n            text-overflow: clip !important;\n            max-width: 100% !important;\n            min-width: 0 !important;\n        }\n\n        #mobile-menu .text-sm,\n        #mobile-menu .text-base {\n            white-space: normal !important;\n            word-wrap: break-word !important;\n            overflow-wrap: break-word !important;\n            overflow: visible !important;\n            text-overflow: clip !important;\n        }\n\n        /* Ensure menu sections don\'t crop content */\n        #mobile-menu .rounded-2xl {\n            overflow: visible !important;\n        }\n\n        #mobile-menu [id$=\"-content\"] {\n            overflow: visible !important;\n        }\n\n        #mobile-menu [id$=\"-content\"]>div {\n            overflow: visible !important;\n        }\n\n        /* Ensure proper padding to prevent text from touching edges */\n        #mobile-menu .px-5 {\n            padding-left: 1.25rem !important;\n            padding-right: 1.25rem !important;\n        }\n\n        #mobile-menu .px-6 {\n            padding-left: 1.5rem !important;\n            padding-right: 1.5rem !important;\n        }\n\n        #mobile-menu .py-2\\.5,\n        #mobile-menu .py-2 {\n            padding-top: 0.625rem !important;\n            padding-bottom: 0.625rem !important;\n        }\n\n        #mobile-menu .py-4 {\n            padding-top: 1rem !important;\n            padding-bottom: 1rem !important;\n        }\n\n        /* Ensure flex items don\'t shrink too much */\n        #mobile-menu .flex.items-center.gap-3 {\n            flex-shrink: 0 !important;\n            min-width: 0 !important;\n        }\n\n        #mobile-menu .mobile-menu-toggle>div {\n            flex: 1 1 auto !important;\n            min-width: 0 !important;\n            overflow: visible !important;\n        }\n\n        /* Ensure SVG icons don\'t get cut off */\n        #mobile-menu svg {\n            flex-shrink: 0 !important;\n        }\n\n        /* Fix overflow-hidden that might crop content */\n        #mobile-menu .overflow-hidden {\n            overflow: visible !important;\n        }\n\n        #mobile-menu .bg-white.rounded-2xl {\n            overflow: visible !important;\n        }\n\n        /* Ensure menu content containers have proper width */\n        #mobile-menu .w-\\[88vw\\] {\n            width: 88vw !important;\n            max-width: 24rem !important;\n            min-width: 280px !important;\n        }\n\n        /* Ensure text in buttons and links is fully visible */\n        #mobile-menu button span,\n        #mobile-menu a span {\n            display: inline-block !important;\n            max-width: 100% !important;\n            word-break: break-word !important;\n        }\n\n        /* Fix any text truncation */\n        #mobile-menu .truncate {\n            white-space: normal !important;\n            overflow: visible !important;\n            text-overflow: clip !important;\n        }\n\n        /* Ensure category labels are fully visible */\n        #mobile-menu .text-xs {\n            white-space: normal !important;\n            word-wrap: break-word !important;\n            overflow: visible !important;\n        }\n\n        /* Fix nested content areas */\n        #mobile-menu [id$=\"-content\"] .px-5,\n        #mobile-menu [id$=\"-content\"] .pb-4 {\n            padding-left: 1.25rem !important;\n            padding-right: 1.25rem !important;\n            padding-bottom: 1rem !important;\n        }\n\n        #mobile-menu [id$=\"-content\"] .space-y-1,\n        #mobile-menu [id$=\"-content\"] .space-y-4 {\n            padding-left: 0 !important;\n            padding-right: 0 !important;\n        }\n\n        /* Ensure all text elements wrap properly */\n        #mobile-menu .font-medium,\n        #mobile-menu .font-bold,\n        #mobile-menu .font-semibold {\n            white-space: normal !important;\n            word-wrap: break-word !important;\n            overflow-wrap: break-word !important;\n        }\n\n        /* Ensure proper spacing for menu items */\n        #mobile-menu .space-y-1>*+* {\n            margin-top: 0.25rem !important;\n        }\n\n        #mobile-menu .space-y-4>*+* {\n            margin-top: 1rem !important;\n        }\n\n        /* Brand Guide: CTAs use Coral (#FF4F4F) */\n        main a.btn-primary:not(header a):not(nav a),\n        main .btn-primary:not(header .btn-primary):not(nav .btn-primary),\n        .section-padding a.btn-primary,\n        .section-padding .btn-primary {\n            background: #FF4F4F !important;\n            background-color: #FF4F4F !important;\n            background-image: none !important;\n            color: #ffffff !important;\n            border: none !important;\n            padding: 0.75rem 1.5rem !important;\n            border-radius: 9999px !important;\n            font-weight: 600 !important;\n            text-decoration: none !important;\n            display: inline-block !important;\n            transition: all 0.3s ease !important;\n            box-shadow: 0 4px 6px rgba(255, 79, 79, 0.3) !important;\n            white-space: nowrap !important;\n        }\n\n        main a.btn-primary:not(header a):not(nav a):hover,\n        main .btn-primary:not(header .btn-primary):not(nav .btn-primary):hover,\n        .section-padding a.btn-primary:hover,\n        .section-padding .btn-primary:hover {\n            background: #e63939 !important;\n            background-color: #e63939 !important;\n            background-image: none !important;\n            color: #ffffff !important;\n            transform: translateY(-2px) !important;\n            box-shadow: 0 6px 12px rgba(255, 79, 79, 0.4) !important;\n        }\n\n        main a.btn-primary:not(header a):not(nav a):active,\n        main .btn-primary:not(header .btn-primary):not(nav .btn-primary):active,\n        .section-padding a.btn-primary:active,\n        .section-padding .btn-primary:active {\n            transform: translateY(0) !important;\n        }\n\n        /* Mobile-first base styles */\n        * {\n            -webkit-tap-highlight-color: rgba(0, 0, 0, 0.1);\n        }\n\n        /* Brand Guide: Body Text - Azo Sans Regular */\n        body {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n            overflow-x: hidden;\n            background: #ffffff;\n        }\n\n        /* Paragraph styling - Black or White based on background */\n        p {\n            color: #1F1F1F;\n        }\n\n        /* Screen reader only - for SEO purposes */\n        .sr-only {\n            position: absolute;\n            width: 1px;\n            height: 1px;\n            padding: 0;\n            margin: -1px;\n            overflow: hidden;\n            clip: rect(0, 0, 0, 0);\n            white-space: nowrap;\n            border-width: 0;\n        }\n\n        /* Touch-friendly improvements - exclude navigation */\n        @media (max-width: 768px) {\n\n            /* Only apply to page content, not navigation */\n            main a:not(header a):not(nav a),\n            main button:not(header button):not(nav button),\n            .section-padding a,\n            .section-padding button {\n                min-height: 44px;\n                min-width: 44px;\n                display: inline-flex;\n                align-items: center;\n                justify-content: center;\n            }\n\n            /* Hero section buttons - ensure proper touch targets */\n            section#hero .contact-button {\n                min-height: 48px;\n                min-width: 200px;\n            }\n\n            img {\n                max-width: 100%;\n                height: auto;\n            }\n\n            /* Prevent horizontal scroll */\n            html,\n            body {\n                max-width: 100%;\n                overflow-x: hidden;\n            }\n\n            /* Better text rendering on mobile */\n            body {\n                -webkit-font-smoothing: antialiased;\n                -moz-osx-font-smoothing: grayscale;\n                text-rendering: optimizeLegibility;\n            }\n\n            /* Improved spacing for mobile */\n            .container {\n                padding-left: 1rem;\n                padding-right: 1rem;\n            }\n\n            /* Better line heights for readability */\n            p,\n            span,\n            div {\n                line-height: 1.6;\n            }\n        }\n\n        @media (max-width: 480px) {\n\n            /* Extra small mobile optimizations */\n            .container {\n                padding-left: 0.75rem;\n                padding-right: 0.75rem;\n            }\n\n            /* Ensure buttons are touch-friendly - exclude navigation */\n            main button:not(header button):not(nav button),\n            main a.button:not(header a):not(nav a),\n            .section-padding button,\n            .section-padding a.button,\n            .section-padding .btn {\n                padding: 0.75rem 1.25rem;\n                font-size: 0.9rem;\n            }\n        }\n\n        /* Brand Guide: Headers - Azo Sans Uber (Uppercase) */\n        h1,\n        h3,\n        h4,\n        h5,\n        h6 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-weight: 400;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            color: #1F1F1F;\n            -webkit-font-smoothing: antialiased;\n            -moz-osx-font-smoothing: grayscale;\n        }\n\n        /* Brand Guide: h2 - Coral Color */\n        h2 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-weight: 400;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            color: #FF4F4F;\n            -webkit-font-smoothing: antialiased;\n            -moz-osx-font-smoothing: grayscale;\n        }\n\n        h3.av-title,\n        h1.av-title {\n            font-family: \'Azo Sans Uber\', sans-serif !important;\n            font-weight: 400;\n            letter-spacing: 0.02em;\n            text-transform: uppercase;\n        }\n\n        /* Brand Guide: h3.av-title - Aqua Color for visibility */\n        h3.av-title {\n            color: #18F1E1 !important;\n            text-shadow: 0 0 10px rgba(24, 241, 225, 0.5),\n                0 0 20px rgba(24, 241, 225, 0.3),\n                0 2px 4px rgba(0, 0, 0, 0.3);\n            font-weight: 700 !important;\n        }\n\n        h1.av-title {\n            font-size: 4rem !important;\n            font-weight: 400 !important;\n            letter-spacing: 0.02em !important;\n            position: relative;\n            display: inline-block;\n            transform-style: preserve-3d;\n            perspective: 1000px;\n            text-rendering: optimizeLegibility;\n            -webkit-font-smoothing: antialiased;\n            -moz-osx-font-smoothing: grayscale;\n            color: #FF4F4F;\n            animation: float3d 6s ease-in-out infinite;\n            transform: translateZ(20px) rotateX(5deg);\n            transition: all 0.3s ease;\n        }\n\n        h1.av-title:hover {\n            transform: translateZ(30px) rotateX(0deg) scale(1.05);\n            color: #e63939;\n        }\n\n        @keyframes shimmer {\n\n            0%,\n            100% {\n                background-position: 0% 50%;\n            }\n\n            50% {\n                background-position: 100% 50%;\n            }\n        }\n\n        @keyframes float3d {\n\n            0%,\n            100% {\n                transform: translateZ(20px) rotateX(5deg) translateY(0px);\n            }\n\n            50% {\n                transform: translateZ(25px) rotateX(2deg) translateY(-5px);\n            }\n        }\n\n        @media (max-width: 768px) {\n            h1.av-title {\n                font-size: 2.25rem !important;\n                letter-spacing: 0.08em !important;\n                margin-bottom: 0.75rem !important;\n            }\n\n            h3.av-title {\n                font-size: 1.1rem !important;\n                margin-bottom: 0.5rem !important;\n            }\n\n            /* Hero section mobile improvements */\n            section.relative.h-screen {\n                min-height: 90vh;\n                max-height: 100vh;\n                padding: 1.5rem 0.75rem;\n                padding-top: max(1.5rem, env(safe-area-inset-top, 1.5rem));\n                padding-bottom: max(1.5rem, env(safe-area-inset-bottom, 1.5rem));\n                display: flex;\n                align-items: center;\n                justify-content: center;\n            }\n\n            .relative.z-10.text-center {\n                padding: 0.75rem 0.5rem;\n                width: 100%;\n            }\n\n            .relative.z-10.text-center .max-w-6xl {\n                padding: 0;\n            }\n\n            div.wall {\n                font-size: 0.95rem !important;\n                line-height: 1.5 !important;\n                padding: 0 0.5rem !important;\n                max-width: 100% !important;\n                margin: 0 auto 1.25rem auto !important;\n                text-transform: none !important;\n                letter-spacing: 0.02em !important;\n            }\n\n            button.contact-button,\n            a.contact-button {\n                margin-top: 0.75rem;\n                transform: scale(1);\n                width: 100%;\n                max-width: 280px;\n            }\n\n            button.contact-button .button-inner,\n            a.contact-button .button-inner {\n                padding: 0.875rem 1.25rem !important;\n            }\n\n            button.contact-button .button-inner span,\n            a.contact-button .button-inner span {\n                font-size: 0.9rem !important;\n            }\n\n            /* Trust indicators mobile */\n            .flex.flex-wrap.items-center.justify-center.gap-4 {\n                gap: 0.75rem !important;\n                margin-top: 1.25rem !important;\n                padding: 0 0.5rem !important;\n            }\n\n            .flex.flex-wrap.items-center.justify-center.gap-4>div {\n                font-size: 0.7rem !important;\n            }\n\n            .flex.flex-wrap.items-center.justify-center.gap-4 .w-2 {\n                width: 0.375rem !important;\n                height: 0.375rem !important;\n            }\n        }\n\n        @media (max-width: 480px) {\n            h1.av-title {\n                font-size: 1.75rem !important;\n                letter-spacing: 0.06em !important;\n                margin-bottom: 0.5rem !important;\n            }\n\n            h3.av-title {\n                font-size: 0.95rem !important;\n                margin-bottom: 0.375rem !important;\n            }\n\n            .section-padding {\n                padding: 1.5rem 0;\n            }\n\n            div.wall {\n                font-size: 0.85rem !important;\n                margin: 0 auto 1rem auto !important;\n                line-height: 1.45 !important;\n                padding: 0 0.5rem !important;\n                max-width: 100% !important;\n            }\n\n            button.contact-button,\n            a.contact-button {\n                margin-top: 0.625rem;\n                transform: scale(1);\n                width: 100%;\n                max-width: 260px;\n            }\n\n            button.contact-button .button-inner,\n            a.contact-button .button-inner {\n                padding: 0.75rem 1rem !important;\n            }\n\n            button.contact-button .button-inner span,\n            a.contact-button .button-inner span {\n                font-size: 0.85rem !important;\n            }\n\n            /* Hero section small mobile */\n            section.relative.h-screen {\n                min-height: 85vh;\n                padding: 1.25rem 0.5rem;\n                padding-top: max(1.25rem, env(safe-area-inset-top, 1.25rem));\n                padding-bottom: max(1.25rem, env(safe-area-inset-bottom, 1.25rem));\n            }\n\n            .relative.z-10.text-center {\n                padding: 0.5rem 0.25rem;\n            }\n\n            /* Trust indicators small mobile */\n            .flex.flex-wrap.items-center.justify-center.gap-4 {\n                gap: 0.5rem !important;\n                margin-top: 1rem !important;\n                flex-wrap: wrap !important;\n            }\n\n            .flex.flex-wrap.items-center.justify-center.gap-4>div {\n                font-size: 0.65rem !important;\n                flex: 0 1 auto;\n            }\n\n            .flex.flex-wrap.items-center.justify-center.gap-4 .w-2 {\n                width: 0.35rem !important;\n                height: 0.35rem !important;\n            }\n        }\n\n        @media (max-width: 375px) {\n            h1.av-title {\n                font-size: 1.5rem !important;\n                letter-spacing: 0.05em !important;\n                margin-bottom: 0.5rem !important;\n            }\n\n            h3.av-title {\n                font-size: 0.875rem !important;\n                margin-bottom: 0.25rem !important;\n            }\n\n            div.wall {\n                font-size: 0.8rem !important;\n                margin: 0 auto 0.875rem auto !important;\n                line-height: 1.4 !important;\n                max-width: 100% !important;\n                padding: 0 0.375rem !important;\n            }\n\n            /* Hero section extra small mobile */\n            section.relative.h-screen {\n                min-height: 85vh;\n                padding: 1rem 0.375rem;\n                padding-top: max(1rem, env(safe-area-inset-top, 1rem));\n                padding-bottom: max(1rem, env(safe-area-inset-bottom, 1rem));\n            }\n\n            .relative.z-10.text-center {\n                padding: 0.375rem 0.125rem;\n            }\n\n            button.contact-button,\n            a.contact-button {\n                max-width: 240px;\n                margin-top: 0.5rem;\n            }\n\n            button.contact-button .button-inner,\n            a.contact-button .button-inner {\n                padding: 0.7rem 0.9rem !important;\n            }\n\n            button.contact-button .button-inner span,\n            a.contact-button .button-inner span {\n                font-size: 0.8rem !important;\n            }\n\n            /* Trust indicators extra small mobile */\n            .flex.flex-wrap.items-center.justify-center.gap-4 {\n                gap: 0.4rem !important;\n                margin-top: 0.875rem !important;\n            }\n\n            .flex.flex-wrap.items-center.justify-center.gap-4>div {\n                font-size: 0.6rem !important;\n            }\n\n            .flex.flex-wrap.items-center.justify-center.gap-4 .w-2 {\n                width: 0.3rem !important;\n                height: 0.3rem !important;\n            }\n        }\n\n        /* 3D Button Styles */\n        button.contact-button,\n        a.contact-button {\n            all: unset;\n            cursor: pointer;\n            -webkit-tap-highlight-color: rgba(0, 0, 0, 0);\n            position: relative;\n            border-radius: 999vw;\n            background-color: rgba(0, 0, 0, 0.75);\n            box-shadow: -0.15em -0.15em 0.15em -0.075em rgba(5, 5, 5, 0.25),\n                0.0375em 0.0375em 0.0675em 0 rgba(5, 5, 5, 0.1);\n            display: inline-block;\n            margin-top: 1rem;\n            text-decoration: none;\n        }\n\n        button.contact-button::after,\n        a.contact-button::after {\n            content: \"\";\n            position: absolute;\n            z-index: 0;\n            width: calc(100% + 0.3em);\n            height: calc(100% + 0.3em);\n            top: -0.15em;\n            left: -0.15em;\n            border-radius: inherit;\n            background: linear-gradient(-135deg,\n                    rgba(5, 5, 5, 0.5),\n                    transparent 20%,\n                    transparent 100%);\n            filter: blur(0.0125em);\n            opacity: 0.25;\n            mix-blend-mode: multiply;\n        }\n\n        button.contact-button .button-outer,\n        a.contact-button .button-outer {\n            position: relative;\n            z-index: 1;\n            border-radius: inherit;\n            transition: box-shadow 300ms ease;\n            will-change: box-shadow;\n            box-shadow: 0 0.05em 0.05em -0.01em rgba(5, 5, 5, 1),\n                0 0.01em 0.01em -0.01em rgba(5, 5, 5, 0.5),\n                0.15em 0.3em 0.1em -0.01em rgba(5, 5, 5, 0.25);\n        }\n\n        button.contact-button:hover .button-outer,\n        a.contact-button:hover .button-outer {\n            box-shadow: 0 0 0 0 rgba(5, 5, 5, 1), 0 0 0 0 rgba(5, 5, 5, 0.5),\n                0 0 0 0 rgba(5, 5, 5, 0.25);\n        }\n\n        button.contact-button .button-inner,\n        a.contact-button .button-inner {\n            --inset: 0.035em;\n            position: relative;\n            z-index: 1;\n            border-radius: inherit;\n            padding: 1em 1.5em;\n            background-image: linear-gradient(135deg,\n                    rgba(230, 230, 230, 1),\n                    rgba(180, 180, 180, 1));\n            transition: box-shadow 300ms ease, clip-path 250ms ease,\n                background-image 250ms ease, transform 250ms ease;\n            will-change: box-shadow, clip-path, background-image, transform;\n            overflow: clip;\n            clip-path: inset(0 0 0 0 round 999vw);\n            box-shadow:\n                /* 1 */\n                0 0 0 0 inset rgba(5, 5, 5, 0.1),\n                /* 2 */\n                -0.05em -0.05em 0.05em 0 inset rgba(5, 5, 5, 0.25),\n                /* 3 */\n                0 0 0 0 inset rgba(5, 5, 5, 0.1),\n                /* 4 */\n                0 0 0.05em 0.2em inset rgba(255, 255, 255, 0.25),\n                /* 5 */\n                0.025em 0.05em 0.1em 0 inset rgba(255, 255, 255, 1),\n                /* 6 */\n                0.12em 0.12em 0.12em inset rgba(255, 255, 255, 0.25),\n                /* 7 */\n                -0.075em -0.25em 0.25em 0.1em inset rgba(5, 5, 5, 0.25);\n        }\n\n        button.contact-button:hover .button-inner,\n        a.contact-button:hover .button-inner {\n            clip-path: inset(clamp(1px, 0.0625em, 2px) clamp(1px, 0.0625em, 2px) clamp(1px, 0.0625em, 2px) clamp(1px, 0.0625em, 2px) round 999vw);\n            box-shadow:\n                /* 1 */\n                0.1em 0.15em 0.05em 0 inset rgba(5, 5, 5, 0.75),\n                /* 2 */\n                -0.025em -0.03em 0.05em 0.025em inset rgba(5, 5, 5, 0.5),\n                /* 3 */\n                0.25em 0.25em 0.2em 0 inset rgba(5, 5, 5, 0.5),\n                /* 4 */\n                0 0 0.05em 0.5em inset rgba(255, 255, 255, 0.15),\n                /* 5 */\n                0 0 0 0 inset rgba(255, 255, 255, 1),\n                /* 6 */\n                0.12em 0.12em 0.12em inset rgba(255, 255, 255, 0.25),\n                /* 7 */\n                -0.075em -0.12em 0.2em 0.1em inset rgba(5, 5, 5, 0.25);\n        }\n\n        button.contact-button .button-inner span,\n        a.contact-button .button-inner span {\n            position: relative;\n            z-index: 4;\n            font-family: \'Azo Sans Uber\', sans-serif;\n            letter-spacing: 0.02em;\n            font-weight: 400;\n            text-transform: uppercase;\n            color: rgba(0, 0, 0, 0);\n            background-image: linear-gradient(135deg,\n                    rgba(25, 25, 25, 1),\n                    rgba(75, 75, 75, 1));\n            -webkit-background-clip: text;\n            background-clip: text;\n            transition: transform 250ms ease;\n            display: inline-flex;\n            align-items: center;\n            will-change: transform;\n            text-shadow: rgba(0, 0, 0, 0.1) 0 0 0.1em;\n            -webkit-user-select: none;\n            -moz-user-select: none;\n            -ms-user-select: none;\n            user-select: none;\n            font-size: 1rem;\n        }\n\n        /* Brand Guide: Get Your Quote button - Black color */\n        a.contact-button .button-inner span:not(.flex) {\n            background-image: linear-gradient(135deg, #1F1F1F, #1F1F1F);\n            -webkit-background-clip: text;\n            background-clip: text;\n        }\n\n        /* Brand Guide: Call Us button - Coral color */\n        button.contact-button .button-inner span.flex.items-center.gap-2 {\n            background-image: linear-gradient(135deg, #FF4F4F, #e63939);\n            -webkit-background-clip: text;\n            background-clip: text;\n        }\n\n        button.contact-button .button-inner span.flex.items-center.gap-2 svg {\n            stroke: #FF4F4F;\n        }\n\n        button.contact-button:hover .button-inner span.flex.items-center.gap-2 svg {\n            stroke: #e63939;\n        }\n\n        button.contact-button .button-inner span svg,\n        a.contact-button .button-inner span svg {\n            fill: none;\n            stroke: #1F1F1F;\n            stroke-width: 2.5;\n            width: 1em;\n            height: 1em;\n            flex-shrink: 0;\n            filter: drop-shadow(0 0 0.05em rgba(0, 0, 0, 0.3));\n        }\n\n        button.contact-button:hover .button-inner span svg,\n        a.contact-button:hover .button-inner span svg {\n            stroke: #1F1F1F;\n        }\n\n        button.contact-button:hover .button-inner span,\n        a.contact-button:hover .button-inner span {\n            transform: scale(0.975);\n        }\n\n        button.contact-button:active .button-inner,\n        a.contact-button:active .button-inner {\n            transform: scale(0.975);\n        }\n\n        .section-padding {\n            padding: 2rem 0;\n            background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 50%, #f1f3f5 100%);\n        }\n\n        /* Hide busy canvas animations for cleaner background */\n        .section-padding canvas {\n            display: none !important;\n        }\n\n        .hero-gradient {\n            background: linear-gradient(135deg, rgba(255, 79, 79, 0.5) 0%, rgba(24, 241, 225, 0.5) 100%);\n        }\n\n        .hero-overlay {\n            background: rgba(0, 0, 0, 0.5);\n        }\n\n        /* Interactive Brochure Section Styles - AV Theme */\n        .brochure-section {\n            background: radial-gradient(circle, rgba(10, 15, 35, 0.95) 0%, rgba(4, 11, 28, 1) 100%);\n            position: relative;\n            overflow: hidden;\n            font-family: \'Azo Sans\', sans-serif;\n            min-height: 92vh;\n            display: flex;\n            align-items: center;\n            padding-top: 0;\n            padding-bottom: 0;\n        }\n\n        .brochure-section .container {\n            width: 100%;\n            padding-top: 3rem;\n            padding-bottom: 3rem;\n            padding-left: clamp(1.5rem, 3vw, 3rem);\n            padding-right: clamp(1.5rem, 3vw, 3rem);\n        }\n\n        .brochure-header {\n            margin-bottom: 2rem !important;\n        }\n\n        .brochure-header h2 {\n            margin-bottom: 0.75rem;\n        }\n\n        .brochure-header p {\n            font-size: 1.05rem;\n        }\n\n        .content-grid {\n            gap: clamp(1.5rem, 2.5vw, 2.5rem);\n            align-items: stretch;\n        }\n\n        .feature-list {\n            gap: 0.9rem;\n            margin-bottom: 2rem;\n        }\n\n        .brochure-cta-group {\n            gap: 1rem;\n        }\n\n        .compact-tags {\n            gap: 0.75rem;\n            padding-top: 0.75rem;\n        }\n\n        .compact-tags .brochure-tag {\n            font-size: 0.8rem;\n        }\n\n        /* Animated keyboard spotlight section */\n        .keyboard-section {\n            background: radial-gradient(circle at 20% 20%, rgba(255, 79, 79, 0.15), transparent 45%),\n                radial-gradient(circle at 80% 10%, rgba(24, 241, 225, 0.12), transparent 50%),\n                #1F1F1F;\n            color: #fff;\n            padding: 2rem 1.5rem 4.5rem 1.5rem;\n            position: relative;\n            overflow: visible;\n        }\n\n        /* Compact desktop view */\n        @media (min-width: 1025px) {\n            .keyboard-section {\n                padding: 1.5rem 1.5rem 4rem 1.5rem;\n            }\n\n            .keyboard-wrapper {\n                gap: 1rem;\n                padding: 0 1rem 1.25rem 1rem;\n            }\n\n            .keyboard-content {\n                gap: 1.25rem;\n                min-height: 180px;\n            }\n\n            .keyboard .key {\n                font-size: 2rem;\n                padding: 0.25rem 0.4rem;\n            }\n\n            .keyboard-message {\n                font-size: 1.05rem;\n                line-height: 1.35;\n                max-width: 420px;\n            }\n\n            .keyboard-mail {\n                width: 160px;\n                height: 160px;\n            }\n\n            .keyboard-mail-label {\n                transform: translate(-40px, 150px);\n                font-size: 0.75rem;\n                padding: 0.4rem 0.85rem;\n            }\n        }\n\n        .keyboard-particles {\n            position: absolute;\n            inset: 0;\n            overflow: hidden;\n            z-index: 0;\n            pointer-events: none;\n        }\n\n        .keyboard-particles::after {\n            content: \"\";\n            position: absolute;\n            inset: 0;\n            background: radial-gradient(circle at 30% 20%, rgba(255, 79, 79, 0.15), transparent 55%),\n                radial-gradient(circle at 70% 60%, rgba(24, 241, 225, 0.12), transparent 60%);\n            opacity: 0.45;\n        }\n\n        .keyboard-particles .particle {\n            position: absolute;\n            border-radius: 50%;\n            background: rgba(255, 79, 79, 0.12);\n            box-shadow: 0 0 12px rgba(24, 241, 225, 0.45);\n            width: var(--size, 30px);\n            height: var(--size, 30px);\n            left: var(--x, 50%);\n            top: var(--y, 50%);\n            animation: keyboardParticleDrift var(--duration, 18s) ease-in-out infinite;\n            animation-delay: var(--delay, 0s);\n            transform-origin: center;\n            opacity: 0.75;\n        }\n\n        @keyframes keyboardParticleDrift {\n            0% {\n                transform: translate3d(0, 0, 0) scale(1);\n                opacity: 0.8;\n            }\n\n            50% {\n                transform: translate3d(var(--dx, 20px), var(--dy, -40px), 0) scale(1.25);\n                opacity: 0.35;\n            }\n\n            100% {\n                transform: translate3d(0, 0, 0) scale(1);\n                opacity: 0.8;\n            }\n        }\n\n        .keyboard-wrapper {\n            max-width: 1200px;\n            margin: 0 auto;\n            text-align: left;\n            display: flex;\n            flex-direction: column;\n            align-items: flex-start;\n            gap: