(max-width: 375px) {\n            .keyboard-section {\n                padding: 1.5rem 0.5rem 3rem 0.5rem;\n            }\n\n            /* Hide even more particles on very small screens */\n            .keyboard-particles .particle:nth-child(n+8) {\n                display: none;\n            }\n\n            .keyboard-particles .particle {\n                opacity: 0.25;\n            }\n\n            .keyboard-wrapper {\n                padding: 0 0.5rem 1rem 0.5rem;\n                gap: 1.5rem;\n            }\n\n            .keyboard {\n                gap: 0.15rem;\n            }\n\n            .keyboard .key {\n                font-size: clamp(1rem, 7.5vw, 1.3rem);\n                padding: 0.3rem 0.35rem;\n                min-width: 44px;\n                min-height: 44px;\n            }\n\n            .keyboard .key-space {\n                width: clamp(0.5rem, 2.5vw, 1rem);\n            }\n\n            .keyboard-message {\n                font-size: clamp(0.8rem, 4vw, 0.95rem);\n                line-height: 1.65;\n                padding: 0 0.5rem;\n            }\n\n            .keyboard-mail {\n                width: 130px;\n                height: 130px;\n                min-width: 130px;\n                min-height: 130px;\n            }\n\n            .keyboard-mail-label {\n                transform: translate(-30px, 120px);\n                max-width: 110px;\n                font-size: clamp(0.65rem, 3.5vw, 0.8rem);\n                padding: 0.55rem 0.9rem;\n                min-height: 44px;\n            }\n\n            .animated-mail {\n                height: 120px;\n                width: 160px;\n            }\n\n            .animated-mail .body {\n                border-width: 0 0 80px 160px;\n            }\n\n            .animated-mail .top-fold {\n                border-width: 40px 80px 0 80px;\n                top: 40px;\n            }\n\n            .animated-mail .back-fold {\n                width: 160px;\n                height: 80px;\n            }\n\n            .animated-mail .left-fold {\n                border-width: 40px 0 40px 80px;\n            }\n\n            .animated-mail .letter {\n                left: 16px;\n                width: 128px;\n                height: 48px;\n            }\n        }\n\n        /* Very small screens (320px and below) */\n        @media (max-width: 320px) {\n            .keyboard-section {\n                padding: 1.25rem 0.5rem 2.5rem 0.5rem;\n            }\n\n            .keyboard-particles .particle:nth-child(n+6) {\n                display: none;\n            }\n\n            .keyboard-wrapper {\n                padding: 0 0.5rem 0.75rem 0.5rem;\n                gap: 1.25rem;\n            }\n\n            .keyboard .key {\n                font-size: clamp(0.95rem, 8vw, 1.2rem);\n                padding: 0.25rem 0.3rem;\n            }\n\n            .keyboard-message {\n                font-size: clamp(0.75rem, 4.5vw, 0.9rem);\n                padding: 0 0.25rem;\n            }\n\n            .keyboard-mail {\n                width: 120px;\n                height: 120px;\n                min-width: 120px;\n                min-height: 120px;\n            }\n\n            .keyboard-mail-label {\n                transform: translate(-28px, 110px);\n                max-width: 100px;\n                font-size: clamp(0.65rem, 4vw, 0.75rem);\n                padding: 0.5rem 0.8rem;\n            }\n        }\n\n        /* Reduced motion support for accessibility */\n        @media (prefers-reduced-motion: reduce) {\n            .keyboard-particles .particle {\n                animation: none;\n                opacity: 0.2;\n            }\n\n            .keyboard-mail {\n                animation: none;\n            }\n        }\n\n        /* Performance optimizations for mobile */\n        @media (max-width: 768px) {\n            .keyboard-section {\n                will-change: auto;\n            }\n\n            .keyboard-particles {\n                will-change: transform;\n            }\n\n            .keyboard-mail {\n                will-change: transform;\n            }\n        }\n\n        @media (max-width: 1024px) {\n            .brochure-section {\n                min-height: auto;\n                display: block;\n                padding-top: 0;\n                padding-bottom: 0;\n            }\n\n            .brochure-section .container {\n                padding-top: 2.5rem;\n                padding-bottom: 2.5rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .brochure-section .container {\n                padding-top: 2rem;\n                padding-bottom: 2rem;\n                padding-left: 1rem;\n                padding-right: 1rem;\n            }\n\n            .brochure-header {\n                margin-bottom: 1.5rem !important;\n            }\n\n            .brochure-header h2 {\n                font-size: 1.75rem !important;\n                line-height: 1.3;\n                margin-bottom: 0.75rem;\n            }\n\n            .brochure-header p {\n                font-size: 0.95rem !important;\n                padding: 0 0.5rem;\n            }\n\n            .brochure-badge {\n                font-size: 0.75rem;\n                padding: 0.4rem 1rem;\n            }\n\n            .content-grid {\n                gap: 1.5rem;\n            }\n\n            .brochure-subtitle {\n                font-size: 1.5rem !important;\n                line-height: 1.4;\n                margin-bottom: 1rem;\n            }\n\n            .brochure-section p.text-lg {\n                font-size: 0.95rem !important;\n                line-height: 1.6;\n                margin-bottom: 1.25rem;\n            }\n\n            .feature-list {\n                gap: 0.75rem;\n                margin-bottom: 1.5rem;\n            }\n\n            .brochure-check-item {\n                padding: 0.75rem;\n            }\n\n            .brochure-check-text {\n                font-size: 0.9rem;\n            }\n\n            .brochure-check-description {\n                font-size: 0.8rem;\n                line-height: 1.5;\n            }\n\n            .brochure-cta-group {\n                flex-direction: column;\n                gap: 0.75rem;\n            }\n\n            .brochure-view-button,\n            .brochure-download-button {\n                width: 100%;\n                justify-content: center;\n                padding: 0.875rem 1.5rem;\n                font-size: 0.9rem;\n            }\n\n            .compact-tags {\n                flex-wrap: wrap;\n                gap: 0.5rem;\n            }\n\n            .brochure-tag {\n                font-size: 0.7rem;\n                padding: 0.4rem 0.75rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .brochure-section .container {\n                padding-top: 1.5rem;\n                padding-bottom: 1.5rem;\n                padding-left: 0.75rem;\n                padding-right: 0.75rem;\n            }\n\n            .brochure-header h2 {\n                font-size: 1.5rem !important;\n            }\n\n            .brochure-header p {\n                font-size: 0.875rem !important;\n            }\n\n            .brochure-subtitle {\n                font-size: 1.25rem !important;\n            }\n\n            .brochure-section p.text-lg {\n                font-size: 0.875rem !important;\n            }\n\n            .brochure-preview {\n                margin-bottom: 1rem;\n            }\n        }\n\n        .brochure-section h2 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            letter-spacing: 0.08em;\n            text-transform: uppercase;\n        }\n\n        .brochure-section h3,\n        .brochure-section .brochure-subtitle {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            letter-spacing: 0.06em;\n            text-transform: uppercase;\n        }\n\n        .brochure-section p,\n        .brochure-check-text,\n        .brochure-check-description,\n        .brochure-tag {\n            font-family: \'Azo Sans\', sans-serif;\n            letter-spacing: 0.02em;\n        }\n\n        .brochure-section .pill-label {\n            font-family: \'Azo Sans\', sans-serif;\n            letter-spacing: 0.12em;\n            text-transform: uppercase;\n        }\n\n        .brochure-section::before {\n            content: \"\";\n            position: absolute;\n            inset: 0;\n            background-image:\n                radial-gradient(circle at 20% 50%, rgba(255, 79, 79, 0.18) 0%, transparent 45%),\n                radial-gradient(circle at 80% 50%, rgba(24, 241, 225, 0.15) 0%, transparent 45%);\n            pointer-events: none;\n        }\n\n        #brochure-webgl-canvas {\n            position: absolute;\n            inset: 0;\n            width: 100%;\n            height: 100%;\n            overflow: hidden;\n            z-index: 0;\n        }\n\n        .brochure-badge {\n            background: #FF4F4F;\n            color: #ffffff;\n            padding: 0.5rem 1.5rem;\n            border-radius: 50px;\n            font-size: 0.875rem;\n            font-weight: 700;\n            letter-spacing: 0.05em;\n            text-transform: uppercase;\n            display: inline-block;\n            box-shadow: 0 4px 18px rgba(255, 79, 79, 0.35);\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        .brochure-preview {\n            position: relative;\n            background: #0f172a;\n            border-radius: 1.5rem;\n            box-shadow: 0 25px 55px -15px rgba(15, 23, 42, 0.85);\n            overflow: hidden;\n            transition: transform 0.45s ease, box-shadow 0.45s ease;\n            border: 2px solid rgba(255, 79, 79, 0.35);\n        }\n\n        .brochure-preview:hover {\n            transform: translateY(-6px);\n            box-shadow: 0 35px 60px -20px rgba(255, 79, 79, 0.5);\n            border-color: rgba(255, 79, 79, 0.6);\n        }\n\n        .brochure-preview::before {\n            content: \"\";\n            position: absolute;\n            inset: 0;\n            background: repeating-linear-gradient(45deg, transparent, transparent 2px, rgba(255, 79, 79, 0.05) 2px, rgba(255, 79, 79, 0.05) 4px);\n            opacity: 0.4;\n            pointer-events: none;\n        }\n\n        .brochure-image {\n            width: 100%;\n            height: 100%;\n            object-fit: contain;\n            transition: transform 0.6s ease;\n        }\n\n        .brochure-preview:hover .brochure-image {\n            transform: scale(1.03);\n        }\n\n        .brochure-check-item {\n            display: flex;\n            align-items: flex-start;\n            gap: 0.75rem;\n        }\n\n        .brochure-check-icon {\n            flex-shrink: 0;\n            width: 1.5rem;\n            height: 1.5rem;\n            border-radius: 50%;\n            background: #FF4F4F;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n        }\n\n        .brochure-check-text {\n            font-weight: 600;\n            color: #ffffff;\n        }\n\n        .brochure-check-description {\n            color: #1F1F1F;\n            margin-top: 0.25rem;\n            opacity: 0.7;\n        }\n\n        .brochure-button {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            background: #FF4F4F;\n            color: #ffffff;\n            padding: 0.85rem 1.75rem;\n            border-radius: 9999px;\n            font-weight: 700;\n            font-size: 1rem;\n            font-family: \'Azo Sans\', sans-serif;\n            border: none;\n            cursor: pointer;\n            box-shadow: 0 20px 35px -15px rgba(255, 79, 79, 0.65);\n            transition: transform 0.3s ease, box-shadow 0.3s ease;\n        }\n\n        .brochure-button:hover {\n            transform: translateY(-2px) scale(1.02);\n            box-shadow: 0 30px 45px -20px rgba(255, 79, 79, 0.75);\n            background: #e63939;\n        }\n\n        .brochure-download-button {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            border: 2px solid #FF4F4F;\n            color: #1F1F1F;\n            padding: 0.8rem 1.5rem;\n            border-radius: 0.5rem;\n            font-weight: 700;\n            font-family: \'Azo Sans\', sans-serif;\n            letter-spacing: 0.04em;\n            transition: all 0.3s ease;\n            text-decoration: none;\n        }\n\n        .brochure-download-button:hover {\n            background: #FF4F4F;\n            color: #ffffff;\n            transform: translateY(-2px);\n        }\n\n        .brochure-tag {\n            display: inline-flex;\n            align-items: center;\n            gap: 0.4rem;\n            color: #1F1F1F;\n            font-size: 0.9rem;\n            font-weight: 500;\n            text-transform: uppercase;\n            letter-spacing: 0.08em;\n            opacity: 0.7;\n        }\n\n        .brochure-tag-icon {\n            color: #FF4F4F;\n            width: 1.15rem;\n            height: 1.15rem;\n        }\n\n        .brochure-modal {\n            position: fixed;\n            inset: 0;\n            z-index: 9999;\n            display: none;\n            background-color: rgba(0, 0, 0, 0.85);\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        .brochure-modal.show {\n            display: block;\n        }\n\n        .brochure-modal-content {\n            position: relative;\n            width: 100%;\n            height: 100%;\n        }\n\n        .brochure-close-button {\n            position: fixed;\n            top: 1rem;\n            right: 1rem;\n            background: rgba(15, 23, 42, 0.9);\n            color: #FF4F4F;\n            border: none;\n            border-radius: 50%;\n            padding: 0.6rem;\n            cursor: pointer;\n            transition: transform 0.2s ease, background 0.2s ease;\n            box-shadow: 0 8px 20px rgba(15, 23, 42, 0.7);\n            z-index: 10001;\n            pointer-events: auto;\n        }\n\n        .brochure-close-button:hover {\n            transform: scale(1.08);\n            background: rgba(30, 41, 59, 0.95);\n        }\n\n        .brochure-iframe {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            border: none;\n            background: transparent;\n        }\n\n        #brochureLoader {\n            display: none;\n        }\n\n        /* Text styles */\n        div.wall {\n            margin: 0 auto 2rem auto;\n            font-size: 1.25rem;\n            line-height: 1.5;\n            display: block;\n            text-shadow: 0px 1px 1px #111;\n            color: #ffffd1;\n            position: relative;\n            font-family: \'Azo Sans\', sans-serif;\n            font-weight: 400;\n            font-style: normal;\n            text-align: center;\n            max-width: 90%;\n            width: 100%;\n            letter-spacing: 0.05em;\n            text-transform: uppercase;\n            word-wrap: break-word;\n            overflow-wrap: break-word;\n            word-break: normal;\n            white-space: normal;\n            hyphens: none;\n            box-sizing: border-box;\n        }\n\n\n        /* Tabs Component Styles */\n        #tabs {\n            width: 100%;\n            max-width: 1400px;\n            display: flex;\n            position: relative;\n            margin: 0 auto;\n            margin-top: 10px;\n            height: auto;\n            min-height: 300px;\n            max-height: none;\n            overflow: visible;\n            padding: 0 20px;\n        }\n\n        #tabs ul {\n            position: relative;\n            display: inline-block;\n            margin: 0;\n            padding: 0;\n            list-style-type: none;\n            vertical-align: top;\n            width: 50%;\n            min-width: 300px;\n        }\n\n        #tabs ul li a {\n            position: relative;\n            display: block;\n            width: 100%;\n            text-decoration: none;\n            color: #1F1F1F;\n            border-top: solid 2px rgba(255, 79, 79, 0.1);\n            padding: 14px 10px;\n            z-index: 1;\n            opacity: .6;\n            background: linear-gradient(90deg, transparent 0%, transparent 100%);\n            -webkit-transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n            -moz-transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n            -o-transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n        }\n\n        #tabs ul li a:hover {\n            opacity: 0.8;\n            background: linear-gradient(90deg, rgba(255, 79, 79, 0.05) 0%, transparent 100%);\n            transform: translateX(5px);\n        }\n\n        #tabs ul li:focus,\n        #tabs ul li a:focus {\n            outline: none;\n        }\n\n        #tabs ul li:nth-child(1) a {\n            border-top: none;\n        }\n\n        #tabs ul li a.active {\n            opacity: 1;\n            background: linear-gradient(90deg, rgba(255, 79, 79, 0.1) 0%, rgba(255, 79, 79, 0.05) 100%);\n            border-left: 3px solid #FF4F4F;\n            padding-left: 15px;\n        }\n\n        #tabs .para-a {\n            font-weight: 700;\n            margin-top: 10px;\n            padding: 6px 16px;\n            text-transform: uppercase;\n            font-size: 10px;\n            letter-spacing: 1.2px;\n            border: none;\n            font-family: \'Azo Sans Uber\', sans-serif;\n            color: #FF4F4F;\n            text-decoration: none;\n            display: inline-block;\n            background: linear-gradient(135deg, rgba(255, 79, 79, 0.1) 0%, rgba(24, 241, 225, 0.1) 100%);\n            border-radius: 18px;\n            transition: all 0.3s ease;\n            position: relative;\n            overflow: hidden;\n        }\n\n        #tabs .para-a::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: -100%;\n            width: 100%;\n            height: 100%;\n            background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent);\n            transition: left 0.5s ease;\n        }\n\n        #tabs .para-a:hover {\n            background: linear-gradient(135deg, rgba(255, 79, 79, 0.2) 0%, rgba(24, 241, 225, 0.2) 100%);\n            color: #FF4F4F;\n            transform: translateY(-2px);\n            box-shadow: 0 4px 12px rgba(255, 79, 79, 0.3);\n        }\n\n        #tabs .para-a:hover::before {\n            left: 100%;\n        }\n\n        #tabs .tag {\n            position: relative;\n            width: 100%;\n        }\n\n        #tabs .icon {\n            position: relative;\n            display: inline-block;\n            width: 40px;\n            height: 40px;\n            background: linear-gradient(135deg, rgba(255, 79, 79, 0.15) 0%, rgba(24, 241, 225, 0.15) 100%);\n            border-radius: 100%;\n            vertical-align: middle;\n            border: 2px solid rgba(255, 79, 79, 0.2);\n            transition: all 0.3s ease;\n            box-shadow: 0 2px 8px rgba(255, 79, 79, 0.1);\n        }\n\n        #tabs ul li a.active .icon,\n        #tabs ul li a:hover .icon {\n            background: linear-gradient(135deg, rgba(255, 79, 79, 0.25) 0%, rgba(24, 241, 225, 0.25) 100%);\n            border-color: #FF4F4F;\n            box-shadow: 0 4px 12px rgba(255, 79, 79, 0.3);\n            transform: scale(1.05);\n        }\n\n        #tabs .block {\n            position: absolute;\n            width: 15px;\n            height: 15px;\n            vertical-align: middle;\n            border: solid 2px #FF4F4F;\n            border-radius: 4px;\n            top: 50%;\n            left: 50%;\n            -webkit-transform: translate(-50%, -50%);\n            -moz-transform: translate(-50%, -50%);\n            -o-transform: translate(-50%, -50%);\n            -ms-transform: translate(-50%, -50%);\n            transform: translate(-50%, -50%);\n            transition: all 0.3s ease;\n        }\n\n        #tabs ul li a.active .block,\n        #tabs ul li a:hover .block {\n            border-color: #FF4F4F;\n            box-shadow: 0 0 8px rgba(255, 79, 79, 0.5);\n        }\n\n        #tabs .circle {\n            position: absolute;\n            padding: 3px;\n            border: solid 2px #FF4F4F;\n            border-radius: 100%;\n            top: 50%;\n            left: 50%;\n            -webkit-transform: translate(-50%, -50%);\n            -moz-transform: translate(-50%, -50%);\n            -o-transform: translate(-50%, -50%);\n            -ms-transform: translate(-50%, -50%);\n            transform: translate(-50%, -50%);\n            transition: all 0.3s ease;\n        }\n\n        #tabs ul li a.active .circle,\n        #tabs ul li a:hover .circle {\n            border-color: #FF4F4F;\n            box-shadow: 0 0 6px rgba(255, 79, 79, 0.4);\n        }\n\n        #tabs .title {\n            display: inline-block;\n            text-transform: uppercase;\n            font-weight: 700;\n            padding: 0 10px;\n            vertical-align: middle;\n            color: #1F1F1F;\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 12px;\n            letter-spacing: 0.8px;\n            transition: all 0.3s ease;\n            line-height: 1.2;\n        }\n\n        #tabs ul li a.active .title {\n            color: #FF4F4F;\n            text-shadow: 0 0 10px rgba(255, 79, 79, 0.3);\n        }\n\n        #tabs ul li a:hover .title {\n            color: #FF4F4F;\n        }\n\n        #tabs .addon {\n            position: relative;\n            width: 85%;\n            top: -18px;\n            margin-left: 60px;\n            letter-spacing: 0.2px;\n            font-size: 12px;\n            line-height: 1.5;\n            color: #1F1F1F;\n            opacity: 0;\n            font-family: \'Azo Sans\', sans-serif;\n            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n            transform: translateY(-10px);\n            word-wrap: break-word;\n            overflow-wrap: break-word;\n            max-width: calc(100% - 60px);\n        }\n\n        #tabs .addon.fadein {\n            opacity: 1;\n            transform: translateY(0);\n        }\n\n        #tabs .addon span {\n            display: block;\n            margin-bottom: 6px;\n            color: #1F1F1F;\n            font-weight: 400;\n        }\n\n        /* Button Styles */\n        #tabs .btn-wrapper {\n            --width: 100%;\n            --height: 45px;\n            --padding: 5px;\n            --border-radius: 18px;\n            --dot-size: 5px;\n            --btn-color: #e4e4e4;\n            --hue: 220deg;\n            --animation-duration: 1.2s;\n\n            position: relative;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            width: var(--width);\n            max-width: 100%;\n            height: var(--height);\n            border-radius: var(--border-radius);\n            border: none;\n            margin-top: 10px;\n\n            background-color: #00000008;\n\n            box-shadow:\n                1px 1px 2px 0 #fffd,\n                2px 2px 2px #0001 inset,\n                2px 2px 4px #0001 inset,\n                2px 2px 8px #0001 inset;\n\n            transition: box-shadow 50ms linear;\n\n            perspective: 150px;\n            perspective-origin: center;\n\n            user-select: none;\n            z-index: 1;\n        }\n\n        #tabs .btn {\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            gap: 0.5em;\n            text-align: center;\n            padding: 0 calc(var(--height) / 2) 0 calc(var(--padding) * 2);\n\n            width: calc(100% - 2 * var(--padding));\n            height: calc(100% - 2 * var(--padding));\n            border-radius: calc(var(--border-radius) - var(--padding));\n            border: none;\n            cursor: pointer;\n\n            background: linear-gradient(#fff2, #0001), var(--btn-color);\n\n            box-shadow:\n                1px 1px 2px -1px #fff inset,\n                0 2px 1px #00000010,\n                0 4px 2px #00000010,\n                0 8px 4px #00000010,\n                0 16px 8px #00000010,\n                0 32px 16px #00000010;\n\n            transition:\n                transform 0.25s cubic-bezier(0.25, 1.5, 0.5, 2.2),\n                box-shadow 0.25s cubic-bezier(0.25, 1.5, 0.5, 1),\n                filter 0.3s cubic-bezier(0.25, 1.5, 0.5, 1);\n            will-change: transform, filter;\n\n            z-index: 2;\n        }\n\n        /* Ensure anchor tags with .btn class work properly */\n        #tabs .btn[href] {\n            text-decoration: none;\n            color: inherit;\n            position: relative;\n            z-index: 2;\n        }\n\n        #tabs .btn[href]:hover,\n        #tabs .btn[href]:focus {\n            text-decoration: none;\n        }\n\n        #tabs .btn-txt {\n            display: inline-block;\n            white-space: nowrap;\n\n            font-size: 12px;\n            font-weight: 600;\n            font-family: \'Azo Sans Uber\', sans-serif;\n            text-transform: uppercase;\n            letter-spacing: 0.6px;\n\n            color: #5550;\n            background-image: linear-gradient(#000a, #555);\n            background-clip: text;\n            filter: drop-shadow(0 1px 0px #fff) drop-shadow(0 -1px 0px #0005);\n        }\n\n        #tabs .dot {\n            position: absolute;\n            top: calc(50% - var(--dot-size) / 2);\n            right: calc(var(--height) / 2);\n            width: var(--dot-size);\n            aspect-ratio: 1 / 1;\n            borde