         font-family: \'Playfair Display\', serif;\n        }\n\n        .btn-primary {\n            background: linear-gradient(135deg, #0050ff 0%, #0040d9 100%);\n            transition: all 0.3s ease;\n        }\n\n        .btn-primary:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(0, 80, 255, 0.4);\n        }\n\n        .section-padding {\n            padding: 5rem 0;\n        }\n\n        @media (min-width: 768px) {\n            .section-padding {\n                padding: 8rem 0;\n            }\n        }\n\n        @keyframes gradient-shift {\n\n            0%,\n            100% {\n                background-position: 0% 50%;\n            }\n\n            50% {\n                background-position: 100% 50%;\n            }\n        }\n\n        .animated-gradient-mountain {\n            background: linear-gradient(-45deg, #1e40af, #3b82f6, #60a5fa, #2563eb);\n            background-size: 400% 400%;\n            animation: gradient-shift 15s ease infinite;\n        }\n\n        @keyframes float {\n\n            0%,\n            100% {\n                transform: translateY(0px);\n            }\n\n            50% {\n                transform: translateY(-20px);\n            }\n        }\n\n        .animate-float {\n            animation: float 6s ease-in-out infinite;\n        }\n\n        @keyframes blob {\n\n            0%,\n            100% {\n                transform: translate(0px, 0px) scale(1);\n            }\n\n            33% {\n                transform: translate(30px, -50px) scale(1.1);\n            }\n\n            66% {\n                transform: translate(-20px, 20px) scale(0.9);\n            }\n        }\n\n        .animate-blob {\n            animation: blob 7s infinite;\n        }\n\n        .animation-delay-2000 {\n            animation-delay: 2s;\n        }\n\n        .animation-delay-4000 {\n            animation-delay: 4s;\n        }\n\n        .feature-icon {\n            width: 64px;\n            height: 64px;\n            background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);\n            border-radius: 16px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            margin-bottom: 1.5rem;\n        }\n\n        .glass {\n            background: rgba(255, 255, 255, 0.1);\n            backdrop-filter: blur(10px);\n            border: 1px solid rgba(255, 255, 255, 0.2);\n        }\n\n        .carousel-container {\n            position: relative;\n            width: 100%;\n            height: 100%;\n        }\n\n        .carousel-slide {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            opacity: 0;\n            transition: opacity 1s ease-in-out;\n        }\n\n        .carousel-slide.active {\n            opacity: 1;\n        }\n\n        .carousel-slide img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n        }\n\n        /* Screen reader only - for SEO purposes */\n        .sr-only {\n            position: absolute;\n            width: 1px;\n            height: 1px;\n            padding: 0;\n            margin: -1px;\n            overflow: hidden;\n            clip: rect(0, 0, 0, 0);\n            white-space: nowrap;\n            border-width: 0;\n        }\n    </style>\n\n    <!-- Structured Data - Service -->\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"Service\",\n      \"serviceType\": \"Photo Booth Set Rental\",\n      \"name\": \"Ski Lift Photo Booth Set Rental\",\n      \"description\": \"Professional ski lift photo booth set rentals featuring authentic retired ski lifts from Colorado\'s premier ski destinations. Mountain-themed photo booths perfect for weddings, parties, and corporate events.\",\n      \"provider\": {\n        \"@type\": \"LocalBusiness\",\n        \"@id\": \"https: