sform: uppercase;\n        }\n\n        .brochure-section::before {\n            content: \"\";\n            position: absolute;\n            inset: 0;\n            background-image:\n                radial-gradient(circle at 20% 50%, rgba(0, 80, 255, 0.18) 0%, transparent 45%),\n                radial-gradient(circle at 80% 50%, rgba(0, 80, 255, 0.15) 0%, transparent 45%);\n            pointer-events: none;\n        }\n\n        #brochure-webgl-canvas {\n            position: absolute;\n            inset: 0;\n            width: 100%;\n            height: 100%;\n            overflow: hidden;\n            z-index: 0;\n        }\n\n        .brochure-badge {\n            background: #1F1F1F;\n            color: #ffffff;\n            padding: 0.4rem 1.25rem;\n            border-radius: 50px;\n            font-size: 0.8rem;\n            font-weight: 400;\n            letter-spacing: 0.05em;\n            text-transform: uppercase;\n            display: inline-block;\n            box-shadow: 0 4px 18px rgba(31, 31, 31, 0.35);\n            font-family: \'Azo Sans Uber\', sans-serif;\n        }\n\n        .brochure-preview {\n            position: relative;\n            background: #0a0f1f;\n            border-radius: 1.5rem;\n            box-shadow: 0 25px 55px -15px rgba(5, 10, 25, 0.85);\n            overflow: hidden;\n            transition: transform 0.45s ease, box-shadow 0.45s ease;\n            border: 2px solid rgba(0, 80, 255, 0.35);\n        }\n\n        .brochure-preview:hover {\n            transform: translateY(-6px);\n            box-shadow: 0 35px 60px -20px rgba(0, 80, 255, 0.5);\n            border-color: rgba(0, 80, 255, 0.6);\n        }\n\n        .brochure-preview::before {\n            content: \"\";\n            position: absolute;\n            inset: 0;\n            background: repeating-linear-gradient(45deg, transparent, transparent 2px, rgba(0, 80, 255, 0.05) 2px, rgba(0, 80, 255, 0.05) 4px);\n            opacity: 0.4;\n            pointer-events: 