 1 !important;\n            visibility: visible !important;\n        }\n\n        /* Reset animation state when display class is removed */\n        .claw-game-container .toy:not(.display) {\n            animation: none !important;\n        }\n\n        .claw-game-container .toy {\n            position: absolute;\n            transition: transform 1s, left 0.3s, top 0.3s;\n            --m: 2;\n            --w: 20px;\n            --h: 27px;\n            transform: rotate(var(--rotate-angle));\n            pointer-events: none;\n        }\n\n        .claw-game-container .toy::after {\n            content: \'\';\n        }\n\n        .claw-game-container .toy.bear::after {\n            --w: 24px;\n            --h: 30px;\n            top: calc(var(--m) * -2px);\n            left: calc(var(--m) * -2px);\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy.bear.grabbed::after {\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy-wrapper .toy.bear::after {\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy.bunny {\n            --w: 20px;\n            --h: 29px;\n        }\n\n        .claw-game-container .toy.bunny::after {\n            --w: 24px;\n            --h: 32px;\n            top: calc(var(--m) * -2px);\n            left: calc(var(--m) * -2px);\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy.bunny.grabbed::after {\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy-wrapper .toy.bunny::after {\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy.golem::after {\n            --w: 26px;\n            --h: 30px;\n            top: calc(var(--m) * -1px);\n            left: calc(var(--m) * -3px);\n            background-image: url(data:image/