(var(--m) * -1px);\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy.penguin.grabbed::after {\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy-wrapper .toy.penguin::after {\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy.robot {\n            --w: 20px;\n            --h: 30px;\n        }\n\n        .claw-game-container .toy.robot::after {\n            --w: 24px;\n            --h: 32px;\n            top: calc(var(--m) * -1px);\n            left: calc(var(--m) * -2px);\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy.robot.grabbed::after {\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy-wrapper .toy.robot::after {\n            background-image: url(data:image/png;base64,);\n        }\n\n        .claw-game-container .toy.selected {\n            pointer-events: all;\n        }\n\n        @keyframes show-toy-1 {\n            0% {\n                opacity: 1;\n                transform: scale(3) translateY(0);\n            }\n\n            50% {\n                opacity: 1;\n                transform: scale(2.5) translateY(-20px);\n            }\n\n            70% {\n                opacity: 0.8;\n                transform: scale(2) translateY(-40px);\n            }\n\n            100% {\n                opacity: 0;\n                transform: scale(1) translateY(-100vh);\n            }\n        }\n\n        .claw-game-container .control .collection-point {\n            filter: brightness(0.8);\n            bottom: calc(var(--m) * 8px);\n        }\n\n        /* Accordion Dropdown Menu Styles */\n        .accordion-wrapper {\n            max-width: 1000px;\n            margin: 0 auto;\n            width: 100%;\n        }\n\n        .accordion-wrapper h1 {\n            color: #1a202c;\n            font-size: 28px;\n            font-weight: 600;\n            text-align: center;\n            margin-bottom: 15px;\n        }\n\n        .accordion-wrapper h1 a {\n            color: #c12c42;\n            font-size: 16px;\n        }\n\n        .accordion-wrapper h2.animated-gradient-text {\n            font-family: \'Press Start 2P\', cursive !important;\n            white-space: nowrap;\n            display: inline-block;\n        }\n\n        .accordion-wrapper p {\n            color: #4a5568;\n            text-align: center;\n            margin-bottom: 30px;\n        }\n\n        .accordion {\n            width: 100%;\n            max-width: 100%;\n            margin: 0 auto;\n            background: #FFFFFF;\n            border-radius: 16px;\n            list-style-type: none;\n            box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);\n            border: 1px solid rgba(226, 232, 240, 0.8);\n            overflow: hidden;\n        }\n\n        .accordion .link {\n            cursor: pointer;\n            display: flex;\n            align-items: center;\n            justify-content: space-between;\n            padding: 20px 24px;\n            color: #1a202c;\n            font-size: 16px;\n            font-weight: 700;\n            border-bottom: 1px solid rgba(226, 232, 240, 0.6);\n            position: relative;\n            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n            background: #FFFFFF;\n            min-height: 44px;\n            touch-action: manipulation;\n        }\n\n        .accordion .link::after {\n            content: \'+\';\n            font-size: 24px;\n            font-weight: 300;\n            color: #667eea;\n            transition: transform 0.3s ease;\n            flex-shrink: 0;\n            margin-left: 16px;\n        }\n\n        .accordion li.open .link::after {\n            transform: rotate(45deg);\n            color: #764ba2;\n        }\n\n        .accordion li:last-child .link {\n            border-bottom: 0;\n        }\n\n        .accordion li.open .link {\n            color: #667eea;\n            background: linear-gradient(135deg, rgba(102, 126, 234, 0.05) 0%, rgba(118, 75, 162, 0.05) 100%);\n            border-bottom-color: rgba(102, 126, 234, 0.2);\n        }\n\n        .accordion .link:hover {\n            background: linear-gradient(135deg, rgba(102, 126, 234, 0.03) 0%, rgba(118, 75, 162, 0.03) 100%);\n            color: #667eea;\n            padding-left: 28px;\n        }\n\n        .submenu {\n            display: none;\n            background: linear-gradient(135deg, rgba(247, 250, 252, 0.8) 0%, rgba(255, 255, 255, 0.9) 100%);\n            font-size: 15px;\n            list-style-type: none;\n            padding: 0;\n            border-top: 1px solid rgba(226, 232, 240, 0.6);\n        }\n\n        .submenu li {\n            border-bottom: 1px solid rgba(226, 232, 240, 0.4);\n        }\n\n        .submenu li:last-child {\n            border-bottom: 0;\n        }\n\n        .submenu p {\n            color: #4a5568;\n            padding: 20px 24px;\n            margin: 0;\n            line-height: 1.7;\n            font-size: 15px;\n        }\n\n        .submenu p[style*=\"color: #000000\"],\n        .submenu p[style*=\"color: black\"],\n        .submenu li:first-child p {\n            color: #000000 !important;\n            font-weight: 500 !important;\n        }\n\n        /* Force black text for the space question */\n        .accordion li:first-child .submenu p {\n            color: #000000 !important;\n            opacity: 1 !important;\n            visibility: visible !important;\n        }\n\n        .submenu a {\n            display: block;\n            text-decoration: none;\n            color: #2d3748;\n            padding: 12px 24px;\n            transition: all 0.25s ease;\n        }\n\n        .submenu a:hover {\n            background: rgba(102, 126, 234, 0.05);\n            color: #667eea;\n            padding-left: 28px;\n        }\n    </style>\n</head>\n\n<body>\n    <div id=\"nav-placeholder\"></div>\n\n    <section class=\"relative h-screen md:h-screen flex items-center justify-center overflow-hidden hero-section\">\n        <div class=\"absolute inset-0 bg-cover bg-center\"\n            style=\"background-image: url(\'../assets/images/clawmachine/hero.jpg\'); background-position: center center;\">\n        </div>\n        <div class=\"absolute inset-0 hero-gradient\"></div>\n        <div class=\"relative z-10 text-center text-white px-4 md:px-6 py-8 md:py-12\">\n            <div class=\"max-w-6xl mx-auto\">\n                <!-- Gaming Badge -->\n                <div class=\"mb-4 md:mb-6\">\n                    <span class=\"hero-badge\">🎮 ARCADE CLASSIC</span>\n                </div>\n\n                <!-- Animated Keyboard Title -->\n                <div class=\"keyboard mb-6 md:mb-8\">\n                    <span class=\"key\">C</span>\n                    <span class=\"key\">L</span>\n                    <span class=\"key\">A</span>\n                    <span class=\"key\">W</span>\n                    <span class=\"key\">&nbsp;</span>\n                    <span class=\"key\">M</span>\n                    <span class=\"key\">A</span>\n                    <span class=\"key\">C</span>\n                    <span class=\"key\">H</span>\n                    <span class=\"key\">I</span>\n                    <span class=\"key\">N</span>\n                    <span class=\"key\">E</span>\n                </div>\n\n                <!-- Hero Title -->\n                <h3 class=\"text-2xl md:text-3xl lg:text-4xl xl:text-5xl mb-4 md:mb-6 px-2\">Nationwide Rentals</h3>\n\n                <!-- Hero Description -->\n                <p\n                    class=\"text-base md:text-lg lg:text-xl xl:text-2xl mb-8 md:mb-10 max-w-4xl mx-auto px-2 leading-relaxed\">\n                    A classic arcade favorite, our claw machine brings nonstop fun and excitement to any event.\n                    Experience the thrill of the grab!\n                </p>\n\n                <!-- CTA Buttons -->\n                <div class=\"mt-8 md:mt-10 flex flex-col sm:flex-row gap-4 md:gap-6 items-center justify-center\">\n                    <a href=\"../contact-us.html\" class=\"hero-btn-primary\">\n                        <i class=\"fas fa-tag mr-2\"></i>\n                        <span>Get Your Quote</span>\n                    </a>\n                    <button type=\"button\" data-click-to-call data-call-text=\"Contact Us\"\n                        class=\"hero-btn-secondary cursor-pointer\">\n                        <i class=\"fas fa-phone mr-2\"></i>\n                        <span>Contact Us</span>\n                    </button>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Content 1 -->\n    <section class=\"py-6 md:py-8 gradient-grainy-bg content-section-height\">\n        <div class=\"container mx-auto px-4 md:px-6\">\n            <div class=\"grid md:grid-cols-2 gap-4 md:gap-6\">\n                <div class=\"card-container order-2 md:order-1\">\n                    <div class=\"card\">\n                        <a href=\"../contact-us.html\" class=\"card__button\">Learn more</a>\n                    </div>\n                </div>\n                <div class=\"flex flex-col justify-center items-start order-1 md:order-2\">\n                    <div class=\"game-content-card w-full\">\n                        <h3 class=\"game-content-title\">Level Up Your Event</h3>\n                        <p class=\"game-content-text\">\n                            Looking for a way to make your event unforgettable while keeping guests entertained? Our\n                            claw machine rentals are the perfect solution. Whether it\'s a lively party, a corporate\n                            gathering, or a branded activation, these interactive games get everyone involved, cheering,\n                            and reaching for prizes.\n                        </p>\n                        <p class=\"game-content-text\">\n                            With vibrant lights, fun sounds, and a mix of custom-branded goodies inside, the claw\n                            machines bring excitement and energy to any event space. They encourage friendly\n                            competition, spark laughter, and add a nostalgic touch that guests of all ages will love.\n                            Plus, our rentals are simple to set up, so you can focus on enjoying the experience and\n                            watching your guests have a blast. Turn your next event into a playful, engaging experience\n                            that people will remember long after the last prize is claimed.\n                        </p>\n                        <a href=\"../contact-us.html\" class=\"game-btn\">Get A Quote</a>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Content 2 -->\n    <section class=\"py-6 md:py-8 bg-white content-section-height\"\n        style=\"position: relative; overflow-x: hidden; overflow-y: visible; background: #3399ff; max-width: 100vw;\">\n        <div class=\"ripple-background\">\n            <div class=\"circle xxlarge shade1\"></div>\n            <div class=\"circle xlarge shade2\"></div>\n            <div class=\"circle large shade3\"></div>\n            <div class=\"circle medium shade4\"></div>\n            <div class=\"circle small shade5\"></div>\n        </div>\n        <div class=\"container mx-auto px-4 md:px-6\"\n            style=\"position: relative; z-index: 1; max-width: 100%; overflow-x: hidden;\">\n            <div class=\"flex flex-col items-center text-center mb-6 md:mb-8 px-2\">\n                <span class=\"game-badge mb-3 md:mb-4\">Arcade Classic</span>\n                <h2 class=\"text-xl md:text-2xl lg:text-3xl xl:text-4xl 2xl:text-5xl font-bold mb-4 md:mb-6 animated-gradient-text px-2\"\n                    style=\"font-family: \'Press Start 2P\', cursive !important; line-height: 1.4;\">What is a Claw Machine?\n                </h2>\n                <p class=\"game-text mb-4 md:mb-5\">\n                    A claw machine is a classic arcade game that\'s all about skill, luck, and excitement. Guests use a\n                    joystick to control a mechanical claw, trying to grab a prize from inside the machine and drop it\n                    into the winning slot. It\'s a fun, interactive experience that keeps people coming back for more\n                    while creating a lively and playful atmosphere at any event.\n                </p>\n                <p class=\"game-text\">\n                    Using our claw machines is simple and stress-free. We handle the setup, so all you need to do is\n                    stock it with your chosen prizes and let your guests take turns testing their luck and skill.\n                    Whether you\'re encouraging friendly competition, rewarding attendees, or adding a nostalgic touch to\n                    your event, our claw machine rentals are guaranteed to bring excitement and engagement to any\n                    occasion.\n                </p>\n            </div>\n            <div class=\"flex items-center justify-center\">\n                <div class=\"card-container-right card-container-optimized\">\n                    <div class=\"feature-card\">\n                        <div class=\"card-icon\">\n                            <img src=\"../assets/images/clawmachine/icon1.png\" alt=\"Icon 1\">\n                        </div>\n                        <div class=\"card-content\">\n                            <button class=\"card-button\">Delivery</button>\n                            <p>We\'ll bring the claw machine straight to your venue, right on time and ready for the fun.\n                            </p>\n                        </div>\n                    </div>\n                    <div class=\"feature-card\">\n                        <div class=\"card-icon\">\n                            <img src=\"../assets/images/clawmachine/icon2.png\" alt=\"Icon 2\">\n                        </div>\n                        <div class=\"card-content\">\n                            <button class=\"card-button\">Setup</button>\n                            <p>Our crew will handle the setup process, so your guests can jump in and start playing\n                                right away.</p>\n                        </div>\n                    </div>\n                    <div class=\"feature-card\">\n                        <div class=\"card-icon\">\n                            <img src=\"../assets/images/clawmachine/icon3.png\" alt=\"Icon 3\">\n                        </div>\n                        <div class=\"card-content\">\n                            <button class=\"card-button\">Breakdown</button>\n                            <p>Once the event is over, we\'ll safely pack everything up for removal.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Ready to Book Section -->\n    <section\n        class=\"relative py-8 md:py-12 lg:py-16 flex items-center justify-center overflow-hidden min-h-[50vh] md:min-h-[60vh]\">\n        <div class=\"absolute inset-0 bg-cover bg-center\"\n            style=\"background-image: url(\'../assets/images/clawmachine/pic2.jpg\');\"></div>\n        <div class=\"absolute inset-0 hero-gradient\"></div>\n        <div class=\"relative z-10 text-center text-white px-4 md:px-6 max-w-4xl mx-auto py-4\">\n            <h2 class=\"text-xl md:text-2xl lg:text-4xl font-bold mb-3 md:mb-5\">Ready to Book?</h2>\n            <p class=\"text-sm md:text-base lg:text-lg mb-5 md:mb-7 px-2\">\n                Book your claw machine rental and add a dose of excitement to your next event! Our team is ready to\n                assist you in creating a memorable experience for your guests.\n            </p>\n            <a href=\"../contact-us.html\" class=\"animated-gradient-btn\"><span>Get A Quote</span></a>\n        </div>\n    </section>\n\n    <!-- Benefits Section and Game -->\n    <section class=\"py-16 md:py-20 lg:py-24 bg-white content-section-height\"\n        style=\"position: relative; overflow: hidden; background: #3399ff;\">\n        <div class=\"ripple-background ripple-background-mirrored\">\n            <div class=\"circle xxlarge shade1\"></div>\n            <div class=\"circle xlarge shade2\"></div>\n            <div class=\"circle large shade3\"></div>\n            <div class=\"circle medium shade4\"></div>\n            <div class=\"circle small shade5\"></div>\n        </div>\n        <div class=\"container mx-auto px-4 md:px-6 lg:px-8\" style=\"position: relative; z-index: 1; max-width: 1400px;\">\n            <!-- Section Header -->\n            <div class=\"flex flex-col items-center text-center mb-12 md:mb-16 lg:mb-20\">\n                <span class=\"game-badge mb-4\">EVENT BENEFITS</span>\n                <h2 class=\"text-3xl md:text-4xl lg:text-5xl font-bold mb-4 md:mb-6 animated-gradient-text\"\n                    style=\"font-family: \'Press Start 2P\', cursive !important;\">Benefits of Having the Claw Machine at\n                    your Event</h2>\n            </div>\n\n            <div class=\"grid lg:grid-cols-2 gap-6 md:gap-8 lg:gap-12 xl:gap-16 items-start\">\n                <!-- Play Mini Game - Left Side -->\n                <div class=\"flex flex-col justify-center items-center order-1 lg:order-2 px-2 md:px-4 lg:px-6\">\n                    <h2 class=\"text-lg md:text-xl lg:text-2xl font-bold mb-6 md:mb-8 lg:mb-10 text-center text-white drop-shadow-lg\"\n                        style=\"font-family: \'Orbitron\', sans-serif; letter-spacing: 0.05em;\">Play Mini Game</h2>\n                    <!-- Game Code Preserved -->\n                    <div class=\"game-wrapper claw-game-container w-full max-w-lg lg:max-w-xl mx-auto\"\n                        style=\"box-sizing: border-box; padding: 1rem;\">\n                        <div class=\"wrapper\"\n                            style=\"width: 100%; max-width: 100%; box-sizing: border-box; padding-left: 0; margin-left: 0;\">\n                            <div class=\"collection-box pix\"></div>\n                            <div class=\"claw-machine\">\n                                <div class=\"box pix\">\n                                    <div class=\"machine-top pix\">\n                                        <div class=\"arm-joint pix\">\n                                            <div class=\"arm pix\">\n                                                <div class=\"claws pix\"></div>\n                                            </div>\n                                        </div>\n                                        <div class=\"rail vert pix\"></div>\n                                        <div class=\"rail hori pix\"></div>\n                                    </div>\n                                    <div class=\"machine-bottom pix\">\n                                        <div class=\"collection-point pix\"></div>\n                                    </div>\n                                </div>\n                                <div class=\"control pix\">\n                                    <div class=\"cover left\"></div>\n                                    <button class=\"hori-btn pix\"></button>\n                                    <button class=\"vert-btn pix\"></button>\n                                    <div class=\"cover right\">\n                                        <div class=\"instruction pix\"></div>\n                                    </div>\n                                    <div class=\"cover bottom\"></div>\n                                    <div class=\"cover top\">\n                                        <div class=\"collection-arrow pix\"></div>\n                                    </div>\n                                    <div class=\"collection-point pix\"></div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Benefits Section - Right Side -->\n                <div class=\"flex flex-col items-center order-2 lg:order-1\">\n                    <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-2 gap-5 md:gap-6 lg:gap-8 w-full\">\n                        <!-- Benefit 1 -->\n                        <div class=\"benefit-card\">\n                            <span class=\"benefit-icon\">🥳</span>\n                            <h3 class=\"benefit-title\">Fun for Everyone</h3>\n                            <p class=\"benefit-desc\">Guests of all ages can join in, from kids testing their skills to\n                                adults reliving their arcade glory days.</p>\n                        </div>\n                        <!-- Benefit 2 -->\n                        <div class=\"benefit-card\">\n                            <span class=\"benefit-icon\">🕹️</span>\n                            <h3 class=\"benefit-title\">Interactive Excitement</h3>\n                            <p class=\"benefit-desc\">The thrill of controlling the claw and aiming for a prize keeps\n                                everyone engaged and coming back for more.</p>\n                        </div>\n                        <!-- Benefit 3 -->\n                        <div class=\"benefit-card\">\n                            <span class=\"benefit-icon\">✨</span>\n                            <h3 class=\"benefit-title\">Memorable Experience</h3>\n                            <p class=\"benefit-desc\">Nostalgia meets modern fun - your guests will be talking about their\n                                wins long after the event ends.</p>\n                        </div>\n                        <!-- Benefit 4 -->\n                        <div class=\"benefit-card\">\n                            <span class=\"benefit-icon\">🎨</span>\n                            <h3 class=\"benefit-title\">Customizable</h3>\n                            <p class=\"benefit-desc\">Wrap the machine in your company\'s colors or logo, and fill it with\n                                branded goodies for a unique activation.</p>\n                        </div>\n                        <!-- Benefit 5 -->\n                        <div class=\"benefit-card\">\n                            <span class=\"benefit-icon\">🚀</span>\n                            <h3 class=\"benefit-title\">Event-Ready Anywhere</h3>\n                            <p class=\"benefit-desc\">Compact, portable, and easy to set up in almost any indoor space.\n                                Perfect for parties and trade shows.</p>\n                        </div>\n                        <!-- Benefit 6 -->\n                        <div class=\"benefit-card\">\n                            <span class=\"benefit-icon\">🎁</span>\n                            <h3 class=\"benefit-title\">Endless Possibilities</h3>\n                            <p class=\"benefit-desc\">Fill it with merch, toys, gift cards, or surprises — the claw\n                                machine adapts to whatever vibe you have.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Content 3 -->\n    <section class=\"py-12 md:py-16 lg:py-20 gradient-grainy-bg content-section-height-compact\">\n        <div class=\"container mx-auto px-4 md:px-6 lg:px-8\" style=\"max-width: 1400px;\">\n            <!-- Section Header -->\n            <div class=\"flex flex-col items-center text-center mb-8 md:mb-10 lg:mb-12 xl:mb-16 px-2\">\n                <span class=\"game-badge mb-3 md:mb-4\">PERFECT EVENTS</span>\n                <h2 class=\"text-xl md:text-2xl lg:text-3xl xl:text-4xl 2xl:text-5xl font-bold mb-3 md:mb-4 lg:mb-6 animated-gradient-text px-2\"\n                    style=\"font-family: \'Press Start 2P\', cursive !important;\">Events Perfect For The Claw Machine</h2>\n                <p class=\"text-sm md:text-base lg:text-lg text-gray-700 max-w-2xl mx-auto leading-relaxed px-2\">\n                    Our claw machine rentals are a fantastic addition to a wide range of events, bringing excitement and\n                    engagement to any occasion.\n                </p>\n            </div>\n\n            <div class=\"grid md:grid-cols-2 gap-8 md:gap-12 lg:gap-16 items-center\">\n                <!-- Image/Content Card - Left Side -->\n                <div class=\"card-container order-2 md:order-1\">\n                    <div class=\"card2\">\n                        <a href=\"../contact-us.html\" class=\"card__button\">Learn more</a>\n                    </div>\n                </div>\n\n                <!-- Events List - Right Side -->\n                <div class=\"flex flex-col justify-center items-start order-1 md:order-2\">\n                    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4 md:gap-6 w-full\">\n                        <div class=\"event-type-card group\">\n                            <div class=\"event-type-icon\">🏢</div>\n                            <h3 class=\"event-type-title\">Corporate Events</h3>\n                            <p class=\"event-type-desc\">Trade shows, team-building activities, office parties, and\n                                corporate celebrations.</p>\n                        </div>\n\n                        <div class=\"event-type-card group\">\n                            <div class=\"event-type-icon\">🎉</div>\n                            <h3 class=\"event-type-title\">Private Parties</h3>\n                            <p class=\"event-type-desc\">Birthday parties, anniversaries, graduations, and milestone\n                                celebrations.</p>\n                        </div>\n\n                        <div class=\"event-type-card group\">\n                            <div class=\"event-type-icon\">✨</div>\n                            <h3 class=\"event-type-title\">Special Occasions</h3>\n                            <p class=\"event-type-desc\">Holiday parties, festivals, grand openings, and themed events.\n                            </p>\n                        </div>\n\n                        <div class=\"event-type-card group\">\n                            <div class=\"event-type-icon\">👨‍👩‍👧‍👦</div>\n                            <h3 class=\"event-type-title\">Family-Friendly Events</h3>\n                            <p class=\"event-type-desc\">Community gatherings, school events, fundraisers, and family\n                                reunions.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Dropdown Section -->\n    <section class=\"py-12 md:py-16 lg:py-20\"\n        style=\"position: relative; overflow-x: hidden; overflow-y: visible; background: #3399ff; max-width: 100vw;\">\n        <div class=\"ripple-background\">\n            <div class=\"circle xxlarge shade1\"></div>\n            <div class=\"circle xlarge shade2\"></div>\n            <div class=\"circle large shade3\"></div>\n            <div class=\"circle medium shade4\"></div>\n            <div class=\"circle small shade5\"></div>\n        </div>\n        <div class=\"container mx-auto px-4 md:px-6 lg:px-8\" style=\"max-width: 1000px; position: relative; z-index: 1;\">\n            <div class=\"accordion-wrapper\">\n                <div class=\"text-center mb-6 md:mb-8 lg:mb-12 px-2\">\n                    <span\n                        class=\"inline-block px-3 py-1.5 md:px-4 md:py-2 bg-gradient-to-r from-blue-500 to-purple-600 text-white text-xs md:text-sm font-bold rounded-full mb-3 md:mb-4 uppercase tracking-wider\">\n                        Got Questions?\n                    </span>\n                    <h2\n                        class=\"text-2xl md:text-3xl lg:text-4xl xl:text-5xl font-bold mb-3 md:mb-4 lg:mb-6 animated-gradient-text px-2\">\n                        Frequently Asked Questions\n                    </h2>\n                    <p class=\"text-sm md:text-base lg:text-lg text-gray-700 max-w-2xl mx-auto leading-relaxed px-2\">\n                        Have questions about our Claw Machine Rentals? We\'re happy to answer them!\n                    </p>\n                </div>\n                <ul id=\"accordion\" class=\"accordion\">\n                    <li>\n                        <div class=\"link\">How much space does the claw machine need?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p style=\"color: #000000 !important; background-color: transparent !important;\">Our claw\n                                    machines are compact and fit comfortably in most event spaces. We recommend a space\n                                    of about 4x4 feet for easy access and gameplay.</p>\n                            </li>\n                        </ul>\n                    </li>\n                    <li>\n                        <div class=\"link\">Can the claw machine be branded?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>Yes! We can wrap the machine with your logo, colors, or custom design, making it a\n                                    perfect fit for brand activations and corporate events.</p>\n                            </li>\n                        </ul>\n                    </li>\n                    <li>\n                        <div class=\"link\">What types of prizes can go inside?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>You can fill the machine with small items like keychains, sunglasses, toys, gift\n                                    cards, or branded giveaways. We’ll help you choose prizes that fit your event theme.\n                                </p>\n                            </li>\n                        </ul>\n                    </li>\n                    <li>\n                        <div class=\"link\">Do you provide the prizes?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>Prizes can be supplied by you, or we can help source items based on your budget and\n                                    event needs.</p>\n                            </li>\n                        </ul>\n                    </li>\n                    <li>\n                        <div class=\"link\">How do guests use the claw machine?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>It’s simple! Guests use the joystick to move the claw, then press the button to try\n                                    and grab a prize. The challenge keeps them coming back for more.</p>\n                            </li>\n                        </ul>\n                    </li>\n                    <li>\n                        <div class=\"link\">Is setup and delivery included?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>Yes, our team handles delivery, setup, and removal, so all you need to do is enjoy\n                                    the fun with your guests.</p>\n                            </li>\n                        </ul>\n                    </li>\n                </ul>\n            </div>\n        </div>\n    </section>\n\n    <!-- Content 4 -->\n    <section class=\"py-12 md:py-16 lg:py-20 gradient-grainy-bg content-section-height-compact\">\n        <div class=\"container mx-auto px-4 md:px-6 lg:px-8\" style=\"max-width: 1400px;\">\n            <!-- Centered Header -->\n            <div class=\"text-center mb-8 md:mb-10 lg:mb-12 xl:mb-16 px-2\">\n                <span\n                    class=\"inline-block px-3 py-1.5 md:px-4 md:py-2 bg-gradient-to-r from-purple-500 to-pink-500 text-white text-xs md:text-sm font-bold rounded-full mb-3 md:mb-4 uppercase tracking-wider\">\n                    Simple Booking Process\n                </span>\n                <h2 class=\"text-xl md:text-2xl lg:text-3xl xl:text-4xl 2xl:text-5xl font-bold mb-3 md:mb-4 lg:mb-6 animated-gradient-text px-2\"\n                    style=\"font-family: \'Press Start 2P\', cursive !important; letter-spacing: 0.02em; word-spacing: 0.05em; line-height: 1.3;\">\n                    How To Book Your Next Claw Machine Rental\n                </h2>\n                <p class=\"text-xs md:text-sm lg:text-base text-gray-700 leading-relaxed max-w-3xl mx-auto px-2\">\n                    Booking your claw machine rental is easy! Follow these simple steps to get started.\n                </p>\n            </div>\n\n            <div class=\"grid md:grid-cols-2 gap-8 md:gap-10 lg:gap-12 items-center\">\n                <div class=\"flex flex-col justify-center items-start order-2 md:order-1\">\n                    <div class=\"space-y-4 md:space-y-5 lg:space-y-6 w-full\">\n                        <div\n                            class=\"booking-step flex items-start gap-4 p-4 md:p-5 bg-white/80 backdrop-blur-sm rounded-xl shadow-md hover:shadow-lg transition-all duration-300 hover:-translate-y-1\">\n                            <div\n                                class=\"flex-shrink-0 w-12 h-12 md:w-14 md:h-14 bg-gradient-to-br from-blue-500 to-purple-600 rounded-full flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg\">\n                                1\n                            </div>\n                            <div class=\"flex-1\">\n                                <h3 class=\"text-sm md:text-base lg:text-lg font-bold text-gray-900 mb-1 md:mb-2\">Share\n                                    Your Event Details</h3>\n                                <p class=\"text-xs md:text-sm lg:text-base text-gray-700 leading-relaxed\">Location, date,\n                                    time, and the games you\'re interested in.</p>\n                            </div>\n                        </div>\n                        <div\n                            class=\"booking-step flex items-start gap-4 p-4 md:p-5 bg-white/80 backdrop-blur-sm rounded-xl shadow-md hover:shadow-lg transition-all duration-300 hover:-translate-y-1\">\n                            <div\n                                class=\"flex-shrink-0 w-12 h-12 md:w-14 md:h-14 bg-gradient-to-br from-purple-500 to-pink-600 rounded-full flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg\">\n                                2\n                            </div>\n                            <div class=\"flex-1\">\n                                <h3 class=\"text-sm md:text-base lg:text-lg font-bold text-gray-900 mb-1 md:mb-2\">We\'ll\n                                    Reach Out</h3>\n                                <p class=\"text-xs md:text-sm lg:text-base text-gray-700 leading-relaxed\">Our sales team\n                                    will contact you to discuss your needs and answer any questions.</p>\n                            </div>\n                        </div>\n                        <div\n                            class=\"booking-step flex items-start gap-4 p-4 md:p-5 bg-white/80 backdrop-blur-sm rounded-xl shadow-md hover:shadow-lg transition-all duration-300 hover:-translate-y-1\">\n                            <div\n                                class=\"flex-shrink-0 w-12 h-12 md:w-14 md:h-14 bg-gradient-to-br from-pink-500 to-red-600 rounded-full flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg\">\n                                3\n                            </div>\n                            <div class=\"flex-1\">\n                                <h3 class=\"text-sm md:text-base lg:text-lg font-bold text-gray-900 mb-1 md:mb-2\">Receive\n                                    Your Quote</h3>\n                                <p class=\"text-xs md:text-sm lg:text-base text-gray-700 leading-relaxed\">We\'ll send over\n                                    a personalized quote tailored to your event.</p>\n                            </div>\n                        </div>\n                        <div\n                            class=\"booking-step flex items-start gap-4 p-4 md:p-5 bg-white/80 backdrop-blur-sm rounded-xl shadow-md hover:shadow-lg transition-all duration-300 hover:-translate-y-1\">\n                            <div\n                                class=\"flex-shrink-0 w-12 h-12 md:w-14 md:h-14 bg-gradient-to-br from-green-500 to-teal-600 rounded-full flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg\">\n                                4\n                            </div>\n                            <div class=\"flex-1\">\n                                <h3 class=\"text-sm md:text-base lg:text-lg font-bold text-gray-900 mb-1 md:mb-2\">Confirm\n                                    & Deposit</h3>\n                                <p class=\"text-xs md:text-sm lg:text-base text-gray-700 leading-relaxed\">Sign the\n                                    service agreement and provide a 50% deposit to secure your rental.</p>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <div class=\"card-container order-1 md:order-2\">\n                    <div class=\"card3\">\n                        <a href=\"#contact\" class=\"card__button\">Get Started</a>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <script src=\"https://code.jquery.com/jquery-3.6.0.min.js\"></script>\n    <script src=\"../assets/components/navigation.js\"></script>\n    <script src=\"../assets/components/footer.js\"></script>\n    <script>\n        // Accordion Dropdown Menu JavaScript\n        $(function () {\n            var Accordion = function (el, multiple) {\n                this.el = el || {};\n                this.multiple = multiple || false;\n\n                // Variables privadas\n                var links = this.el.find(\'.link\');\n                // Evento\n                links.on(\'click\', { el: this.el, multiple: this.multiple }, this.dropdown)\n            }\n\n            Accordion.prototype.dropdown = function (e) {\n                var $el = e.data.el;\n                $this = $(this),\n                    $next = $this.next();\n\n                $next.slideToggle();\n                $this.parent().toggleClass(\'open\');\n\n                if (!e.data.multiple) {\n                    $el.find(\'.submenu\').not($next).slideUp().parent().removeClass(\'open\');\n                };\n            }\n\n            var accordion = new Accordion($(\'#accordion\'), false);\n        });\n    </script>\n    <script>\n        // Claw Machine Mini Game JavaScript\n        (function () {\n            const gameContainer = document.querySelector(\'.claw-game-container\');\n            if (!gameContainer) return;\n\n            const elements = {\n                clawMachine: gameContainer.querySelector(\'.claw-machine\'),\n                box: gameContainer.querySelector(\'.box\'),\n                collectionBox: gameContainer.querySelector(\'.collection-box\'),\n                collectionArrow: gameContainer.querySelector(\'.collection-arrow\'),\n                toys: [],\n            }\n\n            const settings = {\n                targetToy: null,\n                collectedNumber: 0,\n            }\n\n            const m = 2\n            const toys = {\n                bear: {\n                    w: 20 * m,\n                    h: 27 * m,\n                },\n                bunny: {\n                    w: 20 * m,\n                    h: 29 * m,\n                },\n                golem: {\n                    w: 20 * m,\n                    h: 27 * m,\n                },\n                cucumber: {\n                    w: 16 * m,\n                    h: 28 * m,\n                },\n                penguin: {\n                    w: 24 * m,\n                    h: 22 * m,\n                },\n                robot: {\n                    w: 20 * m,\n                    h: 30 * m,\n                },\n            }\n\n            const sortedToys = [...Object.keys(toys), ...Object.keys(toys)].sort(\n                () => 0.5 - Math.random(),\n            )\n\n            const cornerBuffer = 16\n\n            const machineBuffer = {\n                x: 36,\n                y: 16,\n            }\n\n            const radToDeg = rad => Math.round(rad * (180 / Math.PI))\n            const calcX = (i, n) => i % n\n            const calcY = (i, n) => Math.floor(i / n)\n\n            const {\n                width: machineWidth,\n                height: machineHeight,\n                top: machineTop,\n            } = elements.clawMachine.getBoundingClientRect()\n\n            const { height: machineTopHeight } = gameContainer\n                .querySelector(\'.machine-top\')\n                .getBoundingClientRect()\n\n            const { height: machineBottomHeight, top: machineBottomTop } = gameContainer\n                .querySelector(\'.machine-bottom\')\n                .getBoundingClientRect()\n\n            const maxArmLength = machineBottomTop - machineTop - machineBuffer.y\n\n            const adjustAngle = angle => {\n                const adjustedAngle = angle % 360\n                return adjustedAngle < 0 ? adjustedAngle + 360 : adjustedAngle\n            }\n\n            const randomN = (min, max) => {\n                return Math.round(min - 0.5 + Math.random() * (max - min + 1))\n            }\n\n            //* classes *//\n\n            class Button {\n                constructor({ className, action, isLocked, pressAction, releaseAction }) {\n                    Object.assign(this, {\n                        el: gameContainer.querySelector(`.${className}`),\n                        isLocked,\n                    })\n                    this.el.addEventListener(\'click\', action)\n                        ;[\'mousedown\', \'touchstart\'].forEach(action =>\n                            this.el.addEventListener(action, pressAction),\n                        )\n                        ;[\'mouseup\', \'touchend\'].forEach(action =>\n                            this.el.addEventListener(action, releaseAction),\n                        )\n\n                    if (!isLocked) this.activate()\n                }\n                activate() {\n                    this.isLocked = false\n                    this.el.classList.add(\'active\')\n                }\n                deactivate() {\n                    this.isLocked = true\n                    this.el.classList.remove(\'active\')\n                }\n            }\n\n            class WorldObject {\n                constructor(props) {\n                    Object.assign(this, {\n                        x: 0,\n                        y: 0,\n                        z: 0,\n                        angle: 0,\n                        transformOrigin: { x: 0, y: 0 },\n                        interval: null,\n                        default: {},\n                        moveWith: [],\n                        el: props.className && gameContainer.querySelector(`.${props.className}`),\n                        ...props,\n                    })\n                    this.setStyles()\n                    if (props.className) {\n                        const { width, height } = this.el.getBoundingClientRect()\n                        this.w = width\n                        this.h = height\n                    }\n                    ;[\'x\', \'y\', \'w\', \'h\'].forEach(key => {\n                        this.default[key] = this[key]\n                    })\n                }\n                setStyles() {\n                    Object.assign(this.el.style, {\n                        left: `${this.x}px`,\n                        top: !this.bottom && `${this.y}px`,\n                        bottom: this.bottom,\n                        width: `${this.w}px`,\n                        height: `${this.h}px`,\n                        transformOrigin: this.transformOrigin,\n                    })\n                    this.el.style.zIndex = this.z\n                }\n                setClawPos(clawPos) {\n                    this.clawPos = clawPos\n                }\n                setTransformOrigin(transformOrigin) {\n                    this.transformOrigin =\n                        transformOrigin === \'center\'\n                            ? \'center\'\n                            : `${transformOrigin.x}px ${transformOrigin.y}px`\n                    this.setStyles()\n                }\n                handleNext(next) {\n                    if (this.interval) {\n                        clearInterval(this.interval)\n                        this.interval = null\n                    }\n                    if (next) next()\n                }\n                resumeMove({ moveKey, target, moveTime, next }) {\n                    this.interval = null\n                    this.move({ moveKey, target, moveTime, next })\n                }\n                resizeShadow() {\n                    elements.box.style.setProperty(\'--scale\', 0.5 + this.h / maxArmLength / 2)\n                }\n                move({ moveKey, target, moveTime, next }) {\n                    if (this.interval) {\n                        clearInterval(this.interval)\n                        this.interval = null\n                        this.handleNext(next)\n                    } else {\n                        const moveTarget = target || this.default[moveKey]\n                        this.interval = setInterval(() => {\n                            // Safety check: ensure element still exists\n                            if (!this.el || !this.el.parentNode) {\n                                clearInterval(this.interval)\n                                this.interval = null\n                                return\n                            }\n\n                            const distance =\n                                Math.abs(this[moveKey] - moveTarget) < 10\n                                    ? Math.abs(this[moveKey] - moveTarget)\n                                    : 10\n                            const increment = this[moveKey] > moveTarget ? -distance : distance\n                            if (\n                                increment > 0\n                                    ? this[moveKey] < moveTarget\n                                    : this[moveKey] > moveTarget\n                            ) {\n                                this[moveKey] += increment\n                                this.setStyles()\n                                if (moveKey === \'h\') this.resizeShadow()\n                                if (this.moveWith.length) {\n                                    this.moveWith.forEach(obj => {\n                                        if (!obj || !obj.el || !obj.el.parentNode) return\n                                        obj[moveKey === \'h\' ? \'y\' : moveKey] += increment\n                                        obj.setStyles()\n                                    })\n                                }\n                            } else {\n                                this.handleNext(next)\n                            }\n                        }, moveTime || 100)\n                    }\n                }\n                distanceBetween(target) {\n                    return Math.round(\n                        Math.sqrt(\n                            Math.pow(this.x - target.x, 2) + Math.pow(this.y - target.y, 2),\n                        ),\n                    )\n                }\n            }\n\n            class Toy extends WorldObject {\n                constructor(props) {\n                    const toyType = sortedToys[props.index]\n                    const size = toys[toyType]\n                    super({\n                        el: Object.assign(document.createElement(\'div\'), {\n                            className: `toy pix ${toyType}`,\n                        }),\n                        x:\n                            cornerBuffer +\n                            calcX(props.index, 4) * ((machineWidth - cornerBuffer * 3) / 4) +\n                            size.w / 2 +\n                            randomN(-6, 6),\n                        y:\n                            machineBottomTop -\n                            machineTop +\n                            cornerBuffer +\n                            calcY(props.index, 4) *\n                            ((machineBottomHeight - cornerBuffer * 2) / 3) -\n                            size.h / 2 +\n                            randomN(-2, 2),\n                        z: 0,\n                        toyType,\n                        isCollected: false,\n                        collectionTimeouts: [],\n                        ...size,\n                        ...props,\n                    })\n                    elements.box.append(this.el)\n                    const toy = this\n\n                    this.el.addEventListener(\'click\', () => this.collectToy(toy))\n                    elements.toys.push(this)\n                }\n                collectToy(toy) {\n                    // Prevent multiple collections of the same toy\n                    if (toy.isCollected || !toy.el || !toy.el.parentNode) {\n                        return\n                    }\n\n                    // Clear any existing timeouts\n                    toy.collectionTimeouts.forEach(timeout => clearTimeout(timeout))\n                    toy.collectionTimeouts = []\n\n                    toy.isCollected = true\n                    toy.el.classList.remove(\'selected\')\n                    toy.x = machineWidth / 2 - toy.w / 2\n                    toy.y = machineHeight / 2 - toy.h / 2\n                    toy.z = 7\n                    toy.el.style.setProperty(\'--rotate-angle\', \'0deg\')\n                    toy.setTransformOrigin(\'center\')\n\n                    // Reset any previous animation state and classes\n                    toy.el.classList.remove(\'display\', \'selected\', \'grabbed\')\n                    toy.el.style.removeProperty(\'opacity\')\n                    toy.el.style.removeProperty(\'visibility\')\n                    toy.el.style.removeProperty(\'transform\')\n                    toy.el.style.removeProperty(\'animation\')\n\n                    // Clear targetToy if this is the target\n                    if (settings.targetToy === toy) {\n                        settings.targetToy = null\n                    }\n\n                    // Force a reflow to reset animation state\n                    void toy.el.offsetWidth\n\n                    // Ensure toy is visible before starting animation\n                    toy.el.style.opacity = \'1\'\n                    toy.el.style.visibility = \'visible\'\n                    toy.el.classList.add(\'display\')\n                    elements.clawMachine.classList.add(\'show-overlay\')\n                    settings.collectedNumber++\n\n                    const toyWrapper = Object.assign(document.createElement(\'div\'), {\n                        className: `toy-wrapper ${settings.collectedNumber > 6 ? \'squeeze-in\' : \'\'\n                            }`,\n                        innerHTML: `<div class=\"toy pix ${toy.toyType}\"></div>`,\n                    })\n                    elements.collectionBox.appendChild(toyWrapper)\n\n                    // Fallback: ensure toy in collection box is visible after animation completes\n                    const toyElement = toyWrapper.querySelector(\'.toy\')\n\n                    // Make collection box toy visible earlier (after 1.5s instead of 2s)\n                    const timeout1 = setTimeout(() => {\n                        if (toyElement && toyElement.parentNode) {\n                            toyElement.style.opacity = \'1\'\n                            toyElement.style.transform = \'translateY(0)\'\n                            toyElement.style.visibility = \'visible\'\n                            toyElement.style.animation = \'none\'\n                        }\n                    }, 1500)\n                    toy.collectionTimeouts.push(timeout1)\n\n                    // Ensure collection box toy is definitely visible after full animation\n                    const timeout2 = setTimeout(() => {\n                        if (toyElement && toyElement.parentNode) {\n                            toyElement.style.opacity = \'1\'\n                            toyElement.style.transform = \'translateY(0)\'\n                            toyElement.style.visibility = \'visible\'\n                            toyElement.style.animation = \'none\'\n                        }\n                    }, 2000)\n                    toy.collectionTimeouts.push(timeout2)\n\n                    // Hide and clean up the original toy after animation completes\n                    const timeout3 = setTimeout(() => {\n                        // Remove display class and reset styles\n                        if (toy.el) {\n                            toy.el.classList.remove(\'display\', \'selected\', \'grabbed\')\n                            toy.el.style.opacity = \'0\'\n                            toy.el.style.visibility = \'hidden\'\n                            toy.el.style.transform = \'\'\n                            toy.el.style.animation = \'\'\n                        }\n\n                        // Remove toy from toys array to prevent re-collection\n                        const toyIndex = elements.toys.indexOf(toy)\n                        if (toyIndex > -1) {\n                            elements.toys.splice(toyIndex, 1)\n                        }\n\n                        // Clear toy from any moveWith arrays\n                        [vertRail, armJoint, arm].forEach(obj => {\n                            if (obj && obj.moveWith) {\n                                const moveWithIndex = obj.moveWith.indexOf(toy)\n                                if (moveWithIndex > -1) {\n                                    obj.moveWith[moveWithIndex] = null\n                                }\n                            }\n                        })\n\n                        // Clear targetToy if it\'s this toy\n                        if (settings.targetToy === toy) {\n                            settings.targetToy = null\n                        }\n\n                        // Remove toy from DOM to prevent state conflicts\n                        if (toy.el && toy.el.parentNode) {\n                            try {\n                                toy.el.parentNode.removeChild(toy.el)\n                            } catch (e) {\n                                // Element might already be removed\n                            }\n                        }\n\n                        // Clear all timeouts\n                        toy.collectionTimeouts.forEach(timeout => clearTimeout(timeout))\n                        toy.collectionTimeouts = []\n\n                        elements.clawMachine.classList.remove(\'show-overlay\')\n                        if (!gameContainer.querySelector(\'.selected\'))\n                            elements.collectionArrow.classList.remove(\'active\')\n                    }, 2000)\n                    toy.collectionTimeouts.push(timeout3)\n                }\n                setRotateAngle() {\n                    const angle =\n                        radToDeg(\n                            Math.atan2(\n                                this.y + this.h / 2 - this.clawPos.y,\n                                this.x + this.w / 2 - this.clawPos.x,\n                            ),\n                        ) - 90\n                    const adjustedAngle = Math.round(adjustAngle(angle))\n                    this.angle =\n                        adjustedAngle < 180 ? adjustedAngle * -1 : 360 - adjustedAngle\n                    this.el.style.setProperty(\'--rotate-angle\', `${this.angle}deg`)\n                }\n            }\n\n            //* set up *//\n            elements.box.style.setProperty(\'--shadow-pos\', `${maxArmLength}px`)\n\n            const armJoint = new WorldObject({\n                className: \'arm-joint\',\n            })\n\n            const vertRail = new WorldObject({\n                className: \'vert\',\n                moveWith: [null, armJoint],\n            })\n\n            const arm = new WorldObject({\n                className: \'arm\',\n            })\n\n            armJoint.resizeShadow()\n\n            armJoint.move({\n                moveKey: \'y\',\n                target: machineTopHeight - machineBuffer.y,\n                moveTime: 50,\n                next: () =>\n                    vertRail.resumeMove({\n                        moveKey: \'x\',\n                        target: machineBuffer.x,\n                        moveTime: 50,\n                        next: () => {\n                            Object.assign(armJoint.default, {\n                                y: machineTopHeight - machineBuffer.y,\n                                x: machineBuffer.x,\n                            })\n                            Object.assign(vertRail.default, {\n                                x: machineBuffer.x,\n                            })\n                            activateHoriBtn()\n                        },\n                    }),\n            })\n\n            const doOverlap = (a, b) => {\n                return b.x > a.x && b.x < a.x + a.w && b.y > a.y && b.y < a.y + a.h\n            }\n\n            const getClosestToy = () => {\n                const claw = {\n                    y: armJoint.y + maxArmLength + machineBuffer.y + 7,\n                    x: armJoint.x + 7,\n                    w: 40,\n                    h: 32,\n                }\n                // Filter out collected toys and ensure toys still exist in DOM\n                const overlappedToys = elements.toys.filter(t => {\n                    return !t.isCollected &&\n                        t.el &&\n                        t.el.parentNode &&\n                        doOverlap(t, claw)\n                })\n\n                if (overlappedToys.length) {\n                    const toy = overlappedToys.sort((a, b) => b.index - a.index)[0]\n                    // Double-check toy is still valid\n                    if (toy && !toy.isCollected && toy.el && toy.el.parentNode) {\n                        toy.setTransformOrigin({\n                            x: claw.x - toy.x,\n                            y: claw.y - toy.y,\n                        })\n                        toy.setClawPos({\n                            x: claw.x,\n                            y: claw.y,\n                        })\n                        settings.targetToy = toy\n                    } else {\n                        settings.targetToy = null\n                    }\n                } else {\n                    settings.targetToy = null\n                }\n            }\n\n            new Array(12).fill(\'\').forEach((_, i) => {\n                if (i === 8) return\n                new Toy({ index: i })\n            })\n\n            const stopHoriBtnAndActivateVertBtn = () => {\n                if (armJoint.interval) {\n                    clearInterval(armJoint.interval)\n                    armJoint.interval = null\n                }\n                horiBtn.deactivate()\n                vertBtn.activate()\n            }\n\n            const activateHoriBtn = () => {\n                horiBtn.activate()\n                    ;[vertRail, armJoint, arm].forEach(c => {\n                        if (c.interval) {\n                            clearInterval(c.interval)\n                            c.interval = null\n                        }\n                    })\n            }\n\n            const dropToy = () => {\n                arm.el.classList.add(\'open\')\n                if (settings.targetToy &&\n                    !settings.targetToy.isCollected &&\n                    settings.targetToy.el &&\n                    settings.targetToy.el.parentNode) {\n                    settings.targetToy.z = 3\n                    settings.targetToy.move({\n                        moveKey: \'y\',\n                        target: machineHeight - settings.targetToy.h - 30,\n                        moveTime: 50,\n                    })\n                        ;[vertRail, armJoint, arm].forEach(obj => (obj.moveWith[0] = null))\n                }\n                setTimeout(() => {\n                    arm.el.classList.remove(\'open\')\n                    activateHoriBtn()\n                    if (settings.targetToy &&\n                        !settings.targetToy.isCollected &&\n                        settings.targetToy.el &&\n                        settings.targetToy.el.parentNode) {\n                        settings.targetToy.el.classList.add(\'selected\')\n                        elements.collectionArrow.classList.add(\'active\')\n                        settings.targetToy = null\n                    } else {\n                        settings.targetToy = null\n                    }\n                }, 700)\n            }\n\n            const grabToy = () => {\n                if (settings.targetToy &&\n                    !settings.targetToy.isCollected &&\n                    settings.targetToy.el &&\n                    settings.targetToy.el.parentNode) {\n                    ;[vertRail, armJoint, arm].forEach(\n                        obj => (obj.moveWith[0] = settings.targetToy),\n                    )\n                    settings.targetToy.setRotateAngle()\n                    settings.targetToy.el.classList.add(\'grabbed\')\n                } else {\n                    arm.el.classList.add(\'missed\')\n                    settings.targetToy = null\n                }\n            }\n\n            const horiBtn = new Button({\n                className: \'hori-btn\',\n                isLocked: true,\n                pressAction: () => {\n                    arm.el.classList.remove(\'missed\')\n                    vertRail.move({\n                        moveKey: \'x\',\n                        target: machineWidth - armJoint.w - machineBuffer.x,\n                        next: stopHoriBtnAndActivateVertBtn,\n                    })\n                },\n                releaseAction: () => {\n                    clearInterval(vertRail.interval)\n                    stopHoriBtnAndActivateVertBtn()\n                },\n            })\n\n            const vertBtn = new Button({\n                className: \'vert-btn\',\n                isLocked: true,\n                pressAction: () => {\n                    if (vertBtn.isLocked) return\n                    armJoint.move({\n                        moveKey: \'y\',\n                        target: machineBuffer.y,\n                    })\n                },\n                releaseAction: () => {\n                    clearInterval(armJoint.interval)\n                    vertBtn.deactivate()\n                    getClosestToy()\n                    setTimeout(() => {\n                        arm.el.classList.add(\'open\')\n                        arm.move({\n                            moveKey: \'h\',\n                            target: maxArmLength,\n                            next: () =>\n                                setTimeout(() => {\n                                    arm.el.classList.remove(\'open\')\n                                    grabToy()\n                                    arm.resumeMove({\n                                        moveKey: \'h\',\n                                        next: () => {\n                                            vertRail.resumeMove({\n                                                moveKey: \'x\',\n                                                next: () => {\n                                                    armJoint.resumeMove({\n                                                        moveKey: \'y\',\n                                                        next: dropToy,\n                                                    })\n                                                },\n                                            })\n                                        },\n                                    })\n                                }, 500),\n                        })\n                    }, 500)\n                },\n            })\n        })();\n    </script>\n    <!-- Load Back to Top Component -->\n    <script src=\"../../assets/components/back-to-top.js\"></script>\n\n</body>', NULL, 'published', NULL, '2025-12-14 00:30:10', '2025-12-14 00:30:10');
INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(61, 'Stick Drop', 'game-rentals-stick-drop', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Stick Drop Rental | MiHi Entertainment</title>\n    <link rel=\"icon\" type=\"image/svg+xml\" href=\"../../assets/images/favicon.svg\">\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link\n        href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=Playfair+Display:wght@400;500;600;700;800;900&display=swap\"\n        rel=\"stylesheet\">\n    <link\n        href=\"https://fonts.googleapis.com/css2?family=Orbitron:wght@400;500;600;700;800;900&family=Rajdhani:wght@300;400;500;600;700&family=Exo+2:wght@400;500;600;700;800;900&display=swap\"\n        rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@900&display=swap\" rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Barlow:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css\">\n    <style>\n        @font-face {\n            font-family: \'AzoSansUber\';\n            src: url(\'../../assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\');\n            font-weight: 400;\n            font-style: normal;\n        }\n\n        html,\n        body {\n            overflow-x: hidden;\n        }\n\n        body {\n            font-family: \'Inter\', sans-serif;\n            color: #1a202c;\n        }\n\n        h1,\n        h2,\n        h3,\n        h4,\n        h5,\n        h6 {\n            font-family: \'Rajdhani\', sans-serif;\n            font-weight: 600;\n            letter-spacing: 0.02em;\n        }\n\n        .btn-primary {\n            background: linear-gradient(135deg, #0050ff 0%, #0040d9 100%);\n            transition: all 0.3s ease;\n        }\n\n        .btn-primary:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(0, 80, 255, 0.4);\n        }\n\n        .section-padding {\n            padding: 5rem 0;\n        }\n\n        .hero-gradient {\n            background: linear-gradient(135deg, rgba(0, 0, 0, 0.65) 0%, rgba(0, 0, 0, 0.65) 100%);\n        }\n\n        /* Hero Section Typography */\n        .hero-section h3 {\n            font-family: \'Orbitron\', sans-serif;\n            font-weight: 700;\n            font-size: 1.5rem;\n            letter-spacing: 0.15em;\n            text-transform: uppercase;\n            background: linear-gradient(135deg, #64b5f6 0%, #42a5f5 50%, #90caf9 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n            text-shadow: 0 0 30px rgba(100, 181, 246, 0.5);\n            margin-bottom: 1.5rem;\n            animation: glow 2s ease-in-out infinite alternate;\n        }\n\n        @media (min-width: 768px) {\n            .hero-section h3 {\n                font-size: 2rem;\n                letter-spacing: 0.2em;\n            }\n        }\n\n        @keyframes glow {\n            from {\n                filter: brightness(1);\n                text-shadow: 0 0 20px rgba(100, 181, 246, 0.5);\n            }\n\n            to {\n                filter: brightness(1.2);\n                text-shadow: 0 0 40px rgba(100, 181, 246, 0.8), 0 0 60px rgba(66, 165, 245, 0.4);\n            }\n        }\n\n        .hero-section p {\n            font-family: \'Exo 2\', sans-serif;\n            font-weight: 400;\n            letter-spacing: 0.02em;\n            line-height: 1.6;\n        }\n\n        /* Hero Section Content Container - Desktop Transform */\n        @media (min-width: 768px) {\n            .hero-section .relative.z-10 {\n                transform: translateY(-60px);\n            }\n        }\n\n        /* Keyboard Animation Styles */\n        .keyboard {\n            font-family: \'AzoSansUber\', sans-serif;\n            font-weight: 400;\n            letter-spacing: 0.1em;\n        }\n\n        .key {\n            font-size: 3.5rem;\n            display: inline-block;\n            letter-spacing: 0.08em;\n            transition: transform 0.2s;\n            text-shadow: 0 0 20px rgba(100, 181, 246, 0.5);\n        }\n\n        @media (min-width: 768px) {\n            .key {\n                font-size: 4.5rem;\n                letter-spacing: 0.1em;\n            }\n        }\n\n        h3.reaction-game-title {\n            font-family: \'AzoSansUber\', sans-serif !important;\n            font-weight: 400;\n            color: #ffffff;\n        }\n\n        @keyframes pressDown1 {\n\n            30%,\n            40%,\n            100% {\n                transform: translateY(0);\n            }\n\n            35% {\n                transform: translateY(6px);\n            }\n        }\n\n        @keyframes pressDown2 {\n\n            70%,\n            80%,\n            100% {\n                transform: translateY(0);\n            }\n\n            75% {\n                transform: translateY(6px);\n            }\n        }\n\n        @keyframes pressDown3 {\n\n            30%,\n            40%,\n            100% {\n                transform: translateY(0);\n            }\n\n            35% {\n                transform: translateY(6px);\n            }\n        }\n\n        @keyframes pressDown4 {\n\n            40%,\n            50%,\n            100% {\n                transform: translateY(0);\n            }\n\n            45% {\n                transform: translateY(6px);\n            }\n        }\n\n        @keyframes pressDown5 {\n\n            20%,\n            30%,\n            100% {\n                transform: translateY(0);\n            }\n\n            25% {\n                transform: translateY(6px);\n            }\n        }\n\n        @keyframes pressDown6 {\n\n            60%,\n            70%,\n            100% {\n                transform: translateY(0);\n            }\n\n            65% {\n                transform: translateY(6px);\n            }\n        }\n\n        @keyframes pressDown7 {\n\n            10%,\n            20%,\n            100% {\n                transform: translateY(0);\n            }\n\n            15% {\n                transform: translateY(6px);\n            }\n        }\n\n        @keyframes pressDown8 {\n\n            35%,\n            45%,\n            100% {\n                transform: translateY(0);\n            }\n\n            40% {\n                transform: translateY(6px);\n            }\n        }\n\n        @keyframes pressDown9 {\n\n            50%,\n            60%,\n            100% {\n                transform: translateY(0);\n            }\n\n            55% {\n                transform: translateY(6px);\n            }\n        }\n\n        @keyframes pressDown10 {\n\n            25%,\n            35%,\n            100% {\n                transform: translateY(0);\n            }\n\n            30% {\n                transform: translateY(6px);\n            }\n        }\n\n        @keyframes pressDown11 {\n\n            15%,\n            25%,\n            100% {\n                transform: translateY(0);\n            }\n\n            20% {\n                transform: translateY(6px);\n            }\n        }\n\n        @keyframes pressDown12 {\n\n            45%,\n            55%,\n            100% {\n                transform: translateY(0);\n            }\n\n            50% {\n                transform: translateY(6px);\n            }\n        }\n\n        .key:nth-child(1) {\n            animation: pressDown1 2s infinite;\n        }\n\n        .key:nth-child(2) {\n            animation: pressDown2 3s infinite;\n        }\n\n        .key:nth-child(3) {\n            animation: pressDown3 4s infinite;\n        }\n\n        .key:nth-child(4) {\n            animation: pressDown4 2.5s infinite;\n        }\n\n        .key:nth-child(5) {\n            animation: pressDown5 2.5s infinite;\n        }\n\n        .key:nth-child(6) {\n            animation: pressDown6 3.5s infinite;\n        }\n\n        .key:nth-child(7) {\n            animation: pressDown7 2.2s infinite;\n        }\n\n        .key:nth-child(8) {\n            animation: pressDown8 3.2s infinite;\n        }\n\n        .key:nth-child(9) {\n            animation: pressDown9 2.8s infinite;\n        }\n\n        .key:nth-child(10) {\n            animation: pressDown10 3.3s infinite;\n        }\n\n        .key:nth-child(11) {\n            animation: pressDown11 2.7s infinite;\n        }\n\n        .key:nth-child(12) {\n            animation: pressDown12 3.1s infinite;\n        }\n\n        /* Responsive adjustments for smaller screens */\n        @media (max-width: 640px) {\n            .key {\n                font-size: 2.5rem;\n                letter-spacing: 0.06em;\n            }\n        }\n\n        /* Animated Gradient Button */\n        .animated-gradient-btn {\n            --width: 220px;\n            --height: 70px;\n            --border: 4px;\n            --violet: #6559ae;\n            --orange: #ff7159;\n            --deg: 120deg;\n            --size: 400%;\n            --dur: 3s;\n\n            display: block;\n            position: relative;\n            width: var(--width);\n            height: var(--height);\n            margin: 0 auto;\n            text-transform: uppercase;\n            text-decoration: none;\n            text-align: center;\n            letter-spacing: 3px;\n            line-height: var(--height);\n            font-family: \'Rajdhani\', sans-serif;\n            font-weight: 600;\n            font-size: 24px;\n            z-index: 1;\n        }\n\n        .animated-gradient-btn::after {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            margin: auto;\n            background: linear-gradient(var(--deg), var(--violet), var(--orange), var(--violet));\n            background-size: var(--size) var(--size);\n            -webkit-clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 216px 4px, 216px 66px, 4px 66px, 4px 100%, 100% 100%, 100% 0%, 0% 0%);\n            clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 216px 4px, 216px 66px, 4px 66px, 4px 100%, 100% 100%, 100% 0%, 0% 0%);\n            animation: gradient var(--dur) ease-in-out infinite, border 1s forwards ease-in-out reverse;\n        }\n\n        .animated-gradient-btn>span {\n            display: block;\n            position: relative;\n            z-index: 2;\n            background: linear-gradient(var(--deg), var(--violet), var(--orange), var(--violet));\n            background-size: var(--size) var(--size);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n            animation: gradient var(--dur) ease-in-out infinite;\n        }\n\n        @keyframes gradient {\n            0% {\n                background-position: 14% 0%;\n            }\n\n            50% {\n                background-position: 87% 100%;\n            }\n\n            100% {\n                background-position: 14% 0%;\n            }\n        }\n\n        @keyframes border {\n            0% {\n                -webkit-clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 216px 4px, 216px 66px, 4px 66px, 4px 100%, 100% 100%, 100% 0%, 0% 0%);\n                clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 216px 4px, 216px 66px, 4px 66px, 4px 100%, 100% 100%, 100% 0%, 0% 0%);\n            }\n\n            25% {\n                -webkit-clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 216px 4px, 216px 66px, 216px 66px, 216px 100%, 100% 100%, 100% 0%, 0% 0%);\n                clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 216px 4px, 216px 66px, 216px 66px, 216px 100%, 100% 100%, 100% 0%, 0% 0%);\n            }\n\n            50% {\n                -webkit-clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 216px 4px, 216px 4px, 216px 4px, 216px 4px, 216px 4px, 100% 0%, 0% 0%);\n                clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 216px 4px, 216px 4px, 216px 4px, 216px 4px, 216px 4px, 100% 0%, 0% 0%);\n            }\n\n            75% {\n                -webkit-clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 4px 4px, 4px 4px, 4px 4px, 4px 4px, 4px 4px, 4px 0%, 0% 0%);\n                clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 4px 4px, 4px 4px, 4px 4px, 4px 4px, 4px 4px, 4px 0%, 0% 0%);\n            }\n\n            100% {\n                -webkit-clip-path: polygon(0% 100%, 4px 100%, 4px 100%, 4px 100%, 4px 100%, 4px 100%, 4px 100%, 4px 100%, 4px 100%, 0% 100%);\n                clip-path: polygon(0% 100%, 4px 100%, 4px 100%, 4px 100%, 4px 100%, 4px 100%, 4px 100%, 4px 100%, 4px 100%, 0% 100%);\n            }\n        }\n\n        /* Mobile Responsive Styles */\n        @media (max-width: 768px) {\n\n            /* Hero Section Mobile */\n            .hero-section {\n                min-height: 70vh;\n                height: auto;\n                padding: 3rem 1rem;\n            }\n\n            /* Optimize background image for mobile */\n            .hero-section .bg-cover {\n                background-attachment: scroll;\n                background-position: center center;\n            }\n\n            /* Hero Section Content Container - Optimized for Mobile */\n            .hero-section .relative.z-10 {\n                width: 100%;\n                max-width: 100%;\n                box-sizing: border-box;\n                overflow-x: hidden;\n                transform: translateY(0) !important;\n                padding: 1rem 0;\n            }\n\n            /* Ensure button wrapper doesn\'t overflow */\n            .hero-section .relative.z-10>a.animated-gradient-btn {\n                margin-left: auto;\n                margin-right: auto;\n                display: block;\n            }\n\n            /* Prevent text clipping */\n            .hero-section .animated-gradient-btn>span {\n                position: relative;\n                z-index: 10;\n            }\n\n            /* Hero Section Content - Optimized Sizes for Mobile */\n            .hero-section .keyboard {\n                margin-bottom: 1.25rem !important;\n                padding: 0 0.5rem;\n            }\n\n            .hero-section .key {\n                font-size: 2.75rem !important;\n                letter-spacing: 0.06em !important;\n            }\n\n            .hero-section h3 {\n                font-size: 1.875rem !important;\n                margin-bottom: 0.875rem !important;\n                padding: 0 0.5rem;\n                line-height: 1.2;\n            }\n\n            .hero-section p {\n                font-size: 1rem !important;\n                margin-bottom: 1.75rem !important;\n                padding: 0 0.5rem;\n                line-height: 1.5;\n            }\n\n            /* Animated Gradient Button Mobile - Optimized Size */\n            .hero-section .animated-gradient-btn {\n                --width: 190px;\n                --height: 58px;\n                --border: 4px;\n                width: 190px !important;\n                height: 58px !important;\n                min-width: 190px;\n                min-height: 58px;\n                font-size: 18px !important;\n                letter-spacing: 2px;\n                line-height: 58px !important;\n                max-width: calc(100% - 2rem);\n                box-sizing: border-box;\n                overflow: visible;\n                cursor: pointer;\n                -webkit-tap-highlight-color: rgba(255, 255, 255, 0.2);\n            }\n\n            .hero-section .animated-gradient-btn::after {\n                width: 190px !important;\n                height: 58px !important;\n                left: 0 !important;\n                right: auto !important;\n                top: 0 !important;\n                bottom: auto !important;\n                margin: 0 !important;\n                -webkit-clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 186px 4px, 186px 54px, 4px 54px, 4px 100%, 100% 100%, 100% 0%, 0% 0%) !important;\n                clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 186px 4px, 186px 54px, 4px 54px, 4px 100%, 100% 100%, 100% 0%, 0% 0%) !important;\n                animation: gradient var(--dur) ease-in-out infinite !important;\n            }\n\n            .hero-section .animated-gradient-btn>span {\n                line-height: 58px !important;\n                display: flex !important;\n                align-items: center !important;\n                justify-content: center !important;\n                height: 100% !important;\n                width: 100% !important;\n                white-space: nowrap;\n                overflow: visible;\n                padding: 0;\n                font-size: 18px !important;\n            }\n\n            /* Regular Animated Gradient Button Mobile (for other sections) */\n            .animated-gradient-btn {\n                --width: 180px;\n                --height: 55px;\n                font-size: 20px;\n                letter-spacing: 1px;\n            }\n\n            .animated-gradient-btn::after {\n                -webkit-clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 176px 4px, 176px 51px, 4px 51px, 4px 100%, 100% 100%, 100% 0%, 0% 0%);\n                clip-path: polygon(0% 100%, 4px 100%, 4px 4px, 176px 4px, 176px 51px, 4px 51px, 4px 100%, 100% 100%, 100% 0%, 0% 0%);\n            }\n        }\n\n        @media (max-width: 640px) {\n\n            /* Hero Section - Small Mobile Optimization */\n            .hero-section {\n                min-height: 65vh;\n                padding: 2.5rem 0.75rem;\n            }\n\n            .hero-section .relative.z-10 {\n                padding: 0.75rem 0;\n            }\n\n            .hero-section .keyboard {\n                margin-bottom: 1rem !important;\n                padding: 0 0.25rem;\n            }\n\n            .hero-section .key {\n                font-size: 2.25rem !important;\n                letter-spacing: 0.05em !important;\n            }\n\n            .hero-section h3 {\n                font-size: 1.5rem !important;\n                margin-bottom: 0.75rem !important;\n                padding: 0 0.5rem;\n                line-height: 1.2;\n            }\n\n            .hero-section p {\n                font-size: 0.9375rem !important;\n                margin-bottom: 1.5rem !important;\n                padding: 0 0.5rem;\n                line-height: 1.5;\n            }\n\n            .hero-section .animated-gradient-btn {\n                --width: 170px;\n                --height: 54px;\n                --border: 3px;\n                width: 170px !important;\n                height: 54px !important;\n                min-width: 170px;\n                min-height: 54px;\n                font-size: 16px !important;\n                letter-spacing: 1.5px;\n                line-height: 54px !important;\n                max-width: calc(100% - 1.5rem);\n                box-sizing: border-box;\n                overflow: visible;\n            }\n\n            .hero-section .animated-gradient-btn::after {\n                width: 170px !important;\n                height: 54px !important;\n                left: 0 !important;\n                right: auto !important;\n                top: 0 !important;\n                bottom: auto !important;\n                margin: 0 !important;\n                -webkit-clip-path: polygon(0% 100%, 3px 100%, 3px 3px, 167px 3px, 167px 51px, 3px 51px, 3px 100%, 100% 100%, 100% 0%, 0% 0%) !important;\n                clip-path: polygon(0% 100%, 3px 100%, 3px 3px, 167px 3px, 167px 51px, 3px 51px, 3px 100%, 100% 100%, 100% 0%, 0% 0%) !important;\n                animation: gradient var(--dur) ease-in-out infinite !important;\n            }\n\n            .hero-section .animated-gradient-btn>span {\n                line-height: 54px !important;\n                display: flex !important;\n                align-items: center !important;\n                justify-content: center !important;\n                height: 100% !important;\n                width: 100% !important;\n                white-space: nowrap;\n                overflow: visible;\n                padding: 0;\n                font-size: 16px !important;\n            }\n\n            .animated-gradient-btn {\n                --width: 160px;\n                --height: 50px;\n                font-size: 18px;\n            }\n\n            .animated-gradient-btn::after {\n                -webkit-clip-path: polygon(0% 100%, 3px 100%, 3px 3px, 157px 3px, 157px 47px, 3px 47px, 3px 100%, 100% 100%, 100% 0%, 0% 0%);\n                clip-path: polygon(0% 100%, 3px 100%, 3px 3px, 157px 3px, 157px 47px, 3px 47px, 3px 100%, 100% 100%, 100% 0%, 0% 0%);\n            }\n        }\n\n        /* Step Animation Styles */\n        .step-item {\n            opacity: 0;\n            transform: translateX(-20px);\n            transition: all 0.6s ease-out;\n        }\n\n        .step-item.animate {\n            opacity: 1;\n            transform: translateX(0);\n        }\n\n        .step-item:nth-child(1) {\n            transition-delay: 0.1s;\n        }\n\n        .step-item:nth-child(2) {\n            transition-delay: 0.2s;\n        }\n\n        .step-item:nth-child(3) {\n            transition-delay: 0.3s;\n        }\n\n        .step-item:nth-child(4) {\n            transition-delay: 0.4s;\n        }\n\n        .step-item:hover {\n            transform: translateX(5px);\n        }\n\n        .step-item:hover .step-badge {\n            transform: scale(1.1) rotate(5deg);\n            box-shadow: 0 4px 12px rgba(23, 26, 31, 0.4);\n        }\n\n        .step-badge {\n            transition: all 0.3s ease;\n        }\n\n        .step-item.animate .step-badge {\n            animation: badgePulse 0.6s ease-out;\n        }\n\n        @keyframes badgePulse {\n            0% {\n                transform: scale(0);\n                opacity: 0;\n            }\n\n            50% {\n                transform: scale(1.2);\n            }\n\n            100% {\n                transform: scale(1);\n                opacity: 1;\n            }\n        }\n\n        /* Gradient Grainy Background */\n        .gradient-grainy-bg {\n            position: relative;\n            background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);\n        }\n\n        .gradient-grainy-bg::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background-image:\n                repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.03) 0px, transparent 1px, transparent 2px, rgba(0, 0, 0, 0.03) 3px),\n                repeating-linear-gradient(90deg, rgba(0, 0, 0, 0.03) 0px, transparent 1px, transparent 2px, rgba(0, 0, 0, 0.03) 3px);\n            background-size: 4px 4px;\n            pointer-events: none;\n            opacity: 0.5;\n        }\n\n        .gradient-grainy-bg>* {\n            position: relative;\n            z-index: 1;\n        }\n\n        /* Accordion Dropdown Menu Styles */\n        .accordion-wrapper {\n            max-width: 900px;\n            margin: 0 auto;\n            width: 100%;\n        }\n\n        .accordion-wrapper h1 {\n            color: #1a202c;\n            font-size: 28px;\n            font-weight: 600;\n            text-align: center;\n            margin-bottom: 15px;\n        }\n\n        .accordion-wrapper h1 a {\n            color: #c12c42;\n            font-size: 16px;\n        }\n\n        .accordion-wrapper p {\n            color: #4a5568;\n            text-align: center;\n            margin-bottom: 30px;\n        }\n\n        .accordion {\n            width: 100%;\n            max-width: 100%;\n            margin: 0 auto;\n            background: #FFFFFF;\n            border-radius: 8px;\n            list-style-type: none;\n            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);\n            border: 1px solid #e2e8f0;\n        }\n\n        .accordion .link {\n            cursor: pointer;\n            display: block;\n            padding: 15px 20px;\n            color: #1a202c;\n            font-size: 16px;\n            font-weight: 700;\n            border-bottom: 1px solid #e2e8f0;\n            position: relative;\n            transition: all 0.4s ease;\n            background: #FFFFFF;\n        }\n\n        .accordion li:last-child .link {\n            border-bottom: 0;\n        }\n\n        .accordion li.open .link {\n            color: #b63b4d;\n            background: #f7fafc;\n        }\n\n        .accordion .link:hover {\n            background: #f7fafc;\n            color: #2d3748;\n        }\n\n        .submenu {\n            display: none;\n            background: #f7fafc;\n            font-size: 14px;\n            list-style-type: none;\n            padding: 0;\n        }\n\n        .submenu li {\n            border-bottom: 1px solid #e2e8f0;\n        }\n\n        .submenu li:last-child {\n            border-bottom: 0;\n        }\n\n        .submenu p {\n            color: #4a5568;\n            padding: 15px 20px;\n            margin: 0;\n            line-height: 1.6;\n        }\n\n        .submenu a {\n            display: block;\n            text-decoration: none;\n            color: #2d3748;\n            padding: 12px 20px;\n            transition: all 0.25s ease;\n        }\n\n        .submenu a:hover {\n            background: #edf2f7;\n            color: #b63b4d;\n        }\n\n        /* Mobile Responsive for Accordion */\n        @media (max-width: 768px) {\n            .accordion-wrapper {\n                padding: 0 0.5rem;\n            }\n\n            .accordion-wrapper h1 {\n                font-size: 22px;\n                margin-bottom: 10px;\n            }\n\n            .accordion .link {\n                padding: 12px 15px;\n                font-size: 14px;\n            }\n\n            .submenu p {\n                padding: 12px 15px;\n                font-size: 13px;\n            }\n        }\n    </style>\n</head>\n\n<body>\n    <div id=\"nav-placeholder\"></div>\n\n    <section class=\"relative h-screen md:h-screen flex items-center justify-center overflow-hidden hero-section\">\n        <div class=\"absolute inset-0 bg-cover bg-center\"\n            style=\"background-image: url(\'../../assets/images/stickdrop/hero.jpg\');\"></div>\n        <div class=\"absolute inset-0 hero-gradient\"></div>\n        <div class=\"relative z-10 text-center text-white px-4 md:px-6 py-8 md:py-0\">\n            <div class=\"keyboard mb-6 md:mb-8\">\n                <span class=\"key\" style=\"color: #FF4F4F;\">S</span>\n                <span class=\"key\" style=\"color: #FF4F4F;\">T</span>\n                <span class=\"key\" style=\"color: #FF4F4F;\">I</span>\n                <span class=\"key\" style=\"color: #FF4F4F;\">C</span>\n                <span class=\"key\" style=\"color: #FF4F4F;\">K</span>\n                <span class=\"key\">&nbsp;</span>\n                <span class=\"key\" style=\"color: #18F1E1;\">D</span>\n                <span class=\"key\" style=\"color: #18F1E1;\">R</span>\n                <span class=\"key\" style=\"color: #18F1E1;\">O</span>\n                <span class=\"key\" style=\"color: #18F1E1;\">P</span>\n            </div>\n            <h3 class=\"reaction-game-title\">Reaction Game</h3>\n            <p class=\"text-lg md:text-xl lg:text-2xl mb-8 md:mb-10 max-w-5xl mx-auto px-2\"\n                style=\"color: #ffffff;font-family: \'AzoSans\', sans-serif; font-weight: 400;\">\n                Test your reflexes and keep the crowd on their toes with our Stick Drop game, a fast-paced challenge\n                everyone will love.\n            </p>\n            <a href=\"../contact-us.html\" class=\"animated-gradient-btn\"\n                style=\"font-family: \'AzoSans\', sans-serif; font-weight: 700;\"><span\n                    style=\"color: #18F1E1; -webkit-text-fill-color: #18F1E1; background: none; -webkit-background-clip: unset; background-clip: unset;\">Contact\n                    Us</span></a>\n        </div>\n    </section>\n\n    <!-- 1st Section -->\n    <section id=\"1st-section\" class=\"py-10 md:py-14 lg:py-16 bg-white relative overflow-hidden\">\n        <div class=\"container mx-auto px-4 md:px-6 lg:px-8\">\n            <div class=\"max-w-6xl mx-auto\">\n                <div class=\"grid lg:grid-cols-2 gap-8 lg:gap-10 items-center\">\n                    <!-- Image Column -->\n                    <div class=\"order-2 lg:order-1\">\n                        <div class=\"relative rounded-xl lg:rounded-2xl overflow-hidden shadow-xl group\">\n                            <div class=\"aspect-[3/4] overflow-hidden\">\n                                <img src=\"../assets/images/stickdrop/Stick-Drop.png\"\n                                    alt=\"Stick Drop game in action at an outdoor event\"\n                                    class=\"w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-700\">\n                            </div>\n                            <div\n                                class=\"absolute inset-0 bg-gradient-to-t from-black/20 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500\">\n                            </div>\n                        </div>\n                    </div>\n\n                    <!-- Content Column -->\n                    <div class=\"order-1 lg:order-2 space-y-4\">\n                        <h2 class=\"text-3xl md:text-3xl lg:text-5xl font-bold text-gray-900 leading-tight\"\n                            style=\"font-family: \'AzoSansUber\', sans-serif; font-weight: 400; color: #FF4F4F;\">\n                            Spark Energy at Your Event\n                        </h2>\n                        <div class=\"w-16 h-0.5 rounded-full\" style=\"background-color: #FF4F4F;\"></div>\n                        <div class=\"space-y-3 text-gray-700 leading-relaxed\">\n                            <p class=\"text-base md:text-lg\"\n                                style=\"color: #1F1F1F;font-family: \'AzoSans\', sans-serif; font-weight: 400;\">\n                                Looking for a fun and interactive way to spark energy at your event? Our Stick Drop game\n                                brings the excitement with a simple yet addictive challenge that guests can\'t resist.\n                            </p>\n                            <p class=\"text-base md:text-lg\"\n                                style=\"color: #1F1F1F;font-family: \'AzoSans\', sans-serif; font-weight: 400;\">\n                                Players watch as sticks drop one by one from the tower above and race to catch them\n                                before they hit the ground. It\'s quick, competitive, and endlessly entertaining – making\n                                it perfect for breaking the ice, encouraging friendly competition, and keeping guests\n                                engaged throughout your event.\n                            </p>\n                        </div>\n                        <div class=\"pt-2\">\n                            <a href=\"../contact-us.html\"\n                                class=\"inline-block btn-primary text-black font-semibold px-6 py-3 rounded-lg text-base md:text-lg\"\n                                style=\"font-family: \'AzoSans\', sans-serif; font-weight: 700; letter-spacing: 0.05em; background: #18F1E1 !important;\">\n                                GET A QUOTE\n                            </a>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- 2nd Section -->\n    <section id=\"2nd-section\" class=\"py-8 md:py-10 lg:py-12 bg-white\">\n        <div class=\"container mx-auto px-4 md:px-6 lg:px-8\">\n            <div class=\"max-w-6xl mx-auto\">\n                <!-- What is Stick Drop Section -->\n                <div class=\"text-center mb-8 md:mb-10\">\n                    <h2 class=\"text-2xl md:text-3xl lg:text-4xl font-bold text-gray-900 mb-4\"\n                        style=\"font-family: \'AzoSansUber\', sans-serif; font-weight: 400; color: #FF4F4F;\">\n                        What is the Stick Drop Reaction Game?\n                    </h2>\n                    <div class=\"max-w-4xl mx-auto space-y-3 text-gray-700\">\n                        <p class=\"text-sm md:text-base leading-relaxed\"\n                            style=\"color: #1F1F1F;font-family: \'AzoSans\', sans-serif; font-weight: 400;\">\n                            The Stick Drop Reaction Game is a reflex-testing game where sticks are released at random\n                            intervals from a central pole. Players must stay sharp and react quickly to catch each one\n                            before it falls.\n                        </p>\n                        <p class=\"text-sm md:text-base leading-relaxed\"\n                            style=\"color: #1F1F1F;font-family: \'AzoSans\', sans-serif; font-weight: 400;\">\n                            Easy to learn and fun to master, this game creates an exciting and interactive experience\n                            that draws in participants and spectators alike.\n                        </p>\n                    </div>\n                    <div class=\"w-16 h-0.5 rounded-full mx-auto mt-4\" style=\"background-color: #FF4F4F;\">\n                    </div>\n                </div>\n\n                <!-- What\'s Included Section -->\n                <div class=\"mt-10\">\n                    <h2 class=\"text-2xl md:text-3xl lg:text-4xl font-bold text-gray-900 text-center mb-6 md:mb-8\"\n                        style=\"font-family: \'AzoSansUber\', sans-serif; font-weight: 400; color: #FF4F4F;\">\n                        What\'s Included When You Book our Stick Drop Reaction Game?\n                    </h2>\n                    <div class=\"grid md:grid-cols-3 gap-4 md:gap-6\">\n                        <!-- DELIVERY Card -->\n                        <div class=\"rounded-xl p-5 md:p-6 shadow-lg hover:shadow-xl transition-all duration-300 hover:-translate-y-1 group\"\n                            style=\"background-color: #18F1E1;\">\n                            <div class=\"flex flex-col items-center text-center\">\n                                <div\n                                    class=\"w-16 h-16 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center mb-4 group-hover:scale-110 transition-transform duration-300\">\n                                    <i class=\"fas fa-truck text-2xl\" style=\"color: #1F1F1F;\"></i>\n                                </div>\n                                <div class=\"font-semibold px-5 py-1.5 rounded-lg mb-3 text-xs md:text-sm uppercase tracking-wide inline-block\"\n                                    style=\"font-family: \'Rajdhani\', sans-serif; background-color: #FF4F4F; color: #ffffff;\">\n                                    DELIVERY\n                                </div>\n                                <p class=\"text-xs md:text-sm leading-relaxed\" style=\"color: #1F1F1F;\">\n                                    We\'ll deliver the Stick Drop Game directly to your event location, hassle-free.\n                                </p>\n                            </div>\n                        </div>\n\n                        <!-- SETUP Card -->\n                        <div class=\"rounded-xl p-5 md:p-6 shadow-lg hover:shadow-xl transition-all duration-300 hover:-translate-y-1 group\"\n                            style=\"background-color: #18F1E1;\">\n                            <div class=\"flex flex-col items-center text-center\">\n                                <div\n                                    class=\"w-16 h-16 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center mb-4 group-hover:scale-110 transition-transform duration-300\">\n                                    <i class=\"fas fa-tools text-2xl\" style=\"color: #1F1F1F;\"></i>\n                                </div>\n                                <div class=\"font-semibold px-5 py-1.5 rounded-lg mb-3 text-xs md:text-sm uppercase tracking-wide inline-block\"\n                                    style=\"font-family: \'Rajdhani\', sans-serif; background-color: #FF4F4F; color: #ffffff;\">\n                                    SETUP\n                                </div>\n                                <p class=\"text-xs md:text-sm leading-relaxed\" style=\"color: #1F1F1F;\">\n                                    Our team will set up the game and make sure it\'s ready for guests to play.\n                                </p>\n                            </div>\n                        </div>\n\n                        <!-- BREAKDOWN Card -->\n                        <div class=\"rounded-xl p-5 md:p-6 shadow-lg hover:shadow-xl transition-all duration-300 hover:-translate-y-1 group\"\n                            style=\"background-color: #18F1E1;\">\n                            <div class=\"flex flex-col items-center text-center\">\n                                <div\n                                    class=\"w-16 h-16 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center mb-4 group-hover:scale-110 transition-transform duration-300\">\n                                    <i class=\"fas fa-box text-2xl\" style=\"color: #1F1F1F;\"></i>\n                                </div>\n                                <div class=\"font-semibold px-5 py-1.5 rounded-lg mb-3 text-xs md:text-sm uppercase tracking-wide inline-block\"\n                                    style=\"font-family: \'Rajdhani\', sans-serif; background-color: #FF4F4F; color: #ffffff;\">\n                                    BREAKDOWN\n                                </div>\n                                <p class=\"text-xs md:text-sm leading-relaxed\" style=\"color: #1F1F1F;\">\n                                    After your event wraps, we\'ll take care of the teardown and pack the game away for\n                                    you.\n                                </p>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- 3rd Section -->\n    <section id=\"3rd-section\" class=\"relative py-8 md:py-10 lg:py-12 overflow-hidden\">\n        <!-- Background Image -->\n        <div class=\"absolute inset-0 bg-cover bg-center\"\n            style=\"background-image: url(\'../../assets/images/stickdrop/pic4.jpg\');\"></div>\n        <!-- Overlay -->\n        <div class=\"absolute inset-0 bg-gradient-to-r from-black/70 via-black/60 to-black/70\"></div>\n\n        <!-- Content -->\n        <div class=\"container mx-auto px-4 md:px-6 lg:px-8 relative z-10\">\n            <div class=\"max-w-6xl mx-auto text-center text-white\">\n                <h2 class=\"text-3xl md:text-4xl lg:text-5xl font-bold mb-3 md:mb-4\"\n                    style=\"font-family: \'AzoSansUber\', sans-serif; font-weight: 400;\">\n                    <span style=\"color: #FF4F4F;\">Ready to </span><span style=\"color: #18F1E1;\">Book?</span>\n                </h2>\n                <p class=\"text-base md:text-lg lg:text-xl mb-6 md:mb-8 text-white/95 leading-relaxed max-w-5xl mx-auto\">\n                    Book your Stick Drop game rental and add a dose of excitement to your next event! Our team is ready\n                    to assist you in creating a memorable experience for your guests.\n                </p>\n                <div class=\"flex justify-center\">\n                    <a href=\"../contact-us.html\"\n                        class=\"inline-block bg-blue-600 hover:bg-blue-700 text-black font-semibold px-8 md:px-10 py-3 md:py-4 rounded-lg text-base md:text-lg uppercase tracking-wide transition-all duration-300 transform hover:scale-105 hover:shadow-2xl\"\n                        style=\"font-family: \'AzoSans\', sans-serif; font-weight: 700; box-shadow: 0 4px 15px rgba(37, 99, 235, 0.4); background: #18F1E1 !important;\">\n                        CONTACT US\n                    </a>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- 4th Section -->\n    <section id=\"4th-section\" class=\"py-6 md:py-8 lg:py-10 bg-white\">\n        <div class=\"container mx-auto px-4 md:px-6 lg:px-8\">\n            <div class=\"max-w-6xl mx-auto\">\n                <!-- Section Header -->\n                <div class=\"text-center mb-6 md:mb-8\">\n                    <h2 class=\"text-xl md:text-2xl lg:text-3xl font-bold text-gray-900 mb-2\"\n                        style=\"font-family: \'AzoSansUber\', sans-serif; font-weight: 400; color: #FF4F4F;\">\n                        Benefits of Having the Stick Drop at Your Event\n                    </h2>\n                    <div class=\"w-20 h-0.5 rounded-full mx-auto mb-4\" style=\"background-color: #FF4F4F;\">\n                    </div>\n                    <p class=\"text-sm md:text-base text-gray-700 max-w-3xl mx-auto leading-relaxed\">\n                        Want to create a dynamic and engaging atmosphere at your event? Here\'s how a Stick Drop rental\n                        can help:\n                    </p>\n                </div>\n\n                <!-- Benefits Grid -->\n                <div class=\"grid md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-5\">\n                    <!-- Benefit 1: Fun for All Ages -->\n                    <div\n                        class=\"bg-gray-50 rounded-lg p-4 md:p-5 hover:shadow-lg transition-all duration-300 hover:-translate-y-1 border border-gray-100\">\n                        <h3 class=\"text-base md:text-lg font-bold text-gray-900 mb-2\"\n                            style=\"font-family: \'Rajdhani\', sans-serif;\">\n                            Fun for All Ages\n                        </h3>\n                        <p class=\"text-xs md:text-sm text-gray-700 leading-relaxed\">\n                            From kids to adults, anyone can join in on the challenge and enjoy testing their reflexes.\n                        </p>\n                    </div>\n\n                    <!-- Benefit 2: Fast-Paced Competition -->\n                    <div\n                        class=\"bg-gray-50 rounded-lg p-4 md:p-5 hover:shadow-lg transition-all duration-300 hover:-translate-y-1 border border-gray-100\">\n                        <h3 class=\"text-base md:text-lg font-bold text-gray-900 mb-2\"\n                            style=\"font-family: \'Rajdhani\', sans-serif;\">\n                            Fast-Paced Competition\n                        </h3>\n                        <p class=\"text-xs md:text-sm text-gray-700 leading-relaxed\">\n                            The thrill of racing to catch falling sticks keeps players on edge and creates plenty of\n                            laughs and excitement.\n                        </p>\n                    </div>\n\n                    <!-- Benefit 3: Interactive and Engaging -->\n                    <div\n                        class=\"bg-gray-50 rounded-lg p-4 md:p-5 hover:shadow-lg transition-all duration-300 hover:-translate-y-1 border border-gray-100\">\n                        <h3 class=\"text-base md:text-lg font-bold text-gray-900 mb-2\"\n                            style=\"font-family: \'Rajdhani\', sans-serif;\">\n                            Interactive and Engaging\n                        </h3>\n                        <p class=\"text-xs md:text-sm text-gray-700 leading-relaxed\">\n                            Guests don\'t just watch — they participate, cheer each other on, and keep coming back for\n                            another try.\n                        </p>\n                    </div>\n\n                    <!-- Benefit 4: Compact and Versatile -->\n                    <div\n                        class=\"bg-gray-50 rounded-lg p-4 md:p-5 hover:shadow-lg transition-all duration-300 hover:-translate-y-1 border border-gray-100\">\n                        <h3 class=\"text-base md:text-lg font-bold text-gray-900 mb-2\"\n                            style=\"font-family: \'Rajdhani\', sans-serif;\">\n                            Compact and Versatile\n                        </h3>\n                        <p class=\"text-xs md:text-sm text-gray-700 leading-relaxed\">\n                            The Stick Drop doesn\'t take up much room, making it easy to set up in all types of venues.\n                        </p>\n                    </div>\n\n                    <!-- Benefit 5: Perfect Icebreaker -->\n                    <div\n                        class=\"bg-gray-50 rounded-lg p-4 md:p-5 hover:shadow-lg transition-all duration-300 hover:-translate-y-1 border border-gray-100\">\n                        <h3 class=\"text-base md:text-lg font-bold text-gray-900 mb-2\"\n                            style=\"font-family: \'Rajdhani\', sans-serif;\">\n                            Perfect Icebreaker\n                        </h3>\n                        <p class=\"text-xs md:text-sm text-gray-700 leading-relaxed\">\n                            This quick, skill-based challenge encourages guests to mingle and creates instant\n                            interaction.\n                        </p>\n                    </div>\n\n                    <!-- Benefit 6: Memorable and Unique -->\n                    <div\n                        class=\"bg-gray-50 rounded-lg p-4 md:p-5 hover:shadow-lg transition-all duration-300 hover:-translate-y-1 border border-gray-100\">\n                        <h3 class=\"text-base md:text-lg font-bold text-gray-900 mb-2\"\n                            style=\"font-family: \'Rajdhani\', sans-serif;\">\n                            Memorable and Unique\n                        </h3>\n                        <p class=\"text-xs md:text-sm text-gray-700 leading-relaxed\">\n                            It\'s not a game you see every day, which makes it a standout feature at events that guests\n                            will remember.\n                        </p>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- 5th Section -->\n    <section id=\"5th-section\" class=\"py-6 md:py-8 lg:py-10 bg-white\">\n        <div class=\"container mx-auto px-4 md:px-6 lg:px-8\">\n            <div class=\"max-w-6xl mx-auto\">\n                <div class=\"grid lg:grid-cols-2 gap-6 md:gap-8 items-center\">\n                    <!-- Image Column -->\n                    <div class=\"order-2 lg:order-1\">\n                        <div class=\"relative rounded-lg lg:rounded-xl overflow-hidden shadow-lg group\">\n                            <div class=\"aspect-[3/4] overflow-hidden\">\n                                <img src=\"../assets/images/stickdrop/Stick-Drop-2.png\"\n                                    alt=\"People playing Stick Drop Reaction Game at an indoor event\"\n                                    class=\"w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-700\">\n                            </div>\n                            <div\n                                class=\"absolute inset-0 bg-gradient-to-t from-black/10 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500\">\n                            </div>\n                        </div>\n                    </div>\n\n                    <!-- Content Column -->\n                    <div class=\"order-1 lg:order-2 space-y-4\">\n                        <h2 class=\"text-2xl md:text-3xl lg:text-4xl font-bold text-gray-900 leading-tight\"\n                            style=\"font-family: \'AzoSansUber\', sans-serif; font-weight: 400; color: #FF4F4F;\">\n                            Events Perfect For The Stick Drop Reaction Game\n                        </h2>\n                        <div class=\"w-16 h-0.5 rounded-full\" style=\"background-color: #FF4F4F;\"></div>\n                        <p class=\"text-sm md:text-base text-gray-700 leading-relaxed\">\n                            Our Stick Drop game rentals are a fun and versatile addition to many types of events,\n                            including:\n                        </p>\n\n                        <!-- Event Types List -->\n                        <div class=\"space-y-4 pt-2\">\n                            <!-- Corporate Events -->\n                            <div class=\"border-l-4 border-blue-500 pl-4 py-1\">\n                                <h3 class=\"text-base md:text-lg font-bold text-gray-900 mb-1\"\n                                    style=\"font-family: \'Rajdhani\', sans-serif;\">\n                                    Corporate Events\n                                </h3>\n                                <p class=\"text-xs md:text-sm text-gray-700 leading-relaxed\">\n                                    Team-building activities, office parties, company celebrations, and networking\n                                    events.\n                                </p>\n                            </div>\n\n                            <!-- Private Parties -->\n                            <div class=\"border-l-4 border-blue-500 pl-4 py-1\">\n                                <h3 class=\"text-base md:text-lg font-bold text-gray-900 mb-1\"\n                                    style=\"font-family: \'Rajdhani\', sans-serif;\">\n                                    Private Parties\n                                </h3>\n                                <p class=\"text-xs md:text-sm text-gray-700 leading-relaxed\">\n                                    Birthdays, graduations, reunions, or any gathering where guests want interactive\n                                    entertainment.\n                                </p>\n                            </div>\n\n                            <!-- Special Occasions -->\n                            <div class=\"border-l-4 border-blue-500 pl-4 py-1\">\n                                <h3 class=\"text-base md:text-lg font-bold text-gray-900 mb-1\"\n                                    style=\"font-family: \'Rajdhani\', sans-serif;\">\n                                    Special Occasions\n                                </h3>\n                                <p class=\"text-xs md:text-sm text-gray-700 leading-relaxed\">\n                                    Weddings, holiday parties, fundraisers, and community celebrations.\n                                </p>\n                            </div>\n\n                            <!-- Family-Friendly Events -->\n                            <div class=\"border-l-4 border-blue-500 pl-4 py-1\">\n                                <h3 class=\"text-base md:text-lg font-bold text-gray-900 mb-1\"\n                                    style=\"font-family: \'Rajdhani\', sans-serif;\">\n                                    Family-Friendly Events\n                                </h3>\n                                <p class=\"text-xs md:text-sm text-gray-700 leading-relaxed\">\n                                    School functions, church events, festivals, and family reunions.\n                                </p>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- New Section Between 5th and 6th -->\n    <section id=\"section-between-5-6\" class=\"py-6 md:py-8 gradient-grainy-bg\">\n        <div class=\"container mx-auto px-4 md:px-6\">\n            <div class=\"accordion-wrapper\">\n                <h1 style=\"font-family: \'AzoSansUber\', sans-serif; font-weight: 400; color: #FF4F4F;\">Frequently asked\n                    questions</h1>\n                <p class=\"text-center text-sm md:text-base px-2\">Have questions about our Stick Drop Reaction Game\n                    Rentals? We\'re happy to answer them!</p>\n                <ul id=\"accordion\" class=\"accordion\">\n                    <li>\n                        <div class=\"link\">How much space is needed for the Stick Drop game?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>The Stick Drop is compact and fits easily into most event spaces. We recommend about\n                                    5x5 feet of space for comfortable play.</p>\n                            </li>\n                        </ul>\n                    </li>\n                    <li>\n                        <div class=\"link\">Is the game suitable for all ages?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>Yes! The Stick Drop is easy to play and fun for guests of all ages, from kids to\n                                    adults.</p>\n                            </li>\n                        </ul>\n                    </li>\n                    <li>\n                        <div class=\"link\">How do players use the Stick Drop game?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>\n                                    How do players use the Stick Drop game?\n\n                                    Players simply stand by the pole and catch sticks as they fall, testing their\n                                    reflexes and hand-eye coordination.</p>\n                            </li>\n                        </ul>\n                    </li>\n                    <li>\n                        <div class=\"link\">Is it suitable for all ages?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>Absolutely! The Stick Drop game is fun for all ages—from kids testing their reflexes\n                                    to adults enjoying the competitive challenge. It\'s a great icebreaker that gets\n                                    everyone involved.</p>\n                            </li>\n                        </ul>\n                    </li>\n                    <li>\n                        <div class=\"link\">Can the Stick Drop be used at corporate events?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>Absolutely. It’s a great way to encourage interaction, teamwork, and a little\n                                    friendly competition at corporate functions.</p>\n                            </li>\n                        </ul>\n                    </li>\n                    <li>\n                        <div class=\"link\">How long does each game last?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>Each round is quick, usually lasting a couple of minutes, making it perfect for\n                                    keeping lines moving and giving everyone a chance to play.</p>\n                            </li>\n                        </ul>\n                    </li>\n                    <li>\n                        <div class=\"link\">Is setup and delivery included?</div>\n                        <ul class=\"submenu\">\n                            <li>\n                                <p>Yes! Our team handles the setup and breakdown, so you can focus on enjoying your\n                                    event while we take care of the details.</p>\n                            </li>\n                        </ul>\n                    </li>\n                </ul>\n            </div>\n        </div>\n    </section>\n\n    <!-- 6th Section -->\n    <section id=\"6th-section\" class=\"py-6 md:py-8 lg:py-10 bg-white\">\n        <div class=\"container mx-auto px-4 md:px-6 lg:px-8\">\n            <div class=\"max-w-6xl mx-auto\">\n                <div class=\"grid lg:grid-cols-2 gap-6 md:gap-8 items-center\">\n                    <!-- Content Column -->\n                    <div class=\"order-2 lg:order-1\">\n                        <h2 class=\"text-2xl md:text-3xl lg:text-4xl font-bold text-gray-900 mb-3\"\n                            style=\"font-family: \'AzoSansUber\', sans-serif; font-weight: 400; color: #FF4F4F;\">\n                            How To Book The Stick Drop Reaction Game\n                        </h2>\n                        <div class=\"w-16 h-0.5 rounded-full mb-4\" style=\"background-color: #FF4F4F;\"></div>\n                        <p class=\"text-sm md:text-base text-gray-700 italic mb-6 leading-relaxed\">\n                            Reserving the Stick Drop Reaction Game is simple!\n                        </p>\n\n                        <!-- Booking Steps -->\n                        <div class=\"space-y-4\" id=\"booking-steps\">\n                            <!-- Step 1 -->\n                            <div class=\"flex gap-4 step-item cursor-pointer\">\n                                <div class=\"step-badge flex-shrink-0 w-8 h-8 rounded-full text-white flex items-center justify-center font-bold text-sm md:text-base shadow-md\"\n                                    style=\"font-family: \'Rajdhani\', sans-serif; background-color: #1F1F1F;\">\n                                    1\n                                </div>\n                                <p class=\"text-sm md:text-base text-gray-700 leading-relaxed pt-1\">\n                                    Give us your event info: location, date, timeframe, and which games you\'d like.\n                                </p>\n                            </div>\n\n                            <!-- Step 2 -->\n                            <div class=\"flex gap-4 step-item cursor-pointer\">\n                                <div class=\"step-badge flex-shrink-0 w-8 h-8 rounded-full text-white flex items-center justify-center font-bold text-sm md:text-base shadow-md\"\n                                    style=\"font-family: \'Rajdhani\', sans-serif; background-color: #1F1F1F;\">\n                                    2\n                                </div>\n                                <p class=\"text-sm md:text-base text-gray-700 leading-relaxed pt-1\">\n                                    Our sales team will follow up to go over the details.\n                                </p>\n                            </div>\n\n                            <!-- Step 3 -->\n                            <div class=\"flex gap-4 step-item cursor-pointer\">\n                                <div class=\"step-badge flex-shrink-0 w-8 h-8 rounded-full text-white flex items-center justify-center font-bold text-sm md:text-base shadow-md\"\n                                    style=\"font-family: \'Rajdhani\', sans-serif; background-color: #1F1F1F;\">\n                                    3\n                                </div>\n                                <p class=\"text-sm md:text-base text-gray-700 leading-relaxed pt-1\">\n                                    You\'ll receive a custom quote.\n                                </p>\n                            </div>\n\n                            <!-- Step 4 -->\n                            <div class=\"flex gap-4 step-item cursor-pointer\">\n                                <div class=\"step-badge flex-shrink-0 w-8 h-8 rounded-full text-white flex items-center justify-center font-bold text-sm md:text-base shadow-md\"\n                                    style=\"font-family: \'Rajdhani\', sans-serif; background-color: #1F1F1F;\">\n                                    4\n                                </div>\n                                <p class=\"text-sm md:text-base text-gray-700 leading-relaxed pt-1\">\n                                    Your booking is secured with a signed agreement and 50% deposit.\n                                </p>\n                            </div>\n                        </div>\n                    </div>\n\n                    <!-- Image Column -->\n                    <div class=\"order-1 lg:order-2\">\n                        <div class=\"relative rounded-lg lg:rounded-xl overflow-hidden shadow-lg group\">\n                            <div class=\"aspect-[3/4] overflow-hidden\">\n                                <img src=\"../assets/images/stickdrop/Stick-Drop-3.png\"\n                                    alt=\"People playing Stick Drop Reaction Game at an indoor event\"\n                                    class=\"w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-700\">\n                            </div>\n                            <div\n                                class=\"absolute inset-0 bg-gradient-to-t from-black/10 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500\">\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <script src=\"https://code.jquery.com/jquery-3.6.0.min.js\"></script>\n    <script src=\"../../assets/components/navigation.js\"></script>\n    <script src=\"../../assets/components/footer.js\"></script>\n\n    <script>\n        // Animate steps on scroll\n        document.addEventListener(\'DOMContentLoaded\', function () {\n            const stepsContainer = document.getElementById(\'booking-steps\');\n            const stepItems = stepsContainer.querySelectorAll(\'.step-item\');\n\n            // Intersection Observer for scroll-triggered animations\n            const observerOptions = {\n                threshold: 0.2,\n                rootMargin: \'0px 0px -50px 0px\'\n            };\n\n            const observer = new IntersectionObserver(function (entries) {\n                entries.forEach(entry => {\n                    if (entry.isIntersecting) {\n                        stepItems.forEach((item, index) => {\n                            setTimeout(() => {\n                                item.classList.add(\'animate\');\n                            }, index * 100);\n                        });\n                        observer.unobserve(entry.target);\n                    }\n                });\n            }, observerOptions);\n\n            if (stepsContainer) {\n                observer.observe(stepsContainer);\n            }\n\n            // Fallback: If IntersectionObserver is not supported, animate immediately\n            if (!window.IntersectionObserver) {\n                stepItems.forEach((item, index) => {\n                    setTimeout(() => {\n                        item.classList.add(\'animate\');\n                    }, index * 100);\n                });\n            }\n        });\n    </script>\n\n    <!-- Accordion Dropdown Menu JavaScript -->\n    <script>\n        $(function () {\n            var Accordion = function (el, multiple) {\n                this.el = el || {};\n                this.multiple = multiple || false;\n\n                // Variables privadas\n                var links = this.el.find(\'.link\');\n                // Evento\n                links.on(\'click\', { el: this.el, multiple: this.multiple }, this.dropdown)\n            }\n\n            Accordion.prototype.dropdown = function (e) {\n                var $el = e.data.el;\n                $this = $(this),\n                    $next = $this.next();\n\n                $next.slideToggle();\n                $this.parent().toggleClass(\'open\');\n\n                if (!e.data.multiple) {\n                    $el.find(\'.submenu\').not($next).slideUp().parent().removeClass(\'open\');\n                };\n            }\n\n            var accordion = new Accordion($(\'#accordion\'), false);\n        });\n    </script>\n    <!-- Load Back to Top Component -->\n    <script src=\"../../assets/components/back-to-top.js\"></script>\n\n</body>', NULL, 'published', NULL, '2025-12-14 00:30:10', '2025-12-14 00:30:10');
INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(62, 'Photo Booth Rental In Aspen,colorado', 'locations-photo-booth-rental-in-aspen-colorado', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Photo Booth Rentals in Aspen, CO | MiHi Entertainment</title>\n    <meta name=\"description\"\n        content=\"Premium photo booth rentals in Aspen, Colorado. From weddings to corporate events, MiHi Entertainment brings cutting-edge technology and unforgettable experiences. Book your Aspen photo booth rental today!\">\n    <meta name=\"keywords\"\n        content=\"photo booth rental Aspen, photo booth Aspen Colorado, event photo booth Aspen, wedding photo booth Aspen, corporate photo booth Aspen, 360 photo booth Aspen, AI photo booth Aspen\">\n    <meta name=\"author\" content=\"MiHi Entertainment\">\n    <meta name=\"robots\" content=\"index, follow\">\n    <link rel=\"canonical\" href=\"https://www.mihiphotobooth.com/locations/photo-booth-rental-in-aspen,colorado.html\">\n\n    <!-- Open Graph / Facebook -->\n    <meta property=\"og:type\" content=\"website\">\n    <meta property=\"og:url\"\n        content=\"https://www.mihiphotobooth.com/locations/photo-booth-rental-in-aspen,colorado.html\">\n    <meta property=\"og:title\" content=\"Photo Booth Rentals in Aspen, CO | MiHi Entertainment\">\n    <meta property=\"og:description\"\n        content=\"Premium photo booth rentals in Aspen, Colorado. Transform your event with cutting-edge technology and unforgettable experiences.\">\n    <meta property=\"og:image\" content=\"https://www.mihiphotobooth.com/assets/images/location/aspen.webp\">\n\n    <!-- Twitter -->\n    <meta property=\"twitter:card\" content=\"summary_large_image\">\n    <meta property=\"twitter:url\"\n        content=\"https://www.mihiphotobooth.com/locations/photo-booth-rental-in-aspen,colorado.html\">\n    <meta property=\"twitter:title\" content=\"Photo Booth Rentals in Aspen, CO | MiHi Entertainment\">\n    <meta property=\"twitter:description\"\n        content=\"Premium photo booth rentals in Aspen, Colorado. Transform your event with cutting-edge technology and unforgettable experiences.\">\n    <meta property=\"twitter:image\" content=\"https://www.mihiphotobooth.com/assets/images/location/aspen.webp\">\n\n    <link rel=\"icon\" type=\"image/svg+xml\" href=\"../assets/images/favicon.svg\">\n\n    <!-- Structured Data -->\n    <script type=\"application/ld+json\">\n    {\n        \"@context\": \"https://schema.org\",\n        \"@type\": \"LocalBusiness\",\n        \"name\": \"MiHi Entertainment - Photo Booth Rentals Aspen\",\n        \"image\": \"https://www.mihiphotobooth.com/assets/images/location/aspen.webp\",\n        \"@id\": \"https://www.mihiphotobooth.com/locations/photo-booth-rental-in-aspen,colorado.html\",\n        \"url\": \"https://www.mihiphotobooth.com/locations/photo-booth-rental-in-aspen,colorado.html\",\n        \"telephone\": \"+1-720-551-6994\",\n        \"priceRange\": \"$$\",\n        \"address\": {\n            \"@type\": \"PostalAddress\",\n            \"addressLocality\": \"Aspen\",\n            \"addressRegion\": \"CO\",\n            \"addressCountry\": \"US\"\n        },\n        \"geo\": {\n            \"@type\": \"GeoCoordinates\",\n            \"latitude\": 39.1911,\n            \"longitude\": -106.8175\n        },\n        \"openingHoursSpecification\": {\n            \"@type\": \"OpeningHoursSpecification\",\n            \"dayOfWeek\": [\n                \"Monday\",\n                \"Tuesday\",\n                \"Wednesday\",\n                \"Thursday\",\n                \"Friday\",\n                \"Saturday\",\n                \"Sunday\"\n            ],\n            \"opens\": \"09:00\",\n            \"closes\": \"18:00\"\n        },\n        \"sameAs\": [\n            \"https://www.mihiphotobooth.com\"\n        ],\n        \"areaServed\": {\n            \"@type\": \"City\",\n            \"name\": \"Aspen\",\n            \"containedIn\": {\n                \"@type\": \"State\",\n                \"name\": \"Colorado\"\n            }\n        },\n        \"serviceType\": \"Photo Booth Rental\",\n        \"description\": \"Premium photo booth rentals in Aspen, Colorado for weddings, corporate events, and special occasions.\"\n    }\n    </script>\n\n    <!-- Tailwind CSS CDN -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <style>\n        /* Azo Sans Font Face Declarations */\n        @font-face {\n            font-family: \'Azo Sans\';\n            src: url(\'../assets/fonts/AzoSans-Regular.woff2\') format(\'woff2\'),\n                url(\'../assets/fonts/AzoSans-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        @font-face {\n            font-family: \'Azo Sans Uber\';\n            src: url(\'../assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\'),\n                url(\'../assets/fonts/AzoSansUber-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        /* Brand Guide: Body Text - Azo Sans Regular */\n        body {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n            overflow-x: hidden;\n            background: #ffffff;\n        }\n\n        p {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n        }\n\n        /* Brand Guide: Headers - Azo Sans Uber (Uppercase) - All Coral */\n        /* Only apply to main content, not footer */\n        main h1, main h2, main h3, main h4, main h5, main h6,\n        .hero-title,\n        .tile-title,\n        .feature-section h2,\n        .booking-text h2,\n        .booking-text h3,\n        .venues-title-section h2,\n        .cta-content h4 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-weight: 400;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            color: #FF4F4F !important;\n            -webkit-font-smoothing: antialiased;\n            -moz-osx-font-smoothing: grayscale;\n        }\n\n        /* Ensure navigation and footer styles are not affected by page CSS */\n        header {\n            position: relative;\n            z-index: 50;\n        }\n\n        footer {\n            position: relative;\n            z-index: 1;\n        }\n\n        /* Protect footer from page CSS overrides */\n        footer,\n        footer * {\n            font-family: inherit !important;\n        }\n\n        footer h1,\n        footer h2,\n        footer h3,\n        footer h4,\n        footer h5,\n        footer h6 {\n            font-family: inherit !important;\n            color: inherit !important;\n            text-transform: none !important;\n            letter-spacing: normal !important;\n            font-weight: inherit !important;\n        }\n\n        footer p,\n        footer span,\n        footer a,\n        footer div {\n            font-family: inherit !important;\n            color: inherit !important;\n        }\n\n        /* Prevent Tailwind from interfering with page-specific styles */\n        .tile-grid,\n        .cta-section,\n        .booking-banner,\n        .feature-section,\n        .map-section {\n            position: relative;\n            z-index: 1;\n        }\n\n        /* Headers already styled above */\n        main h1, main h2, main h3, main h4 {\n            margin: 0;\n        }\n\n        main p {\n            margin: 0;\n            line-height: 1.6;\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n        }\n\n        /* Exclude footer from main content styles */\n        footer h1, footer h2, footer h3, footer h4, footer h5, footer h6 {\n            font-family: inherit !important;\n            color: inherit !important;\n            text-transform: none !important;\n            letter-spacing: normal !important;\n            font-weight: inherit !important;\n            line-height: inherit !important;\n        }\n\n        footer p {\n            font-family: inherit !important;\n            color: inherit !important;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        /* --- SECTION 1: THE TILE GRID (Matches your Screenshot) --- */\n        main {\n            margin: 0;\n            padding: 0;\n        }\n\n        .tile-grid {\n            display: grid !important;\n            grid-template-columns: 1fr 1fr !important;\n            /* 2 Columns */\n            width: 100%;\n        }\n\n        .tile {\n            position: relative;\n            height: 400px;\n            /* Adjust height as needed */\n            background-size: cover !important;\n            background-position: center !important;\n            display: flex !important;\n            flex-direction: column !important;\n            justify-content: center !important;\n            /* Vertically Center text */\n            padding: 40px !important;\n            overflow: hidden;\n        }\n\n        /* Dark Overlay to make text pop */\n        .tile::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background: rgba(0, 0, 0, 0.3);\n            /* Darkens image by 30% */\n            z-index: 1;\n            transition: background 0.3s ease;\n        }\n\n        .tile:hover::before {\n            background: rgba(0, 0, 0, 0.5);\n            /* Darker on hover */\n        }\n\n        .tile-content {\n            position: relative;\n            z-index: 2;\n            color: white;\n            max-width: 90%;\n        }\n\n        .tile-title {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 3rem;\n            font-weight: 400;\n            line-height: 1.2;\n            margin-bottom: 15px;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            color: #FF4F4F !important;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(0, 0, 0, 0.5);\n        }\n\n        .tile-desc {\n            font-family: \'Azo Sans\', sans-serif;\n            font-size: 0.95rem;\n            font-weight: 400;\n            max-width: 500px;\n            color: rgba(255, 255, 255, 0.95);\n            line-height: 1.6;\n        }\n\n        /* Mobile Responsiveness */\n        @media (max-width: 640px) {\n            .tile {\n                height: 300px;\n                padding: 20px !important;\n            }\n\n            .tile-title {\n                font-size: 1.5rem;\n                margin-bottom: 10px;\n            }\n\n            .tile-desc {\n                font-size: 0.85rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .tile-grid {\n                grid-template-columns: 1fr;\n                /* Stack on mobile */\n            }\n\n            .tile {\n                height: 350px;\n                padding: 30px !important;\n            }\n\n            .tile-title {\n                font-size: 2rem;\n            }\n        }\n\n        /* --- SECTION 2: CTA SPLIT (About Us) --- */\n        .cta-section {\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            min-height: 400px;\n        }\n\n        @media (max-width: 640px) {\n            .cta-section {\n                grid-template-columns: 1fr;\n                min-height: auto;\n            }\n\n            .cta-content {\n                padding: 30px 20px;\n            }\n\n            .cta-content h4 {\n                font-size: 1rem;\n                margin-bottom: 12px;\n            }\n\n            .cta-content p {\n                font-size: 0.9rem;\n                margin-bottom: 20px;\n                line-height: 1.6;\n            }\n\n            .btn {\n                padding: 12px 20px;\n                font-size: 0.75rem;\n                width: 100%;\n                text-align: center;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .cta-section {\n                grid-template-columns: 1fr;\n            }\n\n            .cta-content {\n                padding: 40px 30px;\n            }\n        }\n\n        .cta-image {\n            width: 100%;\n            background-image: url(\'../assets/images/location/snow-globe.webp\');\n            background-size: cover;\n            background-position: center;\n        }\n\n        .cta-content {\n            width: 100%;\n            background: #f4f4f4;\n            display: flex;\n            flex-direction: column;\n            justify-content: center;\n            padding: 60px;\n        }\n\n        .cta-content h4 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 1.25rem;\n            font-weight: 400;\n            letter-spacing: 0.02em;\n            margin-bottom: 15px;\n            color: #FF4F4F;\n            text-transform: uppercase;\n            line-height: 1.2;\n        }\n\n        .cta-content p {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n            margin-bottom: 25px;\n            line-height: 1.6;\n        }\n\n        .btn {\n            display: inline-block;\n            border: 2px solid #000;\n            padding: 10px 25px;\n            text-transform: uppercase;\n            font-weight: bold;\n            color: #000;\n            font-size: 0.8rem;\n            width: fit-content;\n            transition: all 0.3s ease;\n        }\n\n        .btn:hover {\n            background: #000;\n            color: white;\n        }\n\n        /* --- SECTION 3: CTA SECTION --- */\n        .booking-banner {\n            position: relative;\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n            justify-content: center;\n            padding: 80px 20px;\n            background: linear-gradient(135deg, #220834 0%, #1a0b44 50%, #051637 100%);\n            text-align: center;\n            overflow: hidden;\n        }\n\n        .booking-banner::before {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: radial-gradient(circle at center, rgba(255, 255, 255, 0.1), transparent 70%);\n            pointer-events: none;\n        }\n\n        .booking-banner img {\n            max-width: 100%;\n            height: auto;\n            width: 300px;\n            margin-bottom: 30px;\n            position: relative;\n            z-index: 2;\n        }\n\n        .booking-text {\n            text-align: center;\n            position: relative;\n            z-index: 2;\n        }\n\n        .booking-text h2 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 1.2rem;\n            font-weight: 400;\n            color: #FF4F4F !important;\n            margin-bottom: 10px;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(255, 79, 79, 0.5);\n        }\n\n        .booking-text h3 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 3rem;\n            font-weight: 400;\n            color: #FF4F4F !important;\n            margin-bottom: 30px;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(255, 79, 79, 0.5);\n        }\n\n        .booking-banner .btn {\n            background: #FF4F4F;\n            color: white;\n            border: none;\n            padding: 18px 40px;\n            font-size: 1rem;\n            font-weight: 600;\n            text-transform: uppercase;\n            letter-spacing: 1px;\n            border-radius: 50px;\n            box-shadow: 0 10px 25px rgba(255, 79, 79, 0.4);\n            transition: all 0.3s ease;\n            text-decoration: none;\n            display: inline-block;\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        .booking-banner .btn:hover {\n            background: #e63939;\n            transform: translateY(-3px);\n            box-shadow: 0 15px 35px rgba(255, 79, 79, 0.5);\n        }\n\n        .booking-banner .btn-call {\n            background: transparent;\n            color: white;\n            border: 2px solid white;\n            padding: 18px 40px;\n            font-size: 1rem;\n            font-weight: 600;\n            text-transform: uppercase;\n            letter-spacing: 1px;\n            border-radius: 50px;\n            transition: all 0.3s ease;\n            cursor: pointer;\n            display: inline-flex;\n            align-items: center;\n            gap: 8px;\n        }\n\n        .booking-banner .btn-call:hover {\n            background: white;\n            color: #220834;\n            transform: translateY(-3px);\n            box-shadow: 0 10px 25px rgba(255, 255, 255, 0.3);\n        }\n\n        .booking-banner .btn-call svg {\n            width: 20px;\n            height: 20px;\n        }\n\n        .booking-banner .btn-group {\n            display: flex;\n            flex-direction: column;\n            gap: 15px;\n            align-items: center;\n            justify-content: center;\n            width: 100%;\n        }\n\n        @media (min-width: 640px) {\n            .booking-banner .btn-group {\n                flex-direction: row;\n                gap: 20px;\n                justify-content: center;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .booking-banner {\n                padding: 50px 20px;\n            }\n\n            .booking-text h2 {\n                font-size: 0.9rem;\n                margin-bottom: 8px;\n            }\n\n            .booking-text h3 {\n                font-size: 1.8rem;\n                margin-bottom: 20px;\n                line-height: 1.2;\n            }\n\n            .booking-banner img {\n                width: 200px;\n                margin-bottom: 20px;\n            }\n\n            .booking-banner .btn,\n            .booking-banner .btn-call {\n                padding: 14px 28px;\n                font-size: 0.875rem;\n                width: 100%;\n                max-width: 280px;\n            }\n        }\n\n        @media (min-width: 768px) {\n            .booking-banner {\n                padding: 100px 20px;\n            }\n\n            .booking-text h2 {\n                font-size: 1.4rem;\n            }\n\n            .booking-text h3 {\n                font-size: 4rem;\n            }\n\n            .booking-banner img {\n                width: 350px;\n            }\n        }\n\n        /* --- SECTION 4: AI BOOTH FEATURE --- */\n        .feature-section {\n            position: relative;\n            min-height: 600px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            background-size: cover;\n            background-position: center;\n            background-repeat: no-repeat;\n            overflow: hidden;\n            margin: 0 auto;\n        }\n\n        .feature-section::before {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: rgba(0, 0, 0, 0.4);\n            z-index: 1;\n        }\n\n        .feature-section img {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n            z-index: 0;\n        }\n\n        .feature-section .feature-content {\n            position: relative;\n            z-index: 2;\n            text-align: center;\n            padding: 80px 20px;\n            max-width: 1000px;\n            margin: 0 auto;\n            width: 100%;\n        }\n\n        .feature-section h2 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 1.2rem;\n            color: #FF4F4F !important;\n            margin-bottom: 10px;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            font-weight: 400;\n            line-height: 1.2;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(255, 79, 79, 0.5);\n        }\n\n        .feature-section h2:last-of-type {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 4rem;\n            font-weight: 400;\n            margin-bottom: 30px;\n            color: #FF4F4F !important;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(255, 79, 79, 0.5);\n        }\n\n        .feature-section p {\n            font-family: \'Azo Sans\', sans-serif;\n            color: rgba(255, 255, 255, 0.95);\n            margin-bottom: 40px;\n            font-size: 1.1rem;\n            line-height: 1.6;\n            max-width: 900px;\n            margin-left: auto;\n            margin-right: auto;\n        }\n\n        .feature-section .btn-learn-more {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            gap: 10px;\n            padding: 18px 40px;\n            background: #FF4F4F;\n            color: white;\n            border-radius: 50px;\n            font-weight: 600;\n            text-decoration: none;\n            transition: all 0.3s ease;\n            box-shadow: 0 10px 30px rgba(255, 79, 79, 0.5);\n            text-transform: uppercase;\n            letter-spacing: 2px;\n            font-size: 1rem;\n            border: none;\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        .feature-section .btn-learn-more:hover {\n            background: #e63939;\n            transform: translateY(-3px);\n            box-shadow: 0 15px 40px rgba(255, 79, 79, 0.6);\n        }\n\n        .feature-section .btn-learn-more svg {\n            width: 20px;\n            height: 20px;\n            transition: transform 0.3s ease;\n        }\n\n        .feature-section .btn-learn-more:hover svg {\n            transform: translateX(5px);\n        }\n\n        @media (max-width: 640px) {\n            .feature-section {\n                min-height: 500px;\n            }\n\n            .feature-section .feature-content {\n                padding: 50px 20px;\n            }\n\n            .feature-section h2 {\n                font-size: 0.9rem;\n                letter-spacing: 2px;\n            }\n\n            .feature-section h2:last-of-type {\n                font-size: 2rem;\n                margin-bottom: 20px;\n                line-height: 1.2;\n            }\n\n            .feature-section p {\n                font-size: 0.95rem;\n                margin-bottom: 30px;\n                line-height: 1.6;\n            }\n\n            .feature-section .btn-learn-more {\n                padding: 14px 28px;\n                font-size: 0.875rem;\n                letter-spacing: 1px;\n            }\n        }\n\n        @media (min-width: 768px) {\n            .feature-section {\n                min-height: 700px;\n            }\n\n            .feature-section .feature-content {\n                padding: 100px 40px;\n            }\n\n            .feature-section h2 {\n                font-size: 1.4rem;\n            }\n\n            .feature-section h2:last-of-type {\n                font-size: 5rem;\n            }\n\n            .feature-section p {\n                font-size: 1.2rem;\n            }\n        }\n\n        /* --- GOOGLE MAPS SECTION --- */\n        /* --- VENUES TITLE SECTION --- */\n        .venues-title-section {\n            background: white;\n            padding: 80px 20px;\n            text-align: center;\n        }\n\n        .venues-title-section h2 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 2.5rem;\n            font-weight: 400;\n            color: #FF4F4F;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            margin-bottom: 30px;\n        }\n\n        .venues-title-section .btn-venues {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            padding: 18px 40px;\n            background: #FF4F4F;\n            color: white;\n            border-radius: 8px;\n            font-weight: 600;\n            text-decoration: none;\n            text-transform: uppercase;\n            letter-spacing: 1px;\n            font-size: 1rem;\n            transition: all 0.3s ease;\n            box-shadow: 0 4px 15px rgba(255, 79, 79, 0.3);\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        .venues-title-section .btn-venues:hover {\n            background: #e63939;\n            transform: translateY(-2px);\n            box-shadow: 0 6px 20px rgba(255, 79, 79, 0.4);\n        }\n\n        @media (max-width: 640px) {\n            .venues-title-section {\n                padding: 50px 20px;\n            }\n\n            .venues-title-section h2 {\n                font-size: 1.5rem;\n                line-height: 1.3;\n                margin-bottom: 20px;\n            }\n\n            .venues-title-section .btn-venues {\n                padding: 14px 28px;\n                font-size: 0.875rem;\n                width: 100%;\n                max-width: 280px;\n            }\n        }\n\n        @media (min-width: 768px) {\n            .venues-title-section {\n                padding: 100px 40px;\n            }\n\n            .venues-title-section h2 {\n                font-size: 3.5rem;\n            }\n        }\n\n        .map-section {\n            width: 100%;\n            height: 500px;\n            margin: 0;\n            padding: 0;\n            overflow: hidden;\n        }\n\n        .map-section iframe {\n            width: 100%;\n            height: 100%;\n            border: none;\n            display: block;\n        }\n\n        @media (max-width: 640px) {\n            .map-section {\n                height: 400px;\n            }\n        }\n\n        @media (min-width: 768px) {\n            .map-section {\n                height: 600px;\n            }\n        }\n\n        /* --- HERO SECTION --- */\n        .hero-section {\n            position: relative;\n            overflow: hidden;\n            background-image: url(\'../assets/images/location/aspen.webp\');\n            background-size: cover;\n            background-position: center;\n            background-repeat: no-repeat;\n            color: white;\n            height: 100vh;\n            min-height: 100vh;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n        }\n\n        .hero-section::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background: rgba(0, 0, 0, 0.7);\n            z-index: 1;\n        }\n\n        .hero-ambient {\n            position: absolute;\n            inset: 0;\n            pointer-events: none;\n        }\n\n        .hero-ambient-glow-1 {\n            position: absolute;\n            top: 10%;\n            left: 50%;\n            transform: translateX(-50%);\n            width: 90%;\n            height: 100%;\n            background: radial-gradient(circle at top, rgba(255, 255, 255, 0.15), transparent 60%);\n        }\n\n        .hero-ambient-glow-2 {\n            position: absolute;\n            top: -6rem;\n            left: 2.5rem;\n            width: 10rem;\n            height: 10rem;\n            border-radius: 50%;\n            background: rgba(236, 72, 153, 0.2);\n            filter: blur(3rem);\n        }\n\n        .hero-ambient-glow-3 {\n            position: absolute;\n            bottom: 2.5rem;\n            right: 2.5rem;\n            width: 13rem;\n            height: 13rem;\n            border-radius: 50%;\n            background: rgba(96, 165, 250, 0.2);\n            filter: blur(120px);\n        }\n\n        .hero-content {\n            position: relative;\n            z-index: 10;\n            text-align: center;\n            padding: 5rem 1.5rem;\n            max-width: 90rem;\n            margin: 0 auto;\n        }\n\n        .hero-title {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 3rem;\n            font-weight: 400;\n            line-height: 1.2;\n            margin-bottom: 2rem;\n            text-transform: uppercase;\n            color: #FF4F4F !important;\n            letter-spacing: 0.02em;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(255, 79, 79, 0.5);\n        }\n\n        .hero-subtitle {\n            font-family: \'Azo Sans\', sans-serif;\n            font-size: 1.1rem;\n            line-height: 1.6;\n            color: #ffffff;\n            margin-bottom: 2rem;\n            max-width: 1200px;\n            margin-left: auto;\n            margin-right: auto;\n            text-shadow: 1px 1px 6px rgba(0, 0, 0, 0.8), 0 0 15px rgba(0, 0, 0, 0.4);\n        }\n\n        .hero-cta {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            padding: 1rem 2rem;\n            background: #FF4F4F;\n            color: white;\n            border-radius: 9999px;\n            font-weight: 600;\n            text-decoration: none;\n            transition: all 0.3s ease;\n            box-shadow: 0 10px 25px rgba(255, 79, 79, 0.4);\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        .hero-cta:hover {\n            background: #e63939;\n            transform: translateY(-2px);\n            box-shadow: 0 15px 35px rgba(255, 79, 79, 0.5);\n        }\n\n        .hero-cta-call {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            gap: 8px;\n            padding: 1rem 2rem;\n            background: transparent;\n            color: white;\n            border: 2px solid white;\n            border-radius: 9999px;\n            font-weight: 600;\n            text-decoration: none;\n            transition: all 0.3s ease;\n            cursor: pointer;\n        }\n\n        .hero-cta-call:hover {\n            background: white;\n            color: #220834;\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(255, 255, 255, 0.3);\n        }\n\n        .hero-cta-call svg {\n            width: 20px;\n            height: 20px;\n        }\n\n        .hero-cta-group {\n            display: flex;\n            flex-direction: column;\n            gap: 15px;\n            align-items: center;\n            justify-content: center;\n            width: 100%;\n        }\n\n        @media (min-width: 640px) {\n            .hero-cta-group {\n                flex-direction: row;\n                gap: 20px;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .hero-section {\n                height: 70vh;\n                min-height: 500px;\n            }\n\n            .hero-content {\n                padding: 3rem 1rem;\n            }\n\n            .hero-title {\n                font-size: 1.75rem;\n                margin-bottom: 1.5rem;\n                line-height: 1.2;\n            }\n\n            .hero-subtitle {\n                font-size: 0.95rem;\n                margin-bottom: 1.5rem;\n                line-height: 1.5;\n            }\n\n            .hero-cta,\n            .hero-cta-call {\n                padding: 12px 24px;\n                font-size: 0.875rem;\n                width: 100%;\n                max-width: 280px;\n            }\n\n            .hero-cta-group {\n                width: 100%;\n                padding: 0 1rem;\n            }\n        }\n\n        @media (min-width: 768px) {\n            .hero-section {\n                height: 100vh;\n                min-height: 100vh;\n            }\n\n            .hero-content {\n                padding: 8rem 1.5rem;\n            }\n\n            .hero-title {\n                font-size: 4.5rem;\n            }\n\n            .hero-subtitle {\n                font-size: 1.2rem;\n                line-height: 1.5;\n            }\n        }\n\n        @media (min-width: 1024px) {\n            .hero-title {\n                font-size: 5rem;\n            }\n        }\n\n        /* Navigation Contact Us Button Fix */\n        header .btn-primary,\n        nav .btn-primary,\n        .btn-primary {\n            background: #FF4F4F !important;\n            background-color: #FF4F4F !important;\n            color: #ffffff !important;\n            border: none;\n            padding: 0.75rem 1.5rem;\n            border-radius: 9999px;\n            font-weight: 600;\n            text-decoration: none;\n            display: inline-block;\n            transition: all 0.3s ease;\n            box-shadow: 0 4px 6px rgba(255, 79, 79, 0.3);\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        header .btn-primary:hover,\n        nav .btn-primary:hover,\n        .btn-primary:hover {\n            background: #e63939 !important;\n            background-color: #e63939 !important;\n            transform: translateY(-2px);\n            box-shadow: 0 6px 12px rgba(255, 79, 79, 0.4);\n        }\n\n        header .btn-primary:active,\n        nav .btn-primary:active,\n        .btn-primary:active {\n            transform: translateY(0);\n        }\n    </style>\n</head>\n\n<body>\n    <!-- Navigation will be loaded by navigation.js -->\n    <script src=\"../assets/components/navigation.js\"></script>\n\n    <main>\n        <!-- Hero Section -->\n        <section class=\"hero-section\">\n            <!-- Ambient elements -->\n            <div class=\"hero-ambient\">\n                <div class=\"hero-ambient-glow-1\"></div>\n                <div class=\"hero-ambient-glow-2\"></div>\n                <div class=\"hero-ambient-glow-3\"></div>\n            </div>\n\n            <div class=\"hero-content\">\n                <h1 class=\"hero-title\">\n                    PHOTO BOOTH RENTALS<br><span style=\"color: #18F1E1;\">IN ASPEN, CO</span>\n                </h1>\n                <p class=\"hero-subtitle\">\n                    Seeking an unforgettable and engaging experience for your upcoming event in Aspen, CO? Look no\n                    further than MiHi Entertainment! We prioritize custom branding and maximizing ROI for our agency\n                    partners as industry experts, ensuring a seamless and memorable experience for guests. Whether it\'s\n                    a wedding or corporate event, our services are perfect for any occasion where you want the best\n                    outcome possible. Trust us to be your reliable partner for your Aspen Photo Booth Rental.\n                </p>\n                <div class=\"flex flex-col sm:flex-row gap-4 sm:gap-6 justify-center items-center px-4\">\n                    <a href=\"../contact-us.html\"\n                        class=\"group relative inline-flex items-center gap-2 sm:gap-3 text-white px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg  shadow-2xl hover:shadow-[#FF4F4F]/50 transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 overflow-hidden w-full sm:w-auto justify-center\"\n                        style=\"background: #FF4F4F;\">\n                        <span class=\"relative z-10\">Get Your Quote</span>\n                    </a>\n                    <button type=\"button\" data-click-to-call data-call-text=\"Call Us\"\n                        class=\"group inline-flex items-center gap-2 sm:gap-3 px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg  backdrop-blur-md bg-white/10 border-2 shadow-xl hover:shadow-2xl transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 text-white w-full sm:w-auto justify-center cursor-pointer\"\n                        style=\"border-color: rgba(24, 241, 225, 0.5);\"\n                        onmouseover=\"this.style.borderColor=\'rgba(24, 241, 225, 0.7)\'; this.style.background=\'rgba(24, 241, 225, 0.2)\';\"\n                        onmouseout=\"this.style.borderColor=\'rgba(24, 241, 225, 0.5)\'; this.style.background=\'rgba(255, 255, 255, 0.1)\';\">\n                        <svg class=\"w-4 h-4 sm:w-5 sm:h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                d=\"M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498A1 1 0 0121 17.72V21a2 2 0 01-2 2h-1C9.716 23 3 16.284 3 8V7a2 2 0 012-2z\">\n                            </path>\n                        </svg>\n                        <span>Call Us</span>\n                    </button>\n                </div>\n            </div>\n        </section>\n\n        <section class=\"tile-section\">\n            <div class=\"container mx-auto px-4 sm:px-6 py-12 md:py-16\">\n                <div class=\"text-center mb-10 md:mb-16\">\n                    <p class=\"text-2xl sm:text-3xl md:text-4xl font-light mb-4 md:mb-6 tracking-[0.2em]\" style=\"font-family: \'Azo Sans\', sans-serif; color: #1F1F1F; opacity: 0.7;\">\n                        OUR TOP</p>\n                    <h2 class=\"text-3xl sm:text-4xl md:text-5xl lg:text-6xl mb-4 md:mb-6\" style=\"font-family: \'Azo Sans Uber\', sans-serif; font-weight: 400; color: #FF4F4F; text-transform: uppercase; letter-spacing: 0.02em; line-height: 1.2;\">\n                        Aspen Photo Booth Services\n                    </h2>\n                    <p class=\"text-lg md:text-xl max-w-3xl mx-auto\" style=\"font-family: \'Azo Sans\', sans-serif; color: #1F1F1F; line-height: 1.6;\">\n                        Explore our wide range of premium photo booth rentals available in Aspen, Colorado\n                    </p>\n                </div>\n            </div>\n        </section>\n\n        <div class=\"tile-grid\">\n\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-1.webp\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">MiHi<br>Photo Booth</div>\n                    <p class=\"tile-desc\">Our sleek and minimal Photo Booth Rental is the top choice for any event. With\n                        custom overlays, booth wraps, backdrops, and full sets.</p>\n                </div>\n            </div>\n\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-2.webp\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">360<br>Photo Booth</div>\n                    <p class=\"tile-desc\">With our 360 booth, your guests will enjoy a photo experience like no other.\n                        Custom branding and social sharing features make it perfect.</p>\n                </div>\n            </div>\n\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-3.webp\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">Vogue<br>Photo Booth</div>\n                    <p class=\"tile-desc\">Make your event one that guests will never forget with our Vogue Booth! Plenty\n                        of room to show off your star quality.</p>\n                </div>\n            </div>\n\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-4.webp\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">Photo<br>Mosaic Wall</div>\n                    <p class=\"tile-desc\">Make your mark at your next event with our Photo Mosaic Wall, which transforms\n                        your brand or image into a stunning mosaic.</p>\n                </div>\n            </div>\n\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-5.gif\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">Bullet-Time<br>Array Booth</div>\n                    <p class=\"tile-desc\">Looking for a photo booth that will make your event stand out? Our Bullet-Time\n                        Photo Array Booth is the answer.</p>\n                </div>\n            </div>\n\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-6.gif\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">Slow-Motion<br>Photo Booth</div>\n                    <p class=\"tile-desc\">Create lasting memories that guests will cherish, with shareable slow-motion\n                        videos that capture every special moment.</p>\n                </div>\n            </div>\n\n            <div class=\"tile\" style=\"background-image: url(\'../assets/video/glambot/glambot-hero.webp\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">GLAMBOT<br>Photo Booth</div>\n                    <p class=\"tile-desc\">Red carpet experience with cinematic slow-motion videos. Our GlamBot captures\n                        stunning, ultra-smooth slow-motion content that makes every guest feel like a celebrity.</p>\n                </div>\n            </div>\n\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-8.webp\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">Roaming<br>Photo Booth</div>\n                    <p class=\"tile-desc\">You don\'t have to worry about missing any memorable moments. Our mobile booth\n                        lets you capture it all on the go!</p>\n                </div>\n            </div>\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-9.gif\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">GREEN SCREEN<br>Photo Booth</div>\n                    <p class=\"tile-desc\">With our Green Screen Booth, the possibilities are endless. Let your guests\n                        choose their own backgrounds and create personalized photos that capture the excitement of your\n                        event.</p>\n                </div>\n            </div>\n\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-10.webp\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">NAME BADGE<br>Photo Booth</div>\n                    <p class=\"tile-desc\">You don\'t have to worry about missing any memorable moments. Our mobile booth\n                        lets you capture it all on the go!</p>\n                </div>\n            </div>\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-11.gif\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">VIDEO TESTIMONIAL<br>Photo Booth</div>\n                    <p class=\"tile-desc\">Make a lasting impression on your guests with our Video Testimonial Booth! It\'s\n                        a great way to gather valuable insights and showcase the impact of your event or product.</p>\n                </div>\n            </div>\n\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-12.webp\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">ADDITIONAL<br>BRANDING OPTIONS</div>\n                    <p class=\"tile-desc\">You don\'t have to worry about missing any memorable moments. Our mobile booth\n                        lets you capture it all on the go!</p>\n                </div>\n            </div>\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-13.webp\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">EVENT<br>PHOTOGRAPHY</div>\n                    <p class=\"tile-desc\">Want to make sure your event is perfectly captured? Our team of expert\n                        photographers is ready to help! With top-of-the-line equipment and a sharp eye for detail, we\'ll\n                        capture every moment of your special occasion, creating beautiful and lasting memories for you\n                        to cherish. </p>\n                </div>\n            </div>\n\n            <div class=\"tile\" style=\"background-image: url(\'../assets/images/location/product-14.gif\');\">\n                <div class=\"tile-content\">\n                    <div class=\"tile-title\">VIRTUAL<br>Photo Booth</div>\n                    <p class=\"tile-desc\">You don\'t have to worry about missing any memorable moments. Our mobile booth\n                        lets you capture it all on the go!</p>\n                </div>\n            </div>\n        </div>\n        <!-- Local SEO Content Section -->\n        <section class=\"cta-section\">\n            <div class=\"cta-image\"></div>\n            <div class=\"cta-content\">\n                <h4>Why Choose MiHi Entertainment for Your Aspen Photo Booth Rental?</h4>\n                <p>Aspen is renowned for its world-class venues, breathtaking mountain scenery, and exclusive events\n                    year-round. Whether you\'re planning a luxury wedding at one of Aspen\'s premier mountain resorts, a\n                    high-end corporate event, or an elegant celebration in this iconic Colorado destination, our photo\n                    booth rentals add the perfect touch of sophistication and entertainment.</p>\n                <p>We serve all of Aspen and the surrounding Roaring Fork Valley, including Snowmass Village, Basalt,\n                    and nearby mountain communities. Our team understands the unique needs of Aspen\'s upscale events and\n                    delivers exceptional service with cutting-edge technology that matches the premium standards of this\n                    world-famous destination.</p>\n                <a href=\"../contact-us.html\" class=\"btn\">Get Your Quote</a>\n            </div>\n        </section>\n\n\n        <div class=\"venues-title-section\">\n            <h2>MOUNTAIN VENUES: <br> <span style=\"color: #18F1E1;\">OUR RECOMMENDED VENUES IN ASPEN</span></h2>\n            <a href=\"#map\" class=\"btn-venues\">VIEW THE VENUES NOW</a>\n        </div>\n        <div class=\"feature-section\">\n            <img src=\"../assets/images/location/ai-bg.webp\" alt=\"AI Photo Booth Rental in Aspen, Colorado\">\n            <div class=\"feature-content\">\n                <h2 style=\"color: #18F1E1 !important;\">CHECK OUT OUR</h2>\n                <h2>AI PHOTO BOOTH</h2>\n                <p>Our revolutionary AI Photo Booth rentals are designed to capture the essence of any event with\n                    unparalleled precision. Our photo booths effortlessly produce high-quality photos, while our\n                    dedicated team works behind the scenes to process them swiftly.</p>\n                <a href=\"../product/ai-photo-booth.html\" class=\"btn-learn-more\"\n                    aria-label=\"Learn more about AI Photo Booth\">\n                    Learn More\n                    <svg fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\">\n                        <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M17 8l4 4m0 0l-4 4m4-4H3\" />\n                    </svg>\n                </a>\n            </div>\n        </div>\n\n        <div class=\"map-section\" id=\"map\">\n            <iframe title=\"Google Maps - Aspen, Colorado\" width=\"100%\" height=\"100%\" style=\"border:0\" loading=\"lazy\"\n                allowfullscreen=\"\" referrerpolicy=\"no-referrer-when-downgrade\"\n                src=\"https://www.google.com/maps?q=Aspen,+Colorado&output=embed\">\n            </iframe>\n        </div>\n\n        <div class=\"booking-banner\">\n            <div class=\"booking-text\">\n                <h2 style=\"color: #18F1E1 !important;\">Ready to Book Your Photo Booth?</h2>\n                <h3>Get Your Quote Today</h3>\n                <div class=\"flex flex-col sm:flex-row gap-4 sm:gap-6 justify-center items-center px-4\">\n                    <a href=\"../contact-us.html\"\n                        class=\"group relative inline-flex items-center gap-2 sm:gap-3 text-white px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg  shadow-2xl hover:shadow-[#FF4F4F]/50 transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 overflow-hidden w-full sm:w-auto justify-center\"\n                        style=\"background: #FF4F4F;\">\n                        <span class=\"relative z-10\">Get Your Quote</span>\n                    </a>\n                    <button type=\"button\" data-click-to-call data-call-text=\"Call Us\"\n                        class=\"group inline-flex items-center gap-2 sm:gap-3 px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg  backdrop-blur-md bg-white/10 border-2 shadow-xl hover:shadow-2xl transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 text-white w-full sm:w-auto justify-center cursor-pointer\"\n                        style=\"border-color: rgba(24, 241, 225, 0.5);\"\n                        onmouseover=\"this.style.borderColor=\'rgba(24, 241, 225, 0.7)\'; this.style.background=\'rgba(24, 241, 225, 0.2)\';\"\n                        onmouseout=\"this.style.borderColor=\'rgba(24, 241, 225, 0.5)\'; this.style.background=\'rgba(255, 255, 255, 0.1)\';\">\n                        <svg class=\"w-4 h-4 sm:w-5 sm:h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                d=\"M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498A1 1 0 0121 17.72V21a2 2 0 01-2 2h-1C9.716 23 3 16.284 3 8V7a2 2 0 012-2z\">\n                            </path>\n                        </svg>\n                        <span>Call Us</span>\n                    </button>\n                </div>\n            </div>\n        </div>\n\n    </main>\n\n    <!-- Footer -->\n    <script src=\"../assets/components/footer.js\"></script>\n    <script src=\"../assets/js/phone-protection.js\"></script>\n    <!-- Load Back to Top Component -->\n    <script src=\"../../assets/components/back-to-top.js\"></script>\n\n\n</body>', NULL, 'published', NULL, '2025-12-14 00:30:10', '2025-12-14 00:30:10');
INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(63, 'Photo Booth Rental In Baton Rouge,louisiana', 'locations-photo-booth-rental-in-baton-rouge-louisiana', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Photo Booth Rentals in Baton Rouge, LA | MiHi Entertainment</title>\n    <meta name=\"description\"\n        content=\"Premium photo booth rentals in Baton Rouge, Louisiana. From Mardi Gras celebrations to LSU events, MiHi Entertainment brings cutting-edge technology and unforgettable experiences. Book your Baton Rouge photo booth rental today!\">\n    <meta name=\"keywords\"\n        content=\"photo booth rental Baton Rouge, photo booth Baton Rouge Louisiana, event photo booth Baton Rouge, wedding photo booth Baton Rouge, corporate photo booth Baton Rouge, 360 photo booth Baton Rouge, AI photo booth Baton Rouge, East Baton Rouge Parish photo booth, LSU photo booth\">\n    <meta name=\"author\" content=\"MiHi Entertainment\">\n    <meta name=\"robots\" content=\"index, follow\">\n    <link rel=\"canonical\"\n        href=\"https://www.mihiphotobooth.com/locations/photo-booth-rental-in-baton-rouge,louisiana.html\">\n\n    <!-- Open Graph / Facebook -->\n    <meta property=\"og:type\" content=\"website\">\n    <meta property=\"og:url\"\n        content=\"https://www.mihiphotobooth.com/locations/photo-booth-rental-in-baton-rouge,louisiana.html\">\n    <meta property=\"og:title\" content=\"Photo Booth Rentals in Baton Rouge, LA | MiHi Entertainment\">\n    <meta property=\"og:description\"\n        content=\"Premium photo booth rentals in Baton Rouge, Louisiana. Transform your event with cutting-edge technology and unforgettable experiences.\">\n    <meta property=\"og:image\" content=\"https://www.mihiphotobooth.com/assets/images/location/baton-rouge.webp\">\n\n    <!-- Twitter -->\n    <meta property=\"twitter:card\" content=\"summary_large_image\">\n    <meta property=\"twitter:url\"\n        content=\"https://www.mihiphotobooth.com/locations/photo-booth-rental-in-baton-rouge,louisiana.html\">\n    <meta property=\"twitter:title\" content=\"Photo Booth Rentals in Baton Rouge, LA | MiHi Entertainment\">\n    <meta property=\"twitter:description\"\n        content=\"Premium photo booth rentals in Baton Rouge, Louisiana. Transform your event with cutting-edge technology and unforgettable experiences.\">\n    <meta property=\"twitter:image\" content=\"https://www.mihiphotobooth.com/assets/images/location/baton-rouge.webp\">\n\n    <link rel=\"icon\" type=\"image/svg+xml\" href=\"../assets/images/favicon.svg\">\n\n    <!-- Structured Data -->\n    <script type=\"application/ld+json\">\n    {\n        \"@context\": \"https://schema.org\",\n        \"@type\": \"LocalBusiness\",\n        \"name\": \"MiHi Entertainment - Photo Booth Rentals Baton Rouge\",\n        \"image\": \"https://www.mihiphotobooth.com/assets/images/location/baton-rouge.webp\",\n        \"@id\": \"https://www.mihiphotobooth.com/locations/photo-booth-rental-in-baton-rouge,louisiana.html\",\n        \"url\": \"https://www.mihiphotobooth.com/locations/photo-booth-rental-in-baton-rouge,louisiana.html\",\n        \"telephone\": \"+1-720-551-6994\",\n        \"priceRange\": \"$$\",\n        \"address\": {\n            \"@type\": \"PostalAddress\",\n            \"addressLocality\": \"Baton Rouge\",\n            \"addressRegion\": \"LA\",\n            \"addressCountry\": \"US\"\n        },\n        \"geo\": {\n            \"@type\": \"GeoCoordinates\",\n            \"latitude\": 30.4515,\n            \"longitude\": -91.1871\n        },\n        \"openingHoursSpecification\": {\n            \"@type\": \"OpeningHoursSpecification\",\n            \"dayOfWeek\": [\n                \"Monday\",\n                \"Tuesday\",\n                \"Wednesday\",\n                \"Thursday\",\n                \"Friday\",\n                \"Saturday\",\n                \"Sunday\"\n            ],\n            \"opens\": \"09:00\",\n            \"closes\": \"18:00\"\n        },\n        \"sameAs\": [\n            \"https://www.mihiphotobooth.com\"\n        ],\n        \"areaServed\": {\n            \"@type\": \"City\",\n            \"name\": \"Baton Rouge\",\n            \"containedIn\": {\n                \"@type\": \"State\",\n                \"name\": \"Louisiana\"\n            }\n        },\n        \"serviceType\": \"Photo Booth Rental\",\n        \"description\": \"Premium photo booth rentals in Baton Rouge, Louisiana for Mardi Gras celebrations, LSU events, corporate events, and special occasions in East Baton Rouge Parish.\"\n    }\n    </script>\n\n    <!-- Tailwind CSS CDN -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <style>\n        /* Azo Sans Font Face Declarations */\n        @font-face {\n            font-family: \'Azo Sans\';\n            src: url(\'../assets/fonts/AzoSans-Regular.woff2\') format(\'woff2\'),\n                url(\'../assets/fonts/AzoSans-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        @font-face {\n            font-family: \'Azo Sans Uber\';\n            src: url(\'../assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\'),\n                url(\'../assets/fonts/AzoSansUber-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        /* Brand Guide: Body Text - Azo Sans Regular */\n        body {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n            overflow-x: hidden;\n            background: #ffffff;\n        }\n\n        p {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n        }\n\n        /* Brand Guide: Headers - Azo Sans Uber (Uppercase) - All Coral */\n        /* Only apply to main content, not footer */\n        main h1, main h2, main h3, main h4, main h5, main h6,\n        .hero-title,\n        .tile-title,\n        .feature-section h2,\n        .booking-text h2,\n        .booking-text h3,\n        .venues-title-section h2,\n        .cta-content h4 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-weight: 400;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            color: #FF4F4F !important;\n            -webkit-font-smoothing: antialiased;\n            -moz-osx-font-smoothing: grayscale;\n        }\n\n        /* Ensure navigation and footer styles are not affected by page CSS */\n        header {\n            position: relative;\n            z-index: 50;\n        }\n\n        footer {\n            position: relative;\n            z-index: 1;\n        }\n\n        /* Protect footer from page CSS overrides */\n        footer,\n        footer * {\n            font-family: inherit !important;\n        }\n\n        footer h1,\n        footer h2,\n        footer h3,\n        footer h4,\n        footer h5,\n        footer h6 {\n            font-family: inherit !important;\n            color: inherit !important;\n            text-transform: none !important;\n            letter-spacing: normal !important;\n            font-weight: inherit !important;\n        }\n\n        footer p,\n        footer span,\n        footer a,\n        footer div {\n            font-family: inherit !important;\n            color: inherit !important;\n        }\n\n        /* Prevent Tailwind from interfering with page-specific styles */\n        .tile-grid,\n        .cta-section,\n        .booking-banner,\n        .feature-section,\n        .map-section {\n            position: relative;\n            z-index: 1;\n        }\n\n        /* Headers already styled above */\n        main h1, main h2, main h3, main h4 {\n            margin: 0;\n        }\n\n        main p {\n            margin: 0;\n            line-height: 1.6;\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n        }\n\n        /* Exclude footer from main content styles */\n        footer h1, footer h2, footer h3, footer h4, footer h5, footer h6 {\n            font-family: inherit !important;\n            color: inherit !important;\n            text-transform: none !important;\n            letter-spacing: normal !important;\n            font-weight: inherit !important;\n            line-height: inherit !important;\n        }\n\n        footer p {\n            font-family: inherit !important;\n            color: inherit !important;\n        }\n\n        a {\n            text-decoration: none;\n        }\n\n        /* --- SECTION 1: THE TILE GRID (Matches your Screenshot) --- */\n        main {\n            margin: 0;\n            padding: 0;\n        }\n\n        .tile-grid {\n            display: grid !important;\n            grid-template-columns: 1fr 1fr !important;\n            /* 2 Columns */\n            width: 100%;\n        }\n\n        .tile {\n            position: relative;\n            height: 400px;\n            /* Adjust height as needed */\n            background-size: cover !important;\n            background-position: center !important;\n            display: flex !important;\n            flex-direction: column !important;\n            justify-content: center !important;\n            /* Vertically Center text */\n            padding: 40px !important;\n            overflow: hidden;\n        }\n\n        /* Dark Overlay to make text pop */\n        .tile::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background: rgba(0, 0, 0, 0.3);\n            /* Darkens image by 30% */\n            z-index: 1;\n            transition: background 0.3s ease;\n        }\n\n        .tile:hover::before {\n            background: rgba(0, 0, 0, 0.5);\n            /* Darker on hover */\n        }\n\n        .tile-content {\n            position: relative;\n            z-index: 2;\n            color: white;\n            max-width: 90%;\n        }\n\n        .tile-title {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 3rem;\n            font-weight: 400;\n            line-height: 1.2;\n            margin-bottom: 15px;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            color: #FF4F4F !important;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(0, 0, 0, 0.5);\n        }\n\n        .tile-desc {\n            font-family: \'Azo Sans\', sans-serif;\n            font-size: 0.95rem;\n            font-weight: 400;\n            max-width: 500px;\n            color: rgba(255, 255, 255, 0.95);\n            line-height: 1.6;\n        }\n\n        /* Mobile Responsiveness */\n        @media (max-width: 640px) {\n            .tile {\n                height: 300px;\n                padding: 20px !important;\n            }\n\n            .tile-title {\n                font-size: 1.5rem;\n                margin-bottom: 10px;\n            }\n\n            .tile-desc {\n                font-size: 0.85rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .tile-grid {\n                grid-template-columns: 1fr;\n                /* Stack on mobile */\n            }\n\n            .tile {\n                height: 350px;\n                padding: 30px !important;\n            }\n\n            .tile-title {\n                font-size: 2rem;\n            }\n        }\n\n        /* --- SECTION 2: CTA SPLIT (About Us) --- */\n        .cta-section {\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            min-height: 400px;\n        }\n\n        @media (max-width: 640px) {\n            .cta-section {\n                grid-template-columns: 1fr;\n                min-height: auto;\n            }\n\n            .cta-content {\n                padding: 30px 20px;\n            }\n\n            .cta-content h4 {\n                font-size: 1rem;\n                margin-bottom: 12px;\n            }\n\n            .cta-content p {\n                font-size: 0.9rem;\n                margin-bottom: 20px;\n                line-height: 1.6;\n            }\n\n            .btn {\n                padding: 12px 20px;\n                font-size: 0.75rem;\n                width: 100%;\n                text-align: center;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .cta-section {\n                grid-template-columns: 1fr;\n            }\n\n            .cta-content {\n                padding: 40px 30px;\n            }\n        }\n\n        .cta-image {\n            width: 100%;\n            background-image: url(\'../assets/images/location/snow-globe.webp\');\n            background-size: cover;\n            background-position: center;\n        }\n\n        .cta-content {\n            width: 100%;\n            background: #f4f4f4;\n            display: flex;\n            flex-direction: column;\n            justify-content: center;\n            padding: 60px;\n        }\n\n        .cta-content h4 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 1.25rem;\n            font-weight: 400;\n            letter-spacing: 0.02em;\n            margin-bottom: 15px;\n            color: #FF4F4F;\n            text-transform: uppercase;\n            line-height: 1.2;\n        }\n\n        .cta-content p {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n            margin-bottom: 25px;\n            line-height: 1.6;\n        }\n\n        .btn {\n            display: inline-block;\n            border: 2px solid #000;\n            padding: 10px 25px;\n            text-transform: uppercase;\n            font-weight: bold;\n            color: #000;\n            font-size: 0.8rem;\n            width: fit-content;\n            transition: all 0.3s ease;\n        }\n\n        .btn:hover {\n            background: #000;\n            color: white;\n        }\n\n        /* --- SECTION 3: CTA SECTION --- */\n        .booking-banner {\n            position: relative;\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n            justify-content: center;\n            padding: 80px 20px;\n            background: linear-gradient(135deg, #220834 0%, #1a0b44 50%, #051637 100%);\n            text-align: center;\n            overflow: hidden;\n        }\n\n        .booking-banner::before {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: radial-gradient(circle at center, rgba(255, 255, 255, 0.1), transparent 70%);\n            pointer-events: none;\n        }\n\n        .booking-banner img {\n            max-width: 100%;\n            height: auto;\n            width: 300px;\n            margin-bottom: 30px;\n            position: relative;\n            z-index: 2;\n        }\n\n        .booking-text {\n            text-align: center;\n            position: relative;\n            z-index: 2;\n        }\n\n        .booking-text h2 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 1.2rem;\n            font-weight: 400;\n            color: #FF4F4F !important;\n            margin-bottom: 10px;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(255, 79, 79, 0.5);\n        }\n\n        .booking-text h3 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 3rem;\n            font-weight: 400;\n            color: #FF4F4F !important;\n            margin-bottom: 30px;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(255, 79, 79, 0.5);\n        }\n\n        .booking-banner .btn {\n            background: #FF4F4F;\n            color: white;\n            border: none;\n            padding: 18px 40px;\n            font-size: 1rem;\n            font-weight: 600;\n            text-transform: uppercase;\n            letter-spacing: 1px;\n            border-radius: 50px;\n            box-shadow: 0 10px 25px rgba(255, 79, 79, 0.4);\n            transition: all 0.3s ease;\n            text-decoration: none;\n            display: inline-block;\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        .booking-banner .btn:hover {\n            background: #e63939;\n            transform: translateY(-3px);\n            box-shadow: 0 15px 35px rgba(255, 79, 79, 0.5);\n        }\n\n        .booking-banner .btn-call {\n            background: transparent;\n            color: white;\n            border: 2px solid white;\n            padding: 18px 40px;\n            font-size: 1rem;\n            font-weight: 600;\n            text-transform: uppercase;\n            letter-spacing: 1px;\n            border-radius: 50px;\n            transition: all 0.3s ease;\n            cursor: pointer;\n            display: inline-flex;\n            align-items: center;\n            gap: 8px;\n        }\n\n        .booking-banner .btn-call:hover {\n            background: white;\n            color: #220834;\n            transform: translateY(-3px);\n            box-shadow: 0 10px 25px rgba(255, 255, 255, 0.3);\n        }\n\n        .booking-banner .btn-call svg {\n            width: 20px;\n            height: 20px;\n        }\n\n        .booking-banner .btn-group {\n            display: flex;\n            flex-direction: column;\n            gap: 15px;\n            align-items: center;\n            justify-content: center;\n            width: 100%;\n        }\n\n        @media (min-width: 640px) {\n            .booking-banner .btn-group {\n                flex-direction: row;\n                gap: 20px;\n                justify-content: center;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .booking-banner {\n                padding: 50px 20px;\n            }\n\n            .booking-text h2 {\n                font-size: 0.9rem;\n                margin-bottom: 8px;\n            }\n\n            .booking-text h3 {\n                font-size: 1.8rem;\n                margin-bottom: 20px;\n                line-height: 1.2;\n            }\n\n            .booking-banner img {\n                width: 200px;\n                margin-bottom: 20px;\n            }\n\n            .booking-banner .btn,\n            .booking-banner .btn-call {\n                padding: 14px 28px;\n                font-size: 0.875rem;\n                width: 100%;\n                max-width: 280px;\n            }\n        }\n\n        @media (min-width: 768px) {\n            .booking-banner {\n                padding: 100px 20px;\n            }\n\n            .booking-text h2 {\n                font-size: 1.4rem;\n            }\n\n            .booking-text h3 {\n                font-size: 4rem;\n            }\n\n            .booking-banner img {\n                width: 350px;\n            }\n        }\n\n        /* --- SECTION 4: AI BOOTH FEATURE --- */\n        .feature-section {\n            position: relative;\n            min-height: 600px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            background-size: cover;\n            background-position: center;\n            background-repeat: no-repeat;\n            overflow: hidden;\n            margin: 0 auto;\n        }\n\n        .feature-section::before {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: rgba(0, 0, 0, 0.4);\n            z-index: 1;\n        }\n\n        .feature-section img {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n            z-index: 0;\n        }\n\n        .feature-section .feature-content {\n            position: relative;\n            z-index: 2;\n            text-align: center;\n            padding: 80px 20px;\n            max-width: 1000px;\n            margin: 0 auto;\n            width: 100%;\n        }\n\n        .feature-section h2 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 1.2rem;\n            color: #FF4F4F !important;\n            margin-bottom: 10px;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            font-weight: 400;\n            line-height: 1.2;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(255, 79, 79, 0.5);\n        }\n\n        .feature-section h2:last-of-type {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 4rem;\n            font-weight: 400;\n            margin-bottom: 30px;\n            color: #FF4F4F !important;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(255, 79, 79, 0.5);\n        }\n\n        .feature-section p {\n            font-family: \'Azo Sans\', sans-serif;\n            color: rgba(255, 255, 255, 0.95);\n            margin-bottom: 40px;\n            font-size: 1.1rem;\n            line-height: 1.6;\n            max-width: 900px;\n            margin-left: auto;\n            margin-right: auto;\n        }\n\n        .feature-section .btn-learn-more {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            gap: 10px;\n            padding: 18px 40px;\n            background: #FF4F4F;\n            color: white;\n            border-radius: 50px;\n            font-weight: 600;\n            text-decoration: none;\n            transition: all 0.3s ease;\n            box-shadow: 0 10px 30px rgba(255, 79, 79, 0.5);\n            text-transform: uppercase;\n            letter-spacing: 2px;\n            font-size: 1rem;\n            border: none;\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        .feature-section .btn-learn-more:hover {\n            background: #e63939;\n            transform: translateY(-3px);\n            box-shadow: 0 15px 40px rgba(255, 79, 79, 0.6);\n        }\n\n        .feature-section .btn-learn-more svg {\n            width: 20px;\n            height: 20px;\n            transition: transform 0.3s ease;\n        }\n\n        .feature-section .btn-learn-more:hover svg {\n            transform: translateX(5px);\n        }\n\n        @media (max-width: 640px) {\n            .feature-section {\n                min-height: 500px;\n            }\n\n            .feature-section .feature-content {\n                padding: 50px 20px;\n            }\n\n            .feature-section h2 {\n                font-size: 0.9rem;\n                letter-spacing: 2px;\n            }\n\n            .feature-section h2:last-of-type {\n                font-size: 2rem;\n                margin-bottom: 20px;\n                line-height: 1.2;\n            }\n\n            .feature-section p {\n                font-size: 0.95rem;\n                margin-bottom: 30px;\n                line-height: 1.6;\n            }\n\n            .feature-section .btn-learn-more {\n                padding: 14px 28px;\n                font-size: 0.875rem;\n                letter-spacing: 1px;\n            }\n        }\n\n        @media (min-width: 768px) {\n            .feature-section {\n                min-height: 700px;\n            }\n\n            .feature-section .feature-content {\n                padding: 100px 40px;\n            }\n\n            .feature-section h2 {\n                font-size: 1.4rem;\n            }\n\n            .feature-section h2:last-of-type {\n                font-size: 5rem;\n            }\n\n            .feature-section p {\n                font-size: 1.2rem;\n            }\n        }\n\n        /* --- GOOGLE MAPS SECTION --- */\n        /* --- VENUES TITLE SECTION --- */\n        .venues-title-section {\n            background: white;\n            padding: 80px 20px;\n            text-align: center;\n        }\n\n        .venues-title-section h2 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 2.5rem;\n            font-weight: 400;\n            color: #FF4F4F;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            margin-bottom: 30px;\n        }\n\n        .venues-title-section .btn-venues {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            padding: 18px 40px;\n            background: #FF4F4F;\n            color: white;\n            border-radius: 8px;\n            font-weight: 600;\n            text-decoration: none;\n            text-transform: uppercase;\n            letter-spacing: 1px;\n            font-size: 1rem;\n            transition: all 0.3s ease;\n            box-shadow: 0 4px 15px rgba(255, 79, 79, 0.3);\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        .venues-title-section .btn-venues:hover {\n            background: #e63939;\n            transform: translateY(-2px);\n            box-shadow: 0 6px 20px rgba(255, 79, 79, 0.4);\n        }\n\n        @media (max-width: 640px) {\n            .venues-title-section {\n                padding: 50px 20px;\n            }\n\n            .venues-title-section h2 {\n                font-size: 1.5rem;\n                line-height: 1.3;\n                margin-bottom: 20px;\n            }\n\n            .venues-title-section .btn-venues {\n                padding: 14px 28px;\n      