eft: 2.5rem;\n            width: 10rem;\n            height: 10rem;\n            border-radius: 50%;\n            background: rgba(236, 72, 153, 0.2);\n            filter: blur(3rem);\n        }\n\n        .hero-ambient-glow-3 {\n            position: absolute;\n            bottom: 2.5rem;\n            right: 2.5rem;\n            width: 13rem;\n            height: 13rem;\n            border-radius: 50%;\n            background: rgba(96, 165, 250, 0.2);\n            filter: blur(120px);\n        }\n\n        .hero-content {\n            position: relative;\n            z-index: 10;\n            text-align: center;\n            padding: 5rem 1.5rem;\n            max-width: 90rem;\n            margin: 0 auto;\n        }\n\n        .hero-title {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-size: 3rem;\n            font-weight: 400;\n            line-height: 1.2;\n            margin-bottom: 2rem;\n            text-transform: uppercase;\n            color: #FF4F4F !important;\n            letter-spacing: 0.02em;\n            text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8), 0 0 20px rgba(255, 79, 79, 0.5);\n        }\n\n        .hero-subtitle {\n            font-family: \'Azo Sans\', sans-serif;\n            font-size: 1.1rem;\n            line-height: 1.6;\n            color: #ffffff;\n            margin-bottom: 2rem;\n            max-width: 1200px;\n            margin-left: auto;\n            margin-right: auto;\n            text-shadow: 1px 1px 6px rgba(0, 0, 0, 0.8), 0 0 15px rgba(0, 0, 0, 0.4);\n        }\n\n        .hero-cta {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            padding: 1rem 2rem;\n            background: #FF4F4F;\n            color: white;\n            border-radius: 9999px;\n            font-weight: 600;\n            text-decoration: none;\n            transition: all 0.3s ease;\n            box-shadow: 0 10px 25px rgba(255, 79, 79, 0.4);\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        .hero-cta:hover {\n            background: #e63939;\n            transform: translateY(-2px);\n            box-shadow: 0 15px 35px rgba(255, 79, 79, 0.5);\n        }\n\n        .hero-cta-call {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            gap: 8px;\n            padding: 1rem 2rem;\n            background: transparent;\n            color: white;\n            border: 2px solid white;\n            border-radius: 9999px;\n            font-weight: 600;\n            text-decoration: none;\n            transition: all 0.3s ease;\n            cursor: pointer;\n        }\n\n        .hero-cta-call:hover {\n            background: white;\n            color: #220834;\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(255, 255, 255, 0.3);\n        }\n\n        .hero-cta-call svg {\n            width: 20px;\n            height: 20px;\n        }\n\n        .hero-cta-group {\n            display: flex;\n            flex-direction: column;\n            gap: 15px;\n            align-items: center;\n            justify-content: center;\n            width: 100%;\n        }\n\n        @media (min-width: 640px) {\n            .hero-cta-group {\n                flex-direction: row;\n                gap: 20px;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .hero-section {\n                height: 70vh;\n                min-height: 500px;\n            }\n\n            .hero-content {\n                padding: 3rem 1rem;\n            }\n\n            .hero-title {\n                font-size: 1.75rem;\n                margin-bottom: 1.5rem;\n                line-height: 1.2;\n            }\n\n            .hero-subtitle {\n                font-size: 0.95rem;\n                margin-bottom: 1.5rem;\n                line-height: 1.5;\n            }\n\n            .hero-cta,\n            .hero-cta-call {\n                padding: 12px 24px;\n                font-size: 0.875rem;\n                width: 100%;\n                max-width: 280px;\n            }\n\n            .hero-cta-group {\n                width: 100%;\n                padding: 0 1rem;\n            }\n        }\n\n        @media (min-width: 768px) {\n            .hero-section {\n                height: 100vh;\n                min-height: 100vh;\n            }\n\n            .hero-content {\n                padding: 8rem 1.5rem;\n            }\n\n            .hero-title {\n                font-size: 4.5rem;\n            }\n\n            .hero-subtitle {\n                font-size: 1.2rem;\n                line-height: 1.5;\n            }\n        }\n\n        @media (min-width: 1024px) {\n            .hero-title {\n                font-size: 5rem;\n            }\n        }\n\n        /* Navigation Contact Us Button Fix */\n        header .btn-primary,\n        nav .btn-primary,\n        .btn-primary {\n            background: #FF4F4F !important;\n            background-color: #FF4F4F !important;\n            color: #ffffff !important;\n            border: none;\n            padding: 0.75rem 1.5rem;\n            border-radius: 9999px;\n            font-weight: 600;\n            text-decoration: none;\n            display: inline-block;\n            transition: all 0.3s ease;\n            box-shadow: 0 4px 6px rgba(255, 79, 79, 0.3);\n            font-family: \'Azo Sans\', sans-serif;\n        }\n\n        header .btn-primary:hover,\n        nav .btn-primary:hover,\n        .btn-primary:hover {\n            background: #e63939 !important;\n            background-color: #e63939 !important;\n            transform: translateY(-2px);\n            box-shadow: 0 6px 12px rgba(255, 79, 79, 0.4);\n        }\n\n        header .btn-primary:active,\n        nav .btn-primary:active,\n        .btn-primary:active {\n            transform: translateY(0);\n        }\n    </style>\n</head>\n\n<body>\n    <!-- Navigatio