(\'seeMoreVideoBooths\');\n                const seeMoreIcon = document.getElementById(\'seeMoreIcon\');\n                const seeMoreText = seeMoreBtn.querySelector(\'span\');\n\n                // Check if cards are currently hidden\n                const isHidden = moreCards[0].classList.contains(\'hidden\');\n\n                moreCards.forEach(card => {\n                    if (isHidden) {\n                        card.classList.remove(\'hidden\');\n                        card.style.display = \'block\';\n                        card.style.animation = \'fadeIn 0.5s ease-in\';\n                    } else {\n                        card.classList.add(\'hidden\');\n                        card.style.display = \'none\';\n                    }\n                });\n\n                // Update button text and icon\n                if (isHidden) {\n                    seeMoreText.textContent = \'See Less\';\n                    seeMoreIcon.style.transform = \'rotate(180deg)\';\n                } else {\n                    seeMoreText.textContent = \'See More\';\n                    seeMoreIcon.style.transform = \'rotate(0deg)\';\n                }\n            }\n\n            function toggleGallery() {\n                const moreItems = document.querySelectorAll(\'.gallery-more\');\n                const seeMoreBtn = document.getElementById(\'seeMoreGallery\');\n                const seeMoreIcon = document.getElementById(\'seeMoreGalleryIcon\');\n                const seeMoreText = seeMoreBtn.querySelector(\'span\');\n\n                // Check if items are currently hidden\n                if (moreItems.length === 0) return;\n                const isHidden = moreItems[0].classList.contains(\'hidden\');\n\n                moreItems.forEach(item => {\n                    if (isHidden) {\n                        item.classList.remove(\'hidden\');\n                        item.style.animation = \'fadeIn 0.5s ease-in\';\n                    } else {\n                  