ll=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                    d=\"M19 9l-7 7-7-7\"></path>\n                            </svg>\n                        </button>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Final CTA Section -->\n        <section\n            class=\"section-padding bg-gradient-to-br from-gray-900 via-yellow-900 to-amber-900 text-white relative overflow-hidden\">\n            <!-- Background Image -->\n            <div class=\"absolute inset-0 z-0 overflow-hidden\">\n                <img src=\"assets/images/lux/lux-20.webp\" alt=\"Lux Photography Background\"\n                    class=\"w-full h-full object-cover\" style=\"object-position: center 20%;\">\n            </div>\n            <!-- Background Overlay -->\n            <div class=\"absolute inset-0 bg-gradient-to-br from-black/70 via-gray-900/75 to-black/70 z-[1]\"></div>\n            <!-- Decorative Elements -->\n            <div class=\"absolute inset-0 opacity-10 z-[2]\">\n                <div class=\"absolute top-20 left-20 w-72 h-72 bg-yellow-400 rounded-full filter blur-3xl animate-blob\">\n                </div>\n                <div\n                    class=\"absolute bottom-20 right-20 w-96 h-96 bg-amber-400 rounded-full filter blur-3xl animate-blob animation-delay-2000\">\n                </div>\n            </div>\n\n            <div class=\"container mx-auto px-4 sm:px-6 relative z-10\">\n                <div class=\"max-w-4xl mx-auto text-center\">\n                    <div class=\"inline-block mb-6 sm:mb-8 px-6 sm:px-8 py-2 sm:py-3 backdrop-blur-md rounded-full border-2 border-white/20\"\n                        style=\"background-color: #FF4F4F;\">\n                        <span class=\"text-white text-xs sm:text-sm font-bold tracking-wider uppercase\">\n                            LET\'S CREATE SOMETHING UNFORGETTABLE\n                        </span>\n                    </div>\n\n                    <h2 class=\"text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-black mb-6 sm:mb-8 leading-tight\"\n                        style=\"font-family: \'AzoSansUber\', sans-serif;\">\n                        <span\n                            style=\"text-shadow: 0 4px 20px rgba(0, 0, 0, 0.9), 0 2px 10px rgba(0, 0, 0, 0.8), 0 0 30px rgba(212, 175, 55, 0.6);\">\n                            <span style=\"color: #FF4F4F;\">Experience Luxury</span> <span\n                                style=\"color: #18F1E1;\">Photography</span>\n                        </span>\n                    </h2>\n\n                    <p\n                        class=\"text-base sm:text-lg md:text-xl mb-8 sm:mb-12 text-white/90 max-w-3xl mx-auto leading-relaxed px-4\">\n                        Let\'s create something unmatched. Reach out today to explore how our Lux Photography can bring\n                        sophistication and timeless memories to your event.\n                    </p>\n\n                    <div class=\"flex flex-col sm:flex-row gap-4 sm:gap-6 justify-center items-center\">\n                        <a href=\"contact-us.html\"\n                            class=\"inline-flex items-center gap-3 bg-white text-gray-900 px-8 sm:px-10 py-4 sm:py-5 rounded-full text-base sm:text-lg font-bold shadow-2xl hover:shadow-white/50 transition-all duration-500 transform hover:scale-110 hover:-translate-y-1\">\n                            <span>Get Your Quote</span>\n                            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                    d=\"M13 7l5 5m0 0l-5 5m5-5H6\" />\n                            </svg>\n                        </a>\n                        <button type=\"button\" data-click-to-call data-call-text=\"Call Us\"\n                            class=\"inline-flex items-center gap-3 px-8 sm:px-10 py-4 sm:py-5 rounded-full text-base sm:text-lg font-bold backdrop-blur-md bg-white/20 border-2 border-white/50 hover:bg-white/30 hover:border-white/70 shadow-xl hover:shadow-2xl transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 text-white cursor-pointer\">\n                            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                    d=\"M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498A1 1 0 0121 17.72V21a2 2 0 01-2 2h-1C9.716 23 3 16.284 3 8V7a2 2 0 012-2z\">\n                                </path>\n                            </svg>\n                            <span>Call Us</span>\n                        </button>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Related Products Section -->\n        <section class=\"section-padding bg-gradient-to-b from-white via-gray-50/30 to-white relative overflow-hidden\">\n            <div class=\"container mx-auto px-4 sm:px-6\">\n                <div class=\"max-w-7xl mx-auto\">\n                    <div class=\"text-center mb-12 sm:mb-16\">\n                        <div\n                            class=\"inline-block mb-4 sm:mb-6 px-6 sm:px-8 py-2 sm:py-3 bg-[#18F1E1] backdrop-blur-md rounded-full border-2 border-[#18F1E1]\">\n                            <span class=\"text-[#1F1F1F] text-xs sm:text-sm font-bold tracking-wider uppercase\">\n                                RELATED PRODUCTS\n                            </span>\n                        </div>\n                        <h2 class=\"text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-light mb-4 sm:mb-6 text-[#1F1F1F] leading-tight\"\n                            style=\"font-family: \'AzoSansUber\', sans-serif;\">\n                            <span class=\"luxury-gradient-text\">Discover Our Related Products</span>\n                        </h2>\n                        <p class=\"text-lg sm:text-xl text-gray-600 max-w-3xl mx-auto leading-relaxed px-4\"\n                            style=\"font-family: \'AzoSans\', sans-serif;\">\n                            Explore more premium photography and photo booth experiences\n                        </p>\n                    </div>\n\n                    <div class=\"grid md:grid-cols-3 gap-6 sm:gap-8\">\n                        <!-- Professional Headshots -->\n                        <a href=\"product/professional-headshots.html\" class=\"group h-full flex flex-col\">\n                            <div\n                                class=\"luxury-card relative rounded-3xl overflow-hidden shadow-xl hover:shadow-2xl transition-all transform hover:scale-105 border border-yellow-200/50 hover:border-yellow-400/70 flex flex-col h-full bg-white\">\n                                <div class=\"aspect-[4/3] relative overflow-hidden flex-shrink-0\">\n                                    <img src=\"assets/images/headshot/professional-headshot-2.webp\"\n                                        alt=\"Professional Headshots\"\n                                        class=\"w-full h-full object-cover group-hover:scale-110 transition-transform duration-500\">\n                                    <div\n                                        class=\"absolute inset-0 bg-gradient-to-t from-black/60 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300\">\n                                    </div>\n                                </div>\n                                <div class=\"p-6 sm:p-8 bg-white flex-grow flex flex-col\">\n                                    <h3 class=\"text-xl sm:text-2xl font-bold mb-3 text-gray-900 group-hover:text-[#FF4F4F] transition-colors\"\n                                        style=\"font-family: \'AzoSans\', sans-serif;\">\n                                        Professional Headshots\n                                    </h3>\n                                    <p class=\"text-gray-600 leading-relaxed flex-grow\">\n                                        Studio-quality headshots on-site with expert lighting and instant touch-ups for\n                                        corporate events and professional needs.\n                                    </p>\n                                </div>\n                            </div>\n                        </a>\n\n                        <!-- Event Photography -->\n                        <a href=\"event-photography.html\" class=\"group h-full flex flex-col\">\n                            <div\n                                class=\"luxury-card relative rounded-3xl overflow-hidden shadow-xl hover:shadow-2xl transition-all transform hover:scale-105 border border-amber-200/50 hover:border-amber-400/70 flex flex-col h-full bg-white\">\n                                <div class=\"aspect-[4/3] relative overflow-hidden flex-shrink-0\">\n                                    <img src=\"assets/images/event-photography/event-photography-1.webp\"\n                                        alt=\"Event Photography\"\n                                        class=\"w-full h-full object-cover group-hover:scale-110 transition-transform duration-500\">\n                                    <div\n                                        class=\"absolute inset-0 bg-gradient-to-t from-black/60 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300\">\n                                    </div>\n                                </div>\n                                <div class=\"p-6 sm:p-8 bg-white flex-grow flex flex-col\">\n                                    <h3 class=\"text-xl sm:text-2xl font-bold mb-3 text-gray-900 group-hover:text-[#FF4F4F] transition-colors\"\n                                        style=\"font-family: \'AzoSans\', sans-serif;\">\n                                        Event Photography\n                                    </h3>\n                                    <p class=\"text-gray-600 leading-relaxed flex-grow\">\n                                        Document every moment of your event with professional quality photography that\n                                        captures the essence of your special occasion.\n                                    </p>\n                                </div>\n                            </div>\n                        </a>\n\n                        <!-- Vogue Photo Booth -->\n                        <a href=\"product/vogue-photo-booth.html\" class=\"group h-full flex flex-col\">\n                            <div\n                                class=\"luxury-card relative rounded-3xl overflow-hidden shadow-xl hover:shadow-2xl transition-all transform hover:scale-105 border border-yellow-200/50 hover:border-yellow-400/70 flex flex-col h-full bg-white\">\n                                <div class=\"aspect-[4/3] relative overflow-hidden flex-shrink-0\">\n                                    <img src=\"assets/images/event-photography/event-photography-10.webp\"\n                                        alt=\"Vogue Photo Booth\"\n                                        class=\"w-full h-full object-cover group-hover:scale-110 transition-transform duration-500\">\n                                    <div\n                                        class=\"absolute inset-0 bg-gradient-to-t from-black/60 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300\">\n                                    </div>\n                                </div>\n                                <div class=\"p-6 sm:p-8 bg-white flex-grow flex flex-col\">\n                                    <h3 class=\"text-xl sm:text-2xl font-bold mb-3 text-gray-900 group-hover:text-[#FF4F4F] transition-colors\"\n                                        style=\"font-family: \'AzoSans\', sans-serif;\">\n                                        Vogue Photo Booth\n                                    </h3>\n                                    <p class=\"text-gray-600 leading-relaxed flex-grow\">\n                                        High-fashion photo booth experience with magazine-quality results and\n                                        sophisticated styling for your luxury events.\n                                    </p>\n                                </div>\n                            </div>\n                        </a>\n                    </div>\n                </div>\n            </div>\n        </section>\n    </main>\n\n    <!-- Lightbox for Image Zoom -->\n    <div id=\"lightbox\" class=\"lightbox\" onclick=\"closeLightbox()\">\n        <span class=\"lightbox-close\" onclick=\"event.stopPropagation(); closeLightbox();\">&times;</span>\n        <div class=\"lightbox-img-container\" onclick=\"event.stopPropagation();\">\n            <img id=\"lightbox-img\" src=\"\" alt=\"Lux Photography - Full view\" onclick=\"toggleZoom(event);\">\n        </div>\n    </div>\n\n    <script>\n        function openLightbox(imageSrc) {\n            event.stopPropagation();\n            const lightbox = document.getElementById(\'lightbox\');\n            const lightboxImg = document.getElementById(\'lightbox-img\');\n            lightboxImg.src = imageSrc;\n            lightboxImg.classList.remove(\'zoomed\'); // Reset zoom state\n            lightbox.classList.add(\'active\');\n            document.body.style.overflow = \'hidden\'; // Prevent scrolling when lightbox is open\n        }\n\n        function closeLightbox() {\n            const lightbox = document.getElementById(\'lightbox\');\n            const lightboxImg = document.getElementById(\'lightbox-img\');\n            lightbox.classList.remove(\'active\');\n            lightboxImg.classList.remove(\'zoomed\'); // Reset zoom state\n            document.body.style.overflow = \'\'; // Restore scrolling\n        }\n\n        function toggleZoom(event) {\n            event.stopPropagation();\n            const lightboxImg = document.getElementById(\'lightbox-img\');\n            lightboxImg.classList.toggle(\'zoomed\');\n        }\n\n        // Close lightbox with Escape key\n        document.addEventListener(\'keydown\', function (event) {\n            if (event.key === \'Escape\') {\n                closeLightbox();\n            }\n        });\n\n        // Detect image orientations and assign classes\n        document.addEventListener(\'DOMContentLoaded\', function () {\n            const galleryItems = document.querySelectorAll(\'.gallery-grid-lux .gallery-item-lux img\');\n\n            galleryItems.forEach(function (img) {\n                // Create a new image to get natural dimensions\n                const testImg = new Image();\n                testImg.onload = function () {\n                    const aspectRatio = this.width / this.height;\n                    const galleryItem = img.closest(\'.gallery-item-lux\');\n\n                    // Remove existing orientation classes\n                    galleryItem.classList.remove(\'landscape\', \'portrait\', \'square\');\n\n                    // Classify based on aspect ratio\n                    if (aspectRatio > 1.1) {\n                        // Landscape (wider than tall)\n                        galleryItem.classList.add(\'landscape\');\n                    } else if (aspectRatio < 0.9) {\n                        // Portrait (taller than wide)\n                        galleryItem.classList.add(\'portrait\');\n                    } else {\n                        // Square (approximately 1:1)\n                        galleryItem.classList.add(\'square\');\n                    }\n                };\n                testImg.src = img.src;\n            });\n        });\n\n        // Toggle technical specifications\n        function toggleSpecs() {\n            const hiddenCards = document.querySelectorAll(\'.hidden-spec\');\n            const button = document.getElementById(\'see-more-btn\');\n            const buttonText = button.querySelector(\'span\');\n            const buttonIcon = document.getElementById(\'see-more-icon\');\n            const isExpanded = hiddenCards[0] && hiddenCards[0].style.display !== \'none\';\n\n            hiddenCards.forEach(card => {\n                if (isExpanded) {\n                    card.style.display = \'none\';\n                } else {\n                    card.style.display = \'block\';\n                }\n            });\n\n            if (isExpanded) {\n                buttonText.textContent = \'See More\';\n                buttonIcon.style.transform = \'rotate(0deg)\';\n            } else {\n                buttonText.textContent = \'See Less\';\n                buttonIcon.style.transform = \'rotate(180deg)\';\n            }\n        }\n\n        // Toggle gallery items\n        function toggleGallery() {\n            const hiddenItems = document.querySelectorAll(\'.gallery-item-hidden\');\n            const button = document.getElementById(\'gallery-see-more-btn\');\n            const buttonText = button.querySelector(\'span\');\n            const buttonIcon = document.getElementById(\'gallery-see-more-icon\');\n            const isExpanded = hiddenItems[0] && hiddenItems[0].classList.contains(\'show\');\n\n            hiddenItems.forEach(item => {\n                if (isExpanded) {\n                    item.classList.remove(\'show\');\n                } else {\n                    item.classList.add(\'show\');\n                }\n            });\n\n            if (isExpanded) {\n                buttonText.textContent = \'See More Photos\';\n                buttonIcon.style.transform = \'rotate(0deg)\';\n            } else {\n                buttonText.textContent = \'See Less\';\n                buttonIcon.style.transform = \'rotate(180deg)\';\n            }\n        }\n    </script>\n\n    <!-- Footer -->\n    <script src=\"assets/components/footer.js\"></script>\n    <!-- Load Back to Top Component -->\n    <script src=\"assets/components/back-to-top.js\"></script>\n\n</body>', NULL, 'published', NULL, '2025-12-14 00:30:10', '2025-12-14 00:30:10');
INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(121, 'Mihi Props', 'mihi-props', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Our Props - MiHi Entertainment</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link\n        href=\"https://fonts.googleapis.com/css2?family=Arvo:wght@400;700&family=Cinzel:wght@500;600;700;800;900&family=Inter:wght@300;400;500;600;700;800;900&family=Montserrat:wght@500;600;700&family=Playfair+Display:wght@400;500;600;700;800;900&display=swap\"\n        rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Source+Code+Pro:wght@400;600;700&display=swap\"\n        rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Dongle&display=swap\" rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/icon?family=Material+Icons\" rel=\"stylesheet\">\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Merriweather:wght@300;900&display=swap\');\n        @import url(\'https://fonts.googleapis.com/css2?family=Righteous&display=swap\');\n\n        @font-face {\n            font-family: \'AzoSansUber\';\n            src: url(\'assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        .font-style-AzoSans {\n            font-family: \'AzoSansUber\', sans-serif;\n        }\n\n        body {\n            font-family: \'Inter\', sans-serif;\n            color: #1a202c;\n            overflow-x: hidden;\n        }\n\n        h1,\n        h2,\n        h3,\n        h4,\n        h5,\n        h6 {\n            font-family: \'Playfair Display\', serif;\n        }\n\n        .btn-primary {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 100%);\n            transition: all 0.3s ease;\n        }\n\n        .btn-primary:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(0, 80, 255, 0.4);\n        }\n\n        /* Bubble Button Animation */\n        .btn {\n            display: inline-block;\n            text-decoration: none;\n        }\n\n        .btn-bubble {\n            color: white;\n            background-repeat: no-repeat;\n            position: relative;\n        }\n\n        .btn-bubble:not(:hover):not(:focus) {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 100%);\n        }\n\n        .btn-bubble:hover,\n        .btn-bubble:focus {\n            animation: bubbles 1s forwards ease-out;\n            background:\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 5% 120% / 0.6em 0.6em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 15% 110% / 0.8em 0.8em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 25% 130% / 0.7em 0.7em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 35% 100% / 0.9em 0.9em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 45% 115% / 0.5em 0.5em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 55% 125% / 1em 1em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 65% 105% / 0.75em 0.75em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 75% 135% / 0.85em 0.85em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 85% 120% / 0.65em 0.65em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 95% 110% / 0.95em 0.95em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 105% 130% / 0.55em 0.55em;\n\n            color: #1f1f1f;\n            background-color: #18F1E1;\n            background-repeat: no-repeat;\n        }\n\n        @keyframes bubbles {\n            100% {\n                background-position:\n                    3% -350%,\n                    18% -280%,\n                    22% -320%,\n                    38% -250%,\n                    42% -380%,\n                    58% -200%,\n                    62% -340%,\n                    78% -180%,\n                    88% -300%,\n                    98% -220%,\n                    102% -360%;\n                box-shadow: inset 0 -6.5em 0 #FF4F4F;\n            }\n        }\n\n        /* Hero Button Responsive */\n        .hero-button {\n            font-size: 1.125rem;\n            padding: 0.75rem 2rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-button {\n                font-size: 1rem;\n                padding: 0.625rem 1.5rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-button {\n                font-size: 0.875rem;\n                padding: 0.5rem 1.25rem;\n            }\n        }\n\n        .section-padding {\n            padding: 5rem 0;\n        }\n\n        @media (max-width: 768px) {\n            .section-padding {\n                padding: 3rem 0;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .section-padding {\n                padding: 2.5rem 0;\n            }\n        }\n\n        .hero-section {\n            background-image: url(\'../assets/images/galleries/ourprops/hero.jpeg\');\n            background-attachment: fixed;\n            background-position: center center;\n            background-size: cover;\n            background-repeat: no-repeat;\n            min-height: 100vh;\n        }\n\n        @media (max-width: 768px) {\n            .hero-section {\n                min-height: 85vh;\n                background-attachment: scroll;\n            }\n        }\n\n        .hero-section .corporate-text {\n            font-family: \'Montserrat\', sans-serif;\n            letter-spacing: 0.3em;\n        }\n\n        @media (max-width: 640px) {\n            .container {\n                padding-left: 1rem;\n                padding-right: 1rem;\n            }\n        }\n\n        .animate-fade-in-up {\n            animation: fadeInUp 1s ease-out forwards;\n            opacity: 0;\n        }\n\n        .animate-delay-200 {\n            animation-delay: 0.2s;\n        }\n\n        .animate-delay-300 {\n            animation-delay: 0.3s;\n        }\n\n        .animate-delay-400 {\n            animation-delay: 0.4s;\n        }\n\n        @keyframes fadeInUp {\n            from {\n                opacity: 0;\n                transform: translateY(20px);\n            }\n\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n\n        /* Curved Carousel Styles */\n        :root {\n            --primary-text-color: snow;\n            --primary-text-color-emphasized: #d3d3d3;\n            --background-color: rgba(252, 252, 252, 0.1);\n            --background-color-emphasized: rgba(252, 252, 252, 0.25);\n            --carousel-animation: 300ms;\n            --shadow: rgba(0, 0, 0, 1);\n        }\n\n        .carousel-container {\n            position: relative;\n            width: 100%;\n            min-height: 700px;\n            height: 700px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            overflow: hidden;\n            margin: 0 auto;\n            z-index: 1;\n        }\n\n        .slides-container {\n            position: relative;\n            width: 100%;\n            height: 100%;\n            min-height: 700px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            overflow: hidden;\n            cursor: grab;\n        }\n\n        .slides-container:active {\n            cursor: grabbing;\n        }\n\n        .slides-wrapper {\n            position: relative;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            width: 100%;\n            height: 100%;\n            transform-origin: center;\n            overflow: visible;\n            min-height: 700px;\n        }\n\n        .slide {\n            position: absolute;\n            left: 50%;\n            top: 50%;\n            max-height: 620px;\n            width: auto;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            padding: 0.5rem;\n            transform-origin: center center;\n            transition: transform 0.3s ease-in-out;\n            pointer-events: none;\n            visibility: visible;\n            opacity: 1;\n            z-index: 1;\n        }\n\n        .slide figure {\n            position: relative;\n            pointer-events: auto;\n            transform-origin: center;\n            cursor: grab;\n            user-select: none;\n        }\n\n        .slide:active figure,\n        .slide.grabbed figure {\n            cursor: grabbing;\n        }\n\n        .slide img {\n            object-fit: contain;\n            max-width: 100%;\n            max-height: 620px;\n            width: auto;\n            height: auto;\n            box-shadow: 3px 3px 30px -1px var(--shadow);\n            border-radius: 4px;\n            transition: transform var(--carousel-animation) ease-in-out, box-shadow var(--carousel-animation) ease-in-out, opacity var(--carousel-animation) ease-in-out;\n            transform: scale(1);\n            display: block;\n            visibility: visible;\n            opacity: 1;\n        }\n\n        .carousel-nav-btn {\n            position: absolute;\n            top: 50%;\n            transform: translateY(-50%) scale(1);\n            z-index: 10000;\n            background: rgba(252, 252, 252, 0.1);\n            border: none;\n            border-radius: 50%;\n            width: 48px;\n            height: 48px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            cursor: pointer;\n            color: var(--primary-text-color);\n            transition: background-color 0.3s ease;\n            font-family: \'Material Icons\';\n            font-size: 20px;\n        }\n\n        .carousel-nav-btn:hover {\n            background: rgba(252, 252, 252, 0.25);\n        }\n\n        .carousel-nav-btn.prev {\n            left: 0.5rem;\n        }\n\n        .carousel-nav-btn.next {\n            right: 0.5rem;\n        }\n\n        .caption-container {\n            position: absolute;\n            left: 0;\n            bottom: 1rem;\n            width: 100%;\n            height: 60px;\n            overflow: hidden;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n        }\n\n        .caption-link {\n            display: inline-block;\n            position: absolute;\n            color: var(--primary-text-color);\n            text-decoration: none;\n            padding: 0.2rem 0.6rem;\n            background-color: var(--background-color);\n            border-radius: 0.4rem;\n            text-align: center;\n            font-family: \'Dongle\', sans-serif;\n            font-size: clamp(0.9rem, 0.9rem + 1.5vw, 1.8rem);\n            line-height: 1;\n            transition: background-color 0.3s ease;\n        }\n\n        .caption-link:hover,\n        .caption-link:focus {\n            background-color: var(--background-color-emphasized);\n            color: var(--primary-text-color-emphasized);\n        }\n\n        .notransition {\n            transition: none !important;\n        }\n\n        /* Modernized Props CTA Section */\n        .props-cta-section {\n            padding: 4rem 0;\n            background: linear-gradient(135deg, rgba(15, 23, 42, 0.95) 0%, rgba(30, 41, 59, 0.95) 100%);\n            position: relative;\n            overflow: hidden;\n        }\n\n        .props-cta-section::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background: radial-gradient(circle at 50% 50%, rgba(0, 80, 255, 0.1) 0%, transparent 70%);\n            pointer-events: none;\n        }\n\n        .props-cta-heading {\n            font-family: \'AzoSansUber\', sans-serif;\n            font-size: clamp(2rem, 4vw + 1rem, 3.5rem);\n            font-weight: 500;\n            color: #0050ff;\n            margin-top: 0;\n            margin-bottom: 1.5rem;\n            letter-spacing: -0.02em;\n            line-height: 1.1;\n            text-transform: uppercase;\n        }\n\n        .props-cta-heading span {\n            color: inherit;\n        }\n\n        .props-cta-description {\n            font-family: \'Inter\', sans-serif;\n            font-size: clamp(1rem, 1.5vw + 0.5rem, 1.25rem);\n            color: rgba(255, 255, 255, 0.9);\n            line-height: 1.7;\n            margin-bottom: 2.5rem;\n            max-width: 800px;\n            margin-left: auto;\n            margin-right: auto;\n            position: relative;\n            z-index: 1;\n        }\n\n        .props-cta-button {\n            display: inline-block;\n            font-family: \'Montserrat\', sans-serif;\n            font-size: clamp(0.875rem, 1vw + 0.5rem, 1rem);\n            font-weight: 600;\n            color: white;\n            text-transform: uppercase;\n            letter-spacing: 0.1em;\n            padding: 1rem 2.5rem;\n            background: linear-gradient(135deg, #1f1f1f 0%, #1f1f1f 100%);\n            border-radius: 50px;\n            text-decoration: none;\n            transition: all 0.3s ease;\n            box-shadow: 0 4px 15px rgba(0, 80, 255, 0.3);\n            position: relative;\n            z-index: 1;\n            overflow: hidden;\n        }\n\n        .props-cta-button::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: -100%;\n            width: 100%;\n            height: 100%;\n            background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);\n            transition: left 0.5s ease;\n        }\n\n        .props-cta-button:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 8px 25px rgba(0, 80, 255, 0.5);\n            background: linear-gradient(135deg, #0080ff 0%, #0050ff 100%);\n        }\n\n        .props-cta-button:hover::before {\n            left: 100%;\n        }\n\n        .props-cta-button:active {\n            transform: translateY(0);\n        }\n\n        @media (max-width: 768px) {\n            .props-cta-section {\n                padding: 3rem 0;\n            }\n\n            .props-cta-description {\n                margin-bottom: 2rem;\n            }\n\n            .props-cta-button {\n                padding: 0.875rem 2rem;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .props-cta-section {\n                padding: 2.5rem 0;\n            }\n        }\n\n        @media (max-width: 600px) {\n            .carousel-container {\n                min-height: 520px;\n                height: 520px;\n                margin: 1.5rem 0;\n            }\n\n            .slides-container {\n                min-height: 520px;\n            }\n\n            .slides-wrapper {\n                min-height: 520px;\n            }\n\n            .slide {\n                max-height: 480px;\n                padding: 0.25rem;\n            }\n\n            .slide img {\n                max-height: 480px;\n                max-width: 360px;\n            }\n\n            .carousel-nav-btn {\n                width: 36px;\n                height: 36px;\n                font-size: 18px;\n            }\n\n            .carousel-nav-btn.prev {\n                left: 0.25rem;\n            }\n\n            .carousel-nav-btn.next {\n                right: 0.25rem;\n            }\n\n            .caption-container {\n                bottom: 0.5rem;\n                height: 50px;\n            }\n\n            .caption-link {\n                font-size: clamp(0.8rem, 0.8rem + 1vw, 1.4rem);\n                padding: 0.15rem 0.5rem;\n            }\n        }\n\n        @media (max-width: 500px) {\n            .carousel-container {\n                min-height: 450px;\n                height: 450px;\n                margin: 1rem 0;\n            }\n\n            .slides-container {\n                min-height: 450px;\n            }\n\n            .slides-wrapper {\n                min-height: 450px;\n            }\n\n            .slide {\n                max-height: 410px;\n                padding: 0.2rem;\n            }\n\n            .slide img {\n                max-height: 410px;\n                max-width: 320px;\n            }\n\n            .carousel-nav-btn {\n                width: 32px;\n                height: 32px;\n                font-size: 16px;\n            }\n        }\n    </style>\n</head>\n\n<body>\n    <div id=\"nav-placeholder\"></div>\n\n    <!-- Hero Section -->\n    <section class=\"relative flex items-center justify-center overflow-hidden py-8 hero-section\">\n        <div class=\"absolute inset-0 bg-black bg-opacity-50\"></div>\n        <div class=\"relative z-10 text-center text-white px-4 w-full\">\n            <div class=\"max-w-3xl mx-auto\">\n                <div class=\"mb-2\">\n                    <p\n                        class=\"max-w-3xl mx-auto text-sm md:text-base leading-tight mb-2 px-4 py-2 text-gray-100 tracking-[0.2em] animate-fade-in-up animate-delay-200 corporate-text rounded-full bg-[#FF4F4F] inline-block\">\n                        BROWSE OUR\n                    </p>\n                    <h1 class=\"text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-light leading-tight animate-fade-in-up corporate-heading px-2\"\n                        style=\"font-family: \'AzoSansUber\', sans-serif;\">\n                        <span style=\"color: #FF4F4F;\">PROP</span> <span style=\"color: #18F1E1;\">COLLECTIONS</span>\n                    </h1>\n                </div>\n\n                <div class=\"h-px w-12 bg-white mx-auto my-3 animate-fade-in-up animate-delay-200\"></div>\n\n                <p\n                    class=\"max-w-3xl mx-auto text-sm md:text-base leading-relaxed mb-4 px-4 sm:px-0 text-gray-100 tracking-normal animate-fade-in-up animate-delay-200 corporate-text\">\n                    Take a look at some of the prop packages we offer for your event! Don\'t see any props that fit your\n                    event theme? Let us know and ask about our custom props!\n                </p>\n                <div class=\"mt-8 mb-8 animate-fade-in-up animate-delay-300\">\n                    <a href=\"./contact-us.html\"\n                        class=\"font-style-AzoSans btn btn-bubble btn-primary hero-button inline-block rounded-lg text-white font-light\"\n                        aria-label=\"Contact us for props\">\n                        Contact Us\n                    </a>\n                </div>\n\n                <div class=\"text-center opacity-90 animate-fade-in-up animate-delay-400\">\n                    <div class=\"h-px w-12 bg-white/70 mx-auto mb-3 transition-all duration-500\"></div>\n                    <p class=\"text-white/80 tracking-wider text-xs font-medium uppercase corporate-location px-4\">\n                        SERVICING DENVER, COLORADO, AND NATIONWIDE CORPORATE EVENTS\n                    </p>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Props1 Section -->\n    <section id=\"props1-section\" class=\"bg-gradient-to-br from-gray-900 via-blue-900 to-gray-900\"\n        style=\"padding: 3rem 0;\">\n        <div class=\"container mx-auto px-4\">\n            <div class=\"carousel-container\">\n                <div class=\"slides-container\" id=\"carousel-slides\">\n                    <div class=\"slides-wrapper\" id=\"slides-wrapper\">\n                        <button class=\"carousel-nav-btn prev\" id=\"prev-btn\" aria-label=\"Previous image\">\n                            <span class=\"material-icons\">arrow_back_ios</span>\n                        </button>\n                        <button class=\"carousel-nav-btn next\" id=\"next-btn\" aria-label=\"Next image\">\n                            <span class=\"material-icons\">arrow_forward_ios</span>\n                        </button>\n                        <!-- Slides will be dynamically inserted here -->\n                        <div class=\"caption-container\">\n                            <div class=\"caption-wrapper\">\n                                <a href=\"#\" class=\"caption-link\" id=\"caption-link\" target=\"_blank\"\n                                    rel=\"noopener noreferrer\"></a>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class=\"container mx-auto px-4 pt-4 pb-8\">\n                <div class=\"max-w-4xl mx-auto text-center\">\n                    <h2 class=\"props-cta-heading\" style=\"color: transparent;\">\n                        <span style=\"color: #FF4F4F;\">NEED PROPS?</span> <span style=\"color: #18F1E1;\">WE\'VE GOT \'EM\n                            ALL</span>\n                    </h2>\n                    <p class=\"props-cta-description\">\n                        Got a photo booth but don\'t know what props you want? From wigs and hats to glasses in every\n                        shape possible, we have \'em all.\n                    </p>\n                    <a href=\"./contact-us.html\" class=\"props-cta-button\"\n                        aria-label=\"Contact us to learn more about props\">\n                        CONTACT US TO LEARN MORE\n                    </a>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Props2 Section -->\n    <section id=\"props2-section\" class=\"bg-gradient-to-br from-slate-900 via-green-900 to-slate-900\"\n        style=\"padding: 3rem 0;\">\n        <div class=\"container mx-auto px-4\">\n            <div class=\"carousel-container\">\n                <div class=\"slides-container\" id=\"carousel-slides-2\">\n                    <div class=\"slides-wrapper\" id=\"slides-wrapper-2\">\n                        <button class=\"carousel-nav-btn prev\" id=\"prev-btn-2\" aria-label=\"Previous image\">\n                            <span class=\"material-icons\">arrow_back_ios</span>\n                        </button>\n                        <button class=\"carousel-nav-btn next\" id=\"next-btn-2\" aria-label=\"Next image\">\n                            <span class=\"material-icons\">arrow_forward_ios</span>\n                        </button>\n                        <!-- Slides will be dynamically inserted here -->\n                        <div class=\"caption-container\">\n                            <div class=\"caption-wrapper\">\n                                <a href=\"#\" class=\"caption-link\" id=\"caption-link-2\" target=\"_blank\"\n                                    rel=\"noopener noreferrer\"></a>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class=\"container mx-auto px-4 pt-4 pb-8\">\n                <div class=\"max-w-4xl mx-auto text-center\">\n                    <h2 class=\"props-cta-heading\" style=\"color: transparent;\">\n                        <span style=\"color: #FF4F4F;\">SIGNS FOR</span> <span style=\"color: #18F1E1;\">EVERYONE</span>\n                    </h2>\n                    <p class=\"props-cta-description\">\n                        Word signs are great for every event but especially great for these: Weddings, Quinceaneras,\n                        Employee Appreciation Parties, Gatsby/20s Shindigs, Bat/Mar Mitzvahs\n                    </p>\n                    <a href=\"./contact-us.html\" class=\"props-cta-button\"\n                        aria-label=\"Contact us to learn more about signs\">\n                        CONTACT US TO LEARN MORE\n                    </a>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Props3 Section -->\n    <section id=\"props3-section\" class=\"bg-gradient-to-br from-slate-900 via-red-900 to-slate-900\"\n        style=\"padding: 3rem 0;\">\n        <div class=\"container mx-auto px-4\">\n            <div class=\"carousel-container\">\n                <div class=\"slides-container\" id=\"carousel-slides-3\">\n                    <div class=\"slides-wrapper\" id=\"slides-wrapper-3\">\n                        <button class=\"carousel-nav-btn prev\" id=\"prev-btn-3\" aria-label=\"Previous image\">\n                            <span class=\"material-icons\">arrow_back_ios</span>\n                        </button>\n                        <button class=\"carousel-nav-btn next\" id=\"next-btn-3\" aria-label=\"Next image\">\n                            <span class=\"material-icons\">arrow_forward_ios</span>\n                        </button>\n                        <!-- Slides will be dynamically inserted here -->\n                        <div class=\"caption-container\">\n                            <div class=\"caption-wrapper\">\n                                <a href=\"#\" class=\"caption-link\" id=\"caption-link-3\" target=\"_blank\"\n                                    rel=\"noopener noreferrer\"></a>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class=\"container mx-auto px-4 pt-4 pb-8\">\n                <div class=\"max-w-4xl mx-auto text-center\">\n                    <h2 class=\"props-cta-heading\" style=\"color: transparent;\">\n                        <span style=\"color: #FF4F4F;\">HOLIDAY PROPS</span> <span style=\"color: #18F1E1;\">TO LAST ALL\n                            WINTER</span>\n                    </h2>\n                    <p class=\"props-cta-description\">\n                        You have to nail those much-anticipated holiday parties - so go all out with our winter-themed\n                        props!\n                    </p>\n                    <a href=\"./contact-us.html\" class=\"props-cta-button\"\n                        aria-label=\"Contact us to learn more about holiday props\">\n                        CONTACT US TO LEARN MORE\n                    </a>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Props4 Section -->\n    <section id=\"props4-section\" class=\"bg-gradient-to-br from-slate-900 via-violet-900 to-slate-900\"\n        style=\"padding: 3rem 0;\">\n        <div class=\"container mx-auto px-4\">\n            <div class=\"carousel-container\">\n                <div class=\"slides-container\" id=\"carousel-slides-4\">\n                    <div class=\"slides-wrapper\" id=\"slides-wrapper-4\">\n                        <button class=\"carousel-nav-btn prev\" id=\"prev-btn-4\" aria-label=\"Previous image\">\n                            <span class=\"material-icons\">arrow_back_ios</span>\n                        </button>\n                        <button class=\"carousel-nav-btn next\" id=\"next-btn-4\" aria-label=\"Next image\">\n                            <span class=\"material-icons\">arrow_forward_ios</span>\n                        </button>\n                        <!-- Slides will be dynamically inserted here -->\n                        <div class=\"caption-container\">\n                            <div class=\"caption-wrapper\">\n                                <a href=\"#\" class=\"caption-link\" id=\"caption-link-4\" target=\"_blank\"\n                                    rel=\"noopener noreferrer\"></a>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class=\"container mx-auto px-4 pt-4 pb-8\">\n                <div class=\"max-w-4xl mx-auto text-center\">\n                    <h2 class=\"props-cta-heading\" style=\"color: transparent;\">\n                        <span style=\"color: #FF4F4F;\">GUN-SLINGERS, COWBOYS</span> <span\n                            style=\"color: #18F1E1;\">BANDITS, UNITE</span>\n                    </h2>\n                    <p class=\"props-cta-description\">\n                        We have the goods to make your Western theme complete! Take a look at our Rustic Booth to match\n                        your event.\n                    </p>\n                    <a href=\"./contact-us.html\" class=\"props-cta-button\"\n                        aria-label=\"Contact us to learn more about western props\">\n                        CONTACT US TO LEARN MORE\n                    </a>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Props5 Section -->\n    <section id=\"props5-section\" class=\"bg-gradient-to-br from-slate-900 via-yellow-900 to-slate-900\"\n        style=\"padding: 3rem 0;\">\n        <div class=\"container mx-auto px-4\">\n            <div class=\"carousel-container\">\n                <div class=\"slides-container\" id=\"carousel-slides-5\">\n                    <div class=\"slides-wrapper\" id=\"slides-wrapper-5\">\n                        <button class=\"carousel-nav-btn prev\" id=\"prev-btn-5\" aria-label=\"Previous image\">\n                            <span class=\"material-icons\">arrow_back_ios</span>\n                        </button>\n                        <button class=\"carousel-nav-btn next\" id=\"next-btn-5\" aria-label=\"Next image\">\n                            <span class=\"material-icons\">arrow_forward_ios</span>\n                        </button>\n                        <!-- Slides will be dynamically inserted here -->\n                        <div class=\"caption-container\">\n                            <div class=\"caption-wrapper\">\n                                <a href=\"#\" class=\"caption-link\" id=\"caption-link-5\" target=\"_blank\"\n                                    rel=\"noopener noreferrer\"></a>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class=\"container mx-auto px-4 pt-4 pb-8\">\n                <div class=\"max-w-4xl mx-auto text-center\">\n                    <h2 class=\"props-cta-heading\" style=\"color: transparent;\">\n                        <span style=\"color: #FF4F4F;\">ROARIN\' 20S PROPS</span> <span style=\"color: #18F1E1;\">FOR YOUR\n                            NEXT SHINDIG</span>\n                    </h2>\n                    <p class=\"props-cta-description\">\n                        Had enough of Gatsby-inspired galas and references to the new Roarin\' 20s? Not us!\n                    </p>\n                    <a href=\"./contact-us.html\" class=\"props-cta-button\"\n                        aria-label=\"Contact us to learn more about 20s props\">\n                        CONTACT US TO LEARN MORE\n                    </a>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <script src=\"../assets/components/navigation.js\"></script>\n    <script src=\"../assets/components/footer.js\"></script>\n\n    <script>\n        // Curved Carousel Implementation\n        document.addEventListener(\'DOMContentLoaded\', function () {\n            const images = [\n                {\n                    src: \'../assets/images/galleries/ourprops/prop1.png\',\n                },\n                {\n                    src: \'../assets/images/galleries/ourprops/prop2.png\',\n                },\n                {\n                    src: \'../assets/images/galleries/ourprops/prop3.png\',\n                },\n                {\n                    src: \'../assets/images/galleries/ourprops/prop4.png\',\n                }\n            ];\n\n            const slidesWrapper = document.getElementById(\'slides-wrapper\');\n            const prevBtn = document.getElementById(\'prev-btn\');\n            const nextBtn = document.getElementById(\'next-btn\');\n            const captionLink = document.getElementById(\'caption-link\');\n            const slidesContainer = document.getElementById(\'carousel-slides\');\n\n            if (!slidesWrapper || !prevBtn || !nextBtn || !slidesContainer) {\n                console.error(\'Carousel elements not found\');\n                return;\n            }\n\n            let currentIndex = 1; // Start at middle image (index 1) for better balance with 4 images\n            let windowWidth = window.innerWidth;\n            let windowHeight = window.innerHeight;\n            let slideWidth = 400;\n            let isDragging = false;\n            let dragStart = 0;\n            let dragOffset = 0;\n            let wheelVelocity = 0;\n\n            // Calculate slide width based on viewport - even larger images\n            function calculateSlideWidth() {\n                windowWidth = window.innerWidth;\n                windowHeight = window.innerHeight;\n\n                // Much larger sizing for bigger images\n                if (windowWidth >= 960) {\n                    slideWidth = Math.min(windowWidth / 2.2, 480);\n                } else if (windowWidth >= 640) {\n                    slideWidth = Math.min(windowWidth / 1.8, 400);\n                } else {\n                    slideWidth = Math.min(windowWidth / 1.6, 340);\n                }\n\n                // Ensure reasonable bounds\n                slideWidth = Math.max(250, Math.min(slideWidth, 480));\n                console.log(\'Slide width calculated:\', slideWidth, \'Window:\', windowWidth, \'x\', windowHeight);\n            }\n\n            // Calculate curved position with proper wrapping for balance\n            function getCurvedPosition(index, centerOffset = 0) {\n                const totalSlides = images.length;\n\n                // Calculate raw relative position\n                let relativeIndex = index - currentIndex - centerOffset;\n\n                // Wrap to ensure images appear on both sides\n                // We want images distributed around center: -2, -1, 0, 1 for 4 images\n                // Or when centered: -1.5, -0.5, 0.5, 1.5\n\n                // Find the shortest distance around the circle\n                const halfRange = totalSlides / 2;\n                while (relativeIndex > halfRange) {\n                    relativeIndex -= totalSlides;\n                }\n                while (relativeIndex < -halfRange) {\n                    relativeIndex += totalSlides;\n                }\n\n                // More compact spacing\n                const spacing = slideWidth * 0.65;\n                const xPos = relativeIndex * spacing;\n\n                // Curved Y position - creates arc effect (more compact)\n                // Use absolute value so both sides curve downward\n                const curveIntensity = windowWidth <= 640 ? 20 : 30; // Less curve on mobile\n                const yPos = -Math.pow(Math.abs(relativeIndex), 1.3) * curveIntensity;\n\n                // Rotation for 3D effect - negative on left, positive on right (more subtle)\n                const rotation = relativeIndex * (windowWidth <= 640 ? 4 : 6); // Less rotation on mobile\n\n                return {\n                    x: xPos,\n                    y: yPos,\n                    rotation: -rotation\n                };\n            }\n\n            // Create slide elements\n            function createSlides() {\n                // Clear existing slides\n                const existingSlides = slidesWrapper.querySelectorAll(\'.slide\');\n                existingSlides.forEach(slide => slide.remove());\n\n                console.log(\'Creating slides for\', images.length, \'images\');\n\n                images.forEach((img, index) => {\n                    const slide = document.createElement(\'div\');\n                    slide.className = \'slide\';\n                    slide.dataset.index = index;\n                    slide.id = `slide-${index}`;\n\n                    const figure = document.createElement(\'figure\');\n                    figure.id = `f${index}`;\n\n                    const imgElement = document.createElement(\'img\');\n                    // Try both relative paths\n                    const imgSrc = img.src.startsWith(\'../\') ? img.src : \'../\' + img.src;\n                    imgElement.src = imgSrc;\n                    imgElement.alt = img.alt || `Prop ${index + 1}`;\n                    imgElement.draggable = false;\n\n                    // Even larger image sizing\n                    const maxImgWidth = windowWidth <= 640 ? 340 : windowWidth <= 960 ? 440 : 480;\n                    imgElement.style.width = Math.min(slideWidth, maxImgWidth) + \'px\';\n                    imgElement.style.maxWidth = maxImgWidth + \'px\';\n                    imgElement.style.height = \'auto\';\n                    imgElement.style.display = \'block\';\n                    imgElement.style.objectFit = \'contain\';\n                    imgElement.style.opacity = \'1\';\n                    imgElement.style.visibility = \'visible\';\n                    imgElement.style.position = \'relative\';\n\n                    // Add error handling for images\n                    imgElement.onerror = function () {\n                        console.error(\'❌ Failed to load image:\', imgSrc);\n                        console.error(\'Trying alternative path...\');\n                        // Try absolute path\n                        const altPath = \'assets/images/galleries/ourprops/prop\' + (index + 1) + \'.png\';\n                        this.src = altPath;\n\n                        this.onerror = function () {\n                            console.error(\'❌ Also failed:\', altPath);\n                            // Show placeholder\n                            this.style.border = \'2px solid red\';\n                            this.style.backgroundColor = \'#333\';\n                            this.style.width = \'200px\';\n                            this.style.height = \'200px\';\n                            this.style.display = \'flex\';\n                            this.style.alignItems = \'center\';\n                            this.style.justifyContent = \'center\';\n                            this.innerHTML = \'<span style=\"color: white;\">Image \' + (index + 1) + \'</span>\';\n                        };\n                    };\n\n                    imgElement.onload = function () {\n                        console.log(\'✓ Successfully loaded image:\', this.src);\n                    };\n\n                    figure.appendChild(imgElement);\n                    slide.appendChild(figure);\n\n                    // Insert before caption container\n                    const captionContainer = slidesWrapper.querySelector(\'.caption-container\');\n                    if (captionContainer) {\n                        slidesWrapper.insertBefore(slide, captionContainer);\n                    } else {\n                        slidesWrapper.appendChild(slide);\n                    }\n\n                    console.log(\'Created slide\', index, \'at element:\', slide);\n                });\n\n                // Wait a moment for images to start loading, then position them\n                setTimeout(() => {\n                    attachSlideListeners();\n                    updateCarousel();\n                }, 100);\n            }\n\n            function attachSlideListeners() {\n                document.querySelectorAll(\'.slide figure\').forEach((figure, index) => {\n                    const slideIndex = parseInt(figure.closest(\'.slide\').dataset.index);\n                    figure.addEventListener(\'mousedown\', (e) => startDrag(e, slideIndex));\n                    figure.addEventListener(\'touchstart\', (e) => startDrag(e, slideIndex));\n                });\n            }\n\n            // Update carousel positions\n            function updateCarousel(offset = 0) {\n                const slides = document.querySelectorAll(\'.slide\');\n                if (slides.length === 0) {\n                    console.warn(\'No slides found in updateCarousel\');\n                    return;\n                }\n\n                console.log(\'Updating carousel with\', slides.length, \'slides, offset:\', offset);\n\n                const centerOffset = offset;\n\n                slides.forEach((slide) => {\n                    const index = parseInt(slide.dataset.index);\n                    const pos = getCurvedPosition(index, centerOffset);\n\n                    // Transform from center (left: 50%, top: 50%)\n                    slide.style.transform = `translate(calc(-50% + ${pos.x}px), calc(-50% + ${pos.y}px)) rotate(${pos.rotation}deg)`;\n                    slide.style.zIndex = images.length - Math.abs(index - currentIndex);\n                    slide.style.visibility = \'visible\';\n                    slide.style.opacity = \'1\';\n                    slide.style.display = \'flex\';\n\n                    const img = slide.querySelector(\'img\');\n                    if (!img) {\n                        console.warn(\'No image found in slide\', index);\n                        return;\n                    }\n\n                    // Ensure image is visible\n                    img.style.display = \'block\';\n                    img.style.opacity = \'1\';\n                    img.style.visibility = \'visible\';\n\n                    // Calculate distance for scaling (using wrapped distance)\n                    let relativeIndex = index - currentIndex - centerOffset;\n                    const totalSlides = images.length;\n                    const halfRange = totalSlides / 2;\n                    while (relativeIndex > halfRange) relativeIndex -= totalSlides;\n                    while (relativeIndex < -halfRange) relativeIndex += totalSlides;\n                    const distance = Math.abs(relativeIndex);\n\n                    // Scale based on distance from center\n                    if (distance < 0.5) {\n                        // Center image - largest\n                        img.style.transform = \'scale(1.15)\';\n                        img.style.opacity = \'1\';\n                        img.style.boxShadow = \'5px 5px 50px -1px rgba(255, 255, 255, 0.6)\';\n                        img.style.zIndex = \'10\';\n                    } else if (distance < 1.5) {\n                        // Near center - medium size\n                        const scale = 1 - (distance - 0.5) * 0.2;\n                        img.style.transform = `scale(${scale})`;\n                        img.style.opacity = Math.max(0.7, 1 - (distance - 0.5) * 0.15);\n                        img.style.boxShadow = \'5px 5px 50px -1px rgba(255, 255, 255, 0.4)\';\n                        img.style.zIndex = \'5\';\n                    } else {\n                        // Far from center - smaller\n                        const scale = Math.max(0.5, 0.8 - (distance - 1.5) * 0.15);\n                        img.style.transform = `scale(${scale})`;\n                        img.style.opacity = Math.max(0.3, 0.6 - (distance - 1.5) * 0.1);\n                        img.style.boxShadow = \'5px 5px 50px -1px rgba(0, 0, 0, 0.8)\';\n                        img.style.zIndex = \'1\';\n                    }\n\n                    console.log(`Slide ${index}: relativeIndex=${relativeIndex.toFixed(2)}, x=${pos.x.toFixed(0)}, y=${pos.y.toFixed(0)}, rot=${pos.rotation.toFixed(1)}deg`);\n                });\n\n                // Update caption (hide if no caption exists)\n                const captionContainer = slidesWrapper.querySelector(\'.caption-container\');\n                if (captionLink && captionContainer) {\n                    if (images[currentIndex] && images[currentIndex].caption) {\n                        captionLink.textContent = images[currentIndex].caption;\n                        captionLink.href = images[currentIndex].href || \'#\';\n                        captionLink.style.display = \'inline-block\';\n                        captionContainer.style.display = \'flex\';\n                    } else {\n                        captionLink.style.display = \'none\';\n                        captionContainer.style.display = \'none\';\n                    }\n                }\n\n                console.log(\'Carousel updated, currentIndex:\', currentIndex);\n            }\n\n            // Navigate carousel\n            function navigate(direction) {\n                currentIndex += direction;\n                if (currentIndex < 0) currentIndex = images.length - 1;\n                if (currentIndex >= images.length) currentIndex = 0;\n                updateCarousel();\n            }\n\n            // Drag handlers\n            function startDrag(e, index) {\n                if (index !== currentIndex) return;\n                isDragging = true;\n                dragStart = e.type.includes(\'mouse\') ? e.pageX : e.touches[0].clientX;\n                dragOffset = 0;\n\n                const slide = document.querySelector(`.slide[data-index=\"${index}\"]`);\n                if (slide) slide.classList.add(\'grabbed\');\n\n                document.addEventListener(\'mousemove\', handleDrag);\n                document.addEventListener(\'mouseup\', endDrag);\n                document.addEventListener(\'touchmove\', handleDrag);\n                document.addEventListener(\'touchend\', endDrag);\n            }\n\n            function handleDrag(e) {\n                if (!isDragging) return;\n                e.preventDefault();\n                const currentX = e.type.includes(\'mouse\') ? e.pageX : e.touches[0].clientX;\n                const diff = (currentX - dragStart) * 0.85;\n                dragOffset = diff;\n\n                if (Math.abs(diff / slideWidth) < 0.75) {\n                    updateCarousel(-diff / slideWidth);\n                }\n            }\n\n            function endDrag() {\n                if (!isDragging) return;\n                isDragging = false;\n\n                const slide = document.querySelector(\'.slide.grabbed\');\n                if (slide) slide.classList.remove(\'grabbed\');\n\n                const threshold = 0.2;\n                if (Math.abs(dragOffset / slideWidth) >= threshold) {\n                    navigate(-Math.sign(dragOffset));\n                } else {\n                    updateCarousel();\n                }\n\n                dragOffset = 0;\n\n                document.removeEventListener(\'mousemove\', handleDrag);\n                document.removeEventListener(\'mouseup\', endDrag);\n                document.removeEventListener(\'touchmove\', handleDrag);\n                document.removeEventListener(\'touchend\', endDrag);\n            }\n\n            // Wheel handler\n            function handleWheel(e) {\n                const direction = Math.sign(e.deltaY);\n\n                if ((direction > 0 && wheelVelocity < 0) || (direction < 0 && wheelVelocity > 0)) {\n                    wheelVelocity = 0;\n                }\n\n                wheelVelocity += 0.2 * direction;\n\n                if (Math.abs(wheelVelocity) > 1) {\n                    navigate(Math.sign(wheelVelocity));\n                    wheelVelocity = 0;\n                }\n            }\n\n            // Event listeners\n            prevBtn.addEventListener(\'click\', () => navigate(-1));\n            nextBtn.addEventListener(\'click\', () => navigate(1));\n            slidesContainer.addEventListener(\'wheel\', handleWheel);\n\n            // Prevent image dragging\n            document.addEventListener(\'dragstart\', (e) => {\n                if (e.target.tagName === \'IMG\') {\n                    e.preventDefault();\n                }\n            });\n\n            // Initialize\n            setTimeout(() => {\n                console.log(\'Initializing carousel...\');\n                console.log(\'Images array:\', images);\n                console.log(\'Image paths:\', images.map(img => img.src));\n                calculateSlideWidth();\n                createSlides();\n                console.log(\'Carousel initialized with\', images.length, \'images\');\n\n                // Force update after a short delay to ensure images load\n                setTimeout(() => {\n                    updateCarousel();\n                }, 500);\n            }, 200);\n\n            window.addEventListener(\'resize\', () => {\n                calculateSlideWidth();\n                createSlides();\n            });\n\n            // Auto-update on orientation change\n            window.addEventListener(\'orientationchange\', () => {\n                setTimeout(() => {\n                    calculateSlideWidth();\n                    createSlides();\n                }, 100);\n            });\n\n            // Prevent default on carousel container\n            slidesContainer.addEventListener(\'click\', (e) => {\n                if (e.target.closest(\'.carousel-nav-btn\')) return;\n                e.preventDefault();\n            });\n        });\n\n        // Curved Carousel Implementation for Props2 Section\n        document.addEventListener(\'DOMContentLoaded\', function () {\n            const images2 = [\n                {\n                    src: \'../assets/images/galleries/ourprops/prop5.png\',\n                },\n                {\n                    src: \'../assets/images/galleries/ourprops/prop6.png\',\n                },\n                {\n                    src: \'../assets/images/galleries/ourprops/prop7.png\',\n                },\n                {\n                    src: \'../assets/images/galleries/ourprops/prop8.png\',\n                }\n            ];\n\n            const slidesWrapper2 = document.getElementById(\'slides-wrapper-2\');\n            const prevBtn2 = document.getElementById(\'prev-btn-2\');\n            const nextBtn2 = document.getElementById(\'next-btn-2\');\n            const captionLink2 = document.getElementById(\'caption-link-2\');\n            const slidesContainer2 = document.getElementById(\'carousel-slides-2\');\n\n            if (!slidesWrapper2 || !prevBtn2 || !nextBtn2 || !slidesContainer2) {\n                console.error(\'Carousel 2 elements not found\');\n                return;\n            }\n\n            let currentIndex2 = 1;\n            let windowWidth2 = window.innerWidth;\n            let windowHeight2 = window.innerHeight;\n            let slideWidth2 = 400;\n            let isDragging2 = false;\n            let dragStart2 = 0;\n            let dragOffset2 = 0;\n            let wheelVelocity2 = 0;\n\n            function calculateSlideWidth2() {\n                windowWidth2 = window.innerWidth;\n                windowHeight2 = window.innerHeight;\n\n                if (windowWidth2 >= 960) {\n                    slideWidth2 = Math.min(windowWidth2 / 2.2, 480);\n                } else if (windowWidth2 >= 640) {\n                    slideWidth2 = Math.min(windowWidth2 / 1.8, 400);\n      