t.src = imgSrc;\n                    imgElement.alt = img.alt || `Prop ${index + 5}`;\n                    imgElement.draggable = false;\n\n                    const maxImgWidth = windowWidth2 <= 640 ? 340 : windowWidth2 <= 960 ? 440 : 480;\n                    imgElement.style.width = Math.min(slideWidth2, maxImgWidth) + \'px\';\n                    imgElement.style.maxWidth = maxImgWidth + \'px\';\n                    imgElement.style.height = \'auto\';\n                    imgElement.style.display = \'block\';\n                    imgElement.style.objectFit = \'contain\';\n                    imgElement.style.opacity = \'1\';\n                    imgElement.style.visibility = \'visible\';\n                    imgElement.style.position = \'relative\';\n\n                    imgElement.onerror = function () {\n                        console.error(\'❌ Failed to load image:\', imgSrc);\n                        const altPath = \'assets/images/galleries/ourprops/prop\' + (index + 5) + \'.png\';\n                        this.src = altPath;\n                        this.onerror = function () {\n                            console.error(\'❌ Also failed:\', altPath);\n                            this.style.border = \'2px solid red\';\n                            this.style.backgroundColor = \'#333\';\n                            this.style.width = \'200px\';\n                            this.style.height = \'200px\';\n                            this.style.display = \'flex\';\n                            this.style.alignItems = \'center\';\n                            this.style.justifyContent = \'center\';\n                            this.innerHTML = \'<span style=\"color: white;\">Image \' + (index + 5) + \'</span>\';\n                        };\n                    };\n\n                    imgElement.onload = function () {\n                        console.log(\'✓ Successfully loaded image:\', this.src);\n                    };\n\n                    figure.appendChild(imgElement);\n                    slide.appendChild(figure);\n\n                    const captionContainer = slidesWrapper2.querySelector(\'.caption-container\');\n                    if (captionContainer) {\n                        slidesWrapper2.insertBefore(slide, captionContainer);\n                    } else {\n                        slidesWrapper2.appendChild(slide);\n                    }\n                });\n\n                setTimeout(() => {\n                    attachSlideListeners2();\n                    updateCarousel2();\n                }, 100);\n            }\n\n            function attachSlideListeners2() {\n                document.querySelectorAll(\'#slides-wrapper-2 .slide figure\').forEach((figure) => {\n                    const slideIndex = parseInt(figure.closest(\'.slide\').dataset.index);\n                    figure.addEventListener(\'mousedown\', (e) => startDrag2(e, slideIndex));\n                    figure.addEventListener(\'touchstart\', (e) => startDrag2(e, slideIndex));\n                });\n            }\n\n            function updateCarousel2(offset = 0) {\n                const slides = slidesWrapper2.querySelectorAll(\'.slide\');\n                if (slides.length === 0) {\n                    console.warn(\'No slides found in carousel 2\');\n                    return;\n                }\n\n                const centerOffset = offset;\n\n                slides.forEach((slide) => {\n                    const index = parseInt(slide.dataset.index);\n                    const pos = getCurvedPosition2(index, centerOffset);\n\n                    slide.style.transform = `translate(calc(-50% + ${pos.x}px), calc(-50% + ${pos.y}px)) rotate(${pos.rotation}deg)`;\n                    slide.style.zIndex = images2.length - Math.abs(index - currentIndex2);\n                    slide.style.visibility = \'visible\';\n                    slide.style.opacity = \'1\';\n                    slide.style.display = \'flex\';\n\n                    const img = slide.querySelector(\'img\');\n                    if (!img) return;\n\n                    img.style.display = \'block\';\n                    img.style.opacity = \'1\';\n                    img.style.visibility = \'visible\';\n\n                    let relativeIndex = index - currentIndex2 - centerOffset;\n                    const totalSlides = images2.length;\n                    const halfRange = totalSlides / 2;\n                    while (relativeIndex > halfRange) relativeIndex -= totalSlides;\n                    while (relativeIndex < -halfRange) relativeIndex += totalSlides;\n                    const distance = Math.abs(relativeIndex);\n\n                    if (distance < 0.5) {\n                        img.style.transform = \'scale(1.15)\';\n                        img.style.opacity = \'1\';\n                        img.style.boxShadow = \'5px 5px 50px -1px rgba(255, 255, 255, 0.6)\';\n                        img.style.zIndex = \'10\';\n                    } else if (distance < 1.5) {\n                        const scale = 1 - (distance - 0.5) * 0.2;\n                        img.style.transform = `scale(${scale})`;\n                        img.style.opacity = Math.max(0.7, 1 - (distance - 0.5) * 0.15);\n                        img.style.boxShadow = \'5px 5px 50px -1px rgba(255, 255, 255, 0.4)\';\n                        img.style.zIndex = \'5\';\n                    } else {\n                        const scale = Math.max(0.5, 0.8 - (distance - 1.5) * 0.15);\n                        img.style.transform = `scale(${scale})`;\n                        img.style.opacity = Math.max(0.3, 0.6 - (distance - 1.5) * 0.1);\n                        img.style.boxShadow = \'5px 5px 50px -1px rgba(0, 0, 0, 0.8)\';\n                        img.style.zIndex = \'1\';\n                    }\n                });\n\n                const captionContainer = slidesWrapper2.querySelector(\'.caption-container\');\n                if (captionLink2 && captionContainer) {\n                    if (images2[currentIndex2] && images2[currentIndex2].caption) {\n                        captionLink2.textContent = images2[currentIndex2].caption;\n                        captionLink2.href = images2[currentIndex2].href || \'#\';\n                        captionLink2.style.display = \'inline-block\';\n                        captionContainer.style.display = \'flex\';\n                    } else {\n                        captionLink2.style.display = \'none\';\n                        captionContainer.style.display = \'none\';\n                    }\n                }\n            }\n\n            function navigate2(direction) {\n                currentIndex2 += direction;\n                if (currentIndex2 < 0) currentIndex2 = images2.length - 1;\n                if (currentIndex2 >= images2.length) currentIndex2 = 0;\n                updateCarousel2();\n            }\n\n            function startDrag2(e, index) {\n                if (index !== currentIndex2) return;\n                isDragging2 = true;\n                dragStart2 = e.type.includes(\'mouse\') ? e.pageX : e.touches[0].clientX;\n                dragOffset2 = 0;\n\n                const slide = slidesWrapper2.querySelector(`.slide[data-index=\"${index}\"]`);\n                if (slide) slide.classList.add(\'grabbed\');\n\n                document.addEventListener(\'mousemove\', handleDrag2);\n                document.addEventListener(\'mouseup\', endDrag2);\n                document.addEventListener(\'touchmove\', handleDrag2);\n                document.addEventListener(\'touchend\', endDrag2);\n            }\n\n            function handleDrag2(e) {\n                if (!isDragging2) return;\n                e.preventDefault();\n                const currentX = e.type.includes(\'mouse\') ? e.pageX : e.touches[0].clientX;\n                const diff = (currentX - dragStart2) * 0.85;\n                dragOffset2 = diff;\n\n                if (Math.abs(diff / slideWidth2) < 0.75