 = document.getElementById(\'next-btn-5\');\n            const captionLink5 = document.getElementById(\'caption-link-5\');\n            const slidesContainer5 = document.getElementById(\'carousel-slides-5\');\n\n            if (!slidesWrapper5 || !prevBtn5 || !nextBtn5 || !slidesContainer5) {\n                console.error(\'Carousel 5 elements not found\');\n                return;\n            }\n\n            let currentIndex5 = 1;\n            let windowWidth5 = window.innerWidth;\n            let windowHeight5 = window.innerHeight;\n            let slideWidth5 = 400;\n            let isDragging5 = false;\n            let dragStart5 = 0;\n            let dragOffset5 = 0;\n            let wheelVelocity5 = 0;\n\n            function calculateSlideWidth5() {\n                windowWidth5 = window.innerWidth;\n                windowHeight5 = window.innerHeight;\n\n                if (windowWidth5 >= 960) {\n                    slideWidth5 = Math.min(windowWidth5 / 2.2, 480);\n                } else if (windowWidth5 >= 640) {\n                    slideWidth5 = Math.min(windowWidth5 / 1.8, 400);\n                } else {\n                    slideWidth5 = Math.min(windowWidth5 / 1.6, 340);\n                }\n\n                slideWidth5 = Math.max(250, Math.min(slideWidth5, 480));\n            }\n\n            function getCurvedPosition5(index, centerOffset = 0) {\n                const totalSlides = images5.length;\n                let relativeIndex = index - currentIndex5 - centerOffset;\n\n                const halfRange = totalSlides / 2;\n                while (relativeIndex > halfRange) {\n                    relativeIndex -= totalSlides;\n                }\n                while (relativeIndex < -halfRange) {\n                    relativeIndex += totalSlides;\n                }\n\n                const spacing = slideWidth5 * 0.65;\n                const xPos = relativeIndex * spacing;\n                const curveIntensity = windowWidth5 <= 640 ? 20 : 30;\n                const yPos = -Math.pow(Math.abs(relativeIndex), 1.3) * curveIntensity;\n                const rotation = relativeIndex * (windowWidth5 <= 640 ? 4 : 6);\n\n                return {\n                    x: xPos,\n                    y: yPos,\n                    rotation: -rotation\n                };\n            }\n\n            function createSlides5() {\n                const existingSlides = slidesWrapper5.querySelectorAll(\'.slide\');\n                existingSlides.forEach(slide => slide.remove());\n\n                images5.forEach((img, index) => {\n                    const slide = document.createElement(\'div\');\n                    slide.className = \'slide\';\n                    slide.dataset.index = index;\n                    slide.id = `slide-5-${index}`;\n\n                    const figure = document.createElement(\'figure\');\n                    figure.id = `f5-${index}`;\n\n                    const imgElement = document.createElement(\'img\');\n                    const imgSrc = img.src.startsWith(\'../\') ? img.src : \'../\' + img.src;\n                    imgElement.src = imgSrc;\n                    imgElement.alt = img.alt || `Prop ${index + 17}`;\n                    imgElement.draggable = false;\n\n                    const maxImgWidth = windowWidth5 <= 640 ? 340 : windowWidth5 <= 960 ? 440 : 480;\n                    imgElement.style.width = Math.min(slideWidth5, maxImgWidth) + \'px\';\n                    imgElement.style.maxWidth = maxImgWidth + \'px\';\n                    imgElement.style.height = \'auto\';\n                    imgElement.style.display = \'block\';\n                    imgElement.style.objectFit = \'contain\';\n                    imgElement.style.opacity = \'1\';\n                    imgElement.style.visibility = \'visible\';\n                    imgElement.style.position = \'relative\';\n\n                    imgElement.onerror = function () {\n                        console.error(\'❌ Failed to load image:\', imgSrc);\n                        const altPath = \'assets/images/galleries/ourprops/prop\' + (index + 17) + \'.png\';\n                        this.src = altPath;\n                        this.onerror = function () {\n                            console.error(\'❌ Also failed:\', altPath);\n                            this.style.border = \'2px solid red\';\n                            this.style.backgroundColor = \'#333\';\n                            this.style.width = \'200px\';\n                            this.style.height = \'200px\';\n                            this.style.display = \'flex\';\n                            this.style.alignItems = \'center\';\n                            this.style.justifyContent = \'center\';\n                            this.innerHTML = \'<span style=\"color: white;\">Image \' + (index + 17) + \'</span>\';\n                        };\n                    };\n\n                    imgElement.onload = function () {\n                        console.log(\'✓ Successfully loaded image:\', this.src);\n                    };\n\n                    figure.appendChild(imgElement);\n                    slide.appendChild(figure);\n\n                    const captionContainer = slidesWrapper5.querySelector(\'.caption-container\');\n                    if (captionContainer) {\n                        slidesWrapper5.insertBefore(slide, captionContainer);\n                    } else {\n                        slidesWrapper5.appendChild(slide);\n                    }\n                });\n\n                setTimeout(() => {\n                    attachSlideListeners5();\n                    updateCarousel5();\n                }, 100);\n            }\n\n            function attachSlideListeners5() {\n                document.querySelectorAll(\'#slides-wrapper-5 .slide figure\').forEach((figure) => {\n                    const slideIndex = parseInt(figure.closest(\'.slide\').dataset.index);\n                    figure.addEventListener(\'mousedown\', (e) => startDrag5(e, slideIndex));\n                    figure.addEventListener(\'touchstart\', (e) => startDrag5(e, slideIndex));\n                });\n            }\n\n            function updateCarousel5(offset = 0) {\n                const slides = slidesWrapper5.querySelectorAll(\'.slide\');\n                if (slides.length === 0) {\n                    console.warn(\'No slides found in carousel 5\');\n                    return;\n                }\n\n                const centerOffset = offset;\n\n                slides.forEach((slide) => {\n                    const index = parseInt(slide.dataset.index);\n                    const pos = getCurvedPosition5(index, centerOffset);\n\n                    slide.style.transform = `translate(calc(-50% + ${pos.x}px), calc(-50% + ${pos.y}px)) rotate(${pos.rotation}deg)`;\n                    slide.style.zIndex = images5.length - Math.abs(index - currentIndex5);\n                    slide.style.visibility = \'visible\';\n                    slide.style.opacity = \'1\';\n                    slide.style.display = \'flex\';\n\n                    const img = slide.querySelector(\'img\');\n                    if (!img) return;\n\n                    img.style.display = \'block\';\n                    img.style.opacity = \'1\';\n                    img.style.visibility = \'visible\';\n\n                    let relativeIndex = index - currentIndex5 - centerOffset;\n                    const totalSlides = images5.length;\n                    const halfRange = totalSlides / 2;\n                    while (relativeIndex > halfRange) relativeIndex -= totalSlides;\n                    while (relativeIndex < -halfRange) relativeIndex += totalSlides;\n                    const distance = Math.abs(relativeIndex);\n\n                    if (distance < 0.5) {\n                        img.style.transform = \'scale(1.15)\';\n                        img.style.opacity = \'1\';\n                        img.style.boxShadow = \'5px 5px 50px -1px rgba(255, 255, 255, 0.6)\';\n                        img.style.zIndex = \'10\';\n                    } else if (distance < 1.5) {\n                        const scale = 1 - (distance - 0.5) * 0.2;\n                        img.style.transform = `scale(${scale})`;\n                        img.style.opacity = Math.max(0.7, 1 - (distance - 0.5) * 0.15);\n                        img.style.boxShadow = \'5px 5px 50px -1px rgba(255, 255, 255, 0.4)\';\n                        img.style.zIndex = \'5\';\n                    } else {\n                        const scale = Math.max(0.5, 0.8 - (distance - 1.5) * 0.15);\n                        img.style.transform = `scale(${scale})`;\n                        img.style.opacity = Math.max(0.3, 0.6 - (distance - 1.5) * 0.1);\n                        img.style.boxShadow = \'5px 5px 50px -1px rgba(0, 0, 0, 0.8)\';\n                        img.style.zIndex = \'1\';\n                    }\n                });\n\n                const captionContainer = slidesWrapper5.querySelector(\'.caption-container\');\n                if (captionLink5 && captionContainer) {\n                    if (images5[currentIndex5] && images5[currentIndex5].caption) {\n                        captionLink5.textContent = images5[currentIndex5].caption;\n                        captionLink5.href = images5[currentIndex5].href || \'#\';\n                        captionLink5.style.display = \'inline-block\';\n                        captionContainer.style.display = \'flex\';\n                    } else {\n                        captionLink5.style.display = \'none\';\n                        captionContainer.style.display = \'none\';\n                    }\n                }\n            }\n\n            function navigate5(direction) {\n                currentIndex5 += direction;\n                if (currentIndex5 < 0) currentIndex5 = images5.length - 1;\n                if (currentIndex5 >= images5.length) currentIndex5 = 0;\n                updateCarousel5();\n            }\n\n            function startDrag5(e, index) {\n                if (index !== currentIndex5) return;\n                isDragging5 = true;\n                dragStart5 = e.type.includes(\'mouse\') ? e.pageX : e.touches[0].clientX;\n                dragOffset5 = 0;\n\n                const slide = slidesWrapper5.querySelector(`.slide[data-index=\"${index}\"]`);\n                if (slide) slide.classList.add(\'grabbed\');\n\n                document.addEventListener(\'mousemove\', handleDrag5);\n                document.addEventListener(\'mouseup\', endDrag5);\n                document.addEventListener(\'touchmove\', handleDrag5);\n                document.addEventListener(\'touchend\', endDrag5);\n            }\n\n            function handleDrag5(e) {\n                if (!isDragging5) return;\n                e.preventDefault();\n                const currentX = e.type.includes(\'mouse\') ? e.pageX : e.touches[0].clientX;\n                const diff = (currentX - dragStart5) * 0.85;\n                dragOffset5 = diff;\n\n                if (Math.abs(diff / slideWidth5) < 0.75) {\n                    updateCarousel5(-diff / slideWidth5);\n                }\n            }\n\n            function endDrag5() {\n                if (!isDragging5) return;\n                isDragging5 = false;\n\n                const slide = slidesWrapper5.querySelector(\'.slide.grabbed\');\n                if (slide) slide.classList.remove(\'grabbed\');\n\n                const threshold = 0.2;\n                if (Math.abs(dragOffset5 / slideWidth5) >= threshold) {\n                    navigate5(-Math.sign(dragOffset5));\n                } else {\n                    updateCarousel5();\n                }\n\n                dragOffset5 = 0;\n\n                document.removeEventListener(\'mousemove\', handleDrag5);\n                document.removeEventListener(\'mouseup\', endDrag5);\n                document.removeEventListener(\'touchmove\', handleDrag5);\n                document.removeEventListener(\'touchend\', endDrag5);\n            }\n\n            function handleWheel5(e) {\n                if (!slidesContainer5.contains(e.target) && !slidesWrapper5.contains(e.target)) return;\n                const direction = Math.sign(e.deltaY);\n\n                if ((direction > 0 && wheelVelocity5 < 0) || (direction < 0 && wheelVelocity5 > 0)) {\n                    wheelVelocity5 = 0;\n                }\n\n                wheelVelocity5 += 0.2 * direction;\n\n                if (Math.abs(wheelVelocity5) > 1) {\n                    navigate5(Math.sign(wheelVelocity5));\n                    wheelVelocity5 = 0;\n                }\n            }\n\n            prevBtn5.addEventListener(\'click\', () => navigate5(-1));\n            nextBtn5.addEventListener(\'click\', () => navigate5(1));\n            slidesContainer5.addEventListener(\'wheel\', handleWheel5);\n\n            setTimeout(() => {\n                calculateSlideWidth5();\n                createSlides5();\n                setTimeout(() => {\n                    updateCarousel5();\n                }, 500);\n            }, 200);\n\n            window.addEventListener(\'resize\', () => {\n                calculateSlideWidth5();\n                createSlides5();\n            });\n\n            window.addEventListener(\'orientationchange\', () => {\n                setTimeout(() => {\n                    calculateSlideWidth5();\n                    createSlides5();\n                }, 100);\n            });\n        });\n    </script>\n    <!-- Load Back to Top Component -->\n    <script src=\"assets/components/back-to-top.js\"></script>\n\n</body>', NULL, 'published', NULL, '2025-12-14 00:30:10', '2025-12-14 00:30:10');
INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(122, 'Our Add Ons', 'our-add-ons', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Our Add-ons - MiHi Entertainment</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link\n        href=\"https://fonts.googleapis.com/css2?family=Arvo:wght@400;700&family=Cinzel:wght@500;600;700;800;900&family=Inter:wght@300;400;500;600;700;800;900&family=Montserrat:wght@500;600;700&family=Playfair+Display:wght@400;500;600;700;800;900&display=swap\"\n        rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Source+Code+Pro:wght@400;600;700&display=swap\"\n        rel=\"stylesheet\">\n    <link rel=\"stylesheet\"\n        href=\"https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@24,400,0,0\" />\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Merriweather:wght@300;900&display=swap\');\n        @import url(\'https://fonts.googleapis.com/css2?family=Righteous&display=swap\');\n\n        @font-face {\n            font-family: \'AzoSans\';\n            src: url(\'../assets/fonts/AzoSans-Regular.woff2\') format(\'woff2\');\n            font-weight: normal;\n            font-style: normal;\n        }\n\n        @font-face {\n            font-family: \'AzoSansUber\';\n            src: url(\'../assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\');\n            font-weight: normal;\n            font-style: normal;\n        }\n\n        html,\n        body {\n            overflow-x: hidden;\n            width: 100%;\n            max-width: 100%;\n        }\n\n        body {\n            font-family: \'Inter\', sans-serif;\n            color: #1a202c;\n        }\n\n        h1,\n        h2,\n        h3,\n        h4,\n        h5,\n        h6 {\n            font-family: \'Playfair Display\', serif;\n        }\n\n        .btn-primary {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 100%);\n            transition: all 0.3s ease;\n        }\n\n        .btn-primary:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(255, 79, 79, 0.4);\n        }\n\n        /* Bubble Button Animation */\n        .btn {\n            display: inline-block;\n            text-decoration: none;\n        }\n\n        .btn-bubble {\n            color: white;\n            background-repeat: no-repeat;\n            position: relative;\n        }\n\n        .btn-bubble:not(:hover):not(:focus) {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 100%);\n        }\n\n        .btn-bubble:hover,\n        .btn-bubble:focus {\n            animation: bubbles 1s forwards ease-out;\n            background:\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 5% 120% / 0.6em 0.6em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 15% 110% / 0.8em 0.8em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 25% 130% / 0.7em 0.7em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 35% 100% / 0.9em 0.9em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 45% 115% / 0.5em 0.5em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 55% 125% / 1em 1em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 65% 105% / 0.75em 0.75em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 75% 135% / 0.85em 0.85em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 85% 120% / 0.65em 0.65em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 95% 110% / 0.95em 0.95em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 105% 130% / 0.55em 0.55em;\n            background-color: #FF4F4F;\n            background-repeat: no-repeat;\n        }\n\n        @keyframes bubbles {\n            100% {\n                background-position:\n                    3% -350%,\n                    18% -280%,\n                    22% -320%,\n                    38% -250%,\n                    42% -380%,\n                    58% -200%,\n                    62% -340%,\n                    78% -180%,\n                    88% -300%,\n                    98% -220%,\n                    102% -360%;\n                box-shadow: inset 0 -6.5em 0 #FF4F4F;\n            }\n        }\n\n        .font-style-AzoSans {\n            font-family: \'AzoSans\', sans-serif;\n        }\n\n        .hero-button {\n            font-size: 1.125rem;\n            padding: 0.75rem 2rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-button {\n                font-size: 1rem;\n                padding: 0.625rem 1.5rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-button {\n                font-size: 0.875rem;\n                padding: 0.5rem 1.25rem;\n            }\n        }\n\n        .section-padding {\n            padding: 5rem 0;\n        }\n\n        @media (max-width: 768px) {\n            .section-padding {\n                padding: 3rem 0;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .section-padding {\n                padding: 2.5rem 0;\n            }\n        }\n\n        .hero-section {\n            background-image: url(\'../assets/images/galleries/ouraddons/hero.jpeg\');\n            background-attachment: fixed;\n            background-position: center center;\n            background-size: cover;\n            background-repeat: no-repeat;\n            min-height: 100vh;\n        }\n\n        @media (max-width: 768px) {\n            .hero-section {\n                min-height: 85vh;\n                background-attachment: scroll;\n            }\n        }\n\n        .hero-section .corporate-text {\n            font-family: \'Montserrat\', sans-serif;\n            letter-spacing: 0.3em;\n        }\n\n        /* Hero Badge Responsive */\n        .hero-badge {\n            font-size: 0.875rem;\n            font-family: \'AzoSans\', sans-serif;\n        }\n\n        @media (max-width: 768px) {\n            .hero-badge {\n                font-size: 0.75rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-badge {\n                font-size: 0.6875rem;\n            }\n        }\n\n        /* Hero Heading Responsive */\n        .hero-heading {\n            font-size: 4rem;\n            line-height: 1.1;\n        }\n\n        @media (max-width: 1024px) {\n            .hero-heading {\n                font-size: 3.5rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .hero-heading {\n                font-size: 2.5rem;\n                line-height: 1.15;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-heading {\n                font-size: 2rem;\n                line-height: 1.2;\n            }\n        }\n\n        /* Hero Description Responsive */\n        .hero-description {\n            font-size: 1rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-description {\n                font-size: 0.875rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-description {\n                font-size: 0.8125rem;\n            }\n        }\n\n        /* Hero Location Text Responsive */\n        .hero-location {\n            font-size: 0.75rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-location {\n                font-size: 0.6875rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-location {\n                font-size: 0.625rem;\n            }\n        }\n\n        /* Enhanced overlay for mobile readability */\n        @media (max-width: 768px) {\n            .hero-section .bg-opacity-50 {\n                background-color: rgba(0, 0, 0, 0.6) !important;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .container {\n                padding-left: 1rem;\n                padding-right: 1rem;\n            }\n        }\n\n        .animate-fade-in-up {\n            animation: fadeInUp 1s ease-out forwards;\n            opacity: 0;\n        }\n\n        .animate-delay-200 {\n            animation-delay: 0.2s;\n        }\n\n        .animate-delay-300 {\n            animation-delay: 0.3s;\n        }\n\n        .animate-delay-400 {\n            animation-delay: 0.4s;\n        }\n\n        @keyframes fadeInUp {\n            from {\n                opacity: 0;\n                transform: translateY(20px);\n            }\n\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n\n        .addons-heading {\n            font-family: \'Montserrat\', sans-serif;\n            font-weight: 500;\n            font-size: 2.5rem;\n            letter-spacing: 0.15em;\n            text-transform: uppercase;\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 50%, #FF4F4F 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n            line-height: 1.2;\n            text-align: center;\n            margin-bottom: 0.75rem;\n        }\n\n        @media (max-width: 768px) {\n            .addons-heading {\n                font-size: 1.875rem;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .addons-heading {\n                font-size: 1.5rem;\n                letter-spacing: 0.1em;\n            }\n        }\n\n        .addons-subtext {\n            color: #1F1F1F;\n            font-family: \'AzoSans\', sans-serif;\n            line-height: 1.6;\n            font-size: 1rem;\n            text-align: center;\n            max-width: 2xl;\n            margin: 0 auto;\n        }\n\n        .addons-subtext a {\n            color: #FF4F4F;\n            text-decoration: underline;\n            text-underline-offset: 4px;\n            transition: color 0.3s ease;\n        }\n\n        .addons-subtext a:hover {\n            color: #18F1E1;\n        }\n\n        /* Card Styles */\n        .addons-cards-container {\n            margin-top: 3rem;\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));\n            gap: 2rem;\n            width: 100%;\n            overflow-x: hidden;\n        }\n\n        @media (min-width: 640px) {\n            .addons-cards-container {\n                grid-template-columns: repeat(2, 1fr);\n            }\n        }\n\n        @media (min-width: 1024px) {\n            .addons-cards-container {\n                grid-template-columns: repeat(3, 1fr);\n            }\n        }\n\n        @media (min-width: 1280px) {\n            .addons-cards-container {\n                grid-template-columns: repeat(4, 1fr);\n            }\n        }\n\n        .addon-card {\n            display: flex;\n            flex-direction: column;\n            width: 100%;\n            max-width: 100%;\n            overflow: hidden;\n        }\n\n        .addon-card ul {\n            margin: 0;\n            padding: 0;\n            list-style-type: none;\n            display: flex;\n            align-items: center;\n            flex-wrap: wrap;\n            gap: 0.625rem;\n        }\n\n        .addon-card ul li {\n            text-transform: uppercase;\n            background: var(--clr-tag);\n            color: #FF4F4F;\n            font-weight: 500;\n            font-family: \'AzoSans\', sans-serif;\n            font-size: 0.8rem;\n            padding: 0.375rem 0.625rem;\n            border-radius: 0.188rem;\n        }\n\n        .addon-card .content {\n            padding: 0.938rem 0.625rem;\n        }\n\n        .addon-card .content h3 {\n            text-transform: capitalize;\n            font-size: clamp(1.5rem, 1.3909rem + 0.4364vw, 1.8rem);\n            font-family: \'Playfair Display\', serif;\n            margin-bottom: 0.5rem;\n        }\n\n        .addon-card .content p {\n            margin: 0.625rem 0 1.25rem;\n            color: #1F1F1F;\n            font-family: \'AzoSans\', sans-serif;\n            line-height: 1.6;\n        }\n\n        .addon-card-inner {\n            position: relative;\n            width: 100%;\n            height: 18.75rem;\n            background: var(--clr);\n            border-radius: 1.25rem;\n            border-bottom-right-radius: 0;\n            overflow: hidden;\n            max-width: 100%;\n        }\n\n        .addon-card-inner .box {\n            width: 100%;\n            height: 100%;\n            background: #fff;\n            border-radius: 1.25rem;\n            overflow: hidden;\n            position: relative;\n        }\n\n        .addon-card-inner .imgBox {\n            position: absolute;\n            inset: 0;\n        }\n\n        .addon-card-inner .imgBox img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n        }\n\n        .addon-card-inner .icon {\n            position: absolute;\n            bottom: -0.375rem;\n            right: -0.375rem;\n            width: 6rem;\n            height: 6rem;\n            background: var(--clr);\n            border-top-left-radius: 50%;\n            z-index: 1;\n        }\n\n        .addon-card-inner .icon:hover .iconBox {\n            transform: scale(1.1);\n        }\n\n        .addon-card-inner .icon::before {\n            position: absolute;\n            content: \"\";\n            bottom: 0.375rem;\n            left: -1.25rem;\n            background: transparent;\n            width: 1.25rem;\n            height: 1.25rem;\n            border-bottom-right-radius: 1.25rem;\n            box-shadow: 0.313rem 0.313rem 0 0.313rem #fff;\n        }\n\n        .addon-card-inner .icon::after {\n            position: absolute;\n            content: \"\";\n            top: -1.25rem;\n            right: 0.375rem;\n            background: transparent;\n            width: 1.25rem;\n            height: 1.25rem;\n            border-bottom-right-radius: 1.25rem;\n            box-shadow: 0.313rem 0.313rem 0 0.313rem var(--clr);\n        }\n\n        .addon-card-inner .icon .iconBox {\n            position: absolute;\n            inset: 0.625rem;\n            background: #FF4F4F;\n            border-radius: 50%;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            transition: 0.3s;\n            text-decoration: none;\n        }\n\n        .addon-card-inner .icon .iconBox span {\n            color: #fff;\n            font-size: 1.5rem;\n        }\n\n        /* Card color variations for 10 cards */\n        .addon-card:nth-child(1) .addon-card-inner .icon .iconBox {\n            background: #FF4F4F;\n        }\n\n        .addon-card:nth-child(2) .addon-card-inner .icon .iconBox {\n            background: #FF4F4F;\n        }\n\n        .addon-card:nth-child(3) .addon-card-inner .icon .iconBox {\n            background: #FF4F4F;\n        }\n\n        .addon-card:nth-child(4) .addon-card-inner .icon .iconBox {\n            background: #FF4F4F;\n        }\n\n        .addon-card:nth-child(5) .addon-card-inner .icon .iconBox {\n            background: #FF4F4F;\n        }\n\n        .addon-card:nth-child(6) .addon-card-inner .icon .iconBox {\n            background: #FF4F4F;\n        }\n\n        .addon-card:nth-child(7) .addon-card-inner .icon .iconBox {\n            background: #FF4F4F;\n        }\n\n        .addon-card:nth-child(8) .addon-card-inner .icon .iconBox {\n            background: #FF4F4F;\n        }\n\n        .addon-card:nth-child(9) .addon-card-inner .icon .iconBox {\n            background: #FF4F4F;\n        }\n\n        .addon-card:nth-child(10) .addon-card-inner .icon .iconBox {\n            background: #FF4F4F;\n        }\n    </style>\n</head>\n\n<body>\n    <div id=\"nav-placeholder\"></div>\n\n    <!-- Hero Section -->\n    <section class=\"relative flex items-center justify-center overflow-hidden py-4 sm:py-6 md:py-8 hero-section\">\n        <div class=\"absolute inset-0 bg-black bg-opacity-50\"></div>\n        <div class=\"relative z-10 text-center text-white px-3 sm:px-4 md:px-6 w-full\">\n            <div class=\"max-w-3xl mx-auto\">\n                <div class=\"mb-2 sm:mb-3 text-center\">\n                    <p class=\"hero-badge inline-block leading-tight mb-2 sm:mb-3 px-3 sm:px-4 py-1.5 sm:py-2 text-gray-100 tracking-[0.15em] sm:tracking-[0.2em] animate-fade-in-up animate-delay-200 corporate-text rounded-full\"\n                        style=\"font-weight: 600; background-color: #FF4F4F; font-family: \'AzoSans\', sans-serif; display: inline-block;\">\n                        ENHANCE YOUR EVENT WITH OUR\n                    </p>\n                    <h1 class=\"mt-2 sm:mt-3 hero-heading font-light leading-tight animate-fade-in-up corporate-heading px-2 sm:px-4\"\n                        style=\"font-family: \'AzoSansUber\', sans-serif; text-shadow: 0 2px 10px rgba(0, 0, 0, 0.5), 0 0 20px rgba(10, 10, 10, 0.3);\">\n                        <span style=\"color: #FF4F4F;\">OUR</span> <span style=\"color: #18F1E1;\">ADD-ONS</span>\n                    </h1>\n                </div>\n\n                <div class=\"h-px w-12 sm:w-16 bg-white mx-auto my-2 sm:my-3 animate-fade-in-up animate-delay-200\"></div>\n\n                <p\n                    class=\"font-style-AzoSans mx-auto hero-description leading-relaxed mb-4 sm:mb-6 px-3 sm:px-4 md:px-0 text-white/80 tracking-normal animate-fade-in-up animate-delay-200 corporate-text\">\n                    Scroll down to view all of the package add-ons available for any event! Contact us for more\n                    information on how to add any of these amazing additions to your next photo booth rental.\n                </p>\n                <div class=\"mt-6 sm:mt-8 mb-6 sm:mb-8 animate-fade-in-up animate-delay-300\">\n                    <a href=\"contact-us.html\"\n                        class=\"font-style-AzoSans btn btn-bubble btn-primary hero-button inline-block rounded-lg text-white font-semibold\"\n                        aria-label=\"Contact us for add-ons\">\n                        Contact Us\n                    </a>\n                </div>\n\n                <div class=\"text-center opacity-90 animate-fade-in-up animate-delay-400\">\n                    <div class=\"h-px w-10 sm:w-12 bg-white/70 mx-auto mb-2 sm:mb-3 transition-all duration-500\"></div>\n                    <p\n                        class=\"text-white/80 tracking-wider hero-location font-medium uppercase corporate-location px-3 sm:px-4\">\n                        SERVICING DENVER, COLORADO, AND NATIONWIDE CORPORATE EVENTS\n                    </p>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Addons Section -->\n    <section id=\"addons-section\" class=\"py-8 md:py-12 bg-white overflow-hidden\">\n        <div class=\"container mx-auto px-4 max-w-full\">\n            <div class=\"max-w-4xl mx-auto\">\n                <h2 class=\"addons-heading animate-fade-in-up\"\n                    style=\"color: #FF4F4F; -webkit-text-fill-color: #FF4F4F; background: none; -webkit-background-clip: unset; background-clip: unset; font-family: \'AzoSansUber\', sans-serif;\">\n                    OUR ADD-ONS INCLUDE:\n                </h2>\n                <p class=\"addons-subtext animate-fade-in-up animate-delay-200\">\n                    For additional information and pricing, <a href=\"contact-us.html\">contact us</a>.\n                </p>\n            </div>\n\n            <div class=\"addons-cards-container\">\n                <div class=\"addon-card\">\n                    <div class=\"addon-card-inner\" style=\"--clr:#fff;\">\n                        <div class=\"box\">\n                            <div class=\"imgBox\">\n                                <img src=\"../assets/images/galleries/ouraddons/addon1.jpeg\" alt=\"Additional Hours\">\n                            </div>\n                            <div class=\"icon\">\n                                <a href=\"contact-us.html\" class=\"iconBox\">\n                                    <span class=\"material-symbols-outlined\">arrow_outward</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"content\">\n                        <h3 style=\"color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">ADDITIONAL</span> <span style=\"color: #18F1E1;\">HOURS</span>\n                        </h3>\n                        <p>Need we say more? Your guests will be having so much fun with our booth, that you\'ll want to\n                            add more time!</p>\n                    </div>\n                </div>\n\n                <div class=\"addon-card\">\n                    <div class=\"addon-card-inner\" style=\"--clr:#fff;\">\n                        <div class=\"box\">\n                            <div class=\"imgBox\">\n                                <img src=\"../assets/images/galleries/ouraddons/addon2.jpg\" alt=\"Idle Hours\">\n                            </div>\n                            <div class=\"icon\">\n                                <a href=\"contact-us.html\" class=\"iconBox\">\n                                    <span class=\"material-symbols-outlined\">arrow_outward</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"content\">\n                        <h3 style=\"color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">IDLE</span> <span style=\"color: #18F1E1;\">HOURS</span>\n                        </h3>\n                        <p>If you\'re wanting to shut down the booth for those important speeches, or other times when\n                            your guests’ attention will be elsewhere, we won\'t charge you the full price for our\n                            operational hours.</p>\n                    </div>\n                </div>\n\n                <div class=\"addon-card\">\n                    <div class=\"addon-card-inner\" style=\"--clr:#fff;\">\n                        <div class=\"box\">\n                            <div class=\"imgBox\">\n                                <img src=\"../assets/images/galleries/ouraddons/addon3.png\" alt=\"Digital Sharing\">\n                            </div>\n                            <div class=\"icon\">\n                                <a href=\"contact-us.html\" class=\"iconBox\">\n                                    <span class=\"material-symbols-outlined\">arrow_outward</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"content\">\n                        <h3 style=\"color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">DIGITAL</span> <span style=\"color: #18F1E1;\">SHARING</span>\n                        </h3>\n                        <p>Let your guests share their photos via text or email! Wi-Fi is required for these to send\n                            instantly, otherwise they\'ll be delivered after your event.</p>\n                    </div>\n                </div>\n\n                <div class=\"addon-card\">\n                    <div class=\"addon-card-inner\" style=\"--clr:#fff;\">\n                        <div class=\"box\">\n                            <div class=\"imgBox\">\n                                <img src=\"../assets/images/galleries/ouraddons/addon4.jpeg\" alt=\"Social Sharing Kiosk\">\n                            </div>\n                            <div class=\"icon\">\n                                <a href=\"contact-us.html\" class=\"iconBox\">\n                                    <span class=\"material-symbols-outlined\">arrow_outward</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"content\">\n                        <h3 style=\"color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">SOCIAL</span> <span style=\"color: #18F1E1;\">SHARING</span>\n                        </h3>\n                        <p>Have a large number of attendees? After your guests take their pictures at the photo booth,\n                            the pictures are automatically sent to the kiosk where guests can then share their pictures\n                            online.</p>\n                    </div>\n                </div>\n\n                <div class=\"addon-card\">\n                    <div class=\"addon-card-inner\" style=\"--clr:#fff;\">\n                        <div class=\"box\">\n                            <div class=\"imgBox\">\n                                <img src=\"../assets/images/galleries/ouraddons/addon5.jpg\"\n                                    alt=\"Green Screen Background\">\n                            </div>\n                            <div class=\"icon\">\n                                <a href=\"contact-us.html\" class=\"iconBox\">\n                                    <span class=\"material-symbols-outlined\">arrow_outward</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"content\">\n                        <h3 style=\"color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">GREEN</span> <span style=\"color: #FF4F4F;\">SCREEN</span> <span\n                                style=\"color: #18F1E1;\">BACKGROUND</span>\n                        </h3>\n                        <p>Instead of picking just one backdrop, why not 6? We\'ll set up a green screen and work with\n                            you to choose or create images that your guests can pick from!</p>\n                    </div>\n                </div>\n\n                <div class=\"addon-card\">\n                    <div class=\"addon-card-inner\" style=\"--clr:#fff;\">\n                        <div class=\"box\">\n                            <div class=\"imgBox\">\n                                <img src=\"../assets/images/galleries/ouraddons/addon6.jpeg\"\n                                    alt=\"VIP Red Carpet Setting\">\n                            </div>\n                            <div class=\"icon\">\n                                <a href=\"contact-us.html\" class=\"iconBox\">\n                                    <span class=\"material-symbols-outlined\">arrow_outward</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"content\">\n                        <h3 style=\"color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">VIP</span> <span style=\"color: #FF4F4F;\">RED</span> <span\n                                style=\"color: #FF4F4F;\">CARPET</span> <span style=\"color: #18F1E1;\">SETTING</span>\n                        </h3>\n                        <p>We will bring along our red carpet and rope off the photo booth area, creating the feel of\n                            exclusivity and glamour!</p>\n                    </div>\n                </div>\n\n                <div class=\"addon-card\">\n                    <div class=\"addon-card-inner\" style=\"--clr:#fff;\">\n                        <div class=\"box\">\n                            <div class=\"imgBox\">\n                                <img src=\"../assets/images/galleries/ouraddons/addon7.gif\"\n                                    alt=\"Additional Photo Filters\">\n                            </div>\n                            <div class=\"icon\">\n                                <a href=\"contact-us.html\" class=\"iconBox\">\n                                    <span class=\"material-symbols-outlined\">arrow_outward</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"content\">\n                        <h3 style=\"color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">ADDITIONAL</span> <span style=\"color: #18F1E1;\">PHOTO</span>\n                            <span style=\"color: #18F1E1;\">FILTERS</span>\n                        </h3>\n                        <p>Guests can choose to add a filter to their photos. Ranging from black and white, sepia, comic\n                            book, and plenty more!</p>\n                    </div>\n                </div>\n\n                <div class=\"addon-card\">\n                    <div class=\"addon-card-inner\" style=\"--clr:#fff;\">\n                        <div class=\"box\">\n                            <div class=\"imgBox\">\n                                <img src=\"../assets/images/galleries/ouraddons/addon8.jpeg\" alt=\"Custom Backdrop\">\n                            </div>\n                            <div class=\"icon\">\n                                <a href=\"contact-us.html\" class=\"iconBox\">\n                                    <span class=\"material-symbols-outlined\">arrow_outward</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"content\">\n                        <h3 style=\"color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">CUSTOM</span> <span style=\"color: #18F1E1;\">BACKDROP</span>\n                        </h3>\n                        <p>Want to give your event the feeling of an VIP party? You can do so by choosing a custom step\n                            and repeat backdrop. We\'ll design and perfect it just for you!</p>\n                    </div>\n                </div>\n\n                <div class=\"addon-card\">\n                    <div class=\"addon-card-inner\" style=\"--clr:#fff;\">\n                        <div class=\"box\">\n                            <div class=\"imgBox\">\n                                <img src=\"../assets/images/galleries/ouraddons/addon9.jpg\" alt=\"Memory Album Book\">\n                            </div>\n                            <div class=\"icon\">\n                                <a href=\"contact-us.html\" class=\"iconBox\">\n                                    <span class=\"material-symbols-outlined\">arrow_outward</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"content\">\n                        <h3 style=\"color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">MEMORY</span> <span style=\"color: #FF4F4F;\">ALBUM</span> <span\n                                style=\"color: #18F1E1;\">BOOK</span>\n                        </h3>\n                        <p>In addition to the photos your guests receives, one will be placed into a beautiful memory\n                            book, where your guests are encouraged to write their well wishes by the picture.</p>\n                    </div>\n                </div>\n\n                <div class=\"addon-card\">\n                    <div class=\"addon-card-inner\" style=\"--clr:#fff;\">\n                        <div class=\"box\">\n                            <div class=\"imgBox\">\n                                <img src=\"../assets/images/galleries/ouraddons/addon10.gif\"\n                                    alt=\"Unlimited Photo Prints\">\n                            </div>\n                            <div class=\"icon\">\n                                <a href=\"contact-us.html\" class=\"iconBox\">\n                                    <span class=\"material-symbols-outlined\">arrow_outward</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"content\">\n                        <h3 style=\"color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">UNLIMITED</span> <span style=\"color: #FF4F4F;\">PHOTO</span>\n                            <span style=\"color: #18F1E1;\">PRINTS</span>\n                        </h3>\n                        <p>Make sure everyone in the picture is able to get a great printout of the fun they are having.\n                        </p>\n                    </div>\n                </div>\n                <div class=\"addon-card\">\n                    <div class=\"addon-card-inner\" style=\"--clr:#fff;\">\n                        <div class=\"box\">\n                            <div class=\"imgBox\">\n                                <img src=\"../assets/images/galleries/ouraddons/addon11.gif\"\n                                    alt=\"Unlimited Photo Prints\">\n                            </div>\n                            <div class=\"icon\">\n                                <a href=\"contact-us.html\" class=\"iconBox\">\n                                    <span class=\"material-symbols-outlined\">arrow_outward</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"content\">\n                        <h3 style=\"color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">SINGLE</span> <span style=\"color: #FF4F4F;\">PHOTO</span> <span\n                                style=\"color: #18F1E1;\">LAYOUT</span>\n                        </h3>\n                        <p>Our standard photo strips come with every package, but why not add a full single 4x6 Photo to\n                            your event? Customize the design, and make it your own.</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <script src=\"../assets/components/navigation.js\"></script>\n    <script src=\"../assets/components/footer.js\"></script>\n    <!-- Load Back to Top Component -->\n    <script src=\"assets/components/back-to-top.js\"></script>\n\n</body>', NULL, 'published', NULL, '2025-12-14 00:30:10', '2025-12-14 00:30:10');
INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(123, 'Our Booths', 'our-booths', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Our Booths | MiHi Entertainment</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link\n        href=\"https://fonts.googleapis.com/css2?family=Arvo:wght@400;700&family=Cinzel:wght@500;600;700;800;900&family=Inter:wght@300;400;500;600;700;800;900&family=Montserrat:wght@500;600;700&family=Playfair+Display:wght@400;500;600;700;800;900&display=swap\"\n        rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Source+Code+Pro:wght@400;600;700&display=swap\"\n        rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Fira+Sans:wght@400;500;600;700;800&display=swap\"\n        rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Lato:wght@400;700&display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\"\n        href=\"https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@24,400,0,0\" />\n    <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/swiper@8/swiper-bundle.min.css\">\n    <script src=\"https://cdn.jsdelivr.net/npm/swiper@8/swiper-bundle.min.js\"></script>\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Merriweather:wght@300;900&display=swap\');\n        @import url(\'https://fonts.googleapis.com/css2?family=Righteous&display=swap\');\n\n        @font-face {\n            font-family: \'AzoSans\';\n            src: url(\'assets/fonts/AzoSans-Regular.woff2\') format(\'woff2\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        @font-face {\n            font-family: \'AzoSansUber\';\n            src: url(\'assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        .font-style-AzoSans {\n            font-family: \'AzoSans\', sans-serif;\n        }\n\n        .font-style-AzoSansUber {\n            font-family: \'AzoSansUber\', sans-serif;\n        }\n\n        body {\n            font-family: \'Inter\', sans-serif;\n            color: #1a202c;\n        }\n\n        h1,\n        h2,\n        h3,\n        h4,\n        h5,\n        h6 {\n            font-family: \'Playfair Display\', serif;\n        }\n\n        .btn-primary {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 100%);\n            transition: all 0.3s ease;\n        }\n\n        .btn-primary:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(0, 80, 255, 0.4);\n        }\n\n        /* Bubble Button Animation */\n        .btn {\n            display: inline-block;\n            text-decoration: none;\n        }\n\n        .btn-bubble {\n            color: white;\n            background-repeat: no-repeat;\n            position: relative;\n        }\n\n        .btn-bubble:not(:hover):not(:focus) {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 100%);\n        }\n\n        .btn-bubble:hover,\n        .btn-bubble:focus {\n            animation: bubbles 1s forwards ease-out;\n            background:\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 5% 120% / 0.6em 0.6em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 15% 110% / 0.8em 0.8em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 25% 130% / 0.7em 0.7em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 35% 100% / 0.9em 0.9em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 45% 115% / 0.5em 0.5em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 55% 125% / 1em 1em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 65% 105% / 0.75em 0.75em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 75% 135% / 0.85em 0.85em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 85% 120% / 0.65em 0.65em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 95% 110% / 0.95em 0.95em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 105% 130% / 0.55em 0.55em;\n            color: #1f1f1f;\n            background-color: #18F1E1;\n            background-repeat: no-repeat;\n        }\n\n        @keyframes bubbles {\n            100% {\n                background-position:\n                    3% -350%,\n                    18% -280%,\n                    22% -320%,\n                    38% -250%,\n                    42% -380%,\n                    58% -200%,\n                    62% -340%,\n                    78% -180%,\n                    88% -300%,\n                    98% -220%,\n                    102% -360%;\n                box-shadow: inset 0 -6.5em 0 #FF4F4F;\n            }\n        }\n\n        /* Hero Button Responsive */\n        .hero-button {\n            font-size: 1.125rem;\n            padding: 0.75rem 2rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-button {\n                font-size: 1rem;\n                padding: 0.625rem 1.5rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-button {\n                font-size: 0.875rem;\n                padding: 0.5rem 1.25rem;\n            }\n        }\n\n        .section-padding {\n            padding: 5rem 0;\n        }\n\n        @media (max-width: 768px) {\n            .section-padding {\n                padding: 3rem 0;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .section-padding {\n                padding: 2.5rem 0;\n            }\n        }\n\n        .hero-section {\n            background-image: url(\'../assets/images/galleries/ourbooths/hero.jpg\');\n            background-attachment: fixed;\n            background-position: center center;\n            background-size: cover;\n            background-repeat: no-repeat;\n            min-height: 100vh;\n        }\n\n        @media (max-width: 768px) {\n            .hero-section {\n                min-height: 85vh;\n                background-attachment: scroll;\n                padding: 2rem 0;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-section {\n                min-height: 75vh;\n                padding: 1.5rem 0;\n            }\n        }\n\n        .hero-section .corporate-text {\n            font-family: \'Montserrat\', sans-serif;\n            letter-spacing: 0.3em;\n        }\n\n        @media (max-width: 640px) {\n            .hero-section .corporate-text {\n                letter-spacing: 0.15em;\n            }\n        }\n\n        /* Hero Heading Responsive */\n        .hero-heading {\n            font-size: 6rem;\n            line-height: 1.1;\n        }\n\n        @media (max-width: 1024px) {\n            .hero-heading {\n                font-size: 4.5rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .hero-heading {\n                font-size: 3rem;\n                line-height: 1.15;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-heading {\n                font-size: 2.25rem;\n                line-height: 1.2;\n            }\n        }\n\n        /* Hero Badge Responsive */\n        .hero-badge {\n            font-size: 15px;\n        }\n\n        @media (max-width: 768px) {\n            .hero-badge {\n                font-size: 12px;\n                padding: 0.5rem 0.75rem !important;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-badge {\n                font-size: 11px;\n                padding: 0.375rem 0.625rem !important;\n            }\n        }\n\n        /* Hero Description Responsive */\n        .hero-description {\n            font-size: 1rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-description {\n                font-size: 0.875rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-description {\n                font-size: 0.8125rem;\n            }\n        }\n\n        /* Hero Location Text Responsive */\n        .hero-location {\n            font-size: 0.75rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-location {\n                font-size: 0.6875rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-location {\n                font-size: 0.625rem;\n            }\n        }\n\n        /* Enhanced overlay for mobile readability */\n        @media (max-width: 768px) {\n            .hero-section .bg-opacity-50 {\n                background-color: rgba(0, 0, 0, 0.6) !important;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-section .bg-opacity-50 {\n                background-color: rgba(0, 0, 0, 0.65) !important;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .container {\n                padding-left: 1rem;\n                padding-right: 1rem;\n            }\n        }\n\n        .animate-fade-in-up {\n            animation: fadeInUp 1s ease-out forwards;\n            opacity: 0;\n        }\n\n        .animate-delay-200 {\n            animation-delay: 0.2s;\n        }\n\n        .animate-delay-300 {\n            animation-delay: 0.3s;\n        }\n\n        .animate-delay-400 {\n            animation-delay: 0.4s;\n        }\n\n        @keyframes fadeInUp {\n            from {\n                opacity: 0;\n                transform: translateY(20px);\n            }\n\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n\n        /* Appa Section Styles */\n        .appa-section {\n            background: linear-gradient(135deg, #d6e7ff 0%, #e8f0ff 15%, #f0f5ff 30%, #ffffff 45%, #f0f5ff 60%, #e8f0ff 75%, #d6e7ff 90%, #ffffff 100%);\n            position: relative;\n            overflow: hidden;\n        }\n\n        .appa-section::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background:\n                radial-gradient(circle at 15% 25%, rgba(0, 80, 255, 0.2) 0%, rgba(0, 80, 255, 0.1) 40%, transparent 70%),\n                radial-gradient(circle at 85% 75%, rgba(102, 51, 153, 0.18) 0%, rgba(102, 51, 153, 0.08) 40%, transparent 70%),\n                radial-gradient(circle at 50% 50%, rgba(0, 102, 255, 0.15) 0%, rgba(0, 102, 255, 0.06) 40%, transparent 70%);\n            pointer-events: none;\n            z-index: 0;\n        }\n\n        .appa-section::after {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background-image:\n                linear-gradient(rgba(0, 80, 255, 0.12) 1px, transparent 1px),\n                linear-gradient(90deg, rgba(0, 80, 255, 0.12) 1px, transparent 1px);\n            background-size: 50px 50px;\n            pointer-events: none;\n            z-index: 0;\n        }\n\n        /* Animated gradient orbs */\n        .appa-section .bg-orb {\n            position: absolute;\n            border-radius: 50%;\n            filter: blur(90px);\n            pointer-events: none;\n            z-index: 0;\n            animation: float 20s ease-in-out infinite;\n        }\n\n        .appa-section .bg-orb-1 {\n            width: 600px;\n            height: 600px;\n            background: radial-gradient(circle, rgba(0, 80, 255, 0.4) 0%, rgba(0, 80, 255, 0.2) 35%, rgba(0, 80, 255, 0.1) 50%, transparent 75%);\n            top: -200px;\n            left: -200px;\n            animation-delay: 0s;\n        }\n\n        .appa-section .bg-orb-2 {\n            width: 550px;\n            height: 550px;\n            background: radial-gradient(circle, rgba(102, 51, 153, 0.35) 0%, rgba(102, 51, 153, 0.18) 35%, rgba(102, 51, 153, 0.08) 50%, transparent 75%);\n            bottom: -150px;\n            right: -150px;\n            animation-delay: 5s;\n        }\n\n        .appa-section .bg-orb-3 {\n            width: 500px;\n            height: 500px;\n            background: radial-gradient(circle, rgba(0, 102, 255, 0.3) 0%, rgba(0, 102, 255, 0.15) 35%, rgba(0, 102, 255, 0.08) 50%, transparent 75%);\n            top: 50%;\n            left: 50%;\n            transform: translate(-50%, -50%);\n            animation-delay: 10s;\n        }\n\n        @keyframes float {\n\n            0%,\n            100% {\n                transform: translate(0, 0) scale(1);\n            }\n\n            33% {\n                transform: translate(30px, -30px) scale(1.1);\n            }\n\n            66% {\n                transform: translate(-20px, 20px) scale(0.9);\n            }\n        }\n\n        .appa-content {\n            position: relative;\n            z-index: 1;\n        }\n\n        .appa-heading {\n            font-family: \'AzoSansUber\', sans-serif;\n            font-weight: 500;\n            font-size: 3.25rem;\n            letter-spacing: 0.15em;\n            text-transform: uppercase;\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 50%, #FF4F4F 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n            line-height: 1.2;\n        }\n\n        @media (max-width: 768px) {\n            .appa-heading {\n                font-size: 1.75rem;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .appa-heading {\n                font-size: 1.25rem;\n            }\n        }\n\n        .appa-card {\n            background: #ffffff;\n            border-radius: 1.5rem;\n            overflow: hidden;\n            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);\n            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n            border: 1px solid rgba(0, 0, 0, 0.05);\n            height: 100%;\n            display: flex;\n            flex-direction: column;\n        }\n\n        .appa-card:hover {\n            transform: translateY(-8px);\n            box-shadow: 0 20px 40px rgba(0, 80, 255, 0.15);\n            border-color: rgba(0, 80, 255, 0.2);\n        }\n\n        .appa-card-image {\n            position: relative;\n            width: 100%;\n            height: 280px;\n            background: linear-gradient(135deg, #f0f0f0 0%, #e0e0e0 100%);\n            overflow: hidden;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            padding: 1.5rem;\n            flex-shrink: 0;\n        }\n\n        .appa-card-image img {\n            width: 100%;\n            height: 100%;\n            object-fit: contain;\n            transition: transform 0.5s ease;\n        }\n\n        .appa-card:hover .appa-card-image img {\n            transform: scale(1.05);\n        }\n\n        .appa-card-content {\n            padding: 1.5rem;\n            flex-grow: 1;\n            display: flex;\n            flex-direction: column;\n            min-height: 120px;\n        }\n\n        .appa-card-text {\n            color: #1f1f1f;\n            line-height: 1.6;\n            font-size: 0.9375rem;\n            margin: 0;\n        }\n\n        .appa-learn-more-btn {\n            position: relative;\n            display: inline-block;\n            padding: 1.5rem 3rem;\n            border: 2px solid #18F1E1;\n            color: #1f1f1f;\n            font-weight: 800;\n            text-transform: uppercase;\n            letter-spacing: 0.15em;\n            font-size: 1rem;\n            text-decoration: none;\n            -webkit-font-smoothing: antialiased;\n            transition: all 0.3s ease;\n            background: #18F1E1;\n            box-shadow: 0 4px 20px rgba(9, 10, 11, 0.2);\n        }\n\n        .appa-learn-more-btn:hover {\n            border: none;\n            color: #1f1f1f;\n            box-shadow: 0 6px 30px rgba(3, 3, 3, 0.3);\n            transform: translateY(-2px);\n        }\n\n        .appa-learn-more-btn .line-1 {\n            content: \"\";\n            display: block;\n            position: absolute;\n            width: 2px;\n            background-color: #18F1E1;\n            left: 0;\n            bottom: 0;\n            height: 100%;\n        }\n\n        .appa-learn-more-btn .line-2 {\n            content: \"\";\n            display: block;\n            position: absolute;\n            height: 2px;\n            background-color: #18F1E1;\n            left: 0;\n            top: 0;\n            width: 0;\n        }\n\n        .appa-learn-more-btn .line-3 {\n            content: \"\";\n            display: block;\n            position: absolute;\n            width: 2px;\n            background-color: #18F1E1;\n            right: 0;\n            top: 0;\n            height: 100%;\n        }\n\n        .appa-learn-more-btn .line-4 {\n            content: \"\";\n            display: block;\n            position: absolute;\n            height: 2px;\n            background-color: #18F1E1;\n            right: 0;\n            bottom: 0;\n            width: 0;\n        }\n\n        .appa-learn-more-btn:hover .line-1 {\n            animation: move1 1500ms infinite ease;\n        }\n\n        .appa-learn-more-btn:hover .line-2 {\n            animation: move2 1500ms infinite ease;\n        }\n\n        .appa-learn-more-btn:hover .line-3 {\n            animation: move3 1500ms infinite ease;\n        }\n\n        .appa-learn-more-btn:hover .line-4 {\n            animation: move4 1500ms infinite ease;\n        }\n\n        @keyframes move1 {\n            0% {\n                height: 100%;\n                bottom: 0;\n            }\n\n            54% {\n                height: 0;\n                bottom: 100%;\n            }\n\n            55% {\n                height: 0;\n                bottom: 0;\n            }\n\n            100% {\n                height: 100%;\n                bottom: 0;\n            }\n        }\n\n        @keyframes move2 {\n            0% {\n                width: 0;\n                left: 0;\n            }\n\n            50% {\n                width: 100%;\n                left: 0;\n            }\n\n            100% {\n                width: 0;\n                left: 100%;\n            }\n        }\n\n        @keyframes move3 {\n            0% {\n                height: 100%;\n                top: 0;\n            }\n\n            54% {\n                height: 0;\n                top: 100%;\n            }\n\n            55% {\n                height: 0;\n                top: 0;\n            }\n\n            100% {\n                height: 100%;\n                top: 0;\n            }\n        }\n\n        @keyframes move4 {\n            0% {\n                width: 0;\n                right: 0;\n            }\n\n            55% {\n                width: 100%;\n                right: 0;\n            }\n\n            100% {\n                width: 0;\n                right: 100%;\n            }\n        }\n\n        /* Cards Section Styles */\n        .cards-section {\n            background: linear-gradient(135deg, #1f1f1f 0%, #1f1f1f 20%, #1f1f1f 40%, #1f1f1f 60%, #1f1f1f 80%, #1f1f1f 100%);\n            position: relative;\n            overflow: hidden;\n        }\n\n        .cards-section::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background:\n                radial-gradient(circle at 20% 30%, rgba(2, 2, 2, 0.15) 0%, rgba(0, 0, 0, 0.08) 40%, transparent 70%),\n                radial-gradient(circle at 80% 70%, rgba(102, 51, 153, 0.12) 0%, rgba(102, 51, 153, 0.06) 40%, transparent 70%);\n            pointer-events: none;\n            z-index: 0;\n        }\n\n        .cards-section::after {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background-image:\n                linear-gradient(rgba(5, 5, 5, 0.08) 1px, transparent 1px),\n                linear-gradient(90deg, rgba(3, 213, 255, 0.08) 1px, transparent 1px);\n            background-size: 50px 50px;\n            pointer-events: none;\n            z-index: 0;\n        }\n\n        .cards-content {\n            position: relative;\n            z-index: 1;\n        }\n\n        .cards-heading {\n            font-family: \'AzoSansUber\', sans-serif;\n            font-weight: 500;\n            font-size: 3.5rem;\n            letter-spacing: 0.15em;\n            text-transform: uppercase;\n            background: linear-gradient(135deg, #18F1E1 0%, #18F1E1 50%, #18F1E1 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n            line-height: 1.2;\n        }\n\n        @media (max-width: 768px) {\n            .cards-heading {\n                font-size: 1.875rem;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .cards-heading {\n                font-size: 1.5rem;\n            }\n        }\n\n        .cards-text-primary {\n            color: #f9f9f9;\n            line-height: 1.8;\n            font-size: 1.0625rem;\n        }\n\n        .cards-text-secondary {\n            color: #f6f8fd;\n            line-height: 1.8;\n            font-size: 1.0625rem;\n            font-style: italic;\n        }\n\n        .cards-pricing-btn {\n            position: relative;\n            display: inline-block;\n            padding: 1.5rem 3rem;\n            border: 2px solid #FF4F4F;\n            color: #ffffff;\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 100%);\n            font-weight: 700;\n            text-transform: uppercase;\n            letter-spacing: 0.15em;\n            font-size: 1rem;\n            text-decoration: none;\n            -webkit-font-smoothing: antialiased;\n            transition: all 0.3s ease;\n            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);\n        }\n\n        .cards-pricing-btn:hover {\n            border: none;\n            color: #1f1f1f;\n            box-shadow: 0 6px 30px rgba(0, 0, 0, 0.4);\n            transform: translateY(-2px);\n            background: linear-gradient(135deg, #18F1E1 0%, #18F1E1 100%);\n        }\n\n        .cards-pricing-btn .line-1 {\n            content: \"\";\n            display: block;\n            position: absolute;\n            width: 2px;\n            background-color: #FF4F4F;\n            left: 0;\n            bottom: 0;\n            height: 100%;\n        }\n\n        .cards-pricing-btn .line-2 {\n            content: \"\";\n            display: block;\n            position: absolute;\n            height: 2px;\n            background-color: #FF4F4F;\n            left: 0;\n            top: 0;\n     