 region: \"midwest\",\n                    cities: [\"Cleveland\"]\n                }, {\n                    x: 17,\n                    y: 6,\n                    USstate: \"PA\",\n                    capital: \"Harrisburg\",\n                    color: \"#c51162\",\n                    region: \"northeast\",\n                    cities: [\"Pittsburgh\"]\n                }, {\n                    x: 19,\n                    y: 6,\n                    USstate: \"NJ\",\n                    capital: \"Trenton\",\n                    color: \"#c51162\",\n                    region: \"northeast\"\n                }, {\n                    x: 21,\n                    y: 6,\n                    USstate: \"CT\",\n                    capital: \"Hartford\",\n                    color: \"#c51162\",\n                    region: \"northeast\",\n                    cities: [\"Hartford\"]\n                }]\n            }, {\n                data: [{\n                    x: 2,\n                    y: 7,\n                    USstate: \"WA\",\n                    capital: \"Olympia\",\n                    color: \"#2962ff\",\n                    region: \"west\",\n                    cities: [\"Seattle\"]\n                }, {\n                    x: 4,\n                    y: 7,\n                    USstate: \"MT\",\n                    capital: \"Helena\",\n                    color: \"#2962ff\",\n                    region: \"west\"\n                }, {\n                    x: 6,\n                    y: 7,\n                    USstate: \"ND\",\n                    capital: \"Bismarck\",\n                    color: \"#00c853\",\n                    region: \"midwest\"\n                }, {\n                    x: 8,\n                    y: 7,\n                    USstate: \"MN\",\n                    capital: \"Saint Paul\",\n                    color: \"#00c853\",\n                    region: \"midwest\",\n                    cities: [\"Minneapolis\"]\n                }, {\n                    x: 10,\n                    y: 7,\n                    USstate: \"WI\",\n                    capital: \"Madison\",\n                    color: \"#00c853\",\n                    region: \"midwest\"\n                }, {\n                    x: 14,\n                    y: 7,\n                    USstate: \"MI\",\n                    capital: \"Lansing\",\n                    color: \"#00c853\",\n                    region: \"midwest\",\n                    cities: [\"Detroit\"]\n                }, {\n                    x: 18,\n                    y: 7,\n                    USstate: \"NY\",\n                    capital: \"Albany\",\n                    color: \"#c51162\",\n                    region: \"northeast\",\n                    cities: [\"Manhattan\"]\n                }, {\n                    x: 20,\n                    y: 7,\n                    USstate: \"MA\",\n                    capital: \"Boston\",\n                    color: \"#c51162\",\n                    region: \"northeast\",\n                    cities: [\"Boston\", \"Cape Cod\"]\n                }, {\n                    x: 22,\n                    y: 7,\n                    USstate: \"RI\",\n                    capital: \"Providence\",\n                    color: \"#c51162\",\n                    region: \"northeast\",\n                    cities: [\"Newport\"]\n                }]\n            }, {\n                data: [{\n                    x: 19,\n                    y: 8,\n                    USstate: \"VT\",\n                    capital: \"Montpelier\",\n                    color: \"#c51162\",\n                    region: \"northeast\"\n                }, {\n                    x: 21,\n                    y: 8,\n                    USstate: \"NH\",\n                    capital: \"Concord\",\n                    color: \"#c51162\",\n                    region: \"northeast\"\n                }]\n            }, {\n                data: [{\n                    x: 0,\n                    y: 9,\n                    USstate: \"AK\",\n                    capital: \"Juneau\",\n                    color: \"#2962ff\",\n                    region: \"west\"\n                }, {\n                    x: 22,\n                    y: 9,\n                    USstate: \"ME\",\n                    capital: \"Augusta\",\n                    color: \"#c51162\",\n                    region: \"northeast\"\n                }]\n            }]\n        });\n\n        // Count available states after chart is created\n        setTimeout(countAvailableStates, 500);\n\n        // Handle window resize and orientation change for mobile responsiveness\n        let resizeTimer;\n        function handleResize() {\n            clearTimeout(resizeTimer);\n            resizeTimer = setTimeout(function () {\n                const chart = Highcharts.charts.find(chart => chart && chart.renderTo.id === \'container\');\n                if (chart) {\n                    chart.reflow();\n                }\n            }, 250);\n        }\n\n        window.addEventListener(\'resize\', handleResize);\n        window.addEventListener(\'orientationchange\', function () {\n            setTimeout(handleResize, 500);\n        });\n\n        // Store original city list for filtering\n        let originalCityList = [];\n\n        // Modal Functions\n        function openCityModal(state, cities) {\n            const modal = document.getElementById(\'cityModal\');\n            const modalTitle = document.getElementById(\'modalTitle\');\n            const cityList = document.getElementById(\'cityList\');\n            const citySearch = document.getElementById(\'citySearch\');\n            const noResults = document.getElementById(\'noResults\');\n\n            if (modal && modalTitle && cityList) {\n                // Set the modal title based on state\n                const stateNames = {\n                    \'AZ\': \'Arizona\',\n                    \'CA\': \'California\',\n                    \'CO\': \'Colorado\',\n                    \'CT\': \'Connecticut\',\n                    \'DC\': \'D.C.\',\n                    \'FL\': \'Florida\',\n                    \'GA\': \'Georgia\',\n                    \'IL\': \'Illinois\',\n                    \'KY\': \'Kentucky\',\n                    \'LA\': \'Louisiana\',\n                    \'MA\': \'Massachusetts\',\n                    \'MI\': \'Michigan\',\n                    \'MN\': \'Minnesota\',\n                    \'NV\': \'Nevada\',\n                    \'NY\': \'New York\',\n                    \'NC\': \'North Carolina\',\n                    \'OH\': \'Ohio\',\n                    \'OK\': \'Oklahoma\',\n                    \'OR\': \'Oregon\',\n                    \'PA\': \'Pennsylvania\',\n                    \'RI\': \'Rhode Island\',\n                    \'SC\': \'South Carolina\',\n                    \'TN\': \'Tennessee\',\n                    \'TX\': \'Texas\',\n                    \'WA\': \'Washington\'\n                };\n                const stateName = stateNames[state] || state;\n                modalTitle.textContent = `${cities.length} Location${cities.length > 1 ? \'s\' : \'\'} in ${stateName}`;\n\n                // Clear search field\n                if (citySearch) {\n                    citySearch.value = \'\';\n                }\n\n                // Clear existing cities\n                cityList.innerHTML = \'\';\n                originalCityList = [];\n\n                // City-specific page mappings\n                const cityPageMap = {\n                    \'Aspen\': \'locations/photo-booth-rental-in-aspen,colorado.html\',\n                    \'Baton Rouge\': \'locations/photo-booth-rental-in-baton-rouge,louisiana.html\',\n                    \'Boston\': \'locations/photo-booth-rental-in-boston,massachusetts.html\',\n                    \'Cape Cod\': \'locations/photo-booth-rental-in-cape-cod,massachusetts.html\',\n                    \'Charlotte\': \'locations/photo-booth-rental-in-charlotte,north-carolina.html\',\n                    \'Charleston\': \'locations/photo-booth-rental-in-charleston,south-carolina.html\',\n                    \'Chicago\': \'locations/photo-booth-rental-in-chicago,illinois.html\',\n                    \'Cleveland\': \'locations/photo-booth-rental-in-cleveland,ohio.html\',\n                    \'Colorado Springs\': \'locations/photo-booth-rental-in-colorado-springs,colorado.html\',\n                    \'Dallas\': \'locations/photo-booth-rental-in-dallas,texas.html\',\n                    \'Denver\': \'locations/photo-booth-rental-in-denver,colorado.html\',\n                    \'Detroit\': \'locations/photo-booth-rental-in-detroit,michigan.html\',\n                    \'Estes Park\': \'locations/photo-booth-rental-in-estes-park,colorado.html\',\n                    \'Hartford\': \'locations/photo-booth-rental-in-hartford,connecticut.html\',\n                    \'Houston\': \'locations/photo-booth-rental-in-houston,texas.html\',\n                    \'Lafayette\': \'locations/photo-booth-rental-in-lafayette,colorado.html\',\n                    \'Lakewood\': \'locations/photo-booth-rental-in-lakewood,colorado.html\',\n                    \'Las Vegas\': \'locations/photo-booth-rental-in-las-vegas,nevada.html\',\n                    \'Lexington\': \'locations/photo-booth-rental-in-lexington,kentucky.html\',\n                    \'Los Angeles\': \'locations/photo-booth-rental-in-los-angeles,california.html\',\n                    \'Manhattan\': \'locations/photo-booth-rental-in-manhattan,new-york.html\',\n                    \'Minneapolis\': \'locations/photo-booth-rental-in-minneapolis,minnesota.html\',\n                    \'Nashville\': \'locations/photo-booth-rental-in-nashville,tennessee.html\',\n                    \'New Orleans\': \'locations/photo-booth-rental-in-new-orleans,louisiana.html\',\n                    \'Newport\': \'locations/photo-booth-rental-in-newport,rhode-island.html\',\n                    \'Oklahoma City\': \'locations/photo-booth-rental-in-oklahoma-city.html\',\n                    \'Orlando\': \'locations/photo-booth-rental-in-orlando,florida.html\',\n                    \'Phoenix\': \'locations/photo-booth-rental-in-phoenix,arizona.html\',\n                    \'Pittsburgh\': \'locations/photo-booth-rental-in-pittsburgh,pennsylvania.html\',\n                    \'Portland\': \'locations/photo-booth-rental-in-portland,oregon.html\',\n                    \'San Antonio\': \'locations/photo-booth-rental-in-san-antonio,texas.html\',\n                    \'San Diego\': \'locations/photo-booth-rental-in-san-diego,california.html\',\n                    \'San Francisco\': \'locations/photo-booth-rental-in-san-francisco,california.html\',\n                    \'Savannah\': \'locations/photo-booth-rental-in-savannah,georgia.html\',\n                    \'Seattle\': \'locations/photo-booth-rental-in-seattle,washington.html\',\n                    \'Tucson\': \'locations/photo-booth-rental-in-tucson,arizona.html\',\n                    \'Tulsa\': \'locations/photo-booth-rental-in-tulsa,oklahoma.html\',\n                    \'Vail\': \'locations/photo-booth-rental-in-vail,colorado.html\',\n                    \'Washington DC\': \'locations/photo-booth-rental-in-washington-dc.html\'\n                };\n\n                // Function to properly encode file paths with special characters\n                function getCityUrl(city) {\n                    if (cityPageMap[city]) {\n                        // For files with encoded characters in filename, return as-is\n                        return cityPageMap[city];\n                    }\n                    return \'locations.html\';\n                }\n\n                // Add cities to the list\n                cities.forEach(city => {\n                    const li = document.createElement(\'li\');\n                    li.className = \'city-item\';\n                    li.setAttribute(\'data-city\', city.toLowerCase());\n                    const link = document.createElement(\'a\');\n                    // Use city-specific page if available, otherwise use default\n                    link.href = getCityUrl(city);\n                    link.className = \'city-link\';\n                    link.textContent = city;\n                    li.appendChild(link);\n                    cityList.appendChild(li);\n                    originalCityList.push(li.cloneNode(true));\n                });\n\n                // Hide no results message\n                if (noResults) {\n                    noResults.style.display = \'none\';\n                }\n\n                modal.classList.add(\'show\');\n                document.body.style.overflow = \'hidden\';\n\n                // Focus on search input\n                if (citySearch) {\n                    setTimeout(() => citySearch.focus(), 100);\n                }\n            }\n        }\n\n        // Filter cities based on search input\n        function filterCities() {\n            const searchInput = document.getElementById(\'citySearch\');\n            const cityList = document.getElementById(\'cityList\');\n            const noResults = document.getElementById(\'noResults\');\n\n            if (!searchInput || !cityList) return;\n\n            const searchTerm = searchInput.value.toLowerCase().trim();\n            const cityItems = cityList.querySelectorAll(\'.city-item\');\n            let visibleCount = 0;\n\n            cityItems.forEach(item => {\n                const cityName = item.getAttribute(\'data-city\') || \'\';\n                if (cityName.includes(searchTerm)) {\n                    item.style.display = \'\';\n                    visibleCount++;\n                } else {\n                    item.style.display = \'none\';\n                }\n            });\n\n            // Show/hide no results message\n            if (noResults) {\n                if (visibleCount === 0 && searchTerm !== \'\') {\n                    noResults.style.display = \'block\';\n                } else {\n                    noResults.style.display = \'none\';\n                }\n            }\n        }\n\n        function closeCityModal() {\n            const modal = document.getElementById(\'cityModal\');\n            const citySearch = document.getElementById(\'citySearch\');\n            if (modal) {\n                modal.classList.remove(\'show\');\n                document.body.style.overflow = \'\';\n                // Clear search when closing\n                if (citySearch) {\n                    citySearch.value = \'\';\n                    filterCities(); // Reset filter\n                }\n            }\n        }\n\n        // Close modal when clicking outside of it\n        window.addEventListener(\'click\', function (event) {\n            const modal = document.getElementById(\'cityModal\');\n            if (event.target === modal) {\n                closeCityModal();\n            }\n        });\n\n        // Close modal with Escape key\n        document.addEventListener(\'keydown\', function (event) {\n            if (event.key === \'Escape\') {\n                closeCityModal();\n            }\n        });\n    </script>\n\n    <script src=\"../assets/components/navigation.js\"></script>\n    <script src=\"../assets/components/footer.js\"></script>\n    <!-- Load Back to Top Component -->\n    <script src=\"assets/components/back-to-top.js\"></script>\n\n</body>', NULL, 'published', NULL, '2025-12-14 00:30:10', '2025-12-14 00:30:10');
INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(126, 'Our Services', 'our-services', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Our Services | MiHi Entertainment</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link\n        href=\"https://fonts.googleapis.com/css2?family=Arvo:wght@400;700&family=Cinzel:wght@500;600;700;800;900&family=Inter:wght@300;400;500;600;700;800;900&family=Montserrat:wght@500;600;700&family=Playfair+Display:wght@400;500;600;700;800;900&display=swap\"\n        rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Source+Code+Pro:wght@400;600;700&display=swap\"\n        rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Raleway:wght@300;400;500;600;700;800&display=swap\"\n        rel=\"stylesheet\">\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Merriweather:wght@300;900&display=swap\');\n        @import url(\'https://fonts.googleapis.com/css2?family=Righteous&display=swap\');\n\n        @font-face {\n            font-family: \'AzoSans\';\n            src: url(\'assets/fonts/AzoSans-Regular.woff2\') format(\'woff2\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        @font-face {\n            font-family: \'AzoSansUber\';\n            src: url(\'assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        .font-style-AzoSans {\n            font-family: \'AzoSans\', sans-serif;\n        }\n\n        html,\n        body {\n            font-family: \'Inter\', sans-serif;\n            color: #1a202c;\n            width: 100%;\n            max-width: 100vw;\n            overflow-x: hidden;\n            margin: 0;\n            padding: 0;\n        }\n\n        h1,\n        h2,\n        h3,\n        h4,\n        h5,\n        h6 {\n            font-family: \'Playfair Display\', serif;\n        }\n\n        .btn-primary {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 100%);\n            transition: all 0.3s ease;\n        }\n\n        .btn-primary:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(0, 80, 255, 0.4);\n        }\n\n        /* Bubble Button Animation */\n        .btn {\n            display: inline-block;\n            text-decoration: none;\n        }\n\n        .btn-bubble {\n            color: white;\n            background-repeat: no-repeat;\n            position: relative;\n        }\n\n        .btn-bubble:not(:hover):not(:focus) {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 100%);\n        }\n\n        .btn-bubble:hover,\n        .btn-bubble:focus {\n            animation: bubbles 1s forwards ease-out;\n            background:\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 5% 120% / 0.6em 0.6em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 15% 110% / 0.8em 0.8em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 25% 130% / 0.7em 0.7em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 35% 100% / 0.9em 0.9em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 45% 115% / 0.5em 0.5em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 55% 125% / 1em 1em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 65% 105% / 0.75em 0.75em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 75% 135% / 0.85em 0.85em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 85% 120% / 0.65em 0.65em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 95% 110% / 0.95em 0.95em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 105% 130% / 0.55em 0.55em;\n\n            color: #1f1f1f;\n            background-color: #18F1E1;\n            background-repeat: no-repeat;\n        }\n\n        @keyframes bubbles {\n            100% {\n                background-position:\n                    3% -350%,\n                    18% -280%,\n                    22% -320%,\n                    38% -250%,\n                    42% -380%,\n                    58% -200%,\n                    62% -340%,\n                    78% -180%,\n                    88% -300%,\n                    98% -220%,\n                    102% -360%;\n                box-shadow: inset 0 -6.5em 0 #FF4F4F;\n            }\n        }\n\n        /* Hero Button Responsive */\n        .hero-button {\n            font-size: 1.125rem;\n            padding: 0.75rem 2rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-button {\n                font-size: 1rem;\n                padding: 0.625rem 1.5rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-button {\n                font-size: 0.875rem;\n                padding: 0.5rem 1.25rem;\n            }\n        }\n\n        .section-padding {\n            padding: 5rem 0;\n        }\n\n        @media (max-width: 768px) {\n            .section-padding {\n                padding: 3rem 0;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .section-padding {\n                padding: 2.5rem 0;\n            }\n        }\n\n        .services-cards-section.section-padding {\n            padding: 5rem 0;\n        }\n\n        @media (max-width: 768px) {\n            .services-cards-section.section-padding {\n                padding: 3rem 0;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .services-cards-section.section-padding {\n                padding: 2rem 0;\n            }\n        }\n\n        .hero-section {\n            background-image: url(\'../assets/images/galleries/ourservices/hero.jpg\');\n            background-attachment: fixed;\n            background-position: center center;\n            background-size: cover;\n            background-repeat: no-repeat;\n            min-height: 100vh;\n        }\n\n        @media (max-width: 768px) {\n            .hero-section {\n                min-height: 85vh;\n                background-attachment: scroll;\n                padding: 2rem 0;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-section {\n                min-height: 75vh;\n                padding: 1.5rem 0;\n            }\n        }\n\n        .hero-section .corporate-text {\n            font-family: \'Montserrat\', sans-serif;\n            letter-spacing: 0.3em;\n        }\n\n        @media (max-width: 640px) {\n            .hero-section .corporate-text {\n                letter-spacing: 0.15em;\n            }\n        }\n\n        /* Hero Heading Responsive */\n        .hero-heading {\n            font-size: 6rem;\n            line-height: 1.1;\n        }\n\n        @media (max-width: 1024px) {\n            .hero-heading {\n                font-size: 4.5rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .hero-heading {\n                font-size: 3rem;\n                line-height: 1.15;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-heading {\n                font-size: 2.25rem;\n                line-height: 1.2;\n            }\n        }\n\n        /* Hero Badge Responsive */\n        .hero-badge {\n            font-size: 15px;\n        }\n\n        @media (max-width: 768px) {\n            .hero-badge {\n                font-size: 12px;\n                padding: 0.5rem 0.75rem !important;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-badge {\n                font-size: 11px;\n                padding: 0.375rem 0.625rem !important;\n            }\n        }\n\n        /* Hero Description Responsive */\n        .hero-description {\n            font-size: 1rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-description {\n                font-size: 0.875rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-description {\n                font-size: 0.8125rem;\n            }\n        }\n\n        /* Hero Location Text Responsive */\n        .hero-location {\n            font-size: 0.75rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-location {\n                font-size: 0.6875rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-location {\n                font-size: 0.625rem;\n            }\n        }\n\n        /* Enhanced overlay for mobile readability */\n        @media (max-width: 768px) {\n            .hero-section .bg-opacity-50 {\n                background-color: rgba(0, 0, 0, 0.6) !important;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-section .bg-opacity-50 {\n                background-color: rgba(0, 0, 0, 0.65) !important;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .container {\n                padding-left: 1rem;\n                padding-right: 1rem;\n            }\n        }\n\n        .animate-fade-in-up {\n            animation: fadeInUp 1s ease-out forwards;\n            opacity: 0;\n        }\n\n        .animate-delay-200 {\n            animation-delay: 0.2s;\n        }\n\n        .animate-delay-300 {\n            animation-delay: 0.3s;\n        }\n\n        .animate-delay-400 {\n            animation-delay: 0.4s;\n        }\n\n        @keyframes fadeInUp {\n            from {\n                opacity: 0;\n                transform: translateY(20px);\n            }\n\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n\n        /* Card Images Section Styles */\n        * {\n            box-sizing: border-box;\n        }\n\n        body {\n            overflow-x: hidden;\n            max-width: 100vw;\n        }\n\n        .services-cards-section {\n            background: linear-gradient(135deg, #f8f9ff 0%, #f0f4ff 25%, #e8f0ff 50%, #f0f4ff 75%, #f8f9ff 100%);\n            background-size: 200% 200%;\n            position: relative;\n            width: 100%;\n            max-width: 100vw;\n            overflow-x: hidden;\n        }\n\n        .services-cards-section::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background:\n                radial-gradient(circle at 20% 30%, rgba(0, 80, 255, 0.08) 0%, transparent 50%),\n                radial-gradient(circle at 80% 70%, rgba(102, 51, 153, 0.06) 0%, transparent 50%),\n                radial-gradient(circle at 50% 50%, rgba(0, 102, 255, 0.04) 0%, transparent 50%);\n            pointer-events: none;\n            z-index: 0;\n        }\n\n        .services-cards-section::after {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background-image:\n                repeating-linear-gradient(45deg, transparent, transparent 35px, rgba(0, 80, 255, 0.03) 35px, rgba(0, 80, 255, 0.03) 70px),\n                repeating-linear-gradient(-45deg, transparent, transparent 35px, rgba(102, 51, 153, 0.02) 35px, rgba(102, 51, 153, 0.02) 70px);\n            pointer-events: none;\n            z-index: 0;\n        }\n\n        .services-cards-container {\n            position: relative;\n            z-index: 1;\n            max-width: 1800px;\n            width: 100%;\n            margin: 0 auto;\n            padding: 0;\n        }\n\n        @media (max-width: 640px) {\n            .services-cards-container {\n                max-width: 100%;\n            }\n        }\n\n        .services-title {\n            font-family: \'AzoSansUber\', sans-serif;\n            font-weight: 800;\n            text-align: center;\n            margin-bottom: 3rem;\n            font-size: 3rem;\n            letter-spacing: 0.1em;\n            text-transform: uppercase;\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 50%, #FF4F4F 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n            line-height: 1.2;\n        }\n\n        @media (max-width: 1024px) {\n            .services-title {\n                font-size: 2.5rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .services-title {\n                font-size: 2rem;\n                margin-bottom: 2rem;\n                padding: 0 1rem;\n                letter-spacing: 0.08em;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .services-title {\n                font-size: 1.5rem;\n                margin-bottom: 1.5rem;\n                letter-spacing: 0.05em;\n            }\n        }\n\n        /* Letter Drop Animation for SERVICES */\n        .services-word {\n            font-family: \'Montserrat\', sans-serif;\n            font-weight: 800;\n            display: inline-block;\n            vertical-align: baseline;\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 50%, #FF4F4F 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n        }\n\n        .letterDrop {\n            position: relative;\n            top: 0;\n            display: inline-block;\n            text-transform: uppercase;\n            letter-spacing: 0.1em;\n            opacity: 0.8;\n            transform: rotateX(-90deg);\n            animation: letterDrop 1.2s ease 1 normal forwards;\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 50%, #FF4F4F 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n        }\n\n        @keyframes letterDrop {\n            10% {\n                opacity: 0.5;\n            }\n\n            20% {\n                opacity: 0.8;\n                top: 3.75em;\n                transform: rotateX(-360deg);\n            }\n\n            100% {\n                opacity: 1;\n                top: 0;\n                transform: rotateX(360deg);\n            }\n        }\n\n        .letterDrop:nth-child(2n) {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 50%, #FF4F4F 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n        }\n\n        .ld1 {\n            animation-delay: 1.1s;\n        }\n\n        .ld2 {\n            animation-delay: 1.2s;\n        }\n\n        .ld3 {\n            animation-delay: 1.3s;\n        }\n\n        .ld4 {\n            animation-delay: 1.4s;\n        }\n\n        .ld5 {\n            animation-delay: 1.5s;\n        }\n\n        .ld6 {\n            animation-delay: 1.6s;\n        }\n\n        .ld7 {\n            animation-delay: 1.7s;\n        }\n\n        .ld8 {\n            animation-delay: 1.8s;\n        }\n\n        .ld9 {\n            animation-delay: 1.9s;\n        }\n\n        .services-carousel-wrapper {\n            position: relative;\n            width: 100%;\n            max-width: 100vw;\n            padding: 0 5rem;\n            overflow: hidden;\n            box-sizing: border-box;\n        }\n\n        @media (max-width: 1400px) {\n            .services-carousel-wrapper {\n                padding: 0 4rem;\n            }\n        }\n\n        @media (max-width: 1024px) {\n            .services-carousel-wrapper {\n                padding: 0 3.5rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .services-carousel-wrapper {\n                padding: 0 2.5rem;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .services-carousel-wrapper {\n                padding: 0 0;\n                margin: 0;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .services-carousel-wrapper {\n                padding: 0 0;\n                margin: 0;\n            }\n        }\n\n        .services-carousel-container {\n            display: flex;\n            gap: 1rem;\n            overflow-x: auto;\n            scroll-behavior: smooth;\n            scrollbar-width: none;\n            -ms-overflow-style: none;\n            width: 100%;\n            padding: 1rem 0;\n            scroll-snap-type: x mandatory;\n            -webkit-overflow-scrolling: touch;\n            overscroll-behavior-x: contain;\n            box-sizing: border-box;\n        }\n\n        .services-carousel-container::-webkit-scrollbar {\n            display: none;\n        }\n\n        @media (max-width: 1024px) {\n            .services-carousel-container {\n                gap: 0.875rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .services-carousel-container {\n                gap: 1rem;\n                padding: 0.75rem 0;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .services-carousel-container {\n                gap: 0;\n                padding: 0.5rem 0;\n                scroll-padding: 0;\n                width: 100vw;\n                max-width: 100vw;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .services-carousel-container {\n                gap: 0;\n                padding: 0.5rem 0;\n                scroll-padding: 0;\n                width: 100vw;\n                max-width: 100vw;\n            }\n        }\n\n        @media (max-width: 360px) {\n            .services-carousel-container {\n                gap: 0;\n                padding: 0.5rem 0;\n                scroll-padding: 0;\n                width: 100vw;\n                max-width: 100vw;\n            }\n        }\n\n        .services-grid {\n            display: flex;\n            gap: 1rem;\n            width: max-content;\n            box-sizing: border-box;\n        }\n\n        @media (max-width: 1024px) {\n            .services-grid {\n                gap: 0.875rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .services-grid {\n                gap: 1rem;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .services-grid {\n                gap: 0;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .services-grid {\n                gap: 0;\n            }\n        }\n\n        @media (max-width: 360px) {\n            .services-grid {\n                gap: 0;\n            }\n        }\n\n        .carousel-arrow {\n            position: absolute;\n            top: 50%;\n            transform: translateY(-50%);\n            background: rgba(43, 231, 248, 0.95);\n            border: 2px solid #18F1E1;\n            color: #1F1F1F;\n            width: 50px;\n            height: 50px;\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            cursor: pointer;\n            z-index: 10;\n            transition: all 0.3s ease;\n            box-shadow: 0 4px 12px rgba(0, 80, 255, 0.2);\n        }\n\n        .carousel-arrow:hover {\n            background: #18F1E1;\n            color: #1F1F1F;\n            transform: translateY(-50%) scale(1.1);\n            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4);\n        }\n\n        .carousel-arrow:active {\n            transform: translateY(-50%) scale(0.95);\n        }\n\n        .carousel-arrow-left {\n            left: 1rem;\n        }\n\n        .carousel-arrow-right {\n            right: 1rem;\n        }\n\n        @media (max-width: 768px) {\n            .carousel-arrow {\n                width: 44px;\n                height: 44px;\n                border-width: 2px;\n            }\n\n            .carousel-arrow-left {\n                left: 0.75rem;\n            }\n\n            .carousel-arrow-right {\n                right: 0.75rem;\n            }\n\n            .carousel-arrow svg {\n                width: 20px;\n                height: 20px;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .carousel-arrow {\n                width: 40px;\n                height: 40px;\n                background: rgba(255, 255, 255, 0.98);\n                box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);\n            }\n\n            .carousel-arrow-left {\n                left: 0.25rem;\n            }\n\n            .carousel-arrow-right {\n                right: 0.25rem;\n            }\n\n            .carousel-arrow svg {\n                width: 16px;\n                height: 16px;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .carousel-arrow {\n                width: 36px;\n                height: 36px;\n            }\n\n            .carousel-arrow-left {\n                left: 0.125rem;\n            }\n\n            .carousel-arrow-right {\n                right: 0.125rem;\n            }\n\n            .carousel-arrow svg {\n                width: 14px;\n                height: 14px;\n            }\n        }\n\n        @media (max-width: 360px) {\n            .carousel-arrow {\n                width: 32px;\n                height: 32px;\n            }\n\n            .carousel-arrow svg {\n                width: 12px;\n                height: 12px;\n            }\n        }\n\n        .service-card {\n            background: #ffffff;\n            border-radius: 1rem;\n            overflow: hidden;\n            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);\n            transition: all 0.3s ease;\n            display: flex;\n            flex-direction: column;\n            flex-shrink: 0;\n            scroll-snap-align: start;\n            flex: 0 0 calc((100% - 2rem) / 3);\n            width: calc((100% - 2rem) / 3);\n            max-width: calc((100% - 2rem) / 3);\n            box-sizing: border-box;\n        }\n\n        @media (max-width: 1400px) {\n            .service-card {\n                flex: 0 0 calc((100% - 2rem) / 3);\n                width: calc((100% - 2rem) / 3);\n                max-width: calc((100% - 2rem) / 3);\n            }\n        }\n\n        @media (max-width: 1024px) {\n            .service-card {\n                flex: 0 0 calc((100% - 1.75rem) / 3);\n                width: calc((100% - 1.75rem) / 3);\n                max-width: calc((100% - 1.75rem) / 3);\n            }\n        }\n\n        @media (max-width: 768px) {\n            .service-card {\n                flex: 0 0 calc((100% - 1rem) / 2);\n                width: calc((100% - 1rem) / 2);\n                max-width: calc((100% - 1rem) / 2);\n            }\n        }\n\n        @media (max-width: 640px) {\n            .service-card {\n                flex: 0 0 100vw;\n                width: 100vw;\n                max-width: 100vw;\n                scroll-snap-align: center;\n                border-radius: 0.75rem;\n                margin: 0;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .service-card {\n                flex: 0 0 100vw;\n                width: 100vw;\n                max-width: 100vw;\n                border-radius: 0.5rem;\n            }\n        }\n\n        @media (max-width: 360px) {\n            .service-card {\n                flex: 0 0 100vw;\n                width: 100vw;\n                max-width: 100vw;\n            }\n        }\n\n        .service-card:hover {\n            transform: translateY(-8px);\n            box-shadow: 0 12px 24px rgba(0, 80, 255, 0.15);\n        }\n\n        .service-card-image {\n            width: 100%;\n            height: 300px;\n            object-fit: cover;\n            display: block;\n        }\n\n        @media (max-width: 768px) {\n            .service-card-image {\n                height: 240px;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .service-card-image {\n                height: 220px;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .service-card-image {\n                height: 200px;\n            }\n        }\n\n        .service-card-content {\n            padding: 1.5rem;\n            flex: 1;\n            display: flex;\n            flex-direction: column;\n        }\n\n        @media (max-width: 768px) {\n            .service-card-content {\n                padding: 1.25rem;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .service-card-content {\n                padding: 1rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .service-card-content {\n                padding: 0.875rem;\n            }\n        }\n\n        .service-card-title {\n            font-family: \'AzoSansUber\', sans-serif;\n            font-weight: 500;\n            color: #FF4F4F;\n            font-size: 1.125rem;\n            line-height: 1.4;\n            margin-bottom: 1rem;\n        }\n\n        @media (max-width: 1024px) {\n            .service-card-title {\n                font-size: 1rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .service-card-title {\n                font-size: 0.9375rem;\n                margin-bottom: 0.875rem;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .service-card-title {\n                font-size: 0.9375rem;\n                margin-bottom: 0.75rem;\n                line-height: 1.3;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .service-card-title {\n                font-size: 0.875rem;\n                margin-bottom: 0.625rem;\n            }\n        }\n\n        .service-card-text {\n            font-family: \'Inter\', sans-serif;\n            color: #4a5568;\n            font-size: 0.9375rem;\n            line-height: 1.6;\n            flex: 1;\n        }\n\n        @media (max-width: 768px) {\n            .service-card-text {\n                font-size: 0.875rem;\n                line-height: 1.5;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .service-card-text {\n                font-size: 0.8125rem;\n                line-height: 1.5;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .service-card-text {\n                font-size: 0.75rem;\n                line-height: 1.45;\n            }\n        }\n\n        /* Contact Section Styles */\n        .contact-section {\n            position: relative;\n            min-height: 350px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            background-image: url(\'../assets/images/galleries/ourservices/contact.jpg\');\n            background-size: cover;\n            background-position: center center;\n            background-repeat: no-repeat;\n            background-attachment: fixed;\n            overflow: hidden;\n        }\n\n        @media (max-width: 768px) {\n            .contact-section {\n                background-attachment: scroll;\n                min-height: 300px;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .contact-section {\n                min-height: 280px;\n            }\n        }\n\n        .contact-section::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background: linear-gradient(135deg, rgba(0, 0, 0, 0.6) 0%, rgba(0, 0, 0, 0.4) 100%);\n            z-index: 1;\n        }\n\n        .contact-section-content {\n            position: relative;\n            z-index: 2;\n            text-align: center;\n            padding: 2.5rem 2rem;\n            max-width: 900px;\n            margin: 0 auto;\n        }\n\n        @media (max-width: 768px) {\n            .contact-section-content {\n                padding: 2rem 1.5rem;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .contact-section-content {\n                padding: 1.5rem 1rem;\n            }\n        }\n\n        .contact-section-title {\n            font-family: \'AzoSansUber\', sans-serif;\n            font-weight: 500;\n            max-width: 1000px;\n            margin: 0 auto;\n            line-height: 1.2;\n            color: #FF4F4F;\n            margin-bottom: 1.5rem;\n            text-transform: uppercase;\n            letter-spacing: 0.05em;\n            text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);\n        }\n\n        @media (max-width: 1900px) {\n            .contact-section-title {\n                font-size: 2rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .contact-section-title {\n                font-size: 1.75rem;\n                margin-bottom: 1.25rem;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .contact-section-title {\n                font-size: 1.5rem;\n                margin-bottom: 1rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .contact-section-title {\n                font-size: 1.25rem;\n            }\n        }\n    </style>\n</head>\n\n<body>\n    <div id=\"nav-placeholder\"></div>\n\n    <!-- Hero Section -->\n    <section class=\"relative flex items-center justify-center overflow-hidden py-4 sm:py-6 md:py-8 hero-section\">\n        <div class=\"absolute inset-0 bg-black bg-opacity-50\"></div>\n        <div class=\"relative z-10 text-center text-white px-3 sm:px-4 md:px-6 w-full\">\n            <div class=\"max-w-3xl mx-auto\">\n                <div class=\"mb-2 sm:mb-3\">\n                    <p class=\"inline-block hero-badge leading-tight mb-2 sm:mb-3 px-3 sm:px-4 py-1 sm:py-1.5 text-black-100 tracking-[0.15em] sm:tracking-[0.2em] animate-fade-in-up animate-delay-200 corporate-text rounded-full\"\n                        style=\"font-weight: 800; color: #1f1f1f; background-color: #18F1E1;\">\n                        VIEW OUR\n                    </p>\n                    <h1 class=\"mt-2 sm:mt-3 hero-heading font-light leading-tight animate-fade-in-up corporate-heading px-2 sm:px-4\"\n                        style=\"text-shadow: 0 2px 10px rgba(0, 0, 0, 0.5), 0 0 20px rgba(10, 10, 10, 0.3); color: #FF4F4F; font-family: \'AzoSansUber\', sans-serif;\">\n                        SERVICES\n                    </h1>\n                </div>\n\n                <div class=\"h-px w-16 sm:w-20 bg-white mx-auto my-2 sm:my-3 animate-fade-in-up animate-delay-200\"></div>\n\n                <p\n                    class=\"font-style-AzoSans mx-auto hero-description leading-relaxed mb-4 sm:mb-6 px-3 sm:px-4 md:px-0 text-white/80 tracking-normal animate-fade-in-up animate-delay-200 corporate-text\">\n                    All of our packages come with these standard services included. On top of our standard services, we\n                    also have Premium Add-Ons that you can add to various packages.\n                </p>\n                <div class=\"mt-6 sm:mt-8 mb-6 sm:mb-8 animate-fade-in-up animate-delay-300\">\n                    <a href=\"./contact-us.html\"\n                        class=\"font-style-AzoSans btn btn-bubble btn-primary hero-button inline-block rounded-lg text-white font-semibold\"\n                        aria-label=\"Contact us for services\">\n                        Contact Us\n                    </a>\n                </div>\n\n                <div class=\"text-center opacity-90 animate-fade-in-up animate-delay-400\">\n                    <div class=\"h-px w-10 sm:w-12 bg-white/70 mx-auto mb-2 sm:mb-3 transition-all duration-500\"></div>\n                    <p\n                        class=\"text-white/80 tracking-wider hero-location font-medium uppercase corporate-location px-3 sm:px-4\">\n                        SERVICING DENVER, COLORADO, AND NATIONWIDE CORPORATE EVENTS\n                    </p>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Card Images Section -->\n    <section class=\"section-padding services-cards-section\">\n        <div class=\"services-cards-container\">\n            <h2 class=\"services-title\"\n                style=\"color: #FF4F4F; font-weight: 500; font-family: \'AzoSansUber\', sans-serif;\">OUR STANDARD\n                <span class=\"services-word\" id=\"services-word\"\n                    style=\"color: #FF4F4F; font-weight: 500; font-family: \'AzoSansUber\', sans-serif;\">SERVICES</span>\n                INCLUDE:\n            </h2>\n\n            <div class=\"services-carousel-wrapper\">\n                <button class=\"carousel-arrow carousel-arrow-left\" id=\"servicesCarouselPrev\"\n                    aria-label=\"Previous services\">\n                    <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"\n                        stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M15 18l-6-6 6-6\" />\n                    </svg>\n                </button>\n\n                <div class=\"services-carousel-container\" id=\"servicesCarousel\">\n                    <div class=\"services-grid\">\n                        <!-- Card 1: Unlimited Sessions -->\n                        <div class=\"service-card animate-fade-in-up animate-delay-200\">\n                            <img src=\"../assets/images/galleries/ourservices/cardimg1.jpg\"\n                                alt=\"Unlimited Sessions with Two Prints Per Session\" class=\"service-card-image\"\n                                onerror=\"this.src=\'https://via.placeholder.com/400x300/0050ff/ffffff?text=Unlimited+Sessions\'\">\n                            <div class=\"service-card-content\">\n                                <h3 class=\"service-card-title\">UNLIMITED SESSIONS WITH TWO PRINTS PER SESSION</h3>\n                                <p class=\"service-card-text\">\n                                    We try to be responsible with our printing, which is why we limit the physical\n                                    prints to two per person to prevent waste. Don\'t worry, you\'ll get the option to\n                                    text or email yourself a copy as well!\n                                </p>\n                            </div>\n                        </div>\n\n                        <!-- Card 2: Personalized Props -->\n                        <div class=\"service-card animate-fade-in-up animate-delay-300\">\n                            <img src=\"../assets/images/galleries/ourservices/cardimg2.jpg\"\n                                alt=\"Personalized Props and Pose Flashcards\" class=\"service-card-image\"\n                                onerror=\"this.src=\'https://via.placeholder.com/400x300/0050ff/ffffff?text=Personalized+Props\'\">\n                            <div class=\"service-card-content\">\n                                <h3 class=\"service-card-title\">PERSONALIZED PROPS AND POSE FLASHCARDS</h3>\n                                <p class=\"service-card-text\">\n                                    We\'re always updating our prop selection to keep your pictures fresh and exciting!\n                                    Have you seen our pose flashcards? Your attendant is armed with a stack of\n                                    flashcards that have pose ideas on them. Right before the photo booth takes a\n                                    picture, you\'ll be prompted to strike a pose.\n                                </p>\n                            </div>\n                        </div>\n\n                        <!-- Card 3: Customized Photo Strip -->\n                        <div class=\"service-card animate-fade-in-up animate-delay-400\">\n                            <img src=\"../assets/images/galleries/ourservices/cardimg3.jpg\"\n                                alt=\"Customized Photo Strip Layout Design\" class=\"service-card-image\"\n                                onerror=\"this.src=\'https://via.placeholder.com/400x300/0050ff/ffffff?text=Custom+Photo+Strip\'\">\n                            <div class=\"service-card-content\">\n                                <h3 class=\"service-card-title\">CUSTOMIZED PHOTO STRIP LAYOUT DESIGN</h3>\n                                <p class=\"service-card-text\">\n                                    We make photo strips all day for our clients and we love it! From vintage to modern,\n                                    retro to elegant, we believe each person\'s special event is just that, special, and\n                                    it deserves a custom one of a kind photo strip!\n                                </p>\n                            </div>\n                        </div>\n\n                        <!-- Card 4: Professional Attendant -->\n                        <div class=\"service-card animate-fade-in-up animate-delay-200\">\n                            <img src=\"../assets/images/galleries/ourservices/cardimg4.jpg\"\n                                alt=\"Professional Attendant Service\" class=\"service-card-image\"\n                                onerror=\"this.src=\'https://via.placeholder.com/400x300/0050ff/ffffff?text=Professional+Attendant\'\">\n                            <div class=\"service-card-content\">\n                                <h3 class=\"service-card-title\">ENGAGING ATTENDANTS</h3>\n                                <p class=\"service-card-text\">\n                                    Not only do our attendants deliver and set up the photo booth rental, but they also\n                                    stand by to ensure your guests always have ideas to pose for the camera. Their\n                                    friendly attitude will keep your guests coming back for more.\n                                </p>\n                            </div>\n                        </div>\n\n                        <!-- Card 5: Digital Gallery Access -->\n                        <div class=\"service-card animate-fade-in-up animate-delay-300\">\n                            <img src=\"../assets/images/galleries/ourservices/cardimg5.jpg\" alt=\"Digital Gallery Access\"\n                                class=\"service-card-image\"\n                                onerror=\"this.src=\'https://via.placeholder.com/400x300/0050ff/ffffff?text=Digital+Gallery\'\">\n                            <div class=\"service-card-content\">\n                                <h3 class=\"service-card-title\">ONLINE POST-EVENT GALLERY</h3>\n                                <p class=\"service-card-text\">\n                                    We found that our guests were taking pictures of the printed photo strips and\n                                    texting them to their friends and family so we decided to offer the online gallery\n                                    as a complimentary \"Thank You\" for booking with us.\n                                </p>\n                            </div>\n                        </div>\n\n                        <!-- Card 6: Setup and Breakdown -->\n                        <div class=\"service-card animate-fade-in-up animate-delay-400\">\n                            <img src=\"../assets/images/galleries/ourservices/cardimg6.jpg\"\n                                alt=\"Setup and Breakdown Service\" class=\"service-card-image\"\n                                onerror=\"this.src=\'https://via.placeholder.com/400x300/0050ff/ffffff?text=Setup+Breakdown\'\">\n                            <div class=\"service-card-content\">\n                                <h3 class=\"service-card-title\">CHOICE OF BACKDROPS</h3>\n                                <p class=\"service-card-text\">\n                                    We\'ve got quite the collection of backdrops to block out the background and focus\n                                    fully on you! Does your venue have a great background? We can set up without the\n                                    backdrop! If you\'re feeling crafty, we can use your backdrop.\n                                </p>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <button class=\"carousel-arrow carousel-arrow-right\" id=\"servicesCarouselNext\"\n                    aria-label=\"Next services\">\n                    <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"\n                        stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M9 18l6-6-6-6\" />\n                    </svg>\n                </button>\n            </div>\n        </div>\n    </section>\n\n    <!-- Contact Section -->\n    <section class=\"contact-section\" id=\"contact\">\n        <div class=\"contact-section-content\">\n            <h2 class=\"font-size-10xl contact-section-title animate-fade-in-up\">\n                WANT TO BOOK US FOR YOUR NEXT<br>\n                <span style=\"color: #18F1E1; display: block; margin-top: 0.5rem;\">EVENT?</span>\n            </h2>\n            <div class=\"animate-fade-in-up animate-delay-200\">\n                <a href=\"./contact-us.html\"\n                    class=\"btn btn-bubble btn-primary inline-block px-8 py-3 rounded-lg text-white font-semibold text-lg\"\n                    aria-label=\"Contact us for your event\">\n                    Contact Us\n                </a>\n            </div>\n        </div>\n    </section>\n\n    <script src=\"https://code.jquery.com/jquery-3.6.0.min.js\"></script>\n    <script>\n        // Letter Drop jQuery Plugin\n        (function ($) {\n            $.fn.letterDrop = function () {\n                // Chainability\n                return this.each(function () {\n                    var obj = $(this);\n\n                    var drop = {\n                        arr: obj.text().split(\'\'),\n\n                        range: {\n                            min: 1,\n                            max: 9\n                        },\n\n                        styles: function () {\n                            var dropDelays = \'\\n\', addCSS;\n\n                            for (i = this.range.min; i <= this.range.max; i++) {\n                                dropDelays += \'.ld\' + i + \' { animation-delay: 1.\' + i + \'s; }\\n\';\n                            }\n\n                            addCSS = $(\'<style>\' + dropDelays + \'</style>\');\n                            $(\'head\').append(addCSS);\n                        },\n\n                        main: function () {\n                            var dp = 0;\n                            obj.text(\'\');\n\n                            $.each(this.arr, function (index, value) {\n                                dp = Math.floor(Math.random() * (drop.range.max - drop.range.min + 1) + drop.range.min);\n\n                                if (value === \' \')\n                                    value = \'&nbsp;\'; //Add spaces\n\n                                obj.append(\'<span class=\"letterDrop ld\' + dp + \'\">\' + value + \'</span>\');\n                            });\n                        }\n                    };\n\n                    // Create styles\n                    drop.styles();\n\n                    // Initialise\n                    drop.main();\n                });\n            };\n        }(jQuery));\n\n        // Initialize letterDrop on SERVICES word\n        $(document).ready(function () {\n            $(\'#services-word\').letterDrop();\n\n            // Services Carousel Functionality\n            const carousel = document.getElementById(\'servicesCarousel\');\n            const prevBtn = document.getElementById(\'servicesCarouselPrev\');\n            const nextBtn = document.getElementById(\'servicesCarouselNext\');\n\n            if (carousel && prevBtn && nextBtn) {\n                // Calculate scroll amount based on visible cards\n                function getScrollAmount() {\n                    const firstCard = carousel.querySelector(\'.service-card\');\n                    if (!firstCard) return 0;\n\n                    const cardWidth = firstCard.offsetWidth;\n                    const gap = window.getComputedStyle(carousel).gap;\n                    const gapValue = parseFloat(gap) || 16; // Default to 16px if gap not found\n\n                    // Scroll by 3 cards (or 2 on tablet, 1 on mobile)\n                    let cardsToScroll = 3;\n                    if (window.innerWidth <= 640) {\n                        cardsToScroll = 1;\n                    } else if (window.innerWidth <= 768) {\n                        cardsToScroll = 2;\n                    }\n\n                    return (cardWidth + gapValue) * cardsToScroll;\n                }\n\n                // Improve touch scrolling on mobile\n                let isScrolling = false;\n                carousel.addEventListener(\'touchstart\', () => {\n                    isScrolling = true;\n                });\n\n                carousel.addEventListener(\'touchend\', () => {\n                    setTimeout(() => {\n                        isScrolling = false;\n                        updateButtons();\n                    }, 100);\n                });\n\n                // Check if we can scroll\n                function updateButtons() {\n                    const maxScroll = carousel.scrollWidth - carousel.clientWidth;\n                    const tolerance = 5; // Small tolerance for rounding\n\n                    prevBtn.style.opacity = carousel.scrollLeft <= tolerance ? \'0.5\' : \'1\';\n                    prevBtn.style.pointerEvents = carousel.scrollLeft <= tolerance ? \'none\' : \'auto\';\n                    prevBtn.disabled = carousel.scrollLeft <= tolerance;\n\n                    nextBtn.style.opacity = carousel.scrollLeft >= maxScroll - tolerance ? \'0.5\' : \'1\';\n                    nextBtn.style.pointerEvents = carousel.scrollLeft >= maxScroll - tolerance ? \'none\' : \'auto\';\n                    nextBtn.disabled = carousel.scrollLeft >= maxScroll - tolerance;\n                }\n\n                // Next button\n                nextBtn.addEventListener(\'click\', () => {\n                    const scrollAmount = getScrollAmount();\n                    carousel.scrollBy({\n                        left: scrollAmount,\n                        behavior: \'smooth\'\n                    });\n                });\n\n                // Previous button\n                prevBtn.addEventListener(\'click\', () => {\n                    const scrollAmount = getScrollAmount();\n                    carousel.scrollBy({\n                        left: -scrollAmount,\n                        behavior: \'smooth\'\n                    });\n                });\n\n                // Update buttons on scroll\n                carousel.addEventListener(\'scroll\', updateButtons);\n\n                // Update buttons on resize\n                let resizeTimeout;\n                window.addEventListener(\'resize\', () => {\n                    clearTimeout(resizeTimeout);\n                    resizeTimeout = setTimeout(() => {\n                        updateButtons();\n                    }, 100);\n                });\n\n                // Initial button state\n                setTimeout(updateButtons, 100);\n            }\n        });\n    </script>\n    <script src=\"../assets/components/navigation.js\"></script>\n    <script src=\"../assets/components/footer.js\"></script>\n    <!-- Load Back to Top Component -->\n    <script src=\"assets/components/back-to-top.js\"></script>\n\n</body>', NULL, 'published', NULL, '2025-12-14 00:30:10', '2025-12-14 00:30:10');
INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(127, 'Our Work', 'our-work', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Our Work | Nationwide Photobooth Rentals Services | MiHi Entertainment</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link\n        href=\"https://fonts.googleapis.com/css2?family=Arvo:wght@400;700&family=Cinzel:wght@500;600;700;800;900&family=Inter:wght@300;400;500;600;700;800;900&family=Montserrat:wght@500;600;700&family=Playfair+Display:wght@400;500;600;700;800;900&display=swap\"\n        rel=\"stylesheet\">\n    <link href=\"https://fonts.googleapis.com/css2?family=Source+Code+Pro:wght@400;600;700&display=swap\"\n        rel=\"stylesheet\">\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Merriweather:wght@300;900&display=swap\');\n        @import url(\'https://fonts.googleapis.com/css2?family=Righteous&display=swap\');\n\n        @font-face {\n            font-family: \'AzoSans\';\n            src: url(\'assets/fonts/AzoSans-Regular.woff2\') format(\'woff2\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        @font-face {\n            font-family: \'AzoSansUber\';\n            src: url(\'assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        * {\n            box-sizing: border-box;\n        }\n\n        body {\n            font-family: \'Inter\', sans-serif;\n            color: #1a202c;\n            overflow-x: hidden;\n            width: 100%;\n            max-width: 100vw;\n        }\n\n        html {\n            overflow-x: hidden;\n            width: 100%;\n            max-width: 100vw;\n        }\n\n        h1,\n        h2,\n        h3,\n        h4,\n        h5,\n        h6 {\n            font-family: \'Playfair Display\', serif;\n        }\n\n        .btn-primary {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 100%);\n            transition: all 0.3s ease;\n        }\n\n        .btn-primary:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(0, 80, 255, 0.4);\n        }\n\n        /* Bubble Button Animation */\n        .btn {\n            display: inline-block;\n            text-decoration: none;\n        }\n\n        .btn-bubble {\n            color: white;\n            background-repeat: no-repeat;\n            position: relative;\n        }\n\n        .btn-bubble:not(:hover):not(:focus) {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 100%);\n        }\n\n        .btn-bubble:hover,\n        .btn-bubble:focus {\n            animation: bubbles 1s forwards ease-out;\n            background:\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 5% 120% / 0.6em 0.6em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 15% 110% / 0.8em 0.8em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 25% 130% / 0.7em 0.7em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 35% 100% / 0.9em 0.9em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 45% 115% / 0.5em 0.5em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 55% 125% / 1em 1em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 65% 105% / 0.75em 0.75em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 75% 135% / 0.85em 0.85em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 85% 120% / 0.65em 0.65em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 95% 110% / 0.95em 0.95em,\n                radial-gradient(circle at center, transparent 30%, rgba(238, 238, 255, 0.8) 60%, rgba(238, 238, 255, 0.8) 65%, transparent 70%) 105% 130% / 0.55em 0.55em;\n\n            color: #1f1f1f;\n            background-color: #18F1E1;\n            background-repeat: no-repeat;\n        }\n\n        @keyframes bubbles {\n            100% {\n                background-position:\n                    3% -350%,\n                    18% -280%,\n                    22% -320%,\n                    38% -250%,\n                    42% -380%,\n                    58% -200%,\n                    62% -340%,\n                    78% -180%,\n                    88% -300%,\n                    98% -220%,\n                    102% -360%;\n                box-shadow: inset 0 -6.5em 0 #FF4F4F;\n            }\n        }\n\n        .section-padding {\n            padding: 5rem 0 2rem;\n        }\n\n        @media (max-width: 768px) {\n            .section-padding {\n                padding: 3rem 0 1.5rem;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .section-padding {\n                padding: 2.5rem 0 1rem;\n            }\n        }\n\n        .hero-section {\n            background-image: url(\'../assets/images/galleries/ourworks/hero.jpg\');\n            background-attachment: fixed;\n            background-position: center center;\n            background-size: cover;\n            background-repeat: no-repeat;\n            min-height: 100vh;\n        }\n\n        @media (max-width: 768px) {\n            .hero-section {\n                min-height: 85vh;\n                background-attachment: scroll;\n                padding: 2rem 0;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-section {\n                min-height: 75vh;\n                padding: 1.5rem 0;\n            }\n        }\n\n        .hero-section .corporate-text {\n            font-family: \'Montserrat\', sans-serif;\n            letter-spacing: 0.3em;\n        }\n\n        @media (max-width: 640px) {\n            .hero-section .corporate-text {\n                letter-spacing: 0.15em;\n            }\n        }\n\n        /* Hero Heading Responsive */\n        .hero-heading {\n            font-size: 6rem;\n            line-height: 1.1;\n        }\n\n        @media (max-width: 1024px) {\n            .hero-heading {\n                font-size: 4.5rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .hero-heading {\n                font-size: 3rem;\n                line-height: 1.15;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-heading {\n                font-size: 2.25rem;\n                line-height: 1.2;\n            }\n        }\n\n        /* Hero Badge Responsive */\n        .hero-badge {\n            font-size: 15px;\n        }\n\n        @media (max-width: 768px) {\n            .hero-badge {\n                font-size: 12px;\n                padding: 0.5rem 0.75rem !important;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-badge {\n                font-size: 11px;\n                padding: 0.375rem 0.625rem !important;\n            }\n        }\n\n        /* Hero Description Responsive */\n        .hero-description {\n            font-size: 1rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-description {\n                font-size: 0.875rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-description {\n                font-size: 0.8125rem;\n            }\n        }\n\n        /* Hero Button Responsive */\n        .hero-button {\n            font-size: 1.125rem;\n            padding: 0.75rem 2rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-button {\n                font-size: 1rem;\n                padding: 0.625rem 1.5rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-button {\n                font-size: 0.875rem;\n                padding: 0.5rem 1.25rem;\n            }\n        }\n\n        /* Hero Location Text Responsive */\n        .hero-location {\n            font-size: 0.75rem;\n        }\n\n        @media (max-width: 768px) {\n            .hero-location {\n                font-size: 0.6875rem;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-location {\n                font-size: 0.625rem;\n            }\n        }\n\n        /* Enhanced overlay for mobile readability */\n        @media (max-width: 768px) {\n            .hero-section .bg-opacity-50 {\n                background-color: rgba(0, 0, 0, 0.6) !important;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .hero-section .bg-opacity-50 {\n                background-color: rgba(0, 0, 0, 0.65) !important;\n            }\n        }\n\n        @media (max-width: 640px) {\n            .container {\n                padding-left: 1rem;\n                padding-right: 1rem;\n            }\n        }\n\n        .animate-fade-in-up {\n            animation: fadeInUp 1s ease-out forwards;\n            opacity: 0;\n        }\n\n        .animate-delay-200 {\n            animation-delay: 0.2s;\n        }\n\n        .animate-delay-300 {\n            animation-delay: 0.3s;\n        }\n\n        .animate-delay-400 {\n            animation-delay: 0.4s;\n        }\n\n        @keyframes fadeInUp {\n            from {\n                opacity: 0;\n                transform: translateY(20px);\n            }\n\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n\n        /* Lookbook Gallery Grid Styles - Modern Layout */\n        .lookbook-gallery {\n            width: 90vw;\n            max-width: 1400px;\n            margin: 4em auto 1em;\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n            grid-auto-rows: 60px;\n            grid-auto-flow: dense;\n            align-items: end;\n            align-content: start;\n            gap: 1.5rem;\n            padding: 0 1rem 0.5rem;\n            min-height: fit-content;\n        }\n\n        /* Ensure bottom row items align to bottom */\n        .lookbook-gallery::after {\n            content: \'\';\n            grid-column: 1 / -1;\n            height: 0;\n            display: block;\n        }\n\n        /* Force all items to align to bottom of their grid cells */\n        .lookbook-gallery .gallery-item {\n            align-self: end;\n        }\n\n        .lookbook-gallery .large,\n        .lookbook-gallery .medium,\n        .lookbook-gallery .small {\n            display: flex;\n            height: 100%;\n            width: 100%;\n            grid-column: auto / span 1;\n            position: relative;\n            overflow: hidden;\n            cursor: pointer;\n            border-radius: 16px;\n            background: #000;\n            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15), 0 2px 8px rgba(0, 0, 0, 0.1);\n            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n            opacity: 0;\n            transform: translateY(20px);\n            animation: fadeInUp 0.6s ease-out forwards;\n            align-self: end;\n        }\n\n        @keyframes fadeInUp {\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n\n        .lookbook-gallery .gallery-item:hover {\n            transform: translateY(-8px);\n            box-shadow: 0 12px 40px rgba(0, 80, 255, 0.25), 0 8px 16px rgba(0, 0, 0, 0.2);\n            border: 2px solid rgba(0, 80, 255, 0.3);\n        }\n\n        .gallery-item-title {\n            position: absolute;\n            bottom: 0;\n            left: 0;\n            right: 0;\n            background: linear-gradient(to top, rgba(0, 0, 0, 0.95) 0%, rgba(0, 0, 0, 0.7) 60%, rgba(0, 0, 0, 0.3) 80%, transparent 100%);\n            color: white;\n            padding: 1.25rem 1rem 1rem;\n            font-size: 0.875rem;\n            font-weight: 700;\n            text-transform: uppercase;\n            letter-spacing: 0.1em;\n            z-index: 1;\n            opacity: 1;\n            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n            backdrop-filter: blur(4px);\n        }\n\n        .gallery-item:hover .gallery-item-title {\n            background: linear-gradient(to top, rgba(0, 80, 255, 0.95) 0%, rgba(0, 80, 255, 0.75) 60%, rgba(0, 80, 255, 0.4) 80%, transparent 100%);\n            padding-bottom: 1.25rem;\n            transform: translateY(0);\n        }\n\n        @media (max-width: 768px) {\n            .lookbook-gallery {\n                width: 95vw;\n                gap: 1rem;\n                margin: 2em auto;\n            }\n\n            .gallery-item-title {\n                font-size: 0.75rem;\n                padding: 1rem 0.75rem 0.75rem;\n            }\n        }\n\n        .lookbook-gallery .large {\n            grid-row: span 5;\n            border-radius: 20px;\n        }\n\n        .lookbook-gallery .medium {\n            grid-row: span 4;\n        }\n\n        .lookbook-gallery .small {\n            grid-row: span 3;\n        }\n\n        .lookbook-gallery img,\n        .lookbook-gallery video {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n            transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1), filter 0.4s ease;\n        }\n\n        .lookbook-gallery .gallery-item:hover img,\n        .lookbook-gallery .gallery-item:hover video {\n            transform: scale(1.08);\n        }\n\n        /* Video hover preview */\n        .gallery-item.video-item {\n            position: relative;\n        }\n\n        .gallery-item.video-item::before {\n            content: \'\';\n            position: absolute;\n            top: 50%;\n            left: 50%;\n            transform: translate(-50%, -50%) scale(0.8);\n            width: 70px;\n            height: 70px;\n            background: linear-gradient(135deg, rgba(0, 80, 255, 0.95), rgba(0, 64, 217, 0.95));\n            border-radius: 50%;\n            z-index: 10;\n            opacity: 0;\n            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n            pointer-events: none;\n            box-shadow: 0 8px 24px rgba(0, 80, 255, 0.4);\n        }\n\n        .gallery-item.video-item::after {\n            content: \'\';\n            position: absolute;\n            top: 50%;\n            left: 50%;\n            transform: translate(-42%, -50%) scale(0.8);\n            width: 0;\n            height: 0;\n            border-left: 22px solid white;\n            border-top: 14px solid transparent;\n            border-bottom: 14px solid transparent;\n            z-index: 11;\n            opacity: 0;\n            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n            pointer-events: none;\n            filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.3));\n        }\n\n        .gallery-item.video-item:hover::before {\n            opacity: 1;\n            transform: translate(-50%, -50%) scale(1);\n        }\n\n        .gallery-item.video-item:hover::after {\n            opacity: 1;\n            transform: translate(-42%, -50%) scale(1);\n        }\n\n        .gallery-item.video-item video {\n            pointer-events: none;\n        }\n\n        .gallery-item.video-item:hover video {\n            filter: brightness(0.75) contrast(1.1);\n        }\n\n        /* Image hover effect */\n        .gallery-item:not(.video-item) {\n            cursor: pointer;\n        }\n\n        .gallery-item:not(.video-item):hover img {\n            filter: brightness(0.8) contrast(1.1);\n        }\n\n        /* Add subtle overlay on hover for images */\n        .gallery-item:not(.video-item)::before {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: linear-gradient(135deg, rgba(0, 80, 255, 0.1), rgba(0, 64, 217, 0.05));\n            opacity: 0;\n            transition: opacity 0.4s ease;\n            z-index: 1;\n            pointer-events: none;\n            border-radius: inherit;\n        }\n\n        .gallery-item:not(.video-item):hover::before {\n            opacity: 1;\n        }\n\n        /* Media Modal (for both images and videos) */\n        .media-modal {\n            position: fixed;\n            inset: 0;\n            background: rgba(0, 0, 0, 0.95);\n            z-index: 9999;\n            display: none;\n            align-items: center;\n            justify-content: center;\n            padding: 2rem;\n        }\n\n        .media-modal.active {\n            display: flex;\n        }\n\n        .media-modal-content {\n            position: relative;\n            width: 100%;\n            max-width: 90vw;\n            max-height: 90vh;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n        }\n\n        .media-modal img,\n        .media-modal video {\n            width: 100%;\n            height: auto;\n            max-width: 90vw;\n            max-height: 90vh;\n            object-fit: contain;\n            border-radius: 8px;\n        }\n\n        .media-modal-close {\n            position: absolute;\n            top: -40px;\n            right: 0;\n            color: white;\n            font-size: 2rem;\n            cursor: pointer;\n            background: rgba(255, 255, 255, 0.1);\n            width: 40px;\n            height: 40px;\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            transition: background 0.3s ease;\n            z-index: 10000;\n            border: none;\n            outline: none;\n            -webkit-tap-highlight-color: transparent;\n            touch-action: manipulation;\n        }\n\n        .media-modal-close:hover {\n            background: rgba(255, 255, 255, 0.2);\n        }\n\n        .media-modal-close:active {\n            background: rgba(255, 255, 255, 0.3);\n            transform: scale(0.95);\n        }\n\n        @media (max-width: 1024px) {\n            .lookbook-gallery {\n                width: 92vw;\n                grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n                gap: 1.25rem;\n            }\n        }\n\n        @media (max-width: 768px) {\n            .lookbook-gallery {\n                width: 95vw;\n                grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));\n                gap: 1rem;\n                margin: 2em auto;\n            }\n\n            .lookbook-gallery .large,\n            .lookbook-gallery .medium,\n            .lookbook-gallery .small {\n                border-radius: 12px;\n            }\n\n            .media-modal-content {\n                max-width: 95vw;\n            }\n\n            .media-modal-close {\n                top: 10px;\n                right: 10px;\n                width: 48px;\n                height: 48px;\n                font-size: 2.5rem;\n                background: rgba(255, 255, 255, 0.2);\n                z-index: 10001;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .lookbook-gallery {\n                grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));\n                gap: 0.75rem;\n            }\n\n            .media-modal-close {\n                top: 10px;\n                right: 10px;\n                width: 50px;\n                height: 50px;\n                font-size: 2.8rem;\n                background: rgba(255, 255, 255, 0.25);\n                z-index: 10001;\n            }\n        }\n\n        /* Particle Effect Background */\n        #lookbook-section {\n            position: relative;\n            background-image: radial-gradient(#021027, #000000);\n            overflow: hidden;\n        }\n\n        .particle-container {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            z-index: 0;\n            pointer-events: none;\n        }\n\n        .circle-container {\n            position: absolute;\n            transform: translateY(-10vh);\n            animation-iteration-count: infinite;\n            animation-timing-function: linear;\n        }\n\n        .circle-container .circle {\n            width: 100%;\n            height: 100%;\n            border-radius: 50%;\n            mix-blend-mode: screen;\n            background-image: radial-gradient(hsl(180, 100%, 80%),\n                    hsl(180, 100%, 80%) 10%,\n                    hsla(180, 100%, 80%, 0) 56%);\n            animation: fadein-frames 200ms infinite, scale-frames 2s infinite;\n        }\n\n        @keyframes fadein-frames {\n            0% {\n                opacity: 1;\n            }\n\n            50% {\n                opacity: 0.7;\n            }\n\n            100% {\n                opacity: 1;\n            }\n        }\n\n        @keyframes scale-frames {\n            0% {\n                transform: scale3d(0.4, 0.4, 1);\n            }\n\n            50% {\n                transform: scale3d(2.2, 2.2, 1);\n            }\n\n            100% {\n                transform: scale3d(0.4, 0.4, 1);\n            }\n        }\n\n        /* Ensure content is above particles */\n        #lookbook-section>.container {\n            position: relative;\n            z-index: 1;\n        }\n    </style>\n</head>\n\n<body>\n    <div id=\"nav-placeholder\"></div>\n\n    <!-- Hero Section -->\n    <section class=\"relative flex items-center justify-center overflow-hidden py-4 sm:py-6 md:py-8 hero-section\">\n        <div class=\"absolute inset-0 bg-black bg-opacity-50\"></div>\n        <div class=\"relative z-10 text-center text-white px-3 sm:px-4 md:px-6 w-full\">\n            <div class=\"max-w-3xl mx-auto\">\n                <div class=\"mb-2 sm:mb-3\">\n                    <p class=\"inline-block hero-badge leading-tight mb-2 sm:mb-3 px-3 sm:px-4 py-1 sm:py-1.5 text-white tracking-[0.15em] sm:tracking-[0.2em] animate-fade-in-up animate-delay-200 corporate-text rounded-full\"\n                        style=\"font-weight: 800; background-color: #FF4F4F; font-family: \'AzoSans\', sans-serif;\">\n                        DISCOVER OUR\n                    </p>\n                    <h1 class=\"mt-2 sm:mt-3 hero-heading font-light leading-tight animate-fade-in-up corporate-heading px-2 sm:px-4\"\n                        style=\"text-shadow: 0 2px 10px rgba(0, 0, 0, 0.5), 0 0 20px rgba(10, 10, 10, 0.3); font-family: \'AzoSansUber\', sans-serif;\">\n                        <span style=\"color: #FF4F4F;\">PORT</span><span style=\"color: #18F1E1;\">FOLIO</span>\n                    </h1>\n                </div>\n\n                <div class=\"h-px w-16 sm:w-20 bg-white mx-auto my-2 sm:my-3 animate-fade-in-up animate-delay-200\"></div>\n\n                <p\n                    class=\"font-style-AzoSans mx-auto hero-description leading-relaxed mb-4 sm:mb-6 px-3 sm:px-4 md:px-0 text-white/80 tracking-normal animate-fade-in-up animate-delay-200 corporate-text\">\n                    Discover our stunning range of photo booth experiences, featuring the GIF Booth, Video Booth,\n                    Classic Booth, and more, all presented below.\n                </p>\n                <div class=\"mt-6 sm:mt-8 mb-6 sm:mb-8 animate-fade-in-up animate-delay-300\">\n                    <a href=\"./contact-us.html\"\n                        class=\"font-style-AzoSans btn btn-bubble btn-primary hero-button inline-block rounded-lg text-white font-semibold\"\n                        aria-label=\"Contact us to view our work\">\n                        Contact Us\n                    </a>\n                </div>\n\n                <div class=\"text-center opacity-90 animate-fade-in-up animate-delay-400\">\n                    <div class=\"h-px w-10 sm:w-12 bg-white/70 mx-auto mb-2 sm:mb-3 transition-all duration-500\"></div>\n                    <p\n                        class=\"text-white/80 tracking-wider hero-location font-medium uppercase corporate-location px-3 sm:px-4\">\n                        SERVICING DENVER, COLORADO, AND NATIONWIDE CORPORATE EVENTS\n                    </p>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- LookBook Section -->\n    <section id=\"lookbook-section\" class=\"section-padding\">\n        <div class=\"particle-container\" id=\"particleContainer\"></div>\n        <div class=\"container mx-auto px-4\">\n            <div class=\"max-w-4xl mx-auto text-center\">\n                <!-- Main Heading with Alternating Colors -->\n                <h2 class=\"text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-light leading-tight mb-6 animate-fade-in-up\"\n                    style=\"text-shadow: 0 2px 10px rgba(0, 0, 0, 0.5), 0 0 20px rgba(0, 80, 255, 0.3); font-family: \'AzoSansUber\', sans-serif;\">\n                    <span class=\"text-white\">A </span>\n                    <span class=\"text-[#FF4F4F]\"\n                        style=\"text-shadow: 0 0 20px rgba(0, 0, 0, 0.8), 0 0 40px rgba(255, 79, 79, 0.4);\">LOOKBOOK</span>\n                    <span class=\"text-white\"> THAT\'S NEVER</span>\n                    <br class=\"hidden sm:block\">\n                    <span class=\"text-white\">LOOKED </span>\n                    <span class=\"text-[#18F1E1]\"\n                        style=\"text-shadow: 0 0 20px rgba(2, 2, 2, 0.8), 0 0 40px rgba(77, 219, 255, 0.4);\">QUITE\n                        THIS GOOD</span>\n                </h2>\n\n                <!-- Descriptive Paragraph -->\n                <p class=\"text-base md:text-lg text-gray-200 max-w-2xl mx-auto mb-12 leading-relaxed animate-fade-in-up animate-delay-200\"\n                    style=\"text-shadow: 0 2px 8px rgba(0, 0, 0, 0.7);\">\n                    If any booth catches your eye, just click on its image to explore its dedicated web page and learn\n                    more about the product.\n                </p>\n\n                <!-- Secondary Heading with Underline -->\n                <div class=\"animate-fade-in-up animate-delay-300\">\n                    <h3 class=\"text-xl sm:text-2xl md:text-3xl font-light text-[#18F1E1] mb-3\"\n                        style=\"text-shadow: 0 0 15px rgba(77, 166, 255, 0.6), 0 2px 10px rgba(0, 0, 0, 0.5); font-family: \'AzoSansUber\', sans-serif;\">\n                        ALL ACTIVATIONS\n                    </h3>\n                    <div class=\"h-1 w-24 bg-[#18F1E1] mx-auto\" style=\"box-shadow: 0 0 10px rgba(77, 166, 255, 0.6);\">\n                    </div>\n                </div>\n            </div>\n\n            <!-- Lookbook Gallery Grid -->\n            <div class=\'lookbook-gallery\'>\n                <!-- gal1.mp4 - Video -->\n                <div class=\'large gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal1.mp4\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal1.mp4\' muted loop></video>\n                    <div class=\'gallery-item-title\'>VOGUE BOOTH</div>\n                </div>\n                <!-- gal2.mp4 - Video -->\n                <div class=\'medium gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal2.mp4\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal2.mp4\' muted loop></video>\n                    <div class=\'gallery-item-title\'>VFX 360 BOOTH</div>\n                </div>\n                <!-- gal3.mp4 - Video -->\n                <div class=\'small gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal3.mp4\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal3.mp4\' muted loop></video>\n                    <div class=\'gallery-item-title\'>BOOMERANG/GIF BOOTH</div>\n                </div>\n                <!-- gal4.png - Image -->\n                <div class=\'large gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal4.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal4.png\' alt=\'Gallery image 4\'>\n                    <div class=\'gallery-item-title\'>COVER SHOOT</div>\n                </div>\n                <!-- gal5.mp4 - Video -->\n                <div class=\'small gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal5.mp4\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal5.mp4\' muted loop></video>\n                    <div class=\'gallery-item-title\'>BULLET-TIME ARRAY BOOTH</div>\n                </div>\n                <!-- gal6.png - Image -->\n                <div class=\'medium gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal6.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal6.png\' alt=\'Gallery image 6\'>\n                    <div class=\'gallery-item-title\'>CUSTOM SPORTS CARD</div>\n                </div>\n                <!-- gal7.mp4 - Video -->\n                <div class=\'large gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal7.mp4\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal7.mp4\' muted loop></video>\n                    <div class=\'gallery-item-title\'>GLAMBOT</div>\n                </div>\n                <!-- gal8.png - Image -->\n                <div class=\'small gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal8.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal8.png\' alt=\'Gallery image 8\'>\n                    <div class=\'gallery-item-title\'>CUSTOM NAME BADGE</div>\n                </div>\n                <!-- gal9.png - Image -->\n                <div class=\'medium gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal9.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal9.png\' alt=\'Gallery image 9\'>\n                    <div class=\'gallery-item-title\'>CUSTOM SLEIGH SET</div>\n                </div>\n                <!-- gal10.mp4 - Video -->\n                <div class=\'small gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal10.mp4\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal10.mp4\' muted loop></video>\n                    <div class=\'gallery-item-title\'>360 BOOTH</div>\n                </div>\n                <!-- gal11.mp4 - Video -->\n                <div class=\'large gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal11.mov\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal11.mov\' muted loop></video>\n                    <div class=\'gallery-item-title\'>CUSTOM VFX BOOTH</div>\n                </div>\n                <!-- gal12.png - Image -->\n                <div class=\'medium gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal12.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal12.png\' alt=\'Gallery image 12\'>\n                    <div class=\'gallery-item-title\'>KARDASHIAN GLAM FILTER</div>\n                </div>\n                <!-- gal13.png - Image -->\n                <div class=\'small gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal13.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal13.png\' alt=\'Gallery image 13\'>\n                    <div class=\'gallery-item-title\'>LIGHT PAINTING BOOTH</div>\n                </div>\n                <!-- gal14.png - Image -->\n                <div class=\'large gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal14.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal14.png\' alt=\'Gallery image 14\'>\n                    <div class=\'gallery-item-title\'>PHOTO MOSAIC WALL</div>\n                </div>\n                <!-- gal15.png - Image -->\n                <div class=\'small gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal15.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal15.png\' alt=\'Gallery image 15\'>\n                    <div class=\'gallery-item-title\'>ROAMING PHOTO BOOTH</div>\n                </div>\n                <!-- gal16.mp4 - Video -->\n                <div class=\'medium gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal16.mp4\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal16.mp4\' muted loop></video>\n                    <div class=\'gallery-item-title\'>AI BIG REMOVAL 360 BOOTH</div>\n                </div>\n                <!-- gal17.png - Image -->\n                <div class=\'large gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal17.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal17.png\' alt=\'Gallery image 17\'>\n                    <div class=\'gallery-item-title\'>SKI LIFT CUSTOM SET</div>\n                </div>\n                <!-- gal18.png - Image -->\n                <div class=\'small gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal18.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal18.png\' alt=\'Gallery image 18\'>\n                    <div class=\'gallery-item-title\'>SNOW GLOBE SET</div>\n                </div>\n                <!-- gal19.mp4 - Video -->\n                <div class=\'medium gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal19.mov\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal19.mov\' muted loop></video>\n                    <div class=\'gallery-item-title\'>WATER RAFT GREEN SCREEN</div>\n                </div>\n                <!-- gal20.png - Image -->\n                <div class=\'small gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal20.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal20.png\' alt=\'Gallery image 20\'>\n                    <div class=\'gallery-item-title\'>YOU-PHORIA</div>\n                </div>\n                <!-- gal21.png - Image -->\n                <div class=\'large gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal21.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal21.png\' alt=\'Gallery image 21\'>\n                    <div class=\'gallery-item-title\'>CUSTOM PHOTO LAYOUT</div>\n                </div>\n                <!-- gal22.png - Image -->\n                <div class=\'medium gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal22.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal22.png\' alt=\'Gallery image 22\'>\n                    <div class=\'gallery-item-title\'>VOGUE BOOTH</div>\n                </div>\n                <!-- gal23.png - Image -->\n                <div class=\'small gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal23.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal23.png\' alt=\'Gallery image 23\'>\n                    <div class=\'gallery-item-title\'>FEEL FAMOUS PHOTOGRAPHY</div>\n                </div>\n                <!-- gal24.png - Image -->\n                <div class=\'large gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal24.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal24.png\' alt=\'Gallery image 24\'>\n                    <div class=\'gallery-item-title\'>WALK THE RUNWAY GREEN SCREEN</div>\n                </div>\n                <!-- gal25.png - Image -->\n                <div class=\'small gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal25.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal25.png\' alt=\'Gallery image 25\'>\n                    <div class=\'gallery-item-title\'>VINTAGE PHOTO BOOTH</div>\n                </div>\n                <!-- gal26.png - Image -->\n                <div class=\'medium gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal26.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal26.png\' alt=\'Gallery image 26\'>\n                    <div class=\'gallery-item-title\'>SKI LIFT CUSTOM SET</div>\n                </div>\n                <!-- gal27.png - Image -->\n                <div class=\'small gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal27.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal27.png\' alt=\'Gallery image 27\'>\n                    <div class=\'gallery-item-title\'>FEEL FAMOUS PHOTOGRAPHY</div>\n                </div>\n                <!-- gal28.png - Image -->\n                <div class=\'large gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal28.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal28.png\' alt=\'Gallery image 28\'>\n                    <div class=\'gallery-item-title\'>MEMORY ALBUM</div>\n                </div>\n                <!-- gal29.png - Image -->\n                <div class=\'medium gallery-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal29.png\", \"image\")\'>\n                    <img src=\'../assets/images/galleries/ourworks/gal29.png\' alt=\'Gallery image 29\'>\n                    <div class=\'gallery-item-title\'>FEEL FAMOUS PHOTOGRAPHY</div>\n                </div>\n                <!-- gal30.mp4 - Video -->\n                <div class=\'small gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal30.mp4\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal30.mp4\' muted loop></video>\n                    <div class=\'gallery-item-title\'>CUSTOM VX VIDEO BOOTH</div>\n                </div>\n                <!-- gal31.mp4 - Video -->\n                <div class=\'large gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal31.mp4\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal31.mp4\' muted loop></video>\n                    <div class=\'gallery-item-title\'>CLASSIC PHOTO BOOTH</div>\n                </div>\n                <!-- gal32.mp4 - Video -->\n                <div class=\'medium gallery-item video-item\'\n                    onclick=\'openMediaModal(\"../assets/images/galleries/ourworks/gal32.mp4\", \"video\")\'>\n                    <video src=\'../assets/images/galleries/ourworks/gal32.mp4\' muted loop></video>\n                    <div class=\'gallery-item-title\'>360 BOOTH WITH FOG</div>\n                </div>\n            </div>\n\n            <!-- Media Modal (for both images and videos) -->\n            <div id=\"mediaModal\" class=\"media-modal\" onclick=\"closeMediaModal(event)\">\n                <div class=\"media-modal-content\" onclick=\"event.stopPropagation()\">\n                    <button class=\"media-modal-close\"\n                        onclick=\"event.stopPropagation(); closeMediaModal(event); return false;\" type=\"button\"\n                        aria-label=\"Close modal\">&times;</button>\n                    <img id=\"modalImage\" src=\"\" alt=\"Full size image\" style=\"display: none;\">\n                    <video id=\"modalVideo\" controls style=\"display: none;\"></video>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Icons Script -->\n    <script type=\"module\" src=\"https://unpkg.com/ionicons@5.5.2/dist/ionicons/ionicons.esm.js\"></script>\n    <script nomodule src=\"https://unpkg.com/ionicons@5.5.2/dist/ionicons/ionicons.js\"></script>\n\n    <script>\n        // Video hover preview - play on hover\n        document.addEventListener(\'DOMContentLoaded\', function () {\n            const videoItems = document.querySelectorAll(\'.gallery-item.video-item video\');\n            const galleryItems = document.querySelectorAll(\'.lookbook-gallery .gallery-item\');\n            const gallery = document.querySelector(\'.lookbook-gallery\');\n\n            // Staggered animation for gallery items\n            galleryItems.forEach((item, index) => {\n                const delay = (index % 6) * 0.05 + Math.floor(index / 6) * 0.1;\n                item.style.animationDelay = `${delay}s`;\n            });\n\n            // Balance bottom row - ensure all items align to bottom\n            function balanceBottomRow() {\n                if (!gallery || galleryItems.length === 0) return;\n\n                // Remove existing fillers first\n                const existingFillers = gallery.querySelectorAll(\'.gallery-item-filler\');\n                existingFillers.forEach(filler => filler.remove());\n\n                // Wait for layout to settle\n                requestAnimationFrame(() => {\n                    // Get all gallery items (excluding fillers)\n                    const items = Array.from(galleryItems);\n\n                    // Find the bottom-most position\n                    let maxBottom = 0;\n                    items.forEach(item => {\n                        const rect = item.getBoundingClientRect();\n                        const bottom = rect.bottom;\n                        if (bottom > maxBottom) {\n                            maxBottom = bottom;\n                        }\n                    });\n\n                    // Get grid column count\n                    const gridStyle = window.getComputedStyle(gallery);\n                    const columnCount = gridStyle.gridTemplateColumns.split(\' \').filter(col => col.trim() !== \'\').length;\n\n                    // Find items in the bottom row (those within 5px of maxBottom)\n                    const bottomRowItems = items.filter(item => {\n                        const rect = item.getBoundingClientRect();\n                        return Math.abs(rect.bottom - maxBottom) < 5;\n                    });\n\n                    // If bottom row is incomplete, add fillers\n                    if (bottomRowItems.length > 0 && bottomRowItems.length < columnCount) {\n                        const itemsToAdd = columnCount - bottomRowItems.length;\n                        for (let i = 0; i < itemsToAdd; i++) {\n                            const filler = document.createElement(\'div\');\n                            filler.className = \'gallery-item-filler\';\n                            filler.style.visibility = \'hidden\';\n                            filler.style.height = \'1px\';\n                            filler.style.gridRow = \'span 1\';\n                            filler.style.opacity = \'0\';\n                            filler.style.pointerEvents = \'none\';\n                            gallery.appendChild(filler);\n                        }\n                    }\n                });\n            }\n\n            // Balance on load and resize\n            setTimeout(balanceBottomRow, 300);\n            window.addEventListener(\'resize\', function () {\n                setTimeout(balanceBottomRow, 200);\n            });\n\n            videoItems.forEach(video => {\n                const item = video.closest(\'.gallery-item\');\n\n                item.addEventListener(\'mouseenter\', function () {\n                    video.play().catch(e => {\n                        // Autoplay may be prevented, that\'s okay\n                        console.log(\'Video autoplay prevented:\', e);\n                    });\n                });\n\n                item.addEventListener(\'mouseleave\', function () {\n                    video.pause();\n                    video.currentTime = 0;\n                });\n            });\n        });\n\n        // Open media modal (for both images and videos)\n        function openMediaModal(mediaSrc, type) {\n            const modal = document.getElementById(\'mediaModal\');\n            const modalImage = document.getElementById(\'modalImage\');\n            const modalVideo = document.getElementById(\'modalVideo\');\n\n            if (!modal) return;\n\n            if (type === \'video\') {\n                // Show video, hide image\n                if (modalImage) modalImage.style.display = \'none\';\n                if (modalVideo) {\n                    modalVideo.style.display = \'block\';\n                    modalVideo.src = mediaSrc;\n                    modalVideo.load();\n                }\n            } else {\n                // Show image, hide video\n                if (modalVideo) {\n                    modalVideo.style.display = \'none\';\n                    modalVideo.pause();\n                    modalVideo.src = \'\';\n                }\n                if (modalImage) {\n                    modalImage.style.display = \'block\';\n                    modalImage.src = mediaSrc;\n                }\n            }\n\n            modal.classList.add(\'active\');\n            document.body.style.overflow = \'hidden\';\n\n            // Play video when modal opens (if it\'s a video)\n            if (type === \'video\' && modalVideo) {\n                modalVideo.play().catch(e => {\n                    console.log(\'Video autoplay prevented:\', e);\n                });\n            }\n        }\n\n        // Close media modal\n        function closeMediaModal(event) {\n            const modal = document.getElementById(\'mediaModal\');\n            const modalImage = document.getElementById(\'modalImage\');\n            const modalVideo = document.getElementById(\'modalVideo\');\n\n            if (event) {\n                event.preventDefault();\n                event.stopPropagation();\n            }\n\n            if (modal) {\n                modal.classList.remove(\'active\');\n                document.body.style.overflow = \'\';\n\n                // Clean up\n                if (modalVideo) {\n                    modalVideo.pause();\n                    modalVideo.src = \'\';\n                }\n                if (modalImage) {\n                    modalImage.src = \'\';\n                }\n            }\n        }\n\n        // Add direct event listeners for better mobile support\n        document.addEventListener(\'DOMContentLoaded\', function () {\n            const closeButton = document.querySelector(\'.media-modal-close\');\n            if (closeButton) {\n                // Add multiple event types for better mobile compatibility\n                closeButton.addEventListener(\'click\', function (e) {\n                    e.preventDefault();\n                    e.stopPropagation();\n                    closeMediaModal(e);\n                });\n\n                closeButton.addEventListener(\'touchend\', function (e) {\n                    e.preventDefault();\n                    e.stopPropagation();\n                    closeMediaModal(e);\n                });\n            }\n        });\n\n        // Close modal on Escape key\n        document.addEventListener(\'keydown\', function (e) {\n            if (e.key === \'Escape\') {\n                closeMediaModal();\n            }\n        });\n\n        // Particle Effect Generation\n        function createParticles() {\n            const container = document.getElementById(\'particleContainer\');\n            if (!container) return;\n\n            const particleNum = 100;\n            const particleWidth = 10;\n\n            // Helper function to generate random number\n            function random(max) {\n                return Math.floor(Math.random() * max);\n            }\n\n            // Create 100 circle containers\n            for (let i = 1; i <= particleNum; i++) {\n                const circleContainer = document.createElement(\'div\');\n                circleContainer.className = \'circle-container\';\n\n                const circle = document.createElement(\'div\');\n                circle.className = \'circle\';\n\n                circleContainer.appendChild(circle);\n\n                // Random circle size\n                const circleSize = random(particleWidth) + 1;\n                circleContainer.style.width = circleSize + \'px\';\n                circleContainer.style.height = circleSize + \'px\';\n\n                // Random start position\n                const startPositionY = random(10) + 100;\n                const startX = random(100);\n                const endX = random(100);\n                const endY = -startPositionY - random(30);\n\n                // Random animation duration\n                const moveDuration = 7000 + random(4000);\n                const animationDelay = random(11000);\n                const circleAnimationDelay = random(4000);\n\n                // Create unique animation name\n                const animationName = `move-frames-${i}`;\n\n                // Create keyframe animation\n                const style = document.createElement(\'style\');\n                style.textContent = `\n                    @keyframes ${animationName} {\n                        from {\n                            transform: translate3d(${startX}vw, ${startPositionY}vh, 0);\n                        }\n                        to {\n                            transform: translate3d(${endX}vw, ${endY}vh, 0);\n                        }\n                    }\n                `;\n                document.head.appendChild(style);\n\n                // Apply styles to circle container\n                circleContainer.style.animationName = animationName;\n                circleContainer.style.animationDuration = moveDuration + \'ms\';\n                circleContainer.style.animationDelay = animationDelay + \'ms\';\n\n                // Apply delay to circle animation\n                circle.style.animationDelay = circleAnimationDelay + \'ms\';\n\n                container.appendChild(circleContainer);\n            }\n        }\n\n        // Initialize particles when DOM is ready\n        if (document.readyState === \'loading\') {\n            document.addEventListener(\'DOMContentLoaded\', createParticles);\n        } else {\n            createParticles();\n        }\n    </script>\n\n    <script src=\"../assets/components/navigation.js\"></script>\n    <script src=\"../assets/components/footer.js\"></script>\n    <!-- Load Back to Top Component -->\n    <script src=\"assets/components/back-to-top.js\"></script>\n\n</body>', NULL, 'published', NULL, '2025-12-14 00:30:10', '2025-12-14 00:30:10');
INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(128, 'Photo Booth Bus', 'photo-booth-bus', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <meta name=\"description\"\n        content=\"VW Bus Photo Booth by MiHi Entertainment. A show-stopping photo experience like no other. A restored VW Bus converted into a mobile photo booth for your event.\">\n    <title>VW Bus Photo Booth - MiHi Entertainment</title>\n    <link rel=\"icon\" type=\"image/svg+xml\" href=\"assets/images/favicon.svg\">\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link\n        href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=Playfair+Display:wght@400;500;600;700;800;900&display=swap\"\n        rel=\"stylesheet\">\n\n    <style>\n        * {\n            scroll-behavior: smooth;\n        }\n\n        body {\n            font-family: \'Inter\', sans-serif;\n            color: #1a202c;\n            overflow-x: hidden;\n        }\n\n        main h1,\n        main h2,\n        main h3,\n        main h4,\n        main h5,\n        main h6 {\n            font-family: \'Playfair Display\', serif;\n        }\n\n        .section-padding {\n            padding: 5rem 0;\n        }\n\n        @media (min-width: 768px) {\n            .section-padding {\n                padding: 8rem 0;\n            }\n        }\n\n        /* Sexy Glow Effects */\n        @keyframes pulse-glow {\n\n            0%,\n            100% {\n                box-shadow: 0 0 20px rgba(99, 102, 241, 0.4),\n                    0 0 40px rgba(139, 92, 246, 0.3),\n                    0 0 60px rgba(168, 85, 247, 0.2);\n            }\n\n            50% {\n                box-shadow: 0 0 30px rgba(99, 102, 241, 0.6),\n                    0 0 60px rgba(139, 92, 246, 0.5),\n                    0 0 90px rgba(168, 85, 247, 0.4);\n            }\n        }\n\n        /* Enhanced Blob Animation */\n        @keyframes blob {\n\n            0%,\n            100% {\n                transform: translate(0, 0) scale(1) rotate(0deg);\n            }\n\n            33% {\n                transform: translate(30px, -50px) scale(1.1) rotate(120deg);\n            }\n\n            66% {\n                transform: translate(-20px, 20px) scale(0.9) rotate(240deg);\n            }\n        }\n\n        .animate-blob {\n            animation: blob 7s ease-in-out infinite;\n        }\n\n        .animation-delay-2000 {\n            animation-delay: 2s;\n        }\n\n        .animation-delay-4000 {\n            animation-delay: 4s;\n        }\n\n        /* Sexy Card Hover with 3D Effect */\n        .booth-card {\n            transition: all 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n            position: relative;\n            overflow: hidden;\n            transform-style: preserve-3d;\n            perspective: 1000px;\n        }\n\n        .booth-card::before {\n            content: \'\';\n            position: absolute;\n            inset: -2px;\n            background: linear-gradient(135deg,\n                    rgba(99, 102, 241, 0.3),\n                    rgba(139, 92, 246, 0.3),\n                    rgba(168, 85, 247, 0.3),\n                    rgba(192, 132, 252, 0.3));\n            opacity: 0;\n            transition: opacity 0.5s ease;\n            border-radius: inherit;\n            z-index: -1;\n            filter: blur(10px);\n        }\n\n        .booth-card::after {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: -100%;\n            width: 100%;\n            height: 100%;\n            background: linear-gradient(90deg,\n                    transparent,\n                    rgba(255, 255, 255, 0.3),\n                    transparent);\n            transition: left 0.5s ease;\n        }\n\n        .booth-card:hover::before {\n            opacity: 1;\n        }\n\n        .booth-card:hover::after {\n            left: 100%;\n        }\n\n        .booth-card:hover {\n            transform: translateY(-15px) scale(1.03) rotateX(5deg);\n            box-shadow: 0 25px 50px rgba(99, 102, 241, 0.3),\n                0 0 0 1px rgba(139, 92, 246, 0.2);\n        }\n\n        /* Sexy Gradient Text with Shimmer */\n        .booth-gradient {\n            background: linear-gradient(135deg,\n                    #6366f1 0%,\n                    #8b5cf6 20%,\n                    #a855f7 40%,\n                    #c084fc 60%,\n                    #a855f7 80%,\n                    #8b5cf6 100%);\n            background-size: 200% auto;\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n            animation: shimmer 3s linear infinite;\n        }\n\n        @keyframes shimmer {\n            to {\n                background-position: 200% center;\n            }\n        }\n\n        .sexy-btn {\n            position: relative;\n            overflow: hidden;\n            background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 50%, #a855f7 100%);\n            transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n        }\n\n        .sexy-btn::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: -100%;\n            width: 100%;\n            height: 100%;\n            background: linear-gradient(90deg,\n                    transparent,\n                    rgba(255, 255, 255, 0.4),\n                    transparent);\n            transition: left 0.5s ease;\n        }\n\n        .sexy-btn:hover::before {\n            left: 100%;\n        }\n\n        .sexy-btn:hover {\n            transform: translateY(-3px) scale(1.05);\n            box-shadow: 0 20px 40px rgba(99, 102, 241, 0.5),\n                0 0 0 1px rgba(139, 92, 246, 0.3);\n        }\n\n        .sexy-btn:active {\n            transform: translateY(-1px) scale(1.02);\n        }\n\n        /* Floating Particles */\n        @keyframes float {\n\n            0%,\n            100% {\n                transform: translateY(0px) translateX(0px) rotate(0deg);\n                opacity: 0.7;\n            }\n\n            50% {\n                transform: translateY(-30px) translateX(20px) rotate(180deg);\n                opacity: 1;\n            }\n        }\n\n        .floating-particle {\n            position: absolute;\n            width: 6px;\n            height: 6px;\n            background: radial-gradient(circle, rgba(99, 102, 241, 0.8), transparent);\n            border-radius: 50%;\n            animation: float 8s ease-in-out infinite;\n            box-shadow: 0 0 10px rgba(99, 102, 241, 0.6);\n        }\n\n        /* Enhanced Gallery Images */\n        .gallery-image {\n            transition: all 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n            position: relative;\n            overflow: hidden;\n        }\n\n        .gallery-image::before {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: linear-gradient(135deg,\n                    rgba(99, 102, 241, 0.2),\n                    rgba(139, 92, 246, 0.2));\n            opacity: 0;\n            transition: opacity 0.5s ease;\n            z-index: 1;\n        }\n\n        .gallery-image:hover::before {\n            opacity: 1;\n        }\n\n        .gallery-image:hover {\n            transform: scale(1.1) rotate(2deg);\n            box-shadow: 0 25px 50px rgba(99, 102, 241, 0.4),\n                0 0 0 3px rgba(139, 92, 246, 0.3);\n            z-index: 10;\n        }\n\n        .gallery-image img {\n            transition: transform 0.5s ease;\n        }\n\n        .gallery-image:hover img {\n            transform: scale(1.15);\n        }\n\n\n        /* Scroll Reveal Animation */\n        .reveal {\n            opacity: 0;\n            transform: translateY(50px);\n            transition: all 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n        }\n\n        .reveal.active {\n            opacity: 1;\n            transform: translateY(0);\n        }\n\n        /* Glassmorphism Effect */\n        .glass {\n            background: rgba(255, 255, 255, 0.1);\n            backdrop-filter: blur(10px);\n            -webkit-backdrop-filter: blur(10px);\n            border: 1px solid rgba(255, 255, 255, 0.2);\n        }\n\n        /* Sexy Hero Title Animation */\n        @keyframes title-float {\n\n            0%,\n            100% {\n                transform: translateY(0px);\n            }\n\n            50% {\n                transform: translateY(-10px);\n            }\n        }\n\n        .hero-title {\n            animation: title-float 6s ease-in-out infinite;\n            text-shadow: 0 0 30px rgba(99, 102, 241, 0.5),\n                0 0 60px rgba(139, 92, 246, 0.3);\n        }\n\n        /* Enhanced Auto-Scrolling Gallery */\n        .scroll-container {\n            overflow: hidden;\n            position: relative;\n            mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);\n            -webkit-mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);\n        }\n\n        .scroll-content {\n            display: flex;\n            animation: scroll-left 30s linear infinite;\n        }\n\n        .scroll-content:hover {\n            animation-play-state: paused;\n        }\n\n        @keyframes scroll-left {\n            0% {\n                transform: translateX(0);\n            }\n\n            100% {\n                transform: translateX(-50%);\n            }\n        }\n\n        /* Sexy Lightbox */\n        .lightbox {\n            display: none;\n            position: fixed;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background: rgba(0, 0, 0, 0.95);\n            backdrop-filter: blur(10px);\n            -webkit-backdrop-filter: blur(10px);\n            z-index: 9999;\n            justify-content: center;\n            align-items: center;\n            cursor: zoom-out;\n            animation: fadeIn 0.3s ease;\n        }\n\n        @keyframes fadeIn {\n            from {\n                opacity: 0;\n            }\n\n            to {\n                opacity: 1;\n            }\n        }\n\n        .lightbox.active {\n            display: flex;\n        }\n\n        .lightbox-img-container {\n            position: relative;\n            max-width: 90%;\n            max-height: 90vh;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            animation: scaleIn 0.3s ease;\n        }\n\n        @keyframes scaleIn {\n            from {\n                transform: scale(0.8);\n                opacity: 0;\n            }\n\n            to {\n                transform: scale(1);\n                opacity: 1;\n            }\n        }\n\n        .lightbox img {\n            max-width: 100%;\n            max-height: 90vh;\n            object-fit: contain;\n            border-radius: 12px;\n            box-shadow: 0 0 80px rgba(99, 102, 241, 0.6),\n                0 0 0 2px rgba(139, 92, 246, 0.3);\n            cursor: zoom-in;\n            transition: transform 0.3s ease;\n        }\n\n        .lightbox img.zoomed {\n            transform: scale(2);\n            cursor: zoom-out;\n        }\n\n        .lightbox-close {\n            position: absolute;\n            top: 20px;\n            right: 30px;\n            font-size: 40px;\n            color: white;\n            cursor: pointer;\n            z-index: 10000;\n            width: 50px;\n            height: 50px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            background: rgba(255, 255, 255, 0.1);\n            backdrop-filter: blur(10px);\n            border-radius: 50%;\n            transition: all 0.3s ease;\n            border: 1px solid rgba(255, 255, 255, 0.2);\n        }\n\n        .lightbox-close:hover {\n            background: rgba(255, 255, 255, 0.2);\n            transform: rotate(90deg) scale(1.1);\n            box-shadow: 0 0 20px rgba(99, 102, 241, 0.5);\n        }\n\n        /* Mobile Responsive */\n        @media (max-width: 640px) {\n            .section-padding {\n                padding: 3rem 0;\n            }\n        }\n\n        /* Sexy Background Pattern */\n        .pattern-overlay {\n            position: absolute;\n            inset: 0;\n            background-image:\n                radial-gradient(circle at 20% 50%, rgba(99, 102, 241, 0.1) 0%, transparent 50%),\n                radial-gradient(circle at 80% 80%, rgba(139, 92, 246, 0.1) 0%, transparent 50%),\n                radial-gradient(circle at 40% 20%, rgba(168, 85, 247, 0.1) 0%, transparent 50%);\n            pointer-events: none;\n        }\n\n        /* Enhanced Image Container with Decorative Border */\n        .image-container {\n            position: relative;\n            border-radius: 24px;\n            overflow: hidden;\n            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);\n            transition: all 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n        }\n\n        .image-container::before {\n            content: \'\';\n            position: absolute;\n            inset: -3px;\n            border-radius: 24px;\n            padding: 3px;\n            background: linear-gradient(135deg, #6366f1, #8b5cf6, #a855f7, #c084fc);\n            -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\n            mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\n            -webkit-mask-composite: xor;\n            mask-composite: exclude;\n            opacity: 0;\n            transition: opacity 0.5s ease;\n            z-index: 1;\n        }\n\n        .image-container:hover::before {\n            opacity: 1;\n        }\n\n        .image-container:hover {\n            transform: translateY(-8px);\n            box-shadow: 0 30px 80px rgba(99, 102, 241, 0.3);\n        }\n\n        .image-container img {\n            display: block;\n            width: 100%;\n            height: auto;\n            transition: transform 0.5s ease;\n        }\n\n        .image-container:hover img {\n            transform: scale(1.05);\n        }\n\n\n        /* Enhanced Section Dividers */\n        .section-divider {\n            height: 1px;\n            background: linear-gradient(90deg, transparent, rgba(99, 102, 241, 0.3), transparent);\n            margin: 0 auto;\n            max-width: 1200px;\n        }\n\n        /* Decorative Accent Line */\n        .accent-line {\n            width: 80px;\n            height: 4px;\n            background: linear-gradient(90deg, #6366f1, #8b5cf6, #a855f7);\n            border-radius: 2px;\n            margin: 0 auto;\n        }\n\n        /* Enhanced Gallery with Better Spacing */\n        .gallery-grid {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n            gap: 1.5rem;\n        }\n\n        @media (min-width: 640px) {\n            .gallery-grid {\n                grid-template-columns: repeat(2, 1fr);\n                gap: 2rem;\n            }\n        }\n\n        @media (min-width: 768px) {\n            .gallery-grid {\n                grid-template-columns: repeat(3, 1fr);\n                gap: 2rem;\n            }\n        }\n\n        @media (min-width: 1024px) {\n            .gallery-grid {\n                grid-template-columns: repeat(4, 1fr);\n                gap: 2rem;\n            }\n        }\n\n        /* Better Gallery Image Styling */\n        .gallery-image {\n            aspect-ratio: 1;\n            min-height: 200px;\n        }\n\n        .gallery-image img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n        }\n\n        /* Enhanced Feature Cards */\n        .feature-icon {\n            font-size: 3.5rem;\n            filter: drop-shadow(0 4px 8px rgba(99, 102, 241, 0.3));\n            transition: transform 0.3s ease;\n        }\n\n        .booth-card:hover .feature-icon {\n            transform: scale(1.1) rotate(5deg);\n        }\n\n        /* Better Typography Spacing */\n        .text-section p {\n            margin-bottom: 1.5rem;\n            line-height: 1.8;\n        }\n\n        .text-section p:last-child {\n            margin-bottom: 0;\n        }\n\n        /* Decorative Quote Marks */\n        .quote-accent {\n            font-size: 4rem;\n            line-height: 1;\n            opacity: 0.2;\n            font-family: \'Playfair Display\', serif;\n        }\n\n        /* Enhanced Badge Styling */\n        .badge-modern {\n            display: inline-flex;\n            align-items: center;\n            gap: 0.75rem;\n            padding: 0.75rem 1.5rem;\n            background: linear-gradient(135deg, rgba(255, 255, 255, 0.95), rgba(255, 255, 255, 0.85));\n            backdrop-filter: blur(20px);\n            -webkit-backdrop-filter: blur(20px);\n            border: 2px solid rgba(255, 255, 255, 0.4);\n            border-radius: 50px;\n            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1),\n                inset 0 1px 0 rgba(255, 255, 255, 0.5);\n        }\n\n        /* Section Background Variations */\n        .bg-gradient-modern {\n            background: linear-gradient(135deg, #fafafa 0%, #ffffff 50%, #f8f9ff 100%);\n        }\n\n        /* Enhanced Image Borders */\n        .image-wrapper {\n            position: relative;\n            padding: 12px;\n            background: linear-gradient(135deg, rgba(255, 255, 255, 0.9), rgba(249, 250, 251, 0.9));\n            border-radius: 24px;\n            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.1);\n        }\n\n        .image-wrapper::after {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            border-radius: 24px;\n            padding: 2px;\n            background: linear-gradient(135deg, #6366f1, #8b5cf6, #a855f7);\n            -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\n            mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\n            -webkit-mask-composite: xor;\n            mask-composite: exclude;\n            opacity: 0.3;\n        }\n\n        /* Navigation Contact Us Button Fix - Force visibility */\n        header a[href*=\"contact-us\"],\n        nav a[href*=\"contact-us\"],\n        header a.btn-primary,\n        nav a.btn-primary,\n        header .btn-primary,\n        nav .btn-primary,\n        a.btn-primary,\n        .btn-primary {\n            background: linear-gradient(135deg, #0050ff 0%, #0040d9 100%) !important;\n            background-color: #0050ff !important;\n            background-image: linear-gradient(135deg, #0050ff 0%, #0040d9 100%) !important;\n            color: #ffffff !important;\n            border: none !important;\n            padding: 0.75rem 1.5rem !important;\n            border-radius: 9999px !important;\n            font-weight: 600 !important;\n            text-decoration: none !important;\n            display: inline-block !important;\n            transition: all 0.3s ease !important;\n            box-shadow: 0 4px 6px rgba(0, 80, 255, 0.3) !important;\n            white-space: nowrap !important;\n        }\n\n        header a.btn-primary:hover,\n        nav a.btn-primary:hover,\n        header .btn-primary:hover,\n        nav .btn-primary:hover,\n        a.btn-primary:hover,\n        .btn-primary:hover {\n            background: linear-gradient(135deg, #0040d9 0%, #0033b3 100%) !important;\n            background-color: #0040d9 !important;\n            background-image: linear-gradient(135deg, #0040d9 0%, #0033b3 100%) !important;\n            color: #ffffff !important;\n            transform: translateY(-2px) !important;\n            box-shadow: 0 6px 12px rgba(0, 80, 255, 0.4) !important;\n        }\n\n        header a.btn-primary:active,\n        nav a.btn-primary:active,\n        header .btn-primary:active,\n        nav .btn-primary:active,\n        a.btn-primary:active,\n        .btn-primary:active {\n            transform: translateY(0) !important;\n        }\n    </style>\n</head>\n\n<body class=\"bg-white\">\n    <!-- Navigation -->\n    <script src=\"assets/components/navigation.js\"></script>\n\n    <main>\n        <!-- Hero Section -->\n        <section\n            class=\"relative min-h-[70vh] sm:min-h-[80vh] md:min-h-[90vh] flex items-center justify-center overflow-hidden py-8 sm:py-12 md:py-0\">\n            <!-- Background Image -->\n            <div class=\"absolute inset-0 z-0\">\n                <img src=\"assets/images/boothbus/a92b01_9f587b92c09f4aa3803c36a9c0b1ed98~mv2.jpg\"\n                    alt=\"VW Bus Photo Booth Hero\" class=\"w-full h-full object-cover\">\n                <!-- Gradient Overlay -->\n                <div class=\"absolute inset-0 bg-gradient-to-br from-indigo-900/60 via-purple-900/50 to-violet-900/60\">\n                </div>\n            </div>\n\n            <!-- Enhanced Overlay for text readability -->\n            <div class=\"absolute inset-0 bg-gradient-to-b from-black/50 via-black/30 to-black/50 z-[1]\"></div>\n\n            <!-- Animated Grid Pattern -->\n            <div class=\"absolute inset-0 z-[1] opacity-10\"\n                style=\"background-image: linear-gradient(rgba(255,255,255,0.1) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.1) 1px, transparent 1px); background-size: 50px 50px;\">\n            </div>\n\n            <!-- Glow Orbs -->\n            <div\n                class=\"absolute top-20 left-10 w-48 h-48 sm:w-64 sm:h-64 md:w-96 md:h-96 bg-indigo-300/20 rounded-full blur-3xl animate-blob z-[2]\">\n            </div>\n            <div\n                class=\"absolute bottom-20 right-10 w-48 h-48 sm:w-64 sm:h-64 md:w-96 md:h-96 bg-purple-300/20 rounded-full blur-3xl animate-blob animation-delay-2000 z-[2]\">\n            </div>\n            <div\n                class=\"absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-32 h-32 sm:w-48 sm:h-48 md:w-64 md:h-64 bg-violet-300/15 rounded-full blur-2xl animate-blob animation-delay-4000 z-[2]\">\n            </div>\n\n            <div class=\"relative z-10 container mx-auto px-4 sm:px-6\">\n                <div class=\"max-w-6xl mx-auto text-center\">\n                    <!-- Enhanced Badge -->\n                    <div class=\"badge-modern mb-6 sm:mb-8 reveal\">\n                        <span class=\"text-indigo-900 text-xs sm:text-sm font-bold tracking-wider uppercase\">Denver\n                            Photo Booth Bus</span>\n                        <span\n                            class=\"text-xl sm:text-2xl transform transition-transform duration-300 hover:rotate-12\">🚌</span>\n                    </div>\n\n                    <!-- Main Title -->\n                    <h1 class=\"hero-title text-4xl sm:text-5xl md:text-6xl lg:text-7xl xl:text-8xl font-semibold mb-4 sm:mb-6 leading-tight sm:leading-none tracking-tight px-2 text-white drop-shadow-lg\"\n                        style=\"text-shadow: 2px 2px 6px rgba(0,0,0,0.8);\">\n                        <span class=\"block mb-2\">\n                            VW BUS PHOTO BOOTH\n                        </span>\n                    </h1>\n\n                    <!-- Subtitle -->\n                    <h2 class=\"text-lg sm:text-xl md:text-2xl font-semibold mb-4 sm:mb-6 text-white max-w-3xl mx-auto px-4 drop-shadow-lg\"\n                        style=\"text-shadow: 2px 2px 6px rgba(0,0,0,0.8);\">\n                        A show-stopping photo experience like no other.\n                    </h2>\n\n                    <!-- CTA Buttons -->\n                    <div\n                        class=\"flex flex-col sm:flex-row gap-4 sm:gap-6 justify-center items-center px-4 mt-8 sm:mt-12\">\n                        <a href=\"contact-us.html\"\n                            class=\"sexy-btn group relative inline-flex items-center gap-2 sm:gap-3 text-white px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg font-bold shadow-2xl overflow-hidden w-full sm:w-auto justify-center\">\n                            <span class=\"relative z-10\">CONTACT US</span>\n                        </a>\n                        <button type=\"button\" data-click-to-call data-call-text=\"Call Us\"\n                            class=\"group inline-flex items-center gap-2 sm:gap-3 px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg font-bold backdrop-blur-md bg-white/80 border-2 border-white/50 hover:bg-white/90 hover:border-white/70 shadow-xl hover:shadow-2xl transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 text-indigo-900 w-full sm:w-auto justify-center cursor-pointer\">\n                            <svg class=\"w-4 h-4 sm:w-5 sm:h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                    d=\"M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498A1 1 0 0121 17.72V21a2 2 0 01-2 2h-1C9.716 23 3 16.284 3 8V7a2 2 0 012-2z\">\n                                </path>\n                            </svg>\n                            <span>Call Us</span>\n                        </button>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Introduction Section -->\n        <section class=\"section-padding bg-gradient-modern relative overflow-hidden\">\n            <div class=\"pattern-overlay\"></div>\n            <!-- Floating Particles -->\n            <div class=\"floating-particle\" style=\"top: 10%; left: 15%; animation-delay: 0s;\"></div>\n            <div class=\"floating-particle\" style=\"top: 30%; right: 20%; animation-delay: 2s;\"></div>\n            <div class=\"floating-particle\" style=\"bottom: 20%; left: 25%; animation-delay: 4s;\"></div>\n            <div class=\"floating-particle\" style=\"top: 60%; right: 30%; animation-delay: 6s;\"></div>\n\n            <div class=\"container mx-auto px-4 sm:px-6 relative z-10\">\n                <div class=\"max-w-5xl mx-auto\">\n                    <div class=\"text-center mb-12\">\n                        <!-- Decorative Accent Line -->\n                        <div class=\"accent-line mb-8 reveal\"></div>\n\n                        <h2\n                            class=\"reveal text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-bold mb-6 sm:mb-8 text-gray-900 leading-tight\">\n                            <span class=\"booth-gradient\" data-text=\"VW BUS PHOTO BOOTH\">LIFE IS A HIGHWAY\n                                DENVER PHOTO BOOTH BUS</span>\n                        </h2>\n\n                        <div class=\"text-section text-left max-w-4xl mx-auto\">\n                            <p\n                                class=\"reveal text-base sm:text-lg md:text-xl mb-6 sm:mb-8 text-gray-700 leading-relaxed\">\n                                When you live in Colorful Colorado, you have to expect the unexpected. After all,\n                                there\'s a\n                                reason we have the saying, \"If you don\'t like the weather, just wait five minutes.\"\n                            </p>\n                            <p class=\"reveal text-base sm:text-lg text-gray-700 leading-relaxed\">\n                                In addition to some of the most beautiful landscapes in the world, we have some of the\n                                world\'s craziest weather. Which can make event planning just slightly…difficult. Sure,\n                                your\n                                weather app may say that it\'s going to be 90 degrees with only a 40% chance of snow, but\n                                how\n                                can you be sure?\n                            </p>\n                            <p class=\"reveal text-base sm:text-lg text-gray-700 leading-relaxed\">\n                                And do you really want to wager the success of your event on something outside of your\n                                control? Of course not. That\'s why we usually have fallback plans. Indoor locations. Or\n                                canopies with customized hand warmers at the very least.\n                            </p>\n                            <p class=\"reveal text-base sm:text-lg text-gray-700 leading-relaxed\">\n                                When you\'re planning your event, you want to leave nothing to chance.\n                            </p>\n                            <p\n                                class=\"reveal text-base sm:text-lg text-gray-700 leading-relaxed font-semibold text-indigo-900\">\n                                And that includes your photo booth.\n                            </p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Section Divider -->\n            <div class=\"section-divider mt-12\"></div>\n        </section>\n\n        <!-- VW Bus Photo Booth Section -->\n        <section class=\"section-padding bg-white relative overflow-hidden\">\n            <div class=\"container mx-auto px-4 sm:px-6\">\n                <div class=\"max-w-6xl mx-auto\">\n                    <div class=\"grid md:grid-cols-2 gap-8 lg:gap-12 items-center\">\n                        <div class=\"reveal order-2 md:order-1\">\n                            <div class=\"image-container\">\n                                <img src=\"assets/images/boothbus/a92b01_5627e716543144b093221f6166fc3945~mv2.jpg\"\n                                    alt=\"VW Bus Photo Booth\" class=\"w-full h-auto\">\n                            </div>\n                        </div>\n                        <div class=\"reveal order-1 md:order-2\">\n                            <div\n                                class=\"inline-block mb-6 sm:mb-8 px-6 sm:px-8 py-2 sm:py-3 glass rounded-full border-2 border-indigo-300/50\">\n                                <span\n                                    class=\"text-indigo-900 text-xs sm:text-sm font-bold tracking-wider flex items-center gap-2\">\n                                    <span\n                                        class=\"text-lg sm:text-xl transform transition-transform duration-300 hover:rotate-12\">🚌</span>\n                                    INTRODUCING THE LIFE OF THE PARTY\n                                </span>\n                            </div>\n                            <h2 class=\"text-3xl sm:text-4xl md:text-5xl font-bold mb-6 text-gray-900\">\n                                <span class=\"booth-gradient\" data-text=\"MEET OUR PHOTO BUS!\">MEET OUR PHOTO BUS!</span>\n                            </h2>\n                            <div class=\"text-section\">\n                                <p class=\"text-base sm:text-lg text-gray-700 leading-relaxed\">\n                                    Hi! We\'re MiHi Photo Booth. We\'ve been voted Denver\'s Best Photo Booth Service.\n                                </p>\n                                <p class=\"text-base sm:text-lg text-gray-700 leading-relaxed\">\n                                    Why? Because we love what we do.\n                                </p>\n                                <p class=\"text-base sm:text-lg text-gray-700 leading-relaxed\">\n                                    And what we do is help make sure you have the best darn party possible.\n                                    We\'re constantly heading back to the lab to shift your fun into overdrive.\n                                </p>\n                                <p class=\"text-base sm:text-lg text-gray-700 leading-relaxed\">\n                                    We have unique photo booths. We have tons of props. We have pose flash cards.\n                                </p>\n                                <p\n                                    class=\"text-base sm:text-lg text-gray-700 leading-relaxed font-semibold text-indigo-900\">\n                                    And now we have a VW Bus photo booth.\n                                </p>\n                            </div>\n                            <div class=\"mt-8\">\n                                <a href=\"contact-us.html\"\n                                    class=\"sexy-btn inline-flex items-center gap-3 text-white px-8 sm:px-10 py-4 sm:py-5 rounded-full text-base sm:text-lg font-bold shadow-2xl overflow-hidden\">\n                                    <span class=\"relative z-10\">GET PRICING NOW</span>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Meet Our Photo Bus Section -->\n        <section class=\"section-padding bg-gradient-modern relative overflow-hidden\">\n            <div class=\"pattern-overlay\"></div>\n            <div class=\"container mx-auto px-4 sm:px-6 relative z-10\">\n                <div class=\"max-w-6xl mx-auto\">\n                    <div class=\"text-center mb-12\">\n                        <div class=\"accent-line mb-8 reveal\"></div>\n                        <h2 class=\"reveal text-3xl sm:text-4xl md:text-5xl font-bold mb-6 text-gray-900\">\n                            <span class=\"booth-gradient\" data-text=\"MEET OUR PHOTO BUS!\">MEET OUR PHOTO BUS!</span>\n                        </h2>\n                    </div>\n                    <div class=\"grid md:grid-cols-2 gap-8 lg:gap-12 items-center mb-16\">\n                        <div class=\"reveal order-2 md:order-1\">\n                            <div class=\"text-section\">\n                                <p class=\"text-base sm:text-lg text-gray-700 leading-relaxed\">\n                                    We took a VW Bus, restored it, and converted the inside into a mobile photo booth.\n                                </p>\n                                <p class=\"text-base sm:text-lg text-gray-700 leading-relaxed\">\n                                    It has all the bells and whistles of a regular photo booth, except it\'s a \'73 out of\n                                    10\n                                    on the awesome scale. A little bit quirky. A little bit classy. A whole lot of fun!\n                                </p>\n                                <p class=\"text-base sm:text-lg text-gray-700 leading-relaxed\">\n                                    It\'s completely enclosed. So none of that pesky weather can get in and ruin your\n                                    fun.\n                                    And if you have to use your indoor location, we can follow you inside.\n                                </p>\n                                <p class=\"text-base sm:text-lg text-gray-700 leading-relaxed\">\n                                    Nothing grabs attention quite like having a big, beautiful blue photo booth bus set\n                                    up\n                                    inside of your building. That\'s kinda the point, right? To have the best party\n                                    possible.\n                                    To make the most memories. To have the most fun. Both inside and outside of the\n                                    booth.\n                                </p>\n                                <p\n                                    class=\"text-base sm:text-lg text-gray-700 leading-relaxed font-semibold text-indigo-900\">\n                                    With MiHi and our Photo Booth Bus, you\'ll cruising in no time!\n                                </p>\n                            </div>\n                        </div>\n                        <div class=\"reveal order-1 md:order-2\">\n                            <div class=\"image-container\">\n                                <img src=\"assets/images/boothbus/a92b01_c0b002e386714ef4acf8e0d1253f026f~mv2.jpg\"\n                                    alt=\"Photo Booth Bus\" class=\"w-full h-auto\">\n                            </div>\n                        </div>\n                    </div>\n\n                    <!-- Gallery Header -->\n                    <div class=\"text-center mb-12\">\n                        <h3 class=\"text-2xl sm:text-3xl md:text-4xl font-bold mb-4 text-gray-900\">\n                            <span class=\"booth-gradient\">Photo Gallery</span>\n                        </h3>\n                        <p class=\"text-base sm:text-lg text-gray-600 max-w-2xl mx-auto\">\n                            Take a look at our stunning VW Bus Photo Booth in action\n                        </p>\n                    </div>\n\n                    <!-- Enhanced Gallery Grid -->\n                    <div class=\"gallery-grid\">\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_39930ef25a034e0aa841ef760a45e0d6~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_39930ef25a034e0aa841ef760a45e0d6~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_44bf731d5e97401cb1cbd7639ddeaba2~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_44bf731d5e97401cb1cbd7639ddeaba2~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_5627e716543144b093221f6166fc3945~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_5627e716543144b093221f6166fc3945~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_d02b880f939d41c4944a85f85a870849~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_d02b880f939d41c4944a85f85a870849~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_8c65157196c047ef9471f3185a213131~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_8c65157196c047ef9471f3185a213131~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_9d798be92e264e168a8b8c2b15d97c14~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_9d798be92e264e168a8b8c2b15d97c14~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_9f587b92c09f4aa3803c36a9c0b1ed98~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_9f587b92c09f4aa3803c36a9c0b1ed98~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_ee681a42b60d4913bf88aec498dc108e~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_ee681a42b60d4913bf88aec498dc108e~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_beb0e7b88dba469ba84dbe4357db78da~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_beb0e7b88dba469ba84dbe4357db78da~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_c0b002e386714ef4acf8e0d1253f026f~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_c0b002e386714ef4acf8e0d1253f026f~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_d02b880f939d41c4944a85f85a870849~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_d02b880f939d41c4944a85f85a870849~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_ee681a42b60d4913bf88aec498dc108e~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_ee681a42b60d4913bf88aec498dc108e~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_fac7b68eae7e44cd985b090bf4b64026~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_fac7b68eae7e44cd985b090bf4b64026~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                        <div class=\"gallery-image rounded-xl overflow-hidden shadow-xl cursor-pointer\"\n                            onclick=\"openLightbox(\'assets/images/boothbus/a92b01_ffb2615d81f74ee1bce8d62926d6fc59~mv2.jpg\')\">\n                            <img src=\"assets/images/boothbus/a92b01_ffb2615d81f74ee1bce8d62926d6fc59~mv2.jpg\"\n                                alt=\"Photo Booth Bus Gallery\" class=\"w-full h-full object-cover\">\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Features Section -->\n        <section class=\"section-padding bg-white relative overflow-hidden\">\n            <!-- Section Divider -->\n            <div class=\"section-divider mb-16\"></div>\n\n            <div class=\"container mx-auto px-4 sm:px-6\">\n                <div class=\"max-w-6xl mx-auto\">\n                    <div class=\"text-center mb-12 sm:mb-16\">\n                        <div class=\"reveal inline-block mb-4\">\n                            <div class=\"flex items-center gap-3 text-indigo-600\">\n                                <div class=\"w-12 h-1 bg-gradient-to-r from-transparent to-indigo-500 rounded\"></div>\n                                <span\n                                    class=\"text-2xl sm:text-3xl transform transition-transform duration-300 hover:scale-110\">🚌</span>\n                                <div class=\"w-12 h-1 bg-gradient-to-l from-transparent to-indigo-500 rounded\"></div>\n                            </div>\n                        </div>\n                        <h2 class=\"reveal text-3xl sm:text-4xl md:text-5xl font-bold mb-4 sm:mb-6 text-gray-900\">\n                            <span class=\"booth-gradient\" data-text=\"VW BUS PHOTO BOOTH FEATURES\">VW BUS PHOTO BOOTH\n                                FEATURES</span>\n                        </h2>\n                        <p class=\"reveal text-base sm:text-lg text-gray-600 max-w-3xl mx-auto\">\n                            If having a VW Bus boosting the vibe at your event isn\'t enough, check out the following\n                            reasons why you should strap in with our Photo bus:\n                        </p>\n                    </div>\n\n                    <div class=\"grid md:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-8\">\n                        <!-- Feature 1 -->\n                        <div\n                            class=\"reveal booth-card bg-gradient-to-br from-indigo-50 to-purple-50 p-6 sm:p-8 rounded-2xl border border-indigo-200/50 hover:border-indigo-300/80\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">🎭</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-indigo-900 text-center\">\n                                Fun props\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                What\'s a photo booth without props? Dull. That\'s what it is.\n                            </p>\n                        </div>\n\n                        <!-- Feature 2 -->\n                        <div class=\"reveal booth-card bg-gradient-to-br from-purple-50 to-violet-50 p-6 sm:p-8 rounded-2xl border border-purple-200/50 hover:border-purple-300/80\"\n                            style=\"transition-delay: 0.1s;\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">♾️</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-purple-900 text-center\">\n                                Unlimited Sessions\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                Don\'t stress about the perfect shot! Just get posing!\n                            </p>\n                        </div>\n\n                        <!-- Feature 3 -->\n                        <div class=\"reveal booth-card bg-gradient-to-br from-violet-50 to-indigo-50 p-6 sm:p-8 rounded-2xl border border-violet-200/50 hover:border-violet-300/80\"\n                            style=\"transition-delay: 0.2s;\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">🖼️</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-violet-900 text-center\">\n                                Two Prints Per Session\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                The basic package comes with two prints to share the fun!\n                            </p>\n                        </div>\n\n                        <!-- Feature 4 -->\n                        <div class=\"reveal booth-card bg-gradient-to-br from-indigo-50 to-purple-50 p-6 sm:p-8 rounded-2xl border border-indigo-200/50 hover:border-indigo-300/80\"\n                            style=\"transition-delay: 0.3s;\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">✨</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-indigo-900 text-center\">\n                                Customized Photo Strips\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                No matter your event, we can create an amazing border!\n                            </p>\n                        </div>\n\n                        <!-- Feature 5 -->\n                        <div class=\"reveal booth-card bg-gradient-to-br from-purple-50 to-violet-50 p-6 sm:p-8 rounded-2xl border border-purple-200/50 hover:border-purple-300/80\"\n                            style=\"transition-delay: 0.4s;\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">🌐</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-purple-900 text-center\">\n                                Online Gallery\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                After your event, head to our website to download your photos.\n                            </p>\n                        </div>\n\n                        <!-- Feature 6 -->\n                        <div class=\"reveal booth-card bg-gradient-to-br from-violet-50 to-indigo-50 p-6 sm:p-8 rounded-2xl border border-violet-200/50 hover:border-violet-300/80\"\n                            style=\"transition-delay: 0.5s;\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">⏰</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-violet-900 text-center\">\n                                Additional Time\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                Your party is a smash! Let us know if you rent more time.\n                            </p>\n                        </div>\n\n                        <!-- Feature 7 -->\n                        <div class=\"reveal booth-card bg-gradient-to-br from-indigo-50 to-purple-50 p-6 sm:p-8 rounded-2xl border border-indigo-200/50 hover:border-indigo-300/80\"\n                            style=\"transition-delay: 0.6s;\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">⏸️</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-indigo-900 text-center\">\n                                Idle Time\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                Special idle rates for those times you need to shut down the booth. Like speeches. Or a\n                                demolition derby. Just leave our photo bus out of it!\n                            </p>\n                        </div>\n\n                        <!-- Feature 8 -->\n                        <div class=\"reveal booth-card bg-gradient-to-br from-purple-50 to-violet-50 p-6 sm:p-8 rounded-2xl border border-purple-200/50 hover:border-purple-300/80\"\n                            style=\"transition-delay: 0.7s;\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">📱</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-purple-900 text-center\">\n                                Digital Sharing\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                Share your photos directly to your phone or social media!\n                            </p>\n                        </div>\n\n                        <!-- Feature 9 -->\n                        <div class=\"reveal booth-card bg-gradient-to-br from-violet-50 to-indigo-50 p-6 sm:p-8 rounded-2xl border border-violet-200/50 hover:border-violet-300/80\"\n                            style=\"transition-delay: 0.8s;\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">📸</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-violet-900 text-center\">\n                                Social Media Kiosk\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                For those extra-large parties! Photos get sent to the kiosk where you can share them\n                                directly on social media. Ask about branding opportunities for corporate events!\n                            </p>\n                        </div>\n\n                        <!-- Feature 10 -->\n                        <div class=\"reveal booth-card bg-gradient-to-br from-indigo-50 to-purple-50 p-6 sm:p-8 rounded-2xl border border-indigo-200/50 hover:border-indigo-300/80\"\n                            style=\"transition-delay: 0.9s;\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">🖨️</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-indigo-900 text-center\">\n                                Unlimited Prints\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                For those times when you need more than 2 prints. Make sure everyone in the shot gets a\n                                keepsake.\n                            </p>\n                        </div>\n\n                        <!-- Feature 11 -->\n                        <div class=\"reveal booth-card bg-gradient-to-br from-purple-50 to-violet-50 p-6 sm:p-8 rounded-2xl border border-purple-200/50 hover:border-purple-300/80\"\n                            style=\"transition-delay: 1s;\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">🎨</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-purple-900 text-center\">\n                                Additional Photo Filters\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                When your photos need a little bit more pizazz. 16 filters in all. Ranging from black\n                                and white to sepia, to comic books, and more!\n                            </p>\n                        </div>\n\n                        <!-- Feature 12 -->\n                        <div class=\"reveal booth-card bg-gradient-to-br from-violet-50 to-indigo-50 p-6 sm:p-8 rounded-2xl border border-violet-200/50 hover:border-violet-300/80\"\n                            style=\"transition-delay: 1.1s;\">\n                            <div class=\"feature-icon text-4xl sm:text-5xl mb-4 text-center\">📖</div>\n                            <h3 class=\"text-xl sm:text-2xl font-bold mb-3 sm:mb-4 text-violet-900 text-center\">\n                                Memory Book\n                            </h3>\n                            <p class=\"text-gray-700 text-center leading-relaxed\">\n                                We\'ll print an extra photo that will be placed in a beautiful memory book that your\n                                guests can sign. This isn\'t some dollar-store scrapbook. This is a high-quality, padded\n                                memory book with slots for the photos and a designated space for your guests to write.\n                                This is the kind of book you\'d find on an episode of Pawn Stars.\n                            </p>\n                        </div>\n                    </div>\n\n                    <div class=\"text-center mt-16\">\n                        <div class=\"accent-line mb-8\"></div>\n                        <a href=\"contact-us.html\"\n                            class=\"sexy-btn inline-flex items-center gap-3 text-white px-8 sm:px-10 py-4 sm:py-5 rounded-full text-base sm:text-lg font-bold shadow-2xl overflow-hidden\">\n                            <span class=\"relative z-10\">GET MORE INFORMATION NOW</span>\n                        </a>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Section Divider -->\n            <div class=\"section-divider mt-16\"></div>\n        </section>\n    </main>\n\n    <!-- Footer -->\n    <script src=\"assets/components/footer.js\"></script>\n\n    <!-- Lightbox -->\n    <div id=\"lightbox\" class=\"lightbox\" onclick=\"closeLightbox(event)\">\n        <div class=\"lightbox-img-container\" onclick=\"event.stopPropagation()\">\n            <span class=\"lightbox-close\" onclick=\"closeLightbox(event)\">&times;</span>\n            <img id=\"lightbox-img\" src=\"\" alt=\"Lightbox Image\" onclick=\"toggleZoom()\">\n        </div>\n    </div>\n\n    <script>\n        // Scroll reveal animation with improved performance\n        const reveals = document.querySelectorAll(\'.reveal\');\n        const revealObserver = new IntersectionObserver((entries) => {\n            entries.forEach(entry => {\n                if (entry.isIntersecting) {\n                    entry.target.classList.add(\'active\');\n                    // Optionally stop observing after animation triggers\n                    // revealObserver.unobserve(entry.target);\n                }\n            });\n        }, {\n            threshold: 0.1,\n            rootMargin: \'0px 0px -50px 0px\'\n        });\n\n        reveals.forEach(reveal => {\n            revealObserver.observe(reveal);\n        });\n\n        // Lightbox functionality\n        function openLightbox(imageSrc) {\n            const lightbox = document.getElementById(\'lightbox\');\n            const lightboxImg = document.getElementById(\'lightbox-img\');\n            lightboxImg.src = imageSrc;\n            lightbox.classList.add(\'active\');\n            document.body.style.overflow = \'hidden\';\n        }\n\n        function closeLightbox(event) {\n            if (event.target.id === \'lightbox\' || event.target.classList.contains(\'lightbox-close\')) {\n                const lightbox = document.getElementById(\'lightbox\');\n                const lightboxImg = document.getElementById(\'lightbox-img\');\n                lightbox.classList.remove(\'active\');\n                lightboxImg.classList.remove(\'zoomed\');\n                document.body.style.overflow = \'\';\n            }\n        }\n\n        function toggleZoom() {\n            const lightboxImg = document.getElementById(\'lightbox-img\');\n            lightboxImg.classList.toggle(\'zoomed\');\n        }\n\n        // Close lightbox on ESC key\n        document.addEventListener(\'keydown\', (e) => {\n            if (e.key === \'Escape\') {\n                const lightbox = document.getElementById(\'lightbox\');\n                const lightboxImg = document.getElementById(\'lightbox-img\');\n                if (lightbox.classList.contains(\'active\')) {\n                    lightbox.classList.remove(\'active\');\n                    lightboxImg.classList.remove(\'zoomed\');\n                    document.body.style.overflow = \'\';\n                }\n            }\n        });\n\n        // Smooth scroll for anchor links\n        document.querySelectorAll(\'a[href^=\"#\"]\').forEach(anchor => {\n            anchor.addEventListener(\'click\', function (e) {\n                const href = this.getAttribute(\'href\');\n                if (href !== \'#\' && href.startsWith(\'#\')) {\n                    e.preventDefault();\n                    const target = document.querySelector(href);\n                    if (target) {\n                        target.scrollIntoView({\n                            behavior: \'smooth\',\n                            block: \'start\'\n                        });\n                    }\n                }\n            });\n        });\n\n        // Add loading animation for images\n        const images = document.querySelectorAll(\'img\');\n        images.forEach(img => {\n            if (!img.complete) {\n                img.style.opacity = \'0\';\n                img.style.transition = \'opacity 0.5s ease\';\n                img.onload = () => {\n                    img.style.opacity = \'1\';\n                };\n            }\n        });\n    </script>\n    <!-- Load Back to Top Component -->\n    <script src=\"assets/components/back-to-top.js\"></script>\n\n</body>', NULL, 'published', NULL, '2025-12-14 00:30:10', '2025-12-14 00:30:10');
INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(129, 'Photo Booth Sets', 'photo-booth-sets', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <meta name=\"description\"\n        content=\"Custom Themed Photo Booth Sets by MiHi Entertainment. When a backdrop isn\'t enough - fully branded, immersive photo set designs made just for you. Perfect for corporate events, weddings, trade shows, and themed parties nationwide.\">\n    <meta name=\"keywords\"\n        content=\"custom photo booth sets, themed photo booth sets, custom photo set design, branded photo booth sets, immersive photo sets, themed event photo sets, custom backdrop sets, photo booth set rental, custom event sets, branded photo sets\">\n    <meta name=\"author\" content=\"MiHi Entertainment\">\n    <meta name=\"robots\" content=\"index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1\">\n    <meta name=\"googlebot\" content=\"index, follow\">\n    <meta name=\"language\" content=\"English\">\n    <meta name=\"distribution\" content=\"global\">\n    <link rel=\"canonical\" href=\"https://www.mihientertainment.com/photo-booth-sets.html\">\n\n    <!-- DNS Prefetch and Preconnect for Performance -->\n    <link rel=\"dns-prefetch\" href=\"https://cdn.tailwindcss.com\">\n    <link rel=\"dns-prefetch\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"dns-prefetch\" href=\"https://fonts.gstatic.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" crossorigin>\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n\n    <!-- Open Graph / Facebook -->\n    <meta property=\"og:type\" content=\"website\">\n    <meta property=\"og:url\" content=\"https://www.mihientertainment.com/photo-booth-sets.html\">\n    <meta property=\"og:title\"\n        content=\"Custom Themed Photo Booth Sets - Fully Branded Immersive Designs | MiHi Entertainment\">\n    <meta property=\"og:description\"\n        content=\"Fully branded, immersive photo set designs made just for you. Transform your event with custom-built sets that bring your theme to life! Perfect for corporate events, weddings, and trade shows.\">\n    <meta property=\"og:image\"\n        content=\"https://www.mihientertainment.com/assets/images/custom-sets/custom-sets-hero.webp\">\n    <meta property=\"og:image:width\" content=\"1200\">\n    <meta property=\"og:image:height\" content=\"630\">\n    <meta property=\"og:site_name\" content=\"MiHi Entertainment\">\n    <meta property=\"og:locale\" content=\"en_US\">\n\n    <!-- Twitter -->\n    <meta name=\"twitter:card\" content=\"summary_large_image\">\n    <meta name=\"twitter:url\" content=\"https://www.mihientertainment.com/photo-booth-sets.html\">\n    <meta name=\"twitter:title\" content=\"Custom Themed Photo Booth Sets - Fully Branded Immersive Designs\">\n    <meta name=\"twitter:description\"\n        content=\"Fully branded, immersive photo set designs made just for you. Transform your event with custom-built sets that bring your theme to life!\">\n    <meta name=\"twitter:image\"\n        content=\"https://www.mihientertainment.com/assets/images/custom-sets/custom-sets-hero.webp\">\n\n    <title>Custom Themed Photo Booth Sets - Fully Branded Immersive Designs | MiHi Entertainment</title>\n    <link rel=\"icon\" type=\"image/svg+xml\" href=\"../../assets/images/favicon.svg\">\n\n    <!-- Schema.org Structured Data -->\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"Organization\",\n      \"name\": \"MiHi Entertainment\",\n      \"url\": \"https://www.mihientertainment.com\",\n      \"logo\": \"https://www.mihientertainment.com/assets/images/logo.png\",\n      \"description\": \"Premium photo booth rentals and event entertainment services nationwide. Specializing in custom themed photo booth sets, branded photo sets, immersive event experiences, AI photo booths, green screen technology, and 360° video booths.\",\n      \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"addressCountry\": \"US\"\n      },\n      \"contactPoint\": {\n        \"@type\": \"ContactPoint\",\n        \"contactType\": \"Customer Service\",\n        \"areaServed\": \"US\"\n      },\n      \"sameAs\": [\n        \"https://www.facebook.com/mihientertainment\",\n        \"https://www.instagram.com/mihientertainment\"\n      ]\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"LocalBusiness\",\n      \"@id\": \"https://www.mihientertainment.com\",\n      \"name\": \"MiHi Entertainment\",\n      \"image\": \"https://www.mihientertainment.com/assets/images/logo.png\",\n      \"description\": \"Premium custom themed photo booth sets and branded photo set design services. Fully branded, immersive photo set designs made just for you. Perfect for corporate events, weddings, trade shows, and themed parties nationwide.\",\n      \"url\": \"https://www.mihientertainment.com\",\n      \"telephone\": \"+1-XXX-XXX-XXXX\",\n      \"priceRange\": \"$$\",\n      \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"addressCountry\": \"US\"\n      },\n      \"geo\": {\n        \"@type\": \"GeoCoordinates\",\n        \"latitude\": \"39.7392\",\n        \"longitude\": \"-104.9903\"\n      },\n      \"areaServed\": {\n        \"@type\": \"Country\",\n        \"name\": \"United States\"\n      },\n      \"aggregateRating\": {\n        \"@type\": \"AggregateRating\",\n        \"ratingValue\": \"4.9\",\n        \"reviewCount\": \"150\"\n      }\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"Product\",\n      \"name\": \"Custom Themed Photo Booth Sets\",\n      \"image\": [\n        \"https://www.mihientertainment.com/assets/images/custom-sets/custom-sets-hero.webp\",\n        \"https://www.mihientertainment.com/assets/images/custom-sets/snow-globe-set.webp\",\n        \"https://www.mihientertainment.com/assets/images/custom-sets/ski-lift-set.webp\"\n      ],\n      \"description\": \"Custom themed photo booth sets with fully branded, immersive designs made just for you. Transform your event with custom-built sets that bring your theme to life. Perfect for corporate events, weddings, trade shows, and themed parties.\",\n      \"brand\": {\n        \"@type\": \"Brand\",\n        \"name\": \"MiHi Entertainment\"\n      },\n      \"category\": \"Event Entertainment\",\n      \"keywords\": \"custom photo booth sets, themed photo booth sets, custom photo set design, branded photo booth sets, immersive photo sets\",\n      \"offers\": {\n        \"@type\": \"AggregateOffer\",\n        \"url\": \"https://www.mihientertainment.com/photo-booth-sets.html\",\n        \"priceCurrency\": \"USD\",\n        \"availability\": \"https://schema.org/InStock\",\n        \"priceSpecification\": {\n          \"@type\": \"UnitPriceSpecification\",\n          \"price\": \"Contact for pricing\"\n        },\n        \"offerCount\": \"Multiple\"\n      },\n      \"aggregateRating\": {\n        \"@type\": \"AggregateRating\",\n        \"ratingValue\": \"5\",\n        \"reviewCount\": \"20\",\n        \"bestRating\": \"5\",\n        \"worstRating\": \"1\"\n      },\n      \"additionalProperty\": [\n        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Design Process\",\n          \"value\": \"Share vision, design & approval, build & prepare, deliver & setup\"\n        },\n        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Customization Level\",\n          \"value\": \"Fully custom designs from scratch\"\n        },\n        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Build Quality\",\n          \"value\": \"Professional build with high-quality materials\"\n        },\n        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Service Level\",\n          \"value\": \"Full service setup including delivery and teardown\"\n        },\n        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Event Types\",\n          \"value\": \"Corporate events, weddings, trade shows, parties, themed events\"\n        }\n      ]\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"Service\",\n      \"serviceType\": \"Custom Themed Photo Booth Set Design and Rental\",\n      \"provider\": {\n        \"@type\": \"LocalBusiness\",\n        \"name\": \"MiHi Entertainment\",\n        \"url\": \"https://www.mihientertainment.com\"\n      },\n      \"areaServed\": {\n        \"@type\": \"Country\",\n        \"name\": \"United States\"\n      },\n      \"description\": \"Custom themed photo booth set design and rental service. Fully branded, immersive photo set designs made just for you. From concept to completion, we create one-of-a-kind photo booth sets that bring your theme to life.\",\n      \"serviceOutput\": \"Custom-built themed photo booth sets with full service setup, delivery, and teardown\",\n      \"offers\": {\n        \"@type\": \"Offer\",\n        \"priceCurrency\": \"USD\",\n        \"availability\": \"https://schema.org/InStock\"\n      },\n      \"aggregateRating\": {\n        \"@type\": \"AggregateRating\",\n        \"ratingValue\": \"5\",\n        \"reviewCount\": \"20\"\n      },\n      \"hasOfferCatalog\": {\n        \"@type\": \"OfferCatalog\",\n        \"name\": \"Custom Photo Booth Set Services\",\n        \"itemListElement\": [\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Custom Set Design\",\n              \"description\": \"Share your vision and we create mockups and refine until perfect\"\n            }\n          },\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Professional Build\",\n              \"description\": \"High-quality materials and expert construction for stunning results\"\n            }\n          },\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Full Service Setup\",\n              \"description\": \"We handle delivery, setup, and teardown so you can focus on your event\"\n            }\n          }\n        ]\n      }\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"WebSite\",\n      \"name\": \"MiHi Entertainment\",\n      \"url\": \"https://www.mihientertainment.com\",\n      \"potentialAction\": {\n        \"@type\": \"SearchAction\",\n        \"target\": {\n          \"@type\": \"EntryPoint\",\n          \"urlTemplate\": \"https://www.mihientertainment.com/search?q={search_term_string}\"\n        },\n        \"query-input\": \"required name=search_term_string\"\n      }\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"BreadcrumbList\",\n      \"itemListElement\": [\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 1,\n          \"name\": \"Home\",\n          \"item\": \"https://www.mihientertainment.com/\"\n        },\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 2,\n          \"name\": \"Photo Booth Sets\",\n          \"item\": \"https://www.mihientertainment.com/photo-booth-sets.html\"\n        }\n      ]\n    }\n    </script>\n\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link\n        href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=Playfair+Display:wght@400;500;600;700;800;900&display=swap\"\n        rel=\"stylesheet\">\n\n    <style>\n        @font-face {\n            font-family: \'AzoSans\';\n            src: url(\'assets/fonts/AzoSans-Regular.woff2\') format(\'woff2\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        @font-face {\n            font-family: \'AzoSansUber\';\n            src: url(\'assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\');\n            font-weight: normal;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        body {\n            font-family: \'Inter\', sans-serif;\n            color: #1a202c;\n        }\n\n        main h1,\n        main h2,\n        main h3,\n        main h4,\n        main h5,\n        main h6 {\n            font-family: \'Playfair Display\', serif;\n        }\n\n        .btn-primary {\n            background: linear-gradient(135deg, #0050ff 0%, #0040d9 100%);\n            transition: all 0.3s ease;\n        }\n\n        .btn-primary:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(0, 80, 255, 0.4);\n        }\n\n        .section-padding {\n            padding: 5rem 0;\n        }\n\n        @media (min-width: 768px) {\n            .section-padding {\n                padding: 8rem 0;\n            }\n        }\n\n        /* Rainbow Gradient Animation for Custom Theme */\n        @keyframes rainbow-shift {\n\n            0%,\n            100% {\n                background-position: 0% 50%;\n            }\n\n            50% {\n                background-position: 100% 50%;\n            }\n        }\n\n        .animated-rainbow-gradient {\n            background: linear-gradient(-45deg,\n                    #FF6B6B, #4ECDC4, #45B7D1, #FFA07A,\n                    #98D8C8, #F7DC6F, #BB8FCE, #FF6B6B);\n            background-size: 400% 400%;\n            animation: rainbow-shift 15s ease infinite;\n        }\n\n        /* Creative Paint Splash Effect */\n        @keyframes paint-splash {\n\n            0%,\n            100% {\n                transform: scale(1) rotate(0deg);\n                opacity: 0.6;\n            }\n\n            50% {\n                transform: scale(1.2) rotate(180deg);\n                opacity: 0.8;\n            }\n        }\n\n        .paint-splash {\n            animation: paint-splash 8s ease-in-out infinite;\n        }\n\n        /* Colorful Glow */\n        .colorful-glow {\n            box-shadow:\n                0 0 20px rgba(255, 107, 107, 0.4),\n                0 0 40px rgba(78, 205, 196, 0.3),\n                0 0 60px rgba(69, 183, 209, 0.2);\n        }\n\n        /* Theme Card Hover */\n        .theme-card {\n            transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n            position: relative;\n            overflow: hidden;\n        }\n\n        .theme-card::before {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: linear-gradient(45deg,\n                    rgba(255, 107, 107, 0.2),\n                    rgba(78, 205, 196, 0.2),\n                    rgba(69, 183, 209, 0.2));\n            opacity: 0;\n            transition: opacity 0.3s ease;\n        }\n\n        .theme-card:hover::before {\n            opacity: 0;\n        }\n\n        .theme-card:hover {\n            transform: translateY(-15px) scale(1.03);\n            box-shadow: 0 30px 60px rgba(0, 0, 0, 0.3);\n        }\n\n        /* Floating Animation */\n        @keyframes float-creative {\n\n            0%,\n            100% {\n                transform: translateY(0px) rotate(0deg);\n            }\n\n            33% {\n                transform: translateY(-20px) rotate(5deg);\n            }\n\n            66% {\n                transform: translateY(-10px) rotate(-5deg);\n            }\n        }\n\n        .float-creative {\n            animation: float-creative 6s ease-in-out infinite;\n        }\n\n        /* Brush Stroke Effect */\n        .brush-stroke {\n            position: relative;\n        }\n\n        .brush-stroke::after {\n            content: \'\';\n            position: absolute;\n            bottom: -10px;\n            left: 0;\n            right: 0;\n            height: 8px;\n            background: linear-gradient(90deg,\n                    #18F1E1 0%,\n                    #18F1E1 25%,\n                    #18F1E1 50%,\n                    #18F1E1 75%,\n                    #18F1E1 100%);\n            border-radius: 4px;\n            opacity: 0.7;\n        }\n\n        .brush-stroke-cyan::after {\n            background: #18F1E1;\n        }\n\n        .btn-start-designing {\n            background-color: #FF4F4F !important;\n        }\n\n        .btn-start-designing::before {\n            display: none !important;\n        }\n\n        .btn-start-designing:hover {\n            background-color: #18F1E1 !important;\n            color: #1F1F1F !important;\n            transform: none !important;\n            box-shadow: none !important;\n        }\n\n        .btn-start-designing:hover::before {\n            display: none !important;\n        }\n\n        /* Gradient Text with Multiple Colors */\n        .rainbow-text {\n            background: linear-gradient(90deg,\n                    #FF6B6B 0%,\n                    #4ECDC4 20%,\n                    #45B7D1 40%,\n                    #FFA07A 60%,\n                    #98D8C8 80%,\n                    #F7DC6F 100%);\n            background-size: 200% 200%;\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n            animation: rainbow-shift 5s ease infinite;\n        }\n\n        /* Creative Button */\n        .btn-creative {\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 50%, #FF4F4F 100%);\n            transition: all 0.3s ease;\n            position: relative;\n            overflow: hidden;\n        }\n\n        .btn-creative::before {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: linear-gradient(135deg, #FF4F4F 0%, #FF4F4F 50%, #FF4F4F 100%);\n            opacity: 0;\n            transition: opacity 0.3s ease;\n        }\n\n        .btn-creative:hover::before {\n            opacity: 1;\n        }\n\n        .btn-creative:hover {\n            transform: translateY(-3px);\n            box-shadow: 0 15px 35px rgba(255, 107, 107, 0.4);\n        }\n\n        /* Sparkle Effect */\n        @keyframes sparkle {\n\n            0%,\n            100% {\n                opacity: 0;\n                transform: scale(0);\n            }\n\n            50% {\n                opacity: 1;\n                transform: scale(1);\n            }\n        }\n\n        .sparkle {\n            animation: sparkle 2s ease-in-out infinite;\n        }\n\n        /* Set Badge */\n        .set-badge {\n            background: linear-gradient(135deg, #18F1E1 0%, #18F1E1 100%);\n            backdrop-filter: blur(10px);\n            border: 2px solid rgba(255, 255, 255, 0.3);\n        }\n\n        /* Image Overlay on Hover */\n        .theme-card-image {\n            position: relative;\n            overflow: hidden;\n        }\n\n        .theme-card-image::after {\n            content: \'VIEW DETAILS\';\n            position: absolute;\n            inset: 0;\n            background: transparent;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            color: white;\n            font-weight: bold;\n            font-size: 1.25rem;\n            opacity: 0;\n            transition: opacity 0.3s ease;\n        }\n\n        .theme-card:hover .theme-card-image::after {\n            opacity: 0;\n        }\n\n        /* Confetti Dots */\n        .confetti-dot {\n            width: 8px;\n            height: 8px;\n            border-radius: 50%;\n            position: absolute;\n            animation: float-creative 4s ease-in-out infinite;\n        }\n\n        /* Paint Brush Strokes */\n        @keyframes paint-draw {\n            0% {\n                stroke-dashoffset: 1000;\n            }\n\n            100% {\n                stroke-dashoffset: 0;\n            }\n        }\n\n        .paint-stroke {\n            stroke-dasharray: 1000;\n            stroke-dashoffset: 1000;\n            animation: paint-draw 3s ease forwards;\n        }\n\n        /* Artist Palette Effect */\n        .palette-spot {\n            width: 60px;\n            height: 60px;\n            border-radius: 50%;\n            position: absolute;\n            filter: blur(20px);\n            animation: pulse-color 4s ease-in-out infinite;\n        }\n\n        @keyframes pulse-color {\n\n            0%,\n            100% {\n                transform: scale(1);\n                opacity: 0.6;\n            }\n\n            50% {\n                transform: scale(1.3);\n                opacity: 0.9;\n            }\n        }\n\n        /* Sketch Lines */\n        .sketch-line {\n            position: absolute;\n            height: 2px;\n            background: rgba(255, 255, 255, 0.2);\n            transform-origin: left;\n        }\n\n        @keyframes draw-line {\n            from {\n                transform: scaleX(0);\n            }\n\n            to {\n                transform: scaleX(1);\n            }\n        }\n\n        .sketch-line {\n            animation: draw-line 2s ease-out forwards;\n        }\n\n        /* 3D Card Tilt Effect */\n        .card-3d {\n            transform-style: preserve-3d;\n            perspective: 1000px;\n        }\n\n        .card-3d:hover {\n            transform: rotateY(5deg) rotateX(5deg);\n        }\n\n        /* Watercolor Background */\n        .watercolor-bg {\n            background:\n                radial-gradient(circle at 20% 50%, rgba(255, 107, 107, 0.3) 0%, transparent 50%),\n                radial-gradient(circle at 80% 80%, rgba(78, 205, 196, 0.3) 0%, transparent 50%),\n                radial-gradient(circle at 40% 20%, rgba(247, 220, 111, 0.3) 0%, transparent 50%),\n                radial-gradient(circle at 70% 40%, rgba(187, 143, 206, 0.3) 0%, transparent 50%);\n        }\n\n        /* Creative Border Animation */\n        @keyframes border-dance {\n\n            0%,\n            100% {\n                border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%;\n            }\n\n            50% {\n                border-radius: 30% 60% 70% 40% / 50% 60% 30% 60%;\n            }\n        }\n\n        .dancing-border {\n            animation: border-dance 8s ease-in-out infinite;\n        }\n\n        /* Dot Bounce Animation */\n        @keyframes dot-bounce {\n\n            0%,\n            100% {\n                transform: translateY(0) scale(1);\n                opacity: 1;\n            }\n\n            50% {\n                transform: translateY(-10px) scale(1.2);\n                opacity: 0.8;\n            }\n        }\n\n        .dot-animated {\n            animation: dot-bounce 1.5s ease-in-out forwards;\n        }\n\n        /* Typewriter Effect */\n        @keyframes typewriter {\n            from {\n                width: 0;\n            }\n\n            to {\n                width: 100%;\n            }\n        }\n\n        .typewriter {\n            overflow: hidden;\n            white-space: nowrap;\n            animation: typewriter 3s steps(40) 1s forwards;\n        }\n\n        /* Paint Splatter */\n        .paint-splatter {\n            position: absolute;\n            width: 100px;\n            height: 100px;\n            background: radial-gradient(circle, rgba(255, 107, 107, 0.4) 0%, transparent 70%);\n            border-radius: 50%;\n            filter: blur(10px);\n        }\n\n        .paint-splatter::before,\n        .paint-splatter::after {\n            content: \'\';\n            position: absolute;\n            width: 40px;\n            height: 40px;\n            background: inherit;\n            border-radius: 50%;\n        }\n\n        .paint-splatter::before {\n            top: -20px;\n            left: 30px;\n        }\n\n        .paint-splatter::after {\n            bottom: -10px;\n            right: 20px;\n        }\n\n        /* Design Tool Icons Floating */\n        @keyframes tool-float {\n\n            0%,\n            100% {\n                transform: translateY(0) rotate(0deg);\n            }\n\n            25% {\n                transform: translateY(-10px) rotate(5deg);\n            }\n\n            75% {\n                transform: translateY(-5px) rotate(-5deg);\n            }\n        }\n\n        .tool-float {\n            animation: tool-float 5s ease-in-out infinite;\n        }\n\n        /* Gradient Border */\n        .gradient-border {\n            position: relative;\n            background: white;\n            border-radius: 24px;\n        }\n\n        .gradient-border::before {\n            content: \'\';\n            position: absolute;\n            inset: -4px;\n            background: linear-gradient(45deg, #18F1E1, #18F1E1, #18F1E1, #18F1E1, #18F1E1);\n            background-size: 300% 300%;\n            border-radius: 26px;\n            z-index: -1;\n            animation: rainbow-shift 3s ease infinite;\n        }\n\n        /* Creative Section Divider */\n        .section-divider {\n            height: 6px;\n            background: linear-gradient(90deg,\n                    #FF6B6B 0%,\n                    #4ECDC4 25%,\n                    #45B7D1 50%,\n                    #FFA07A 75%,\n                    #F7DC6F 100%);\n            background-size: 200% 200%;\n            animation: rainbow-shift 5s ease infinite;\n        }\n    </style>\n</head>\n\n<body class=\"bg-white\">\n    <!-- Navigation -->\n    <script src=\"../../assets/components/navigation.js\"></script>\n\n    <main>\n        <!-- Hero Section -->\n        <section class=\"relative text-white overflow-hidden h-screen flex items-center\">\n            <!-- Background Image -->\n            <div class=\"absolute inset-0 z-0\">\n                <img src=\"../../assets/images/custom-sets/custom-sets-hero.webp\"\n                    alt=\"Custom themed photo booth sets with fully branded immersive designs\" width=\"1920\" height=\"1080\"\n                    class=\"w-full h-full object-cover\" loading=\"eager\" fetchpriority=\"high\">\n                <!-- Light Gradient Overlay for text visibility -->\n                <div class=\"absolute inset-0 bg-gradient-to-br from-purple-900/40 via-pink-900/30 to-blue-900/40\"></div>\n                <!-- Animated Rainbow Overlay -->\n                <div class=\"absolute inset-0 animated-rainbow-gradient opacity-25\"></div>\n            </div>\n\n            <!-- Artist Palette Color Spots -->\n            <div class=\"palette-spot bg-red-400\" style=\"top: 15%; left: 10%; animation-delay: 0s;\"></div>\n            <div class=\"palette-spot bg-yellow-300\" style=\"top: 25%; left: 85%; animation-delay: 1s;\"></div>\n            <div class=\"palette-spot bg-blue-400\" style=\"top: 60%; left: 12%; animation-delay: 2s;\"></div>\n            <div class=\"palette-spot bg-green-400\" style=\"top: 75%; left: 88%; animation-delay: 3s;\"></div>\n            <div class=\"palette-spot bg-purple-400\" style=\"top: 40%; left: 50%; animation-delay: 4s;\"></div>\n            <div class=\"palette-spot bg-pink-400\" style=\"top: 85%; left: 65%; animation-delay: 5s;\"></div>\n\n            <!-- Paint Splatters -->\n            <div class=\"paint-splatter\" style=\"top: 20%; right: 15%; animation-delay: 1s;\"></div>\n            <div class=\"paint-splatter\"\n                style=\"bottom: 25%; left: 20%; animation-delay: 3s; background: radial-gradient(circle, rgba(78, 205, 196, 0.4) 0%, transparent 70%);\">\n            </div>\n            <div class=\"paint-splatter\"\n                style=\"top: 50%; right: 30%; animation-delay: 2s; background: radial-gradient(circle, rgba(247, 220, 111, 0.4) 0%, transparent 70%);\">\n            </div>\n\n            <!-- Sketch Lines -->\n            <div class=\"sketch-line\" style=\"top: 30%; left: 0; width: 200px; animation-delay: 0.5s;\"></div>\n            <div class=\"sketch-line\" style=\"top: 60%; right: 0; width: 250px; animation-delay: 1.5s;\"></div>\n            <div class=\"sketch-line\" style=\"bottom: 40%; left: 20%; width: 180px; animation-delay: 2.5s;\"></div>\n\n            <div class=\"container mx-auto px-4 sm:px-6 pt-20 relative z-10 w-full\">\n                <div class=\"max-w-7xl mx-auto text-center\">\n                    <!-- Badge -->\n                    <span\n                        class=\"inline-block text-white text-xs sm:text-sm font-bold tracking-wider uppercase rounded-full px-3 sm:px-4 py-1 sm:py-1.5 mb-6 sm:mb-8\"\n                        style=\"background-color: #FF4F4F; font-family: \'AzoSans\', sans-serif;\">When A Backdrop\n                        Isn\'t Enough</span>\n\n                    <!-- Main Title -->\n                    <h1 class=\"text-5xl sm:text-6xl md:text-7xl lg:text-8xl font-black mb-6 leading-tight\"\n                        style=\"font-family: \'AzoSansUber\', sans-serif;\">\n                        <span class=\"block drop-shadow-2xl\"\n                            style=\"font-weight: 300; text-shadow: 0 0 40px rgba(0, 0, 0, 0.5);\">\n                            <span style=\"color: #FF4F4F;\">Custom-Themed</span> <span style=\"color: #18F1E1;\">Photo Booth\n                                Sets</span>\n                        </span>\n                    </h1>\n\n                    <!-- Description -->\n                    <div class=\"max-w-3xl mx-auto mb-8\">\n                        <p class=\"text-lg sm:text-xl md:text-2xl leading-relaxed text-white font-light drop-shadow-lg\"\n                            style=\"font-family: \'AzoSans\', sans-serif;\">\n                            Fully branded, immersive photo set designs made just for you. Transform your event with\n                            custom-built sets that bring your theme to life!\n                        </p>\n                    </div>\n\n                    <!-- CTA Buttons -->\n                    <div class=\"flex flex-col sm:flex-row gap-4 sm:gap-6 justify-center items-center px-4\">\n                        <a href=\"contact-us.html\"\n                            class=\"group relative inline-flex items-center gap-2 sm:gap-3 text-white px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg font-bold shadow-2xl transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 w-full sm:w-auto justify-center\"\n                            style=\"background-color: #FF4F4F;\">\n                            <span class=\"relative z-10\">Get Your Quote</span>\n                            <svg class=\"w-4 h-4 sm:w-5 sm:h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                    d=\"M13 7l5 5m0 0l-5 5m5-5H6\"></path>\n                            </svg>\n                        </a>\n                        <button type=\"button\" data-click-to-call data-call-text=\"Call Us\"\n                            class=\"group inline-flex items-center gap-2 sm:gap-3 px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg font-bold border-2 border-white text-white bg-white/10 hover:bg-white hover:text-[#1F1F1F] transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 backdrop-blur-sm cursor-pointer w-full sm:w-auto justify-center\">\n                            <svg class=\"w-4 h-4 sm:w-5 sm:h-5\" fill=\"currentColor\" viewBox=\"0 0 20 20\">\n                                <path\n                                    d=\"M2 3a1 1 0 011-1h2.153a1 1 0 01.986.836l.74 4.435a1 1 0 01-.54 1.06l-1.548.773a11.037 11.037 0 006.105 6.105l.774-1.548a1 1 0 011.059-.54l4.435.74a1 1 0 01.836.986V17a1 1 0 01-1 1h-2C7.82 18 2 12.18 2 5V3z\">\n                                </path>\n                            </svg>\n                            <span>Call Us</span>\n                        </button>\n                    </div>\n\n                    <!-- Trust Indicators -->\n                    <div\n                        class=\"flex flex-wrap items-center justify-center gap-4 sm:gap-8 mt-8 sm:mt-12 text-white/70 px-4\">\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-pink-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">Fully Custom Designs</span>\n                        </div>\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-blue-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">Professional Build</span>\n                        </div>\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-purple-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">Full Service Setup</span>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Floating Creative Elements -->\n            <div class=\"absolute top-20 left-10 w-32 h-32 bg-pink-400/20 rounded-full blur-3xl float-creative\"\n                style=\"z-index: 1;\"></div>\n            <div class=\"absolute bottom-20 right-10 w-40 h-40 bg-blue-400/20 rounded-full blur-3xl float-creative\"\n                style=\"animation-delay: 2s; z-index: 1;\"></div>\n            <div class=\"absolute top-1/2 left-1/4 w-24 h-24 bg-yellow-400/20 rounded-full blur-2xl float-creative\"\n                style=\"animation-delay: 4s; z-index: 1;\"></div>\n            <div class=\"absolute top-1/3 right-1/3 w-28 h-28 bg-green-400/20 rounded-full blur-2xl float-creative\"\n                style=\"animation-delay: 6s; z-index: 1;\"></div>\n        </section>\n\n        <!-- Section Divider -->\n        <div class=\"section-divider\"></div>\n\n        <!-- What We Offer Section -->\n        <section\n            class=\"section-padding bg-gradient-to-br from-white via-pink-50 to-blue-50 watercolor-bg relative overflow-hidden\">\n            <!-- Floating Design Tools -->\n            <div class=\"absolute top-20 left-10 tool-float opacity-20\">\n                <svg class=\"w-16 h-16 text-pink-500\" fill=\"currentColor\" viewBox=\"0 0 20 20\">\n                    <path\n                        d=\"M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z\">\n                    </path>\n                </svg>\n            </div>\n            <div class=\"absolute bottom-20 right-10 tool-float opacity-20\" style=\"animation-delay: 2s;\">\n                <svg class=\"w-16 h-16 text-blue-500\" fill=\"currentColor\" viewBox=\"0 0 20 20\">\n                    <path fill-rule=\"evenodd\"\n                        d=\"M4 2a2 2 0 00-2 2v11a3 3 0 106 0V4a2 2 0 00-2-2H4zm1 14a1 1 0 100-2 1 1 0 000 2zm5-1.757l4.9-4.9a2 2 0 000-2.828L13.485 5.1a2 2 0 00-2.828 0L10 5.757v8.486zM16 18H9.071l6-6H16a2 2 0 012 2v2a2 2 0 01-2 2z\">\n                    </path>\n                </svg>\n            </div>\n\n            <div class=\"container mx-auto px-6 relative z-10\">\n                <div class=\"max-w-6xl mx-auto\">\n                    <div class=\"text-center mb-6\">\n                        <div class=\"inline-flex items-center gap-3\">\n                            <div class=\"w-3 h-3 rounded-full bg-red-400 dot-animated\"></div>\n                            <div class=\"w-3 h-3 rounded-full bg-blue-400 dot-animated\" style=\"animation-delay: 0.2s;\">\n                            </div>\n                            <div class=\"w-3 h-3 rounded-full bg-yellow-400 dot-animated\" style=\"animation-delay: 0.4s;\">\n                            </div>\n                            <div class=\"w-3 h-3 rounded-full bg-green-400 dot-animated\" style=\"animation-delay: 0.6s;\">\n                            </div>\n                            <div class=\"w-3 h-3 rounded-full bg-purple-400 dot-animated\" style=\"animation-delay: 0.8s;\">\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"text-center mb-16\">\n                        <h2 class=\"text-4xl md:text-5xl font-light mb-6 brush-stroke brush-stroke-cyan inline-block pb-4\"\n                            style=\"font-family: \'AzoSansUber\', sans-serif;\">\n                            <span style=\"color: #FF4F4F;\">Immersive Set Experiences</span>\n                        </h2>\n                        <p class=\"text-xl max-w-3xl mx-auto leading-relaxed\" style=\"color: #1F1F1F;\">\n                            We can customize almost every aspect of your event, so why wouldn\'t we have a custom photo\n                            shoot set that your party guests can enjoy?\n                        </p>\n                    </div>\n\n                    <div class=\"grid md:grid-cols-3 gap-8 mb-16\">\n                        <!-- Feature 1 -->\n                        <div\n                            class=\"gradient-border p-8 rounded-3xl shadow-xl hover:shadow-2xl transition-all duration-300 text-center card-3d\">\n                            <div\n                                class=\"w-20 h-20 mx-auto mb-6 bg-gradient-to-br from-[#FF4F4F] to-[#FF4F4F] rounded-3xl flex items-center justify-center transform hover:rotate-12 transition-transform duration-300\">\n                                <svg class=\"w-10 h-10 text-white\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                        d=\"M7 21a4 4 0 01-4-4V5a2 2 0 012-2h4a2 2 0 012 2v12a4 4 0 01-4 4zm0 0h12a2 2 0 002-2v-4a2 2 0 00-2-2h-2.343M11 7.343l1.657-1.657a2 2 0 012.828 0l2.829 2.829a2 2 0 010 2.828l-8.486 8.485M7 17h.01\">\n                                    </path>\n                                </svg>\n                            </div>\n                            <h3 class=\"text-xl font-light mb-3\"\n                                style=\"color: #1F1F1F/50;font-family: \'AzoSansUber\', sans-serif;\">Fully\n                                Custom Designs</h3>\n                            <p class=\"text-[#1F1F1F]-600\">Every set is built from scratch to match your exact vision and\n                                theme</p>\n                        </div>\n\n                        <!-- Feature 2 -->\n                        <div\n                            class=\"gradient-border p-8 rounded-3xl shadow-xl hover:shadow-2xl transition-all duration-300 text-center card-3d\">\n                            <div\n                                class=\"w-20 h-20 mx-auto mb-6 bg-gradient-to-br from-[#FF4F4F] to-[#FF4F4F] rounded-3xl flex items-center justify-center transform hover:rotate-12 transition-transform duration-300\">\n                                <svg class=\"w-10 h-10 text-white\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                        d=\"M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4\">\n                                    </path>\n                                </svg>\n                            </div>\n                            <h3 class=\"text-xl font-light mb-3\"\n                                style=\"color: #1F1F1F/50;font-family: \'AzoSansUber\', sans-serif;\">Professional Build\n                            </h3>\n                            <p class=\"text-[#1F1F1F]-600\">High-quality materials and expert construction for stunning\n                                results\n                            </p>\n                        </div>\n\n                        <!-- Feature 3 -->\n                        <div\n                            class=\"gradient-border p-8 rounded-3xl shadow-xl hover:shadow-2xl transition-all duration-300 text-center card-3d\">\n                            <div\n                                class=\"w-20 h-20 mx-auto mb-6 bg-gradient-to-br from-[#FF4F4F] to-[#FF4F4F] rounded-3xl flex items-center justify-center transform hover:rotate-12 transition-transform duration-300\">\n                                <svg class=\"w-10 h-10 text-white\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                        d=\"M14 10l-2 1m0 0l-2-1m2 1v2.5M20 7l-2 1m2-1l-2-1m2 1v2.5M14 4l-2-1-2 1M4 7l2-1M4 7l2 1M4 7v2.5M12 21l-2-1m2 1l2-1m-2 1v-2.5M6 18l-2-1v-2.5M18 18l2-1v-2.5\">\n                                    </path>\n                                </svg>\n                            </div>\n                            <h3 class=\"text-xl font-light mb-3\"\n                                style=\"color: #1F1F1F/50;font-family: \'AzoSansUber\', sans-serif;\">Full Service Setup\n                            </h3>\n                            <p class=\"text-[#1F1F1F]-600\">We handle delivery, setup, and teardown so you can focus on\n                                your\n                                event</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Section Divider -->\n        <div class=\"section-divider\"></div>\n\n        <!-- Them