ochure-section h3 {\n                font-size: 1.75rem !important;\n            }\n\n            .brochure-section p {\n                font-size: 1rem !important;\n            }\n\n            /* Premium Section */\n            .premium-main-text {\n                font-size: 2rem !important;\n            }\n\n            .premium-subtext {\n                font-size: 0.875rem !important;\n            }\n\n            /* Elegant Sections */\n            .elegant-section .main-text {\n                font-size: 2rem !important;\n            }\n\n            /* Signature Section */\n            section h2[style*=\"font-size: 6.5rem\"] {\n                font-size: 3rem !important;\n            }\n\n            /* Featured Section */\n            .featured-title {\n                font-size: 2rem !important;\n            }\n\n            /* Product Grid */\n            .grid.grid-cols-1.sm\\\\:grid-cols-2.lg\\\\:grid-cols-5 {\n                grid-template-columns: repeat(2, 1fr);\n                gap: 1.5rem;\n            }\n\n            .grid.grid-cols-1.sm\\\\:grid-cols-2.lg\\\\:grid-cols-5 img {\n                width: 100px;\n                height: 100px;\n            }\n\n            .grid.grid-cols-1.sm\\\\:grid-cols-2.lg\\\\:grid-cols-5 h3 {\n                font-size: 1rem;\n            }\n\n            .grid.grid-cols-1.sm\\\\:grid-cols-2.lg\\\\:grid-cols-5 button {\n                font-size: 0.875rem;\n                padding: 0.625rem 1rem;\n            }\n\n            /* CTA Buttons */\n            .cta-section a {\n                width: 100%;\n                padding: 0.875rem 1.5rem;\n                font-size: 0.875rem;\n            }\n\n            /* Decorative divider mobile */\n            .decorative-divider {\n                width: 80%;\n                margin: 1.5rem auto;\n            }\n\n            /* Brochure preview mobile */\n            .brochure-preview {\n                margin: 0 auto;\n            }\n\n            /* Product detail images mobile */\n            .product-image {\n                margin-bottom: 1rem;\n            }\n        }\n\n        /* Extra small devices */\n        @media (max-width: 480px) {\n\n            /* Further reduce font sizes for very small screens */\n            .premium-main-text {\n                font-size: 1.75rem !important;\n            }\n\n            .elegant-section .main-text {\n                font-size: 1.75rem !important;\n            }\n\n            section h2[style*=\"font-size: 2.5rem\"] {\n                font-size: 2rem !important;\n            }\n\n            /* Reduce padding further */\n            .section-padding {\n                padding: 2rem 0;\n            }\n\n            .premium-content-wrapper {\n                padding: 1.5rem 0.75rem;\n            }\n\n            /* Smaller buttons */\n            .btn-elegant {\n                padding: 0.625rem 1.25rem;\n                font-size: 0.875rem;\n            }\n\n            /* Tighter spacing */\n            .brochure-check-item {\n                margin-bottom: 0.75rem;\n            }\n        }\n    </style>\n\n    <!-- JSON-LD Structured Data -->\n    <script type=\"application/ld+json\">\n    {\n        \"@context\": \"https://schema.org\",\n        \"@graph\": [\n            {\n                \"@type\": \"Organization\",\n                \"@id\": \"https://www.mihientertainment.com/#organization\",\n                \"name\": \"MiHi Entertainment\",\n                \"url\": \"https://www.mihientertainment.com\",\n                \"logo\": \"https://www.mihientertainment.com/assets/images/logo.png\",\n                \"sameAs\": [\n                    \"https://www.facebook.com/mihientertainment\",\n                    \"https://www.instagram.com/mihientertainment\"\n                ],\n                \"contactPoint\": {\n                    \"@type\": \"ContactPoint\",\n                    \"telephone\": \"+1-XXX-XXX-XXXX\",\n                    \"contactType\": 