openVideoModal(\'../../assets/video/bullet-time/bullet-time-3.mp4\')\">\n                                    <video class=\"w-full h-full object-cover\" muted loop autoplay playsinline preload=\"none\">\n                                        <source src=\"../../assets/video/bullet-time/bullet-time-3.mp4\" type=\"video/mp4\">\n                                    </video>\n                                    <div class=\"absolute inset-0 bg-black/30 group-hover:bg-black/50 transition-all flex items-center justify-center\">\n                                        <svg class=\"w-12 h-12 text-white opacity-0 group-hover:opacity-100 transition-opacity\" fill=\"currentColor\" viewBox=\"0 0 24 24\">\n                                            <path d=\"M8 5v14l11-7z\"/>\n                                        </svg>\n                                    </div>\n                                </div>\n                                <div class=\"video-item flex-shrink-0 w-80 h-60 md:w-96 md:h-72 rounded-xl overflow-hidden cursor-pointer group relative\" onclick=\"openVideoModal(\'../../assets/video/bullet-time/bullet-time-4.mp4\')\">\n                                    <video class=\"w-full h-full object-cover\" muted loop autoplay playsinline preload=\"none\">\n                                        <source src=\"../../assets/video/bullet-time/bullet-time-4.mp4\" type=\"video/mp4\">\n                                    </video>\n                                    <div class=\"absolute inset-0 bg-black/30 group-hover:bg-black/50 transition-all flex items-center justify-center\">\n                                        <svg class=\"w-12 h-12 text-white opacity-0 group-hover:opacity-100 transition-opacity\" fill=\"currentColor\" viewBox=\"0 0 24 24\">\n                                            <path d=\"M8 5v14l11-7z\"/>\n                                        </svg>\n                                    </div>\n                                </div>\n               