" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M7 21a4 4 0 01-4-4V5a2 2 0 012-2h4a2 2 0 012 2v12a4 4 0 01-4 4zm0 0h12a2 2 0 002-2v-4a2 2 0 00-2-2h-2.343M11 7.343l1.657-1.657a2 2 0 012.828 0l2.829 2.829a2 2 0 010 2.828l-8.486 8.485M7 17h.01\"/>\n                                </svg>\n                            </div>\n                            <h3 class=\"text-xl md:text-2xl font-bold text-white uppercase tracking-wide\">Branded Booth Wrap</h3>\n                        </div>\n                        <p class=\"text-white/90 text-sm md:text-base leading-relaxed transition-all duration-300 group-hover:text-white\">Ensure your booth is fully branded with a custom wrap that makes a lasting impression.</p>\n                    </div>\n\n                    <!-- Card 4: Logo Integration -->\n                    <div class=\"cards-section-card group bg-gradient-to-br from-[#0050ff] via-[#0040d9] to-[#7c3aed] rounded-2xl p-6 lg:p-8 shadow-lg transition-all duration-300 animate-fade-in-up animate-delay-100\">\n                        <div class=\"flex items-start gap-4 mb-4\">\n                            <div class=\"cards-section-icon-container flex-shrink-0 w-12 h-12 bg-white/20 rounded-xl flex items-center justify-center backdrop-blur-sm\">\n                                <svg class=\"w-6 h-6 text-white\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z\"/>\n                                </svg>\n                            </div>\n                            <h3 class=\"text-xl md:text-2xl font-bold text-white uppercase tracking-wide\">Logo Integration</h3>\n                        </div>\n                        <p class=\"text-white/90 text-sm md:text-base leading-relaxed transition-all duration-300 group-hover:text-white\">Incorporate your logo seamlessly into event visuals, ensuring brand presence in every shot.</p>\n                    </div>\n\n                    <!-- Card 5: Data Collection -->\n                    <div class=\"cards-section-card group bg-gradient-to-br from-[#0050ff] via-[#0040d9] to-[#7c3aed] rounded-2xl p-6 lg:p-8 shadow-lg transition-all duration-300 animate-fade-in-up animate-delay-200\">\n                        <div class=\"flex items-start gap-4 mb-4\">\n                            <div class=\"cards-section-icon-container flex-shrink-0 w-12 h-12 bg-white/20 rounded-xl flex items-center justify-center backdrop-blur-sm\">\n                                <svg class=\"w-6 h-6 text-white\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/>\n                                </svg>\n                            </div>\n                            <h3 class=\"text-xl md:text-2xl font-bold text-white uppercase tracking-wide\">Data Collection</h3>\n                        </div>\n                        <p class=\"text-white/90 text-sm md:text-base leading-relaxed transition-all duration-300 group-hover:text-white\">Gather key event data with an integrated data collection system to track engagement and participation.</p>\n                    </div>\n\n                    <!-- Card 6: GIF and Boomerang Capabilities -->\n                    <div class=\"cards-section-card group bg-gradient-to-br from-[#0050ff] via-[#0040d9] to-[#7c3aed] rounded-2xl p-6 lg:p-8 shadow-lg transition-all duration-300 animate-fade-in-up animate-delay-300\">\n                        <div class=\"flex items-start gap-4 mb-4\">\n                            <div class=\"cards-section-icon-container flex-shrink-0 w-12 h-12 bg-white/20 rounded-xl flex items-center justify-center backdrop-blur-sm\">\n                                <svg class=\"w-6 h-6 text-white\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z\"/>\n                                </svg>\n                            </div>\n                            <h3 class=\"text-xl md:text-2xl font-bold text-white uppercase tracking-wide\">GIF and Boomerang Capabilities</h3>\n                        </div>\n                        <p class=\"text-white/90 text-sm md:text-base leading-relaxed transition-all duration-300 group-hover:text-white\">Offer guests the ability to create GIFs and Boomerangs for a fun and interactive experience.</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Image Content Section -->\n    <section class=\"py-10 md:py-12 lg:py-14 bg-gradient-to-br from-white via-blue-50/30 to-purple-50/20 relative overflow-hidden\">\n        <div class=\"absolute inset-0 opacity-40 pointer-events-none\">\n            <div class=\"absolute -top-32 -left-24 w-96 h-96 bg-blue-200/20 rounded-full blur-3xl\"></div>\n            <div class=\"absolute bottom-0 right-0 w-80 h-80 bg-purple-200/20 rounded-full blur-3xl\"></div>\n        </div>\n\n        <div class=\"relative container mx-auto px-6\">\n            <div class=\"grid lg:grid-cols-2 gap-8 lg:gap-12 items-center\">\n                <!-- Left: Technical Specifications -->\n                <div class=\"order-2 lg:order-1 space-y-6 animate-fade-in-up\">\n                    <div>\n                        <h2 class=\"hero-text text-3xl md:text-4xl lg:text-5xl font-bold gradient-title mb-2 leading-tight\">\n                            PHOTO BOOTH<br>TECHNICAL SPECIFICATIONS\n                        </h2>\n                    </div>\n\n                    <div class=\"grid md:grid-cols-2 gap-4\">\n                        <!-- Specification Item 1 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Space Required</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">8\' x 8\' Minimum, 15\' x 8\' Preferred</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Specification Item 2 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Power Needs</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">Standard Outlet</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Specification Item 3 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Setup Duration</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">90 Minutes</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Specification Item 4 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Processing Time</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">Instant</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Specification Item 5 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Instant Internet</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">Hardwired Required</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Specification Item 6 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Photo Capacity</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">Unlimited but Predetermined</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Specification Item 7 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Final Resolution</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">High-Resolution Photos</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Specification Item 8 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Output</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">Digital & Print</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Specification Item 9 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Environment</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">Indoor Use</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Specification Item 10 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Staff</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">One-Two Operators Included</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Specification Item 11 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Standard Duration</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">Full Event, Multi-Day</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Specification Item 12 -->\n                        <div class=\"feature-item\">\n                            <div class=\"flex items-start gap-3\">\n                                <div class=\"feature-icon\"></div>\n                                <div>\n                                    <p class=\"text-gray-800 font-bold text-sm md:text-base mb-1\">Backup</p>\n                                    <p class=\"text-gray-600 text-xs md:text-sm\">Cloud Storage</p>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Right: Image -->\n                <div class=\"order-1 lg:order-2 animate-fade-in-up animate-delay-200\">\n                    <div class=\"enhanced-image-container\">\n                        <img src=\"../assets/images/photobooth/section1/pic7.png\" alt=\"Photo Booth Event Experience\" class=\"w-full h-auto object-cover rounded-2xl\">\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Contact Form Section -->\n    <section class=\"contact-form-section py-10 md:py-12 lg:py-16 bg-white\">\n        <div class=\"container mx-auto px-6\">\n            <!-- Header Section -->\n            <div class=\"text-center mb-8 lg:mb-12 animate-fade-in-up\">\n                <h2 class=\"hero-text text-3xl md:text-4xl lg:text-5xl font-bold gradient-title mb-4 leading-tight\">\n                    CONTACT US NOW\n                </h2>\n                <p class=\"text-gray-700 text-base md:text-lg max-w-3xl mx-auto mb-2\">\n                    Tell us about your event by filling out the form below, and our team will be in touch as soon as possible.\n                </p>\n                <p class=\"text-gray-600 text-sm md:text-base\">\n                    Have more questions? Scroll down to email our team directly!\n                </p>\n            </div>\n\n            <!-- Main Form Section -->\n            <div class=\"max-w-6xl mx-auto\">\n                <div class=\"bg-gradient-to-br from-[#0033b3] via-[#0040d9] to-[#0050ff] rounded-3xl p-6 md:p-8 lg:p-12 shadow-2xl animate-fade-in-up animate-delay-100\">\n                    <form id=\"contactForm\" class=\"space-y-6\">\n                        <!-- Two Column Fields -->\n                        <div class=\"grid md:grid-cols-2 gap-6\">\n                            <!-- Left Column -->\n                            <div class=\"space-y-6\">\n                                <!-- First Name -->\n                                <div>\n                                    <label for=\"firstName\" class=\"block text-white font-semibold text-sm md:text-base mb-2\">\n                                        First Name <span class=\"text-red-300\">*</span>\n                                    </label>\n                                    <input type=\"text\" id=\"firstName\" name=\"firstName\" required \n                                        class=\"contact-form-input\" placeholder=\"Enter your first name\">\n                                </div>\n\n                                <!-- Last Name -->\n                                <div>\n                                    <label for=\"lastName\" class=\"block text-white font-semibold text-sm md:text-base mb-2\">\n                                        Last Name <span class=\"text-red-300\">*</span>\n                                    </label>\n                                    <input type=\"text\" id=\"lastName\" name=\"lastName\" required \n                                        class=\"contact-form-input\" placeholder=\"Enter your last name\">\n                                </div>\n\n                                <!-- Email Address -->\n                                <div>\n                                    <label for=\"email\" class=\"block text-white font-semibold text-sm md:text-base mb-2\">\n                                        Email Address <span class=\"text-red-300\">*</span>\n                                    </label>\n                                    <input type=\"email\" id=\"email\" name=\"email\" required \n                                        class=\"contact-form-input\" placeholder=\"Enter your email address\">\n                                </div>\n\n                                <!-- Phone Number -->\n                                <div>\n                                    <label for=\"phone\" class=\"block text-white font-semibold text-sm md:text-base mb-2\">\n                                        Phone Number <span class=\"text-red-300\">*</span>\n                                    </label>\n                                    <input type=\"tel\" id=\"phone\" name=\"phone\" required \n                                        class=\"contact-form-input\" placeholder=\"Enter your phone number\">\n                                </div>\n\n                                <!-- Type Of Event -->\n                                <div>\n                                    <label for=\"eventType\" class=\"block text-white font-semibold text-sm md:text-base mb-2\">\n                                        Type Of Event <span class=\"text-red-300\">*</span>\n                                    </label>\n                                    <select id=\"eventType\" name=\"eventType\" required class=\"contact-form-select\">\n                                        <option value=\"\">Please select...</option>\n                                        <option value=\"wedding\">Wedding</option>\n                                        <option value=\"corporate\">Corporate Event</option>\n                                        <option value=\"birthday\">Birthday Party</option>\n                                        <option value=\"anniversary\">Anniversary</option>\n                                        <option value=\"graduation\">Graduation</option>\n                                        <option value=\"holiday\">Holiday Party</option>\n                                        <option value=\"other\">Other</option>\n                                    </select>\n                                </div>\n                            </div>\n\n                            <!-- Right Column -->\n                            <div class=\"space-y-6\">\n                                <!-- Date Of Event -->\n                                <div>\n                                    <label class=\"block text-white font-semibold text-sm md:text-base mb-2\">\n                                        Date Of Event <span class=\"text-red-300\">*</span>\n                                    </label>\n                                    <div class=\"grid grid-cols-3 gap-3\">\n                                        <select id=\"eventMonth\" name=\"eventMonth\" required class=\"contact-form-select\">\n                                            <option value=\"\">Month</option>\n                                            <option value=\"01\">January</option>\n                                            <option value=\"02\">February</option>\n                                            <option value=\"03\">March</option>\n                                            <option value=\"04\">April</option>\n                                            <option value=\"05\">May</option>\n                                            <option value=\"06\">June</option>\n                                            <option value=\"07\">July</option>\n                                            <option value=\"08\">August</option>\n                                            <option value=\"09\">September</option>\n                                            <option value=\"10\">October</option>\n                                            <option value=\"11\">November</option>\n                                            <option value=\"12\">December</option>\n                                        </select>\n                                        <select id=\"eventDay\" name=\"eventDay\" required class=\"contact-form-select\">\n                                            <option value=\"\">Day</option>\n                                            <option value=\"01\">1</option>\n                                            <option value=\"02\">2</option>\n                                            <option value=\"03\">3</option>\n                                            <option value=\"04\">4</option>\n                                            <option value=\"05\">5</option>\n                                            <option value=\"06\">6</option>\n                                            <option value=\"07\">7</option>\n                                            <option value=\"08\">8</option>\n                                            <option value=\"09\">9</option>\n                                            <option value=\"10\">10</option>\n                                            <option value=\"11\">11</option>\n                                            <option value=\"12\">12</option>\n                                            <option value=\"13\">13</option>\n                                            <option value=\"14\">14</option>\n                                            <option value=\"15\">15</option>\n                                            <option value=\"16\">16</option>\n                                            <option value=\"17\">17</option>\n                                            <option value=\"18\">18</option>\n                                            <option value=\"19\">19</option>\n                                            <option value=\"20\">20</option>\n                                            <option value=\"21\">21</option>\n                                            <option value=\"22\">22</option>\n                                            <option value=\"23\">23</option>\n                                            <option value=\"24\">24</option>\n                                            <option value=\"25\">25</option>\n                                            <option value=\"26\">26</option>\n                                            <option value=\"27\">27</option>\n                                            <option value=\"28\">28</option>\n                                            <option value=\"29\">29</option>\n                                            <option value=\"30\">30</option>\n                                            <option value=\"31\">31</option>\n                                        </select>\n                                        <select id=\"eventYear\" name=\"eventYear\" required class=\"contact-form-select\">\n                                            <option value=\"\">Year</option>\n                                            <option value=\"2024\">2024</option>\n                                            <option value=\"2025\">2025</option>\n                                            <option value=\"2026\">2026</option>\n                                            <option value=\"2027\">2027</option>\n                                        </select>\n                                    </div>\n                                </div>\n\n                                <!-- Venue Name -->\n                                <div>\n                                    <label for=\"venueName\" class=\"block text-white font-semibold text-sm md:text-base mb-2\">\n                                        Venue Name\n                                    </label>\n                                    <input type=\"text\" id=\"venueName\" name=\"venueName\" \n                                        class=\"contact-form-input\" placeholder=\"Enter venue name\">\n                                </div>\n\n                                <!-- Venue State -->\n                                <div>\n                                    <label for=\"venueState\" class=\"block text-white font-semibold text-sm md:text-base mb-2\">\n                                        Venue State <span class=\"text-red-300\">*</span>\n                                    </label>\n                                    <input type=\"text\" id=\"venueState\" name=\"venueState\" required \n                                        class=\"contact-form-input\" placeholder=\"Enter state\">\n                                </div>\n\n                                <!-- Ideal Budget -->\n                                <div>\n                                    <label for=\"budget\" class=\"block text-white font-semibold text-sm md:text-base mb-2\">\n                                        Ideal Budget\n                                    </label>\n                                    <input type=\"text\" id=\"budget\" name=\"budget\" \n                                        class=\"contact-form-input\" placeholder=\"Enter your budget\">\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Products/Services Checkboxes -->\n                        <div class=\"pt-4\">\n                            <h3 class=\"text-white font-bold text-lg md:text-xl mb-4\">Products/Services You\'re Interested In</h3>\n                            <div class=\"grid md:grid-cols-3 gap-4\">\n                                <!-- Column 1 -->\n                                <div class=\"space-y-3\">\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"photo-booth-printing\" class=\"contact-form-checkbox\">\n                                        <span>Photo Booths (with printing)</span>\n                                    </label>\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"ai-experiences\" class=\"contact-form-checkbox\">\n                                        <span>AI Experiences</span>\n                                    </label>\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"professional-headshots\" class=\"contact-form-checkbox\">\n                                        <span>Professional Headshots</span>\n                                    </label>\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"casino-services\" class=\"contact-form-checkbox\">\n                                        <span>Casino Services</span>\n                                    </label>\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"claw-machine\" class=\"contact-form-checkbox\">\n                                        <span>Claw Machine/Stick Drop</span>\n                                    </label>\n                                </div>\n\n                                <!-- Column 2 -->\n                                <div class=\"space-y-3\">\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"photo-booth-no-printing\" class=\"contact-form-checkbox\">\n                                        <span>Photo Booths (without printing)</span>\n                                    </label>\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"lighting-decor\" class=\"contact-form-checkbox\">\n                                        <span>Lighting & Decor</span>\n                                    </label>\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"event-photography\" class=\"contact-form-checkbox\">\n                                        <span>Professional Event Photography</span>\n                                    </label>\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"dancefloors\" class=\"contact-form-checkbox\">\n                                        <span>Dancefloors</span>\n                                    </label>\n                                </div>\n\n                                <!-- Column 3 -->\n                                <div class=\"space-y-3\">\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"video-booths\" class=\"contact-form-checkbox\">\n                                        <span>Video Booths</span>\n                                    </label>\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"virtual-reality\" class=\"contact-form-checkbox\">\n                                        <span>Virtual Reality</span>\n                                    </label>\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"av-dj\" class=\"contact-form-checkbox\">\n                                        <span>AV + DJ Services</span>\n                                    </label>\n                                    <label class=\"contact-form-checkbox-label\">\n                                        <input type=\"checkbox\" name=\"services\" value=\"staging\" class=\"contact-form-checkbox\">\n                                        <span>Staging</span>\n                                    </label>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- How did you hear about us -->\n                        <div>\n                            <label for=\"hearAboutUs\" class=\"block text-white font-semibold text-sm md:text-base mb-2\">\n                                How did you hear about us?\n                            </label>\n                            <input type=\"text\" id=\"hearAboutUs\" name=\"hearAboutUs\" \n                                class=\"contact-form-input\" placeholder=\"Tell us how you found us\">\n                        </div>\n\n                        <!-- Tell Us About Your Event -->\n                        <div>\n                            <label for=\"eventDetails\" class=\"block text-white font-semibold text-sm md:text-base mb-2\">\n                                Tell Us About Your Event\n                            </label>\n                            <textarea id=\"eventDetails\" name=\"eventDetails\" rows=\"5\" \n                                class=\"contact-form-textarea\" placeholder=\"Share details about your event...\"></textarea>\n                        </div>\n\n                        <!-- Privacy Policy Checkbox -->\n                        <div class=\"flex items-start gap-3 pt-2\">\n                            <input type=\"checkbox\" id=\"privacyPolicy\" name=\"privacyPolicy\" required \n                                class=\"contact-form-checkbox mt-1\">\n                            <label for=\"privacyPolicy\" class=\"text-white text-sm md:text-base\">\n                                I agree to the <a href=\"../privacy-policy.html\" class=\"text-blue-200 underline hover:text-blue-100 transition-colors\">Privacy Policy</a> <span class=\"text-red-300\">*</span>\n                            </label>\n                        </div>\n\n                        <!-- Submit Button -->\n                        <button type=\"submit\" class=\"contact-form-submit-btn\">\n                            GET YOUR QUOTE\n                        </button>\n                    </form>\n                </div>\n\n                <!-- Footer Email Section -->\n                <div class=\"mt-8 bg-gradient-to-r from-[#0050ff] to-[#0040d9] rounded-3xl p-8 md:p-10 text-center animate-fade-in-up animate-delay-200\">\n                    <h3 class=\"text-white font-bold text-2xl md:text-3xl mb-3\">HAVE QUESTIONS?</h3>\n                    <p class=\"text-white/90 text-base md:text-lg mb-6 max-w-2xl mx-auto\">\n                        Send us an email to talk over your event details, we\'re happy to help with any questions you may have.\n                    </p>\n                    <a href=\"mailto:info@mihientertainment.com\" class=\"contact-form-email-btn inline-block\">\n                        EMAIL US\n                    </a>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Last Section -->\n    <section class=\"py-8 md:py-10 lg:py-12 bg-gradient-to-br from-white via-blue-50/30 to-purple-50/20\">\n        <div class=\"container mx-auto px-6\">\n            <!-- Header -->\n            <div class=\"text-center mb-6 lg:mb-8 animate-fade-in-up\">\n                <h2 class=\"hero-text text-2xl md:text-3xl lg:text-4xl font-bold gradient-title mb-3 leading-tight\">\n                    <span class=\"text-xl md:text-2xl lg:text-3xl font-normal text-gray-600 block mb-1.5\">DISCOVER OUR</span>\n                    RELATED PRODUCTS\n                </h2>\n                <p class=\"text-gray-700 text-sm md:text-base max-w-3xl mx-auto\">\n                    Discover more of what we do best—Photo Booths, Activations, and beyond! Click below to browse our related products.\n                </p>\n            </div>\n\n            <!-- Cards Grid -->\n            <div class=\"grid md:grid-cols-3 gap-4 lg:gap-6 max-w-7xl mx-auto\">\n                <!-- Corporate Events Card -->\n                <a href=\"../corporate-events.html\" class=\"last-section-card group animate-fade-in-up animate-delay-100\">\n                    <div class=\"relative aspect-[4/3] rounded-t-2xl overflow-hidden\">\n                        <img src=\"../assets/images/photobooth/lastsection/1.jpg\" alt=\"Corporate Events\" class=\"w-full h-full object-cover\">\n                    </div>\n                    <div class=\"last-section-card-banner rounded-b-2xl\">\n                        <h3>CORPORATE EVENTS</h3>\n                    </div>\n                </a>\n\n                <!-- Weddings Card -->\n                <a href=\"../wedding.html\" class=\"last-section-card group animate-fade-in-up animate-delay-200\">\n                    <div class=\"relative aspect-[4/3] rounded-t-2xl overflow-hidden\">\n                        <img src=\"../assets/images/photobooth/lastsection/2.jpg\" alt=\"Weddings\" class=\"w-full h-full object-cover\">\n                    </div>\n                    <div class=\"last-section-card-banner rounded-b-2xl\">\n                        <h3>WEDDINGS</h3>\n                    </div>\n                </a>\n\n                <!-- Social Events Card -->\n                <a href=\"../socialevents.html\" class=\"last-section-card group animate-fade-in-up animate-delay-300\">\n                    <div class=\"relative aspect-[4/3] rounded-t-2xl overflow-hidden\">\n                        <img src=\"../assets/images/photobooth/lastsection/3.jpg\" alt=\"Social Events\" class=\"w-full h-full object-cover\">\n                    </div>\n                    <div class=\"last-section-card-banner rounded-b-2xl\">\n                        <h3>SOCIAL EVENTS</h3>\n                    </div>\n                </a>\n            </div>\n        </div>\n    </section>\n\n    <script src=\"../assets/components/navigation.js\"></script>\n    <script src=\"../assets/components/footer.js\"></script>\n    <script>\n        const galleryContEl = document.querySelector(\'.gallery-container\');\n        const galleryEl = document.querySelector(\'.gallery\');\n        let zoomedItem = null;\n        let timer;\n        let scrollTop = 0;\n\n        if(typeof CSS.registerProperty === \'function\') {\n            CSS.registerProperty({\n                name: \'--left\',\n                syntax: \'<length>\',\n                inherits: false,\n                initialValue: 0,\n            });\n            CSS.registerProperty({\n                name: \'--top\',\n                syntax: \'<length>\',\n                inherits: false,\n                initialValue: 0,\n            });\n            CSS.registerProperty({\n                name: \'--zoom\',\n                syntax: \'<number>\',\n                inherits: false,\n                initialValue: 1,\n            });\n        }\n\n        galleryEl.addEventListener(\'click\', function(e) {\n            const item = e.target.closest(\'.gallery-item\');\n            \n            if(!item || zoomedItem === item) return;\n            \n            e.preventDefault();\n            e.stopPropagation();\n\n            const picW = item.offsetWidth;\n            const picH = item.offsetHeight;\n            const picCX = item.offsetLeft + picW / 2;\n            const picCY = item.offsetTop + picH / 2;\n            let {paddingLeft: itemPaddLeft, paddingRight: itemPaddRight} = getComputedStyle(item);\n            itemPaddLeft = parseFloat(itemPaddLeft);\n            itemPaddRight = parseFloat(itemPaddRight);\n            const zoom = Math.min(\n                (window.innerHeight - 30) / picH,\n                (window.innerWidth - 30) / picW,\n                item.querySelector(\'img\').naturalWidth / item.querySelector(\'img\').offsetWidth,\n            );\n\n            if(zoomedItem) {\n                galleryEl.style.transitionProperty = \'--left, --top, --zoom, transform-origin\';\n            } else {\n                scrollTop = window.scrollY;\n                galleryEl.style.top = -scrollTop + \'px\';\n            }\n\n            galleryEl.style.transformOrigin = `${picCX}px ${picCY}px`;\n            galleryEl.style.setProperty(\'--left\', `${galleryEl.offsetWidth / 2 - picCX}px`);\n            galleryEl.style.setProperty(\'--top\', `${-item.offsetTop + scrollTop + (window.innerHeight - picH) / 2}px`);\n            galleryEl.style.setProperty(\'--zoom\', zoom);\n            galleryContEl.classList.add(\'zoomed-in\');\n            \n            if(zoomedItem) zoomedItem.classList.remove(\'current\');\n            item.classList.add(\'current\');\n            zoomedItem = item;\n            \n            clearTimeout(timer);\n            galleryContEl.style.overflow = \'hidden\';\n            galleryContEl.style.height = \'100vh\';\n        });\n\n        document.body.addEventListener(\'click\', function(e) {\n            if(!zoomedItem) return;\n            \n            e.preventDefault();\n            \n            galleryContEl.classList.remove(\'zoomed-in\');\n            galleryEl.style.transitionProperty = \'\';\n            galleryEl.style.setProperty(\'--left\', \'\');\n            galleryEl.style.setProperty(\'--top\', \'\');\n            galleryEl.style.setProperty(\'--zoom\', \'\');\n\n            zoomedItem.classList.remove(\'current\');\n            zoomedItem = null;\n\n            clearTimeout(timer);\n            timer = setTimeout(() => {\n                galleryEl.style.top = 0;\n                galleryContEl.style.overflow = \'\';\n                galleryContEl.style.height = \'\';\n                window.scrollTo(0, scrollTop);\n            }, 800);\n        });\n    </script>\n    <!-- Load Back to Top Component -->\n    <script src=\"../../assets/components/back-to-top.js\"></script>\n\n</body>', NULL, 'published', NULL, '2025-12-14 00:30:10', '2025-12-14 00:30:10');
INSERT INTO `pages` (`id`, `title`, `slug`, `content_html`, `custom_css`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(155, 'Professional Headshots', 'product-professional-headshots', '<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <meta name=\"description\"\n        content=\"Professional Headshot Rentals by MiHi Entertainment. Studio-quality headshots on-site with expert lighting, instant touch-ups, and polished digital delivery. Perfect for corporate events, trade shows, LinkedIn photos, and business portraits nationwide.\">\n    <meta name=\"keywords\"\n        content=\"professional headshots, corporate headshots, business headshots, LinkedIn photos, executive portraits, professional photography, headshot rental, corporate photography, trade show headshots, business portraits, professional headshot service\">\n    <meta name=\"author\" content=\"MiHi Entertainment\">\n    <meta name=\"robots\" content=\"index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1\">\n    <meta name=\"googlebot\" content=\"index, follow\">\n    <meta name=\"language\" content=\"English\">\n    <meta name=\"distribution\" content=\"global\">\n    <link rel=\"canonical\" href=\"https://www.mihientertainment.com/product/professional-headshots.html\">\n\n    <!-- DNS Prefetch and Preconnect for Performance -->\n    <link rel=\"dns-prefetch\" href=\"https://cdn.tailwindcss.com\">\n    <link rel=\"dns-prefetch\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"dns-prefetch\" href=\"https://fonts.gstatic.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" crossorigin>\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n\n    <!-- Open Graph / Facebook -->\n    <meta property=\"og:type\" content=\"website\">\n    <meta property=\"og:url\" content=\"https://www.mihientertainment.com/product/professional-headshots.html\">\n    <meta property=\"og:title\"\n        content=\"Professional Headshot Rentals - Studio-Quality Business Portraits | MiHi Entertainment\">\n    <meta property=\"og:description\"\n        content=\"Give your guests studio-quality professional headshots on-site with expert lighting, instant touch-ups, and polished digital delivery. Perfect for corporate events, trade shows, and LinkedIn photos.\">\n    <meta property=\"og:image\"\n        content=\"https://www.mihientertainment.com/assets/images/headshot/professional-headshot-hero.webp\">\n    <meta property=\"og:image:width\" content=\"1200\">\n    <meta property=\"og:image:height\" content=\"630\">\n    <meta property=\"og:site_name\" content=\"MiHi Entertainment\">\n    <meta property=\"og:locale\" content=\"en_US\">\n\n    <!-- Twitter -->\n    <meta name=\"twitter:card\" content=\"summary_large_image\">\n    <meta name=\"twitter:url\" content=\"https://www.mihientertainment.com/product/professional-headshots.html\">\n    <meta name=\"twitter:title\" content=\"Professional Headshot Rentals - Studio-Quality Business Portraits\">\n    <meta name=\"twitter:description\"\n        content=\"Give your guests studio-quality professional headshots on-site with expert lighting, instant touch-ups, and polished digital delivery.\">\n    <meta name=\"twitter:image\"\n        content=\"https://www.mihientertainment.com/assets/images/headshot/professional-headshot-hero.webp\">\n\n    <title>Professional Headshot Rentals - Studio-Quality Business Portraits | MiHi Entertainment</title>\n    <link rel=\"icon\" type=\"image/svg+xml\" href=\"../../assets/images/favicon.svg\">\n\n    <!-- Schema.org Structured Data -->\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"Organization\",\n      \"name\": \"MiHi Entertainment\",\n      \"url\": \"https://www.mihientertainment.com\",\n      \"logo\": \"https://www.mihientertainment.com/assets/images/logo.png\",\n      \"description\": \"Premium photo booth rentals and event entertainment services nationwide. Specializing in professional headshots, corporate photography, AI photo booths, green screen technology, 360° video booths, and immersive event experiences.\",\n      \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"addressCountry\": \"US\"\n      },\n      \"contactPoint\": {\n        \"@type\": \"ContactPoint\",\n        \"contactType\": \"Customer Service\",\n        \"areaServed\": \"US\"\n      },\n      \"sameAs\": [\n        \"https://www.facebook.com/mihientertainment\",\n        \"https://www.instagram.com/mihientertainment\"\n      ]\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"LocalBusiness\",\n      \"@id\": \"https://www.mihientertainment.com\",\n      \"name\": \"MiHi Entertainment\",\n      \"image\": \"https://www.mihientertainment.com/assets/images/logo.png\",\n      \"description\": \"Premium professional headshot rental services. Studio-quality headshots on-site with expert lighting, instant touch-ups, and polished digital delivery. Perfect for corporate events, trade shows, LinkedIn photos, and business portraits nationwide.\",\n      \"url\": \"https://www.mihientertainment.com\",\n      \"telephone\": \"+1-XXX-XXX-XXXX\",\n      \"priceRange\": \"$$\",\n      \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"addressCountry\": \"US\"\n      },\n      \"geo\": {\n        \"@type\": \"GeoCoordinates\",\n        \"latitude\": \"39.7392\",\n        \"longitude\": \"-104.9903\"\n      },\n      \"areaServed\": {\n        \"@type\": \"Country\",\n        \"name\": \"United States\"\n      },\n      \"aggregateRating\": {\n        \"@type\": \"AggregateRating\",\n        \"ratingValue\": \"4.9\",\n        \"reviewCount\": \"150\"\n      }\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"Product\",\n      \"name\": \"Professional Headshot Rental\",\n      \"image\": [\n        \"https://www.mihientertainment.com/assets/images/headshot/professional-headshot-hero.webp\",\n        \"https://www.mihientertainment.com/assets/images/headshot/professional-headshot-1.webp\",\n        \"https://www.mihientertainment.com/assets/images/headshot/professional-headshot-10.webp\"\n      ],\n      \"description\": \"Studio-quality professional headshot rental service for corporate events, trade shows, and business portraits. On-site photography with expert lighting, instant touch-ups, pose coaching, and polished digital delivery. Perfect for LinkedIn photos, executive portraits, and corporate team headshots.\",\n      \"brand\": {\n        \"@type\": \"Brand\",\n        \"name\": \"MiHi Entertainment\"\n      },\n      \"category\": \"Professional Photography\",\n      \"keywords\": \"professional headshots, corporate headshots, business headshots, LinkedIn photos, executive portraits, trade show headshots\",\n      \"offers\": {\n        \"@type\": \"AggregateOffer\",\n        \"url\": \"https://www.mihientertainment.com/product/professional-headshots.html\",\n        \"priceCurrency\": \"USD\",\n        \"availability\": \"https://schema.org/InStock\",\n        \"priceSpecification\": {\n          \"@type\": \"UnitPriceSpecification\",\n          \"price\": \"Contact for pricing\"\n        },\n        \"offerCount\": \"3\"\n      },\n      \"aggregateRating\": {\n        \"@type\": \"AggregateRating\",\n        \"ratingValue\": \"5\",\n        \"reviewCount\": \"30\",\n        \"bestRating\": \"5\",\n        \"worstRating\": \"1\"\n      },\n      \"additionalProperty\": [\n        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Service Duration\",\n          \"value\": \"3-6 hours\"\n        },\n        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Setup Time\",\n          \"value\": \"60-90 minutes\"\n        },\n        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Capture Rate\",\n          \"value\": \"Up to 30 people per hour\"\n        },\n        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Space Required\",\n          \"value\": \"4\' x 4\' minimum\"\n        },\n        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Delivery Method\",\n          \"value\": \"Instant digital delivery, post-event online gallery\"\n        },\n        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Photo Retouching\",\n          \"value\": \"Basic to professional retouching available\"\n        }\n      ]\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"Service\",\n      \"serviceType\": \"Professional Headshot Photography\",\n      \"provider\": {\n        \"@type\": \"LocalBusiness\",\n        \"name\": \"MiHi Entertainment\",\n        \"url\": \"https://www.mihientertainment.com\"\n      },\n      \"areaServed\": {\n        \"@type\": \"Country\",\n        \"name\": \"United States\"\n      },\n      \"description\": \"Studio-quality professional headshot rental service for corporate events, trade shows, and business portraits. On-site photography with expert lighting, instant touch-ups, pose coaching, and polished digital delivery.\",\n      \"serviceOutput\": \"Professional headshot photos with instant digital delivery and post-event online gallery\",\n      \"offers\": {\n        \"@type\": \"Offer\",\n        \"priceCurrency\": \"USD\",\n        \"availability\": \"https://schema.org/InStock\"\n      },\n      \"aggregateRating\": {\n        \"@type\": \"AggregateRating\",\n        \"ratingValue\": \"5\",\n        \"reviewCount\": \"30\"\n      },\n      \"hasOfferCatalog\": {\n        \"@type\": \"OfferCatalog\",\n        \"name\": \"Professional Headshot Packages\",\n        \"itemListElement\": [\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Basic Package\",\n              \"description\": \"Up to 3 hours with professional photographer, basic lighting, and instant digital delivery\"\n            }\n          },\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Recommended Package\",\n              \"description\": \"Up to 4 hours with photographer and assistant, enhanced lighting, basic retouching, and enhanced branding\"\n            }\n          },\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Brand Activation Package\",\n              \"description\": \"Up to 6 hours with two photographers, studio-quality lighting, professional retouching, and custom branded backdrop\"\n            }\n          }\n        ]\n      }\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"WebSite\",\n      \"name\": \"MiHi Entertainment\",\n      \"url\": \"https://www.mihientertainment.com\",\n      \"potentialAction\": {\n        \"@type\": \"SearchAction\",\n        \"target\": {\n          \"@type\": \"EntryPoint\",\n          \"urlTemplate\": \"https://www.mihientertainment.com/search?q={search_term_string}\"\n        },\n        \"query-input\": \"required name=search_term_string\"\n      }\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"BreadcrumbList\",\n      \"itemListElement\": [\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 1,\n          \"name\": \"Home\",\n          \"item\": \"https://www.mihientertainment.com/\"\n        },\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 2,\n          \"name\": \"Products\",\n          \"item\": \"https://www.mihientertainment.com/our-booths.html\"\n        },\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 3,\n          \"name\": \"Professional Headshots\",\n          \"item\": \"https://www.mihientertainment.com/product/professional-headshots.html\"\n        }\n      ]\n    }\n    </script>\n\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <!-- Performance Optimizations -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link rel=\"dns-prefetch\" href=\"https://cdn.tailwindcss.com\">\n\n    <!-- Brand Guide Typography: Azo Sans Font Family -->\n    <style>\n        /* Azo Sans Font Face Declarations */\n        @font-face {\n            font-family: \'Azo Sans\';\n            src: url(\'../../assets/fonts/AzoSans-Regular.woff2\') format(\'woff2\'),\n                url(\'../../assets/fonts/AzoSans-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        @font-face {\n            font-family: \'Azo Sans Uber\';\n            src: url(\'../../assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\'),\n                url(\'../../assets/fonts/AzoSansUber-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        /* Brand Guide: Body Text - Azo Sans Regular */\n        body {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n            background: #ffffff;\n            line-height: 1.7;\n            overflow-x: hidden;\n        }\n\n        p {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n        }\n\n        /* Brand Guide: Headers - Azo Sans Uber (Uppercase) */\n        main h1,\n        main h2,\n        main h3,\n        main h4,\n        main h5,\n        main h6 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-weight: 400;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            color: #FF4F4F;\n            -webkit-font-smoothing: antialiased;\n            -moz-osx-font-smoothing: grayscale;\n        }\n\n        /* Brand Guide: CTAs use Coral (#FF4F4F) */\n        .btn-primary {\n            background: #FF4F4F;\n            color: #ffffff;\n            transition: all 0.3s ease;\n        }\n\n        .btn-primary:hover {\n            background: #e63939;\n            transform: translateY(-2px);\n            box-shadow: 0 20px 40px rgba(255, 79, 79, 0.4);\n        }\n\n        .section-padding {\n            padding: 4rem 0;\n        }\n\n        @media (min-width: 640px) {\n            .section-padding {\n                padding: 5rem 0;\n            }\n        }\n\n        @media (min-width: 768px) {\n            .section-padding {\n                padding: 8rem 0;\n            }\n        }\n\n        @media (min-width: 1024px) {\n            .section-padding {\n                padding: 10rem 0;\n            }\n        }\n\n        /* Premium Professional Gradient */\n        @keyframes professional-shift {\n\n            0%,\n            100% {\n                background-position: 0% 50%;\n            }\n\n            50% {\n                background-position: 100% 50%;\n            }\n        }\n\n        .professional-gradient {\n            background: linear-gradient(135deg, #0f172a 0%, #1e293b 25%, #334155 50%, #475569 75%, #64748b 100%);\n            background-size: 400% 400%;\n            animation: professional-shift 20s ease infinite;\n            position: relative;\n        }\n\n        .professional-gradient::before {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: radial-gradient(circle at 20% 50%, rgba(30, 64, 175, 0.15) 0%, transparent 50%),\n                radial-gradient(circle at 80% 80%, rgba(59, 130, 246, 0.1) 0%, transparent 50%);\n        }\n\n        /* Premium Glassmorphism */\n        .glass-premium {\n            background: rgba(255, 255, 255, 0.05);\n            backdrop-filter: blur(20px) saturate(180%);\n            border: 1px solid rgba(255, 255, 255, 0.18);\n            box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.15);\n        }\n\n        /* Professional Card with Premium Effect */\n        .professional-card {\n            transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);\n            position: relative;\n            overflow: hidden;\n        }\n\n        .professional-card::before {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: linear-gradient(135deg, rgba(30, 64, 175, 0.03) 0%, rgba(59, 130, 246, 0.03) 100%);\n            opacity: 0;\n            transition: opacity 0.5s ease;\n        }\n\n        .professional-card:hover::before {\n            opacity: 1;\n        }\n\n        .professional-card:hover {\n            transform: translateY(-8px) scale(1.02);\n            box-shadow: 0 25px 60px rgba(30, 64, 175, 0.2);\n        }\n\n        /* Premium Package Card */\n        .package-card {\n            transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);\n            position: relative;\n            overflow: hidden;\n            background: linear-gradient(135deg, #ffffff 0%, #f8fafc 100%);\n            border: 1px solid rgba(226, 232, 240, 1);\n        }\n\n        .package-card::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: -100%;\n            width: 100%;\n            height: 100%;\n            background: linear-gradient(90deg, transparent, rgba(30, 64, 175, 0.08), transparent);\n            transition: left 0.7s ease;\n        }\n\n        .package-card:hover::before {\n            left: 100%;\n        }\n\n        .package-card:hover {\n            transform: translateY(-12px);\n            box-shadow: 0 30px 70px rgba(30, 64, 175, 0.25);\n            border-color: rgba(30, 64, 175, 0.3);\n        }\n\n        .package-recommended {\n            border: 2px solid #1e40af;\n            box-shadow: 0 0 0 1px rgba(30, 64, 175, 0.1), 0 25px 60px rgba(30, 64, 175, 0.25);\n            background: linear-gradient(135deg, #ffffff 0%, #eff6ff 100%);\n            position: relative;\n        }\n\n        .package-recommended::after {\n            content: \'RECOMMENDED\';\n            position: absolute;\n            top: -14px;\n            left: 50%;\n            transform: translateX(-50%);\n            background: linear-gradient(135deg, #1e40af 0%, #1e3a8a 100%);\n            color: white;\n            padding: 6px 24px;\n            border-radius: 25px;\n            font-size: 11px;\n            font-weight: 700;\n            letter-spacing: 2px;\n            box-shadow: 0 5px 20px rgba(30, 64, 175, 0.4);\n        }\n\n        /* Enhanced Package Card Styles */\n        .package-card-enhanced {\n            transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);\n            position: relative;\n            overflow: visible;\n        }\n\n        .package-card-enhanced::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: -100%;\n            width: 100%;\n            height: 100%;\n            background: linear-gradient(90deg, transparent, rgba(30, 64, 175, 0.05), transparent);\n            transition: left 0.8s ease;\n            z-index: 1;\n        }\n\n        .package-card-enhanced:hover::before {\n            left: 100%;\n        }\n\n        .package-card-enhanced:hover {\n            transform: translateY(-15px) scale(1.02);\n            box-shadow: 0 35px 80px rgba(30, 64, 175, 0.2), 0 0 0 1px rgba(30, 64, 175, 0.1);\n        }\n\n        .package-recommended-enhanced {\n            border: 2px solid #1e40af;\n            box-shadow: 0 0 0 1px rgba(30, 64, 175, 0.15), 0 30px 70px rgba(30, 64, 175, 0.3);\n            position: relative;\n        }\n\n        .package-recommended-enhanced:hover {\n            transform: translateY(-18px) scale(1.03);\n            box-shadow: 0 40px 90px rgba(30, 64, 175, 0.35), 0 0 0 1px rgba(30, 64, 175, 0.2);\n        }\n\n        /* Package Icon */\n        .package-icon {\n            transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);\n            transform-origin: center;\n        }\n\n        .package-card-enhanced:hover .package-icon {\n            transform: rotate(5deg) scale(1.1);\n        }\n\n        .package-icon-premium {\n            box-shadow: 0 15px 40px rgba(30, 64, 175, 0.3);\n        }\n\n        .package-card-enhanced:hover .package-icon-premium {\n            transform: rotate(8deg) scale(1.15);\n            box-shadow: 0 20px 50px rgba(30, 64, 175, 0.4);\n        }\n\n        /* Enhanced Check Icon */\n        .check-icon-enhanced {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            width: 28px;\n            height: 28px;\n            background: linear-gradient(135deg, #1e40af 0%, #1e3a8a 100%);\n            color: white;\n            border-radius: 50%;\n            font-size: 14px;\n            font-weight: bold;\n            flex-shrink: 0;\n            box-shadow: 0 4px 12px rgba(30, 64, 175, 0.3);\n            transition: all 0.3s ease;\n        }\n\n        .check-icon-premium {\n            background: linear-gradient(135deg, #2563eb 0%, #1e40af 100%);\n            box-shadow: 0 5px 15px rgba(30, 64, 175, 0.4);\n            width: 30px;\n            height: 30px;\n        }\n\n        li:hover .check-icon-enhanced {\n            transform: scale(1.15) rotate(5deg);\n            box-shadow: 0 6px 18px rgba(30, 64, 175, 0.4);\n        }\n\n        /* Premium Check Icon */\n        .check-icon {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            width: 26px;\n            height: 26px;\n            background: linear-gradient(135deg, #1e40af 0%, #1e3a8a 100%);\n            color: white;\n            border-radius: 50%;\n            font-size: 14px;\n            font-weight: bold;\n            flex-shrink: 0;\n            box-shadow: 0 4px 12px rgba(30, 64, 175, 0.3);\n        }\n\n        /* Premium Professional Badge */\n        .professional-badge {\n            background: rgba(255, 255, 255, 0.12);\n            backdrop-filter: blur(20px) saturate(180%);\n            border: 1px solid rgba(255, 255, 255, 0.25);\n            box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.2);\n        }\n\n        /* Premium Feature Icon */\n        .feature-icon {\n            width: 64px;\n            height: 64px;\n            background: #18F1E1;\n            border-radius: 16px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            box-shadow: 0 12px 30px rgba(30, 41, 59, 0.4);\n            transition: all 0.4s ease;\n        }\n\n        .professional-card:hover .feature-icon {\n            transform: rotate(5deg) scale(1.1);\n            box-shadow: 0 15px 40px rgba(30, 41, 59, 0.5);\n        }\n\n        /* Premium Elegant Divider */\n        .elegant-divider {\n            height: 1px;\n            background: linear-gradient(90deg,\n                    transparent 0%,\n                    rgba(226, 232, 240, 0.5) 20%,\n                    rgba(30, 64, 175, 0.3) 50%,\n                    rgba(226, 232, 240, 0.5) 80%,\n                    transparent 100%);\n            margin: 6rem 0;\n            position: relative;\n        }\n\n        .elegant-divider::after {\n            content: \'\';\n            position: absolute;\n            top: 50%;\n            left: 50%;\n            transform: translate(-50%, -50%);\n            width: 120px;\n            height: 1px;\n            background: linear-gradient(90deg, transparent, #1e40af, transparent);\n        }\n\n        /* Premium Tech Spec Card */\n        .tech-spec-card {\n            background: linear-gradient(135deg, #ffffff 0%, #f8fafc 100%);\n            border: 1px solid rgba(226, 232, 240, 1);\n            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n            position: relative;\n            overflow: hidden;\n        }\n\n        .tech-spec-card::before {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: linear-gradient(135deg, rgba(30, 64, 175, 0.05) 0%, transparent 100%);\n            opacity: 0;\n            transition: opacity 0.4s ease;\n        }\n\n        .tech-spec-card:hover::before {\n            opacity: 1;\n        }\n\n        .tech-spec-card:hover {\n            border-color: rgba(30, 64, 175, 0.4);\n            box-shadow: 0 15px 40px rgba(30, 64, 175, 0.15);\n            transform: translateY(-4px);\n        }\n\n        /* Premium Image Overlay */\n        .premium-image-wrapper {\n            position: relative;\n            overflow: hidden;\n            border-radius: 24px;\n        }\n\n        .premium-image-wrapper::after {\n            content: \'\';\n            position: absolute;\n            inset: 0;\n            background: linear-gradient(135deg, rgba(30, 64, 175, 0.05) 0%, transparent 100%);\n            opacity: 0;\n            transition: opacity 0.5s ease;\n        }\n\n        .premium-image-wrapper:hover::after {\n            opacity: 1;\n        }\n\n        .premium-image-wrapper img {\n            transition: transform 0.7s cubic-bezier(0.4, 0, 0.2, 1);\n        }\n\n        .premium-image-wrapper:hover img {\n            transform: scale(1.05);\n        }\n\n        /* Premium Typography */\n        .text-premium {\n            background: linear-gradient(135deg, #0f172a 0%, #1e293b 50%, #334155 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n        }\n\n        /* Floating Animation */\n        @keyframes float {\n\n            0%,\n            100% {\n                transform: translateY(0px);\n            }\n\n            50% {\n                transform: translateY(-20px);\n            }\n        }\n\n        .float-animation {\n            animation: float 6s ease-in-out infinite;\n        }\n\n        /* Premium Section Backgrounds */\n        .section-premium-light {\n            background: linear-gradient(135deg, #ffffff 0%, #f8fafc 50%, #f1f5f9 100%);\n        }\n\n        .section-premium-dark {\n            background: linear-gradient(135deg, #0f172a 0%, #1e293b 50%, #334155 100%);\n        }\n\n        /* Premium Badge */\n        .badge-premium {\n            display: inline-flex;\n            align-items: center;\n            gap: 4px;\n            padding: 6px 12px;\n            background: rgba(255, 255, 255, 0.15);\n            backdrop-filter: blur(20px);\n            border: 1px solid rgba(255, 255, 255, 0.25);\n            border-radius: 50px;\n            font-size: 10px;\n            font-weight: 600;\n            letter-spacing: 0.5px;\n            text-transform: uppercase;\n            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);\n        }\n\n        @media (min-width: 640px) {\n            .badge-premium {\n                gap: 8px;\n                padding: 10px 24px;\n                font-size: 13px;\n                letter-spacing: 1.5px;\n            }\n        }\n\n        /* Premium Shadow */\n        .shadow-premium {\n            box-shadow: 0 25px 60px -12px rgba(0, 0, 0, 0.15), 0 0 0 1px rgba(0, 0, 0, 0.05);\n        }\n\n        .shadow-premium-lg {\n            box-shadow: 0 35px 80px -12px rgba(0, 0, 0, 0.2), 0 0 0 1px rgba(0, 0, 0, 0.05);\n        }\n\n        /* Premium Auto-Scrolling Photo Gallery */\n        .headshot-gallery-container {\n            overflow: hidden;\n            position: relative;\n            width: 100%;\n            mask-image: linear-gradient(to right, transparent 0%, black 5%, black 95%, transparent 100%);\n            -webkit-mask-image: linear-gradient(to right, transparent 0%, black 5%, black 95%, transparent 100%);\n        }\n\n        .headshot-gallery-scroll {\n            display: flex;\n            gap: 1.5rem;\n            width: fit-content;\n            animation: scroll-right-to-left 40s linear infinite;\n        }\n\n        .headshot-gallery-scroll:hover {\n            animation-play-state: paused;\n        }\n\n        @keyframes scroll-right-to-left {\n            0% {\n                transform: translateX(0);\n            }\n\n            100% {\n                transform: translateX(-50%);\n            }\n        }\n\n        .headshot-gallery-item {\n            flex-shrink: 0;\n            width: 280px;\n        }\n\n        @media (min-width: 640px) {\n            .headshot-gallery-item {\n                width: 320px;\n            }\n        }\n\n        @media (min-width: 1024px) {\n            .headshot-gallery-item {\n                width: 360px;\n            }\n        }\n\n        /* Mobile Optimizations */\n        @media (max-width: 640px) {\n            .premium-image-wrapper img {\n                max-width: 100%;\n                height: auto;\n            }\n\n            .professional-card {\n                padding: 1rem;\n            }\n\n            .tech-spec-card {\n                padding: 1.25rem;\n            }\n\n            .package-card {\n                margin-bottom: 1.5rem;\n            }\n\n            /* Hero Image Mobile Optimizations */\n            section[class*=\"hero\"] img[alt*=\"Professional Headshot Hero\"] {\n                object-position: center 40%;\n            }\n\n            /* Enhanced Hero Section Mobile */\n            section[class*=\"hero\"] {\n                min-height: 90vh !important;\n            }\n\n            section[class*=\"hero\"] h1 {\n                letter-spacing: -0.02em;\n            }\n\n            section[class*=\"hero\"] .btn-primary,\n            section[class*=\"hero\"] button[data-click-to-call] {\n                min-height: 52px;\n                box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);\n            }\n\n            section[class*=\"hero\"] .btn-primary:hover,\n            section[class*=\"hero\"] button[data-click-to-call]:hover {\n                transform: translateY(-2px);\n                box-shadow: 0 15px 40px rgba(0, 0, 0, 0.4);\n            }\n\n            section[class*=\"hero\"] p {\n                text-shadow: 1px 1px 10px rgba(0, 0, 0, 0.4) !important;\n            }\n        }\n\n        /* Additional Mobile Enhancements for Hero */\n        @media (max-width: 480px) {\n            section[class*=\"hero\"] h1 {\n                font-size: 2.75rem !important;\n                line-height: 1.1 !important;\n            }\n\n            section[class*=\"hero\"] .container {\n                padding-top: 3rem;\n                padding-bottom: 3rem;\n            }\n        }\n    </style>\n</head>\n\n<body class=\"bg-white\">\n    <!-- Navigation -->\n    <script src=\"../../assets/components/navigation.js\"></script>\n\n    <main>\n        <!-- Hero Section -->\n        <section class=\"relative text-white overflow-hidden h-screen flex items-center\">\n            <!-- Background Image with Parallax Effect -->\n            <div class=\"absolute inset-0 z-0\">\n                <img src=\"../../assets/images/event-photography-1.webp\"\n                    alt=\"Professional headshot photography service at corporate event\" width=\"1920\" height=\"1080\"\n                    class=\"w-full h-full object-cover object-center scale-100 sm:scale-105 md:scale-110 transition-transform duration-[20s] ease-out hidden sm:block\"\n                    loading=\"eager\" fetchpriority=\"high\">\n                <!-- Premium Gradient Overlay -->\n                <div class=\"absolute inset-0 professional-gradient opacity-95\"></div>\n                <!-- Additional Sophisticated Overlay -->\n                <img src=\"../../assets/images/headshot/professional-headshot-hero.webp\"\n                    alt=\"Professional headshot rental service with studio-quality lighting and expert photographer\"\n                    width=\"1920\" height=\"1080\"\n                    class=\"absolute inset-0 w-full h-full object-cover object-center sm:object-center\" loading=\"eager\"\n                    fetchpriority=\"high\">\n                <!-- Premium Light Accents -->\n                <div\n                    class=\"absolute top-1/4 right-1/4 w-48 h-48 sm:w-64 sm:h-64 md:w-96 md:h-96 bg-blue-600/10 rounded-full blur-3xl float-animation\">\n                </div>\n                <div class=\"absolute bottom-1/4 left-1/4 w-48 h-48 sm:w-64 sm:h-64 md:w-96 md:h-96 bg-indigo-600/10 rounded-full blur-3xl float-animation\"\n                    style=\"animation-delay: 2s;\"></div>\n            </div>\n\n            <div class=\"container mx-auto px-4 sm:px-6 pt-20 relative z-10 w-full\">\n                <div class=\"max-w-6xl mx-auto text-center\">\n\n                    <!-- Main Title -->\n                    <h1 class=\"text-4xl sm:text-6xl md:text-7xl lg:text-8xl font-black mb-6 leading-tight\">\n                        <span class=\"block drop-shadow-2xl\"\n                            style=\"color: #FF4F4F; text-shadow: 2px 2px 20px rgba(0, 0, 0, 0.5), 0 0 60px rgba(255, 79, 79, 0.4);\">\n                            Professional\n                        </span>\n                        <span class=\"block drop-shadow-2xl\"\n                            style=\"color: #18F1E1; text-shadow: 2px 2px 20px rgba(0, 0, 0, 0.5), 0 0 60px rgba(24, 241, 225, 0.4);\">\n                            Headshots\n                        </span>\n                    </h1>\n\n                    <!-- Description -->\n                    <div class=\"max-w-3xl mx-auto mb-8 px-4\">\n                        <p class=\"text-lg sm:text-xl md:text-2xl leading-relaxed text-white/95 font-light drop-shadow-lg\"\n                            style=\"text-shadow: 1px 1px 10px rgba(0, 0, 0, 0.4);\">\n                            Give your guests studio-quality professional headshots on-site with expert lighting, instant\n                            touch-ups, and polished digital delivery.\n                        </p>\n                    </div>\n\n                    <!-- CTA Buttons -->\n                    <div class=\"flex flex-col sm:flex-row gap-4 sm:gap-6 justify-center items-center px-4\">\n                        <a href=\"../contact-us.html\"\n                            class=\"btn-primary text-white px-8 py-4 rounded-full text-lg font-bold hover:scale-105 transition-all duration-300 shadow-2xl w-full sm:w-auto\">\n                            Get Your Quote\n                        </a>\n                        <button type=\"button\" data-click-to-call data-call-text=\"Call Us\"\n                            class=\"group inline-flex items-center gap-2 sm:gap-3 px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg  backdrop-blur-md bg-white/10 border-2 shadow-xl hover:shadow-2xl transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 text-white w-full sm:w-auto justify-center cursor-pointer\"\n                            style=\"border-color: rgba(24, 241, 225, 0.5);\"\n                            onmouseover=\"this.style.borderColor=\'rgba(24, 241, 225, 0.7)\'; this.style.background=\'rgba(24, 241, 225, 0.2)\';\"\n                            onmouseout=\"this.style.borderColor=\'rgba(24, 241, 225, 0.5)\'; this.style.background=\'rgba(255, 255, 255, 0.1)\';\">\n                            <svg class=\"w-4 h-4 sm:w-5 sm:h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                    d=\"M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498A1 1 0 0121 17.72V21a2 2 0 01-2 2h-1C9.716 23 3 16.284 3 8V7a2 2 0 012-2z\">\n                                </path>\n                            </svg>\n                            <span>Call Us</span>\n                        </button>\n                    </div>\n\n                    <!-- Trust Indicators -->\n                    <div\n                        class=\"flex flex-wrap items-center justify-center gap-4 sm:gap-8 mt-8 sm:mt-12 text-white/70 px-4\">\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-blue-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">Professional Lighting</span>\n                        </div>\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-indigo-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">Instant Touch-Ups</span>\n                        </div>\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-cyan-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">Digital Delivery</span>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Studio Quality Photos Gallery Section -->\n        <section class=\"section-padding section-premium-light relative overflow-hidden\">\n            <div class=\"container mx-auto px-4 sm:px-6 relative z-10\">\n                <div class=\"mx-auto\">\n                    <div class=\"text-center mb-10 md:mb-16\">\n                        <h2 class=\"text-3xl sm:text-4xl md:text-5xl font-bold mb-6 md:mb-8 leading-tight\">\n                            <span style=\"colo