        {\n          \"@type\": \"PropertyValue\",\n          \"name\": \"Equipment\",\n          \"value\": \"DSLR or iPad\"\n        }\n      ]\n    }\n    </script>\n    \n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"Service\",\n      \"serviceType\": \"Roaming Photo Booth Rental\",\n      \"provider\": {\n        \"@type\": \"LocalBusiness\",\n        \"name\": \"MiHi Entertainment\",\n        \"url\": \"https://www.mihientertainment.com\"\n      },\n      \"areaServed\": {\n        \"@type\": \"Country\",\n        \"name\": \"United States\"\n      },\n      \"description\": \"Mobile roaming photo booth rental service with professional photographers. Capture high-quality photos, GIFs, and Boomerangs throughout your event without wait lines. Instant digital sharing and unlimited venue coverage.\",\n      \"serviceOutput\": \"High-quality photos, GIFs, Boomerangs with instant digital sharing and optional printing\",\n      \"offers\": {\n        \"@type\": \"Offer\",\n        \"priceCurrency\": \"USD\",\n        \"availability\": \"https://schema.org/InStock\"\n      },\n      \"aggregateRating\": {\n        \"@type\": \"AggregateRating\",\n        \"ratingValue\": \"5\",\n        \"reviewCount\": \"30\"\n      },\n      \"hasOfferCatalog\": {\n        \"@type\": \"OfferCatalog\",\n        \"name\": \"Roaming Photo Booth Packages\",\n        \"itemListElement\": [\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Basic Package\",\n              \"description\": \"Up to 3 hours with ring light roamer booth and instant digital sharing\"\n            }\n          },\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Recommended Package\",\n              \"description\": \"Up to 4 hours with DSLR roamer booth, flash photography, and slideshow\"\n            }\n          },\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Brand Activation Package\",\n              \"description\": \"Up to 6 hours with two photographers, live streaming, and custom branding\"\n            }\n          }\n        ]\n      }\n    }\n    </script>\n    \n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"WebSite\",\n      \"name\": \"MiHi Entertainment\",\n      \"url\": \"https://www.mihientertainment.com\",\n      \"potentialAction\": {\n        \"@type\": \"SearchAction\",\n        \"target\": {\n          \"@type\": \"EntryPoint\",\n          \"urlTemplate\": \"https://www.mihientertainment.com/search?q={search_term_string}\"\n        },\n        \"query-input\": \"required name=search_term_string\"\n      }\n    }\n    </script>\n    \n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"BreadcrumbList\",\n      \"itemListElement\": [\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 1,\n          \"name\": \"Home\",\n          \"item\": \"https://www.mihientertainment.com/\"\n        },\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 2,\n          \"name\": \"Products\",\n          \"item\": \"https://www.mihientertainment.com/our-booths.html\"\n        },\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 3,\n          \"name\": \"Roaming Photo Booth\",\n          \"item\": \"https://www.mihientertainment.com/product/roaming-photo-booth.html\"\n        }\n      ]\n    }\n    </script>\n    \n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <!-- Brand Guide Typography: Azo Sans Font Family -->\n    <style>\n        /* Azo Sans Font Face Declarations */\n        @font-face {\n            font-family: \'Azo Sans\';\n            src: url(\'../../assets/fonts/AzoSans-Regular.woff2\') format(\'woff2\'),\n                 url(\'../../assets/fonts/AzoSans-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        @font-face {\n            font-family: \'Azo Sans Uber\';\n            src: url(\'../../assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\'),\n                 url(\'../../assets/fonts/AzoSansUber-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        /* Brand Guide: Body Text - Azo Sans Regular */\n        body {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n        }\n\n        p {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n        }\n\n        /* Brand Guide: Headers - Azo Sans Uber (Uppercase) */\n        main h1,\n        main h2,\n        main h3,\n        main h4,\n        main h5,\n        main h6 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-weight: 400;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            color: #FF4F4F;\n            -webkit-font-smoothing: antialiased;\n            -moz-osx-font-smoothing: grayscale;\n        }\n\n        /* Navigation button styling - ensure it has proper background */\n        header .btn-primary,\n        header nav .btn-primary,\n        nav .btn-primary {\n            background: linear-gradient(135deg, #0050ff 0%, #0040d9 100%) !important;\n            transition: all 0.3s ease;\n        }\n\n        header .btn-primary:hover,\n        header nav .btn-primary:hover,\n        nav .btn-primary:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(0, 80, 255, 0.4);\n        }\n\n        /* Scoped to main content only to avoid affecting navigation */\n        main .btn-primary {\n            background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);\n            transition: all 0.3s ease;\n        }\n\n        main .btn-primary:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 10px 25px rgba(245, 158, 11, 0.4);\n        }\n\n        .section-padding {\n            padding: 5rem 0;\n        }\n\n        @media (min-width: 768px) {\n            .section-padding {\n                padding: 8rem 0;\n            }\n        }\n\n        @keyframes gradient-shift {\n            0%, 100% {\n                background-position: 0% 50%;\n            }\n            50% {\n                background-position: 100% 50%;\n            }\n        }\n\n        .animated-gradient-yellow {\n            background: linear-gradient(-45deg, #f59e0b, #d97706, #b45309, #92400e);\n            background-size: 400% 400%;\n            animation: gradient-shift 15s ease infinite;\n        }\n\n        @keyframes gradient-text {\n            0%, 100% {\n                background-position: 0% 50%;\n            }\n            50% {\n                background-position: 100% 50%;\n            }\n        }\n\n        .animated-gradient-text {\n            background-size: 200% auto;\n            animation: gradient-text 3s ease infinite;\n        }\n\n        .glass {\n            background: rgba(255, 255, 255, 0.1);\n            backdrop-filter: blur(10px);\n            border: 1px solid rgba(255, 255, 255, 0.2);\n        }\n\n        .package-card {\n            transition: all 0.3s ease;\n        }\n\n        .package-card:hover {\n            transform: translateY(-8px);\n            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);\n        }\n\n        .package-featured {\n            border: 2px solid #f59e0b;\n            position: relative;\n        }\n\n        .package-featured::before {\n            content: \'RECOMMENDED\';\n            position: absolute;\n            top: -12px;\n            left: 50%;\n            transform: translateX(-50%);\n            background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);\n            color: white;\n            padding: 4px 20px;\n            border-radius: 20px;\n            font-size: 12px;\n            font-weight: 400;\n        }\n\n        @keyframes float {\n            0%, 100% {\n                transform: translateY(0px);\n            }\n            50% {\n                transform: translateY(-20px);\n            }\n        }\n\n        .animate-float {\n            animation: float 6s ease-in-out infinite;\n        }\n\n        @keyframes blob {\n            0%, 100% {\n                transform: translate(0px, 0px) scale(1);\n            }\n            33% {\n                transform: translate(30px, -50px) scale(1.1);\n            }\n            66% {\n                transform: translate(-20px, 20px) scale(0.9);\n            }\n        }\n\n        .animate-blob {\n            animation: blob 7s infinite;\n        }\n\n        .animation-delay-2000 {\n            animation-delay: 2s;\n        }\n\n        .animation-delay-4000 {\n            animation-delay: 4s;\n        }\n\n        .feature-icon {\n            width: 64px;\n            height: 64px;\n            background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);\n            border-radius: 16px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            margin-bottom: 1.5rem;\n        }\n\n        .tech-spec-card {\n            background: linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%);\n            border: 1px solid #e2e8f0;\n            transition: all 0.3s ease;\n        }\n\n        .tech-spec-card:hover {\n            background: linear-gradient(135deg, #ffffff 0%, #f8fafc 100%);\n            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);\n            transform: translateY(-4px);\n        }\n\n        /* Roaming movement animations for dynamic feel */\n        @keyframes roamLeft {\n            0%, 100% { transform: translateX(0px); }\n            25% { transform: translateX(-8px); }\n            75% { transform: translateX(8px); }\n        }\n\n        @keyframes roamRight {\n            0%, 100% { transform: translateX(0px); }\n            25% { transform: translateX(8px); }\n            75% { transform: translateX(-8px); }\n        }\n\n        @keyframes roamUp {\n            0%, 100% { transform: translateY(0px); }\n            50% { transform: translateY(-12px); }\n        }\n\n        /* Add subtle roaming effect to feature icons */\n        .feature-icon svg {\n            animation: roamLeft 6s ease-in-out infinite;\n        }\n\n        .feature-icon:nth-child(even) svg {\n            animation: roamRight 7s ease-in-out infinite;\n        }\n\n        /* Add roaming effect to floating elements */\n        .roam-element {\n            animation: roamUp 8s ease-in-out infinite;\n        }\n\n        /* Auto-scrolling roaming gallery */\n        .roaming-gallery-container {\n            overflow: hidden;\n            position: relative;\n            width: 100%;\n            mask-image: linear-gradient(to right, transparent 0%, black 5%, black 95%, transparent 100%);\n            -webkit-mask-image: linear-gradient(to right, transparent 0%, black 5%, black 95%, transparent 100%);\n        }\n\n        .roaming-gallery-scroll {\n            display: flex;\n            gap: 1.5rem;\n            width: fit-content;\n            animation: scroll-right-to-left 40s linear infinite;\n        }\n\n        .roaming-gallery-scroll:hover {\n            animation-play-state: paused;\n        }\n\n        @keyframes scroll-right-to-left {\n            0% {\n                transform: translateX(0);\n            }\n            100% {\n                transform: translateX(-50%);\n            }\n        }\n\n        .roaming-gallery-item {\n            flex-shrink: 0;\n            width: 280px;\n        }\n\n        @media (min-width: 640px) {\n            .roaming-gallery-item {\n                width: 320px;\n            }\n        }\n\n        @media (min-width: 1024px) {\n            .roaming-gallery-item {\n                width: 360px;\n            }\n        }\n       \n    </style>\n</head>\n<body class=\"bg-white\">\n    <main>\n        \n        <!-- Hero Section -->\n        <section class=\"relative h-screen flex items-center justify-center overflow-hidden\">\n            <!-- Background Image -->\n            <div class=\"absolute inset-0\">\n                <img src=\"../../assets/images/roaming/roaming-hero.webp\" \n                     alt=\"Mobile roaming photo booth with professional photographer capturing event moments\" \n                     width=\"1920\" height=\"1080\" \n                     class=\"w-full h-full object-cover\" \n                     loading=\"eager\" \n                     fetchpriority=\"high\">\n            </div>\n            <div class=\"absolute inset-0 bg-gradient-to-b from-black/50 via-black/40 to-black/60\"></div>\n            <div class=\"absolute top-20 left-10 w-96 h-96 bg-yellow-500/20 rounded-full blur-3xl animate-blob\"></div>\n            <div class=\"absolute bottom-20 right-10 w-96 h-96 bg-amber-600/20 rounded-full blur-3xl animate-blob animation-delay-2000\"></div>\n            <div class=\"absolute top-1/2 left-1/4 w-72 h-72 bg-orange-500/15 rounded-full blur-2xl animate-blob animation-delay-4000\"></div>\n\n            <!-- Moving elements to represent roaming -->\n            <div class=\"absolute top-1/3 right-1/4 w-24 h-24 bg-yellow-400/30 rounded-full blur-xl animate-float\" style=\"animation-duration: 4s;\"></div>\n            <div class=\"absolute bottom-1/3 left-1/3 w-16 h-16 bg-amber-400/25 rounded-full blur-lg animate-float\" style=\"animation-duration: 3s; animation-delay: 1s;\"></div>\n            <div class=\"absolute top-2/3 right-1/3 w-20 h-20 bg-orange-400/20 rounded-full blur-lg animate-float\" style=\"animation-duration: 5s; animation-delay: 2s;\"></div>\n\n            <div class=\"relative z-10 container mx-auto px-4 sm:px-6 pt-20\">\n                <div class=\"max-w-6xl mx-auto text-center\">\n\n                    <!-- Main Title -->\n                    <h1 class=\"text-5xl sm:text-6xl md:text-7xl lg:text-8xl font-normal mb-6 leading-tight\"\n                        style=\"font-weight: 400; text-shadow: 2px 2px 8px rgba(0,0,0,0.7);\">\n                        <span class=\"block\">ROAMING PHOTO</span><span class=\"block\" style=\"color: #18F1E1;\">BOOTH RENTALS</span>\n                    </h1>\n\n                    <!-- Description -->\n                    <div class=\"max-w-3xl mx-auto mb-8 px-4\">\n                        <p class=\"text-lg sm:text-xl md:text-2xl mb-8 leading-relaxed text-white/95 font-light drop-shadow-lg\">\n                            Bring the camera straight to your guests with our Roaming Photo Booth! Our mobile photographers capture high-quality candid shots, GIFs, and boomerangs, delivering instant digital sharing without guests waiting in line.\n                        </p>\n                    </div>\n\n                    <!-- CTA Buttons -->\n                    <div class=\"flex flex-col sm:flex-row gap-4 sm:gap-6 justify-center items-center px-4\">\n                        <a href=\"../contact-us.html\"\n                            class=\"group relative inline-flex items-center gap-2 sm:gap-3 px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg font-bold shadow-2xl hover:shadow-[#FF4F4F]/50 transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 overflow-hidden w-full sm:w-auto justify-center text-white\" style=\"background: #FF4F4F;\">\n                            <span class=\"relative z-10\">Get Your Quote</span>\n                        </a>\n                        <button type=\"button\" data-click-to-call data-call-text=\"Call Us\" \n                           class=\"group inline-flex items-center gap-2 sm:gap-3 px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg  backdrop-blur-md bg-white/10 border-2 shadow-xl hover:shadow-2xl transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 text-white w-full sm:w-auto justify-center cursor-pointer\" style=\"border-color: rgba(24, 241, 225, 0.5);\" onmouseover=\"this.style.borderColor=\'rgba(24, 241, 225, 0.7)\'; this.style.background=\'rgba(24, 241, 225, 0.2)\';\" onmouseout=\"this.style.borderColor=\'rgba(24, 241, 225, 0.5)\'; this.style.background=\'rgba(255, 255, 255, 0.1)\';\">\n                            <svg class=\"w-4 h-4 sm:w-5 sm:h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498A1 1 0 0121 17.72V21a2 2 0 01-2 2h-1C9.716 23 3 16.284 3 8V7a2 2 0 012-2z\"></path>\n                            </svg>\n                            <span>Call Us</span>\n                        </button>\n                    </div>\n\n                    <!-- Trust Indicators -->\n                    <div class=\"flex flex-wrap items-center justify-center gap-4 sm:gap-8 mt-8 sm:mt-12 text-white/70 px-4\">\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-yellow-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">Instant Digital Sharing</span>\n                        </div>\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-amber-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">Professional Photographers</span>\n                        </div>\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-orange-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">No Wait Lines</span>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Mobile Photo Experience Gallery Section -->\n        <section class=\"section-padding bg-gradient-to-b from-yellow-50 via-white to-amber-50 relative overflow-hidden\">\n            <div class=\"container mx-auto px-4 sm:px-6\">\n                <div class=\"mx-auto\">\n                    <div class=\"text-center mb-12 md:mb-16\">\n                        <h2 class=\"text-4xl md:text-5xl font-normal mb-4 md:mb-6\">\n                            MOBILE PHOTO EXPERIENCE <span style=\"color: #18F1E1;\">WITH INSTANT SHARING</span>\n                        </h2>\n                    </div>\n\n                    <div class=\"roaming-gallery-container\">\n                        <div class=\"roaming-gallery-scroll\">\n                            <!-- First set of gallery items -->\n                            <div class=\"roaming-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-yellow-200/60 transition-all duration-500\">\n                                <img src=\"../../assets/images/roaming/roaming-1.webp\" alt=\"Mobile roaming photographer capturing candid event moments\" width=\"360\" height=\"480\" class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\" loading=\"lazy\">\n                            </div>\n                            <div class=\"roaming-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-yellow-200/60 transition-all duration-500\">\n                                <img src=\"../../assets/images/roaming/roaming-2.webp\" alt=\"Roaming photo booth with instant