\n      ]\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"Service\",\n      \"serviceType\": \"Robot Photo Booth Rental\",\n      \"provider\": {\n        \"@type\": \"LocalBusiness\",\n        \"name\": \"MiHi Entertainment\",\n        \"url\": \"https://www.mihientertainment.com\"\n      },\n      \"areaServed\": {\n        \"@type\": \"Country\",\n        \"name\": \"United States\"\n      },\n      \"description\": \"AI-powered mobile robot photo booth rental service. Rosie the Robot interacts with guests, captures branded photos, and delivers instant digital images. Perfect for trade shows, corporate events, tech expos, and luxury events.\",\n      \"serviceOutput\": \"Digital photos with custom branding and instant sharing\",\n      \"offers\": {\n        \"@type\": \"Offer\",\n        \"priceCurrency\": \"USD\",\n        \"availability\": \"https://schema.org/InStock\"\n      },\n      \"aggregateRating\": {\n        \"@type\": \"AggregateRating\",\n        \"ratingValue\": \"5\",\n        \"reviewCount\": \"30\"\n      },\n      \"hasOfferCatalog\": {\n        \"@type\": \"OfferCatalog\",\n        \"name\": \"Rosie Robot Photo Booth Packages\",\n        \"itemListElement\": [\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Basic Package\",\n              \"description\": \"Up to 3 hours of service with Rosie the Robot\"\n            }\n          },\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Recommended Package\",\n              \"description\": \"Up to 4 hours with enhanced branding and slideshow\"\n            }\n          },\n          {\n            \"@type\": \"Offer\",\n            \"itemOffered\": {\n              \"@type\": \"Service\",\n              \"name\": \"Premium Package\",\n              \"description\": \"Up to 6 hours with custom wardrobe, all print sizes, and live streaming\"\n            }\n          }\n        ]\n      }\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"WebSite\",\n      \"name\": \"MiHi Entertainment\",\n      \"url\": \"https://www.mihientertainment.com\",\n      \"potentialAction\": {\n        \"@type\": \"SearchAction\",\n        \"target\": {\n          \"@type\": \"EntryPoint\",\n          \"urlTemplate\": \"https://www.mihientertainment.com/search?q={search_term_string}\"\n        },\n        \"query-input\": \"required name=search_term_string\"\n      }\n    }\n    </script>\n\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"BreadcrumbList\",\n      \"itemListElement\": [\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 1,\n          \"name\": \"Home\",\n          \"item\": \"https://www.mihientertainment.com/\"\n        },\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 2,\n          \"name\": \"Products\",\n          \"item\": \"https://www.mihientertainment.com/our-booths.html\"\n        },\n        {\n          \"@type\": \"ListItem\",\n          \"position\": 3,\n          \"name\": \"Rosie the Robot Photo Booth\",\n          \"item\": \"https://www.mihientertainment.com/product/rosie-the-robot-photo-booth.html\"\n        }\n      ]\n    }\n    </script>\n\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <style>\n        /* Azo Sans Font Face Declarations */\n        @font-face {\n            font-family: \'Azo Sans\';\n            src: url(\'../assets/fonts/AzoSans-Regular.woff2\') format(\'woff2\'),\n                url(\'../assets/fonts/AzoSans-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        @font-face {\n            font-family: \'Azo Sans Uber\';\n            src: url(\'../assets/fonts/AzoSansUber-Regular.woff2\') format(\'woff2\'),\n                url(\'../assets/fonts/AzoSansUber-Regular.woff\') format(\'woff\');\n            font-weight: 400;\n            font-style: normal;\n            font-display: swap;\n        }\n\n        /* Brand Guide: Body Text - Azo Sans Regular */\n        body {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n            overflow-x: hidden;\n            background: #ffffff;\n        }\n\n        p {\n            font-family: \'Azo Sans\', sans-serif;\n            color: #1F1F1F;\n        }\n\n        /* Brand Guide: Headers - Azo Sans Uber (Uppercase) */\n        main h1,\n        main h2,\n        main h3,\n        main h4,\n        main h5,\n        main h6 {\n            font-family: \'Azo Sans Uber\', sans-serif;\n            font-weight: 400;\n            text-transform: uppercase;\n            letter-spacing: 0.02em;\n            line-height: 1.2;\n            color: #FF4F4F;\n            -webkit-font-smoothing: antialiased;\n            -moz-osx-font-smoothing: grayscale;\n        }\n\n        /* Unified h2 size - matching index.html */\n        main h2 {\n            font-size: clamp(1.875rem, 4vw, 3rem);\n            /* text-3xl sm:text-4xl md:text-5xl equivalent */\n            font-weight: 300 !important;\n            /* Less bold */\n        }\n\n        /* Unified h3 size - matching index.html */\n        main h3 {\n            font-size: clamp(1.5rem, 3vw, 1.875rem);\n            /* text-2xl md:text-3xl equivalent */\n        }\n\n        /* Unified h4 size - matching index.html */\n        main h4 {\n            font-size: 1.25rem;\n            /* text-xl equivalent */\n        }\n\n        /* Unified h5 size - matching index.html */\n        main h5 {\n            font-size: 1.125rem;\n            /* text-lg equivalent */\n        }\n\n        /* Brand Guide: CTAs use Coral (#FF4F4F) */\n        main .btn-primary {\n            background: #FF4F4F;\n            color: #ffffff;\n            transition: all 0.3s ease;\n        }\n\n        main .btn-primary:hover {\n            background: #e63939;\n            transform: translateY(-2px);\n            box-shadow: 0 20px 40px rgba(255, 79, 79, 0.4);\n        }\n\n        /* Minimal protection: only prevent transform from page-level hover effects */\n        header nav a:hover,\n        header nav button:hover {\n            transform: none !important;\n        }\n\n        /* Ensure navigation buttons maintain their original blue styling */\n        header nav .btn-primary,\n        nav .btn-primary {\n            background-color: #0050ff !important;\n            background: linear-gradient(135deg, #0050ff 0%, #0040d9 100%) !important;\n            color: white !important;\n        }\n\n        header nav .btn-primary:hover,\n        nav .btn-primary:hover {\n            background-color: #0040d9 !important;\n            background: linear-gradient(135deg, #0040d9 0%, #0050ff 100%) !important;\n        }\n\n        /* Robot Theme Animations */\n        @keyframes float {\n\n            0%,\n            100% {\n                transform: translateY(0px);\n            }\n\n            50% {\n                transform: translateY(-20px);\n            }\n        }\n\n        @keyframes glow-pulse {\n\n            0%,\n            100% {\n                box-shadow: 0 0 20px rgba(6, 182, 212, 0.4),\n                    0 0 40px rgba(6, 182, 212, 0.2);\n            }\n\n            50% {\n                box-shadow: 0 0 30px rgba(6, 182, 212, 0.6),\n                    0 0 60px rgba(6, 182, 212, 0.3);\n            }\n        }\n\n        @keyframes circuit-flow {\n            0% {\n                stroke-dashoffset: 1000;\n            }\n\n            100% {\n                stroke-dashoffset: 0;\n            }\n        }\n\n        @keyframes scan {\n            0% {\n                transform: translateY(-100%);\n            }\n\n            100% {\n                transform: translateY(100%);\n            }\n        }\n\n        @keyframes scroll-left {\n            0% {\n                transform: translateX(0);\n            }\n\n            100% {\n                transform: translateX(-100%);\n            }\n        }\n\n        .float-animation {\n            animation: float 6s ease-in-out infinite;\n        }\n\n        .scroll-container {\n            overflow: hidden;\n            position: relative;\n        }\n\n        .scroll-content {\n            display: flex;\n            animation: scroll-left 20s linear infinite;\n        }\n\n        .scroll-content:hover {\n            animation-play-state: paused;\n        }\n\n        .glow-pulse {\n            animation: glow-pulse 3s ease-in-out infinite;\n        }\n\n        /* Lightbox Styles */\n        .lightbox {\n            display: none;\n            position: fixed;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background: rgba(0, 0, 0, 0.95);\n            z-index: 9999;\n            justify-content: center;\n            align-items: center;\n            cursor: pointer;\n        }\n\n        .lightbox.active {\n            display: flex;\n        }\n\n        .lightbox img {\n            max-width: 90%;\n            max-height: 90vh;\n            object-fit: contain;\n            border-radius: 8px;\n            box-shadow: 0 0 50px rgba(6, 182, 212, 0.5);\n        }\n\n        .lightbox-close {\n            position: absolute;\n            top: 20px;\n            right: 30px;\n            font-size: 40px;\n            color: white;\n            cursor: pointer;\n            z-index: 10000;\n            width: 50px;\n            height: 50px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            background: rgba(255, 255, 255, 0.1);\n            border-radius: 50%;\n            transition: all 0.3s ease;\n        }\n\n        .lightbox-close:hover {\n            background: rgba(255, 255, 255, 0.2);\n            transform: rotate(90deg);\n        }\n\n        .scan-line {\n            position: absolute;\n            width: 100%;\n            height: 2px;\n            background: linear-gradient(90deg,\n                    transparent,\n                    rgba(6, 182, 212, 0.8),\n                    transparent);\n            animation: scan 4s linear infinite;\n        }\n\n        /* Robot Grid Pattern */\n        .robot-grid {\n            background-image:\n                linear-gradient(rgba(6, 182, 212, 0.03) 1px, transparent 1px),\n                linear-gradient(90deg, rgba(6, 182, 212, 0.03) 1px, transparent 1px);\n            background-size: 50px 50px;\n        }\n\n        /* Hologram Effect */\n        .hologram-text {\n            background: linear-gradient(135deg, #06b6d4, #3b82f6, #8b5cf6);\n            -webkit-background-clip: text;\n            background-clip: text;\n            -webkit-text-fill-color: transparent;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n        }\n\n        /* Section Padding */\n        .section-padding {\n            padding: 5rem 0;\n        }\n\n        @media (min-width: 768px) {\n            .section-padding {\n                padding: 8rem 0;\n            }\n        }\n\n        /* Auto-scrolling gallery */\n        .rosie-gallery-container {\n            overflow: hidden;\n            position: relative;\n            width: 100%;\n            mask-image: linear-gradient(to right, transparent 0%, black 5%, black 95%, transparent 100%);\n            -webkit-mask-image: linear-gradient(to right, transparent 0%, black 5%, black 95%, transparent 100%);\n        }\n\n        .rosie-gallery-scroll {\n            display: flex;\n            gap: 1.5rem;\n            width: fit-content;\n            animation: scroll-right-to-left 40s linear infinite;\n        }\n\n        .rosie-gallery-scroll:hover {\n            animation-play-state: paused;\n        }\n\n        @keyframes scroll-right-to-left {\n            0% {\n                transform: translateX(0);\n            }\n\n            100% {\n                transform: translateX(-50%);\n            }\n        }\n\n        .rosie-gallery-item {\n            flex-shrink: 0;\n            width: 280px;\n        }\n\n        @media (min-width: 640px) {\n            .rosie-gallery-item {\n                width: 320px;\n            }\n        }\n\n        @media (min-width: 1024px) {\n            .rosie-gallery-item {\n                width: 360px;\n            }\n        }\n    </style>\n</head>\n\n<body>\n    <script src=\"../assets/components/navigation.js\"></script>\n\n    <main>\n        <!-- Hero Section -->\n        <section class=\"relative h-screen flex items-center justify-center text-white overflow-hidden\">\n            <!-- Background Image with Overlay -->\n            <div class=\"absolute inset-0 z-0\">\n                <img src=\"../assets/images/rosie-robot/rosie-robot-hero.webp\"\n                    alt=\"Rosie the Robot AI-powered mobile photo booth at event\" width=\"1920\" height=\"1080\"\n                    class=\"w-full h-full object-cover\" loading=\"eager\" fetchpriority=\"high\">\n                <div class=\"absolute inset-0 bg-gradient-to-br from-black/70 via-slate-900/60 to-black/70\"></div>\n            </div>\n\n            <!-- Animated Circuit Lines -->\n            <div class=\"absolute inset-0 z-10 opacity-20 pointer-events-none\">\n                <div class=\"scan-line\"></div>\n            </div>\n\n            <!-- Content -->\n            <div class=\"relative z-10 container mx-auto px-4 sm:px-6 pt-20\">\n                <div class=\"max-w-7xl mx-auto text-center\">\n\n                    <!-- Main Title -->\n                    <h1 class=\"text-4xl sm:text-6xl md:text-7xl lg:text-8xl mb-6 leading-tight text-center\"\n                        style=\"font-weight: 400; text-shadow: 2px 2px 8px rgba(0,0,0,0.7);\">\n                        <span class=\"block\">ROSIE THE ROBOT</span><span class=\"block\" style=\"color: #18F1E1;\">PHOTO\n                            BOOTH RENTALS</span>\n                    </h1>\n\n                    <!-- Description -->\n                    <div class=\"max-w-3xl mx-auto mb-8 px-4\">\n                        <p\n                            class=\"text-lg sm:text-xl md:text-2xl mb-8 leading-relaxed text-white/95 font-light drop-shadow-lg\">\n                            The world\'s first mobile AI robot that interacts with guests, captures moments, and creates\n                            unforgettable experiences\n                        </p>\n                    </div>\n\n                    <!-- CTA Buttons -->\n                    <div class=\"flex flex-col sm:flex-row gap-4 sm:gap-6 justify-center items-center px-4\">\n                        <a href=\"../contact-us.html\"\n                            class=\"group relative inline-flex items-center gap-2 sm:gap-3 text-white px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg  shadow-2xl hover:shadow-[#FF4F4F]/50 transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 overflow-hidden w-full sm:w-auto justify-center\"\n                            style=\"background: #FF4F4F;\">\n                            <span class=\"relative z-10\">Get Your Quote</span>\n                        </a>\n                        <button type=\"button\" data-click-to-call data-call-text=\"Call Us\"\n                            class=\"group inline-flex items-center gap-2 sm:gap-3 px-6 sm:px-10 py-3 sm:py-5 rounded-full text-base sm:text-lg  backdrop-blur-md bg-white/10 border-2 shadow-xl hover:shadow-2xl transition-all duration-500 transform hover:scale-110 hover:-translate-y-1 text-white w-full sm:w-auto justify-center cursor-pointer\"\n                            style=\"border-color: rgba(24, 241, 225, 0.5);\"\n                            onmouseover=\"this.style.borderColor=\'rgba(24, 241, 225, 0.7)\'; this.style.background=\'rgba(24, 241, 225, 0.2)\';\"\n                            onmouseout=\"this.style.borderColor=\'rgba(24, 241, 225, 0.5)\'; this.style.background=\'rgba(255, 255, 255, 0.1)\';\">\n                            <svg class=\"w-4 h-4 sm:w-5 sm:h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                    d=\"M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498A1 1 0 0121 17.72V21a2 2 0 01-2 2h-1C9.716 23 3 16.284 3 8V7a2 2 0 012-2z\">\n                                </path>\n                            </svg>\n                            <span>Call Us</span>\n                        </button>\n                    </div>\n\n                    <!-- Trust Indicators -->\n                    <div\n                        class=\"flex flex-wrap items-center justify-center gap-4 sm:gap-8 mt-8 sm:mt-12 text-white/70 px-4\">\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-cyan-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">Autonomous Navigation</span>\n                        </div>\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-blue-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">AI-Powered Interaction</span>\n                        </div>\n                        <div class=\"flex items-center gap-2\">\n                            <div class=\"w-2 h-2 bg-indigo-400 rounded-full\"></div>\n                            <span class=\"text-xs sm:text-sm font-medium\">Instant Sharing</span>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- About Rosie Section -->\n        <section class=\"section-padding bg-gradient-to-b from-slate-50 to-white relative overflow-hidden\">\n            <!-- Circuit Board Background -->\n            <svg class=\"absolute inset-0 w-full h-full opacity-[0.08]\" xmlns=\"http://www.w3.org/2000/svg\">\n                <defs>\n                    <!-- Circuit Board Pattern -->\n                    <pattern id=\"circuit-about\" x=\"0\" y=\"0\" width=\"400\" height=\"400\" patternUnits=\"userSpaceOnUse\">\n                        <!-- Horizontal Traces -->\n                        <line x1=\"50\" y1=\"50\" x2=\"150\" y2=\"50\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n                        <line x1=\"200\" y1=\"50\" x2=\"350\" y2=\"50\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n                        <line x1=\"50\" y1=\"150\" x2=\"200\" y2=\"150\" stroke=\"#3b82f6\" stroke-width=\"3\" />\n                        <line x1=\"250\" y1=\"150\" x2=\"350\" y2=\"150\" stroke=\"#3b82f6\" stroke-width=\"3\" />\n                        <line x1=\"50\" y1=\"250\" x2=\"150\" y2=\"250\" stroke=\"#6366f1\" stroke-width=\"3\" />\n                        <line x1=\"200\" y1=\"250\" x2=\"300\" y2=\"250\" stroke=\"#6366f1\" stroke-width=\"3\" />\n                        <line x1=\"100\" y1=\"350\" x2=\"250\" y2=\"350\" stroke=\"#8b5cf6\" stroke-width=\"3\" />\n\n                        <!-- Vertical Traces -->\n                        <line x1=\"150\" y1=\"50\" x2=\"150\" y2=\"150\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n                        <line x1=\"150\" y1=\"200\" x2=\"150\" y2=\"350\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n                        <line x1=\"250\" y1=\"50\" x2=\"250\" y2=\"200\" stroke=\"#3b82f6\" stroke-width=\"3\" />\n                        <line x1=\"250\" y1=\"250\" x2=\"250\" y2=\"350\" stroke=\"#3b82f6\" stroke-width=\"3\" />\n                        <line x1=\"100\" y1=\"100\" x2=\"100\" y2=\"250\" stroke=\"#6366f1\" stroke-width=\"3\" />\n                        <line x1=\"300\" y1=\"150\" x2=\"300\" y2=\"300\" stroke=\"#8b5cf6\" stroke-width=\"3\" />\n\n                        <!-- Connection Pads (circles at intersections) -->\n                        <circle cx=\"150\" cy=\"50\" r=\"6\" fill=\"#06b6d4\" />\n                        <circle cx=\"150\" cy=\"150\" r=\"6\" fill=\"#06b6d4\" />\n                        <circle cx=\"150\" cy=\"250\" r=\"6\" fill=\"#3b82f6\" />\n                        <circle cx=\"250\" cy=\"50\" r=\"6\" fill=\"#3b82f6\" />\n                        <circle cx=\"250\" cy=\"150\" r=\"6\" fill=\"#6366f1\" />\n                        <circle cx=\"250\" cy=\"250\" r=\"6\" fill=\"#6366f1\" />\n                        <circle cx=\"100\" cy=\"150\" r=\"6\" fill=\"#8b5cf6\" />\n                        <circle cx=\"100\" cy=\"250\" r=\"6\" fill=\"#8b5cf6\" />\n                        <circle cx=\"300\" cy=\"250\" r=\"6\" fill=\"#a855f7\" />\n\n                        <!-- IC Chips (rectangles) -->\n                        <rect x=\"170\" y=\"70\" width=\"60\" height=\"40\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"2\"\n                            rx=\"2\" />\n                        <line x1=\"175\" y1=\"75\" x2=\"175\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n                        <line x1=\"185\" y1=\"75\" x2=\"185\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n                        <line x1=\"195\" y1=\"75\" x2=\"195\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n                        <line x1=\"205\" y1=\"75\" x2=\"205\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n                        <line x1=\"215\" y1=\"75\" x2=\"215\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n                        <line x1=\"225\" y1=\"75\" x2=\"225\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n\n                        <rect x=\"50\" y=\"170\" width=\"40\" height=\"60\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"\n                            rx=\"2\" />\n                        <line x1=\"55\" y1=\"175\" x2=\"85\" y2=\"175\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n                        <line x1=\"55\" y1=\"185\" x2=\"85\" y2=\"185\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n                        <line x1=\"55\" y1=\"195\" x2=\"85\" y2=\"195\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n                        <line x1=\"55\" y1=\"205\" x2=\"85\" y2=\"205\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n                        <line x1=\"55\" y1=\"215\" x2=\"85\" y2=\"215\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n                        <line x1=\"55\" y1=\"225\" x2=\"85\" y2=\"225\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n\n                        <!-- Resistors (small rectangles) -->\n                        <rect x=\"175\" y=\"145\" width=\"20\" height=\"10\" fill=\"none\" stroke=\"#6366f1\" stroke-width=\"2\"\n                            rx=\"1\" />\n                        <rect x=\"270\" y=\"245\" width=\"20\" height=\"10\" fill=\"none\" stroke=\"#8b5cf6\" stroke-width=\"2\"\n                            rx=\"1\" />\n                        <rect x=\"120\" y=\"345\" width=\"20\" height=\"10\" fill=\"none\" stroke=\"#a855f7\" stroke-width=\"2\"\n                            rx=\"1\" />\n\n                        <!-- Capacitors (parallel lines) -->\n                        <line x1=\"195\" y1=\"245\" x2=\"195\" y2=\"255\" stroke=\"#6366f1\" stroke-width=\"2\" />\n                        <line x1=\"205\" y1=\"245\" x2=\"205\" y2=\"255\" stroke=\"#6366f1\" stroke-width=\"2\" />\n\n                        <!-- Via holes (small circles) -->\n                        <circle cx=\"200\" cy=\"50\" r=\"3\" fill=\"#06b6d4\" opacity=\"0.5\" />\n                        <circle cx=\"50\" cy=\"150\" r=\"3\" fill=\"#3b82f6\" opacity=\"0.5\" />\n                        <circle cx=\"200\" cy=\"250\" r=\"3\" fill=\"#6366f1\" opacity=\"0.5\" />\n                        <circle cx=\"300\" cy=\"150\" r=\"3\" fill=\"#8b5cf6\" opacity=\"0.5\" />\n                    </pattern>\n                </defs>\n                <rect width=\"100%\" height=\"100%\" fill=\"url(#circuit-about)\" />\n            </svg>\n\n            <!-- Glowing Circuit Nodes with Pulse -->\n            <div\n                class=\"absolute top-[20%] left-[15%] w-4 h-4 bg-cyan-400 rounded-full animate-pulse shadow-lg shadow-cyan-400/50\">\n            </div>\n            <div class=\"absolute top-[30%] right-[20%] w-3 h-3 bg-blue-400 rounded-full animate-pulse shadow-lg shadow-blue-400/50\"\n                style=\"animation-delay: 0.5s;\"></div>\n            <div class=\"absolute bottom-[25%] left-[25%] w-4 h-4 bg-indigo-400 rounded-full animate-pulse shadow-lg shadow-indigo-400/50\"\n                style=\"animation-delay: 1s;\"></div>\n            <div class=\"absolute bottom-[35%] right-[30%] w-3 h-3 bg-purple-400 rounded-full animate-pulse shadow-lg shadow-purple-400/50\"\n                style=\"animation-delay: 1.5s;\"></div>\n            <div class=\"absolute top-[45%] left-[45%] w-3 h-3 bg-pink-400 rounded-full animate-pulse shadow-lg shadow-pink-400/50\"\n                style=\"animation-delay: 2s;\"></div>\n\n            <!-- Animated Data Flow Lines -->\n            <svg class=\"absolute inset-0 w-full h-full pointer-events-none opacity-20\">\n                <!-- Flowing circuit traces -->\n                <line x1=\"15%\" y1=\"20%\" x2=\"45%\" y2=\"45%\" stroke=\"#06b6d4\" stroke-width=\"2\" stroke-dasharray=\"10,5\">\n                    <animate attributeName=\"stroke-dashoffset\" from=\"0\" to=\"15\" dur=\"3s\" repeatCount=\"indefinite\" />\n                </line>\n                <line x1=\"80%\" y1=\"30%\" x2=\"45%\" y2=\"45%\" stroke=\"#3b82f6\" stroke-width=\"2\" stroke-dasharray=\"10,5\">\n                    <animate attributeName=\"stroke-dashoffset\" from=\"0\" to=\"15\" dur=\"3.5s\" repeatCount=\"indefinite\" />\n                </line>\n                <line x1=\"25%\" y1=\"75%\" x2=\"45%\" y2=\"45%\" stroke=\"#6366f1\" stroke-width=\"2\" stroke-dasharray=\"10,5\">\n                    <animate attributeName=\"stroke-dashoffset\" from=\"0\" to=\"15\" dur=\"4s\" repeatCount=\"indefinite\" />\n                </line>\n                <line x1=\"70%\" y1=\"65%\" x2=\"45%\" y2=\"45%\" stroke=\"#8b5cf6\" stroke-width=\"2\" stroke-dasharray=\"10,5\">\n                    <animate attributeName=\"stroke-dashoffset\" from=\"0\" to=\"15\" dur=\"4.5s\" repeatCount=\"indefinite\" />\n                </line>\n            </svg>\n\n            <div class=\"container mx-auto px-6 relative z-10\">\n                <div class=\"mx-auto\">\n                    <!-- Section Header -->\n                    <div class=\"text-center mb-16\">\n                        <h2 class=\"text-4xl md:text-5xl lg:text-6xl font-black mb-6\" style=\"color: #FF4F4F;\">\n                            AI-Powered Mobile <span style=\"color: #FF4F4F;\">Photo Booth</span>\n                        </h2>\n                        <div class=\"w-24 h-1 bg-gradient-to-r from-[#18F1E1] to-[#18F1E1] mx-auto\"></div>\n                    </div>\n\n                    <!-- Content Card -->\n                    <div\n                        class=\"bg-white rounded-3xl shadow-2xl p-8 md:p-12 border-2 border-gray-100 hover:border-cyan-200 transition-all\">\n                        <div class=\"grid md:grid-cols-2 gap-12 items-center\">\n                            <!-- Text Content -->\n                            <div>\n                                <h3 class=\"text-3xl  mb-6\" style=\"color: #FF4F4F;\">\n                                    The Future of <span style=\"color: #FF4F4F;\">Event Photography</span>\n                                </h3>\n                                <p class=\"text-lg text-gray-700 leading-relaxed mb-6\">\n                                    Meet <span class=\"font-semibold\" style=\"color: #FF4F4F;\">Rosie the Robot</span>, the\n                                    world\'s first <span class=\"font-semibold\" style=\"color: #FF4F4F;\">mobile photo booth\n                                        on wheels</span>! Rosie interacts with guests, rolls up for photos, and delivers\n                                    instant digital images—all while adding a futuristic, high-tech element to your\n                                    event.\n                                </p>\n                                <p class=\"text-lg text-gray-700 leading-relaxed\">\n                                    Perfect for <span class=\"font-semibold\" style=\"color: #FF4F4F;\">corporate\n                                        activations</span>, <span class=\"font-semibold\" style=\"color: #FF4F4F;\">trade\n                                        shows</span>, <span class=\"font-semibold\" style=\"color: #FF4F4F;\">tech\n                                        expos</span>, and <span class=\"font-semibold\" style=\"color: #FF4F4F;\">luxury\n                                        events</span>. Fully\n                                    brandable and interactive, this robotic photo booth is an instant crowd magnet.\n                                </p>\n                            </div>\n\n                            <!-- Feature Icons -->\n                            <div class=\"grid grid-cols-2 gap-6\">\n                                <div class=\"text-center p-6 bg-gradient-to-br from-cyan-50 to-blue-50 rounded-2xl\">\n                                    <div\n                                        class=\"w-16 h-16 bg-gradient-to-br from-[#18F1E1] to-[#18F1E1] rounded-xl flex items-center justify-center mx-auto mb-4\">\n                                        <svg class=\"w-8 h-8 text-white\" fill=\"none\" stroke=\"#1F1F1F\"\n                                            viewBox=\"0 0 24 24\">\n                                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                                d=\"M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z\">\n                                            </path>\n                                        </svg>\n                                    </div>\n                                    <h4 class=\" text-gray-900\" style=\"color: #FF4F4F;\">AI-Powered</h4>\n                                </div>\n\n                                <div class=\"text-center p-6 bg-gradient-to-br from-blue-50 to-indigo-50 rounded-2xl\">\n                                    <div\n                                        class=\"w-16 h-16 bg-gradient-to-br from-[#18F1E1] to-[#18F1E1] rounded-xl flex items-center justify-center mx-auto mb-4\">\n                                        <svg class=\"w-8 h-8 text-white\" fill=\"none\" stroke=\"#1F1F1F\"\n                                            viewBox=\"0 0 24 24\">\n                                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                                d=\"M13 10V3L4 14h7v7l9-11h-7z\"></path>\n                                        </svg>\n                                    </div>\n                                    <h4 class=\" text-gray-900\" style=\"color: #FF4F4F;\">Fully Mobile</h4>\n                                </div>\n\n                                <div class=\"text-center p-6 bg-gradient-to-br from-indigo-50 to-purple-50 rounded-2xl\">\n                                    <div\n                                        class=\"w-16 h-16 bg-gradient-to-br from-[#18F1E1] to-[#18F1E1] rounded-xl flex items-center justify-center mx-auto mb-4\">\n                                        <svg class=\"w-8 h-8 text-white\" fill=\"none\" stroke=\"#1F1F1F\"\n                                            viewBox=\"0 0 24 24\">\n                                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                                d=\"M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z\">\n                                            </path>\n                                        </svg>\n                                    </div>\n                                    <h4 class=\" text-gray-900\" style=\"color: #FF4F4F;\">Interactive</h4>\n                                </div>\n\n                                <div class=\"text-center p-6 bg-gradient-to-br from-purple-50 to-pink-50 rounded-2xl\">\n                                    <div\n                                        class=\"w-16 h-16 bg-gradient-to-br from-[#18F1E1] to-[#18F1E1] rounded-xl flex items-center justify-center mx-auto mb-4\">\n                                        <svg class=\"w-8 h-8 text-white\" fill=\"none\" stroke=\"#1F1F1F\"\n                                            viewBox=\"0 0 24 24\">\n                                            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                                d=\"M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z\">\n                                            </path>\n                                        </svg>\n                                    </div>\n                                    <h4 class=\" text-gray-900\" style=\"color: #FF4F4F;\">Brandable</h4>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                    <!-- Photo Gallery -->\n                    <div class=\"mt-16\">\n                        <div class=\"text-center mb-12\">\n                            <h3 class=\"text-3xl md:text-4xl  mb-4\" style=\"color: #FF4F4F;\">\n                                See Rosie <span style=\"color: #FF4F4F;\">In Action</span>\n                            </h3>\n                            <p class=\"text-lg\" style=\"color: #1f1f1f;\">Experience the future of event\n                                entertainment</p>\n                        </div>\n\n                        <div class=\"rosie-gallery-container\">\n                            <div class=\"rosie-gallery-scroll\">\n                                <!-- First set of gallery items -->\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-1.webp\"\n                                        alt=\"Rosie Robot AI photo booth at trade show event\" width=\"360\" height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-2.webp\"\n                                        alt=\"Robot photo booth technology with AI interaction\" width=\"360\" height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-3.webp\"\n                                        alt=\"Interactive robot photo booth experience at corporate event\" width=\"360\"\n                                        height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-4.webp\"\n                                        alt=\"AI robot photo booth capturing branded photos\" width=\"360\" height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-5.webp\"\n                                        alt=\"Modern robot photo booth technology for events\" width=\"360\" height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-6.webp\"\n                                        alt=\"Autonomous robot photo booth at tech expo\" width=\"360\" height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                                <!-- Duplicate set for seamless loop -->\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-1.webp\"\n                                        alt=\"Rosie Robot AI photo booth at trade show event\" width=\"360\" height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-2.webp\"\n                                        alt=\"Robot photo booth technology with AI interaction\" width=\"360\" height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-3.webp\"\n                                        alt=\"Interactive robot photo booth experience at corporate event\" width=\"360\"\n                                        height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-4.webp\"\n                                        alt=\"AI robot photo booth capturing branded photos\" width=\"360\" height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-5.webp\"\n                                        alt=\"Modern robot photo booth technology for events\" width=\"360\" height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                                <div\n                                    class=\"rosie-gallery-item group relative overflow-hidden rounded-3xl aspect-[3/4] shadow-xl hover:shadow-cyan-200/60 transition-all duration-500\">\n                                    <img src=\"../assets/images/rosie-robot/rosie-robot-6.webp\"\n                                        alt=\"Autonomous robot photo booth at tech expo\" width=\"360\" height=\"480\"\n                                        class=\"gallery-image w-full h-full object-cover transition-transform duration-700 group-hover:scale-110\"\n                                        loading=\"lazy\">\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Lightbox Modal -->\n            <div id=\"rosieLightbox\"\n                class=\"fixed inset-0 bg-black/90 backdrop-blur-sm z-50 hidden items-center justify-center p-6\">\n                <button id=\"rosieClose\"\n                    class=\"absolute top-6 right-6 w-11 h-11 rounded-full bg-white/15 border border-white/30 text-white flex items-center justify-center hover:bg-white/25 transition\">\n                    <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                        <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\">\n                        </path>\n                    </svg>\n                </button>\n                <div class=\"relative max-w-5xl w-full flex flex-col items-center gap-5\">\n                    <div class=\"max-h-[80vh] w-full flex items-center justify-center\">\n                        <img id=\"rosieLightboxImage\" src=\"\" alt=\"Rosie Robot full view\"\n                            class=\"max-h-[80vh] w-full object-contain rounded-2xl shadow-2xl transition-transform duration-200 ease-out\"\n                            style=\"transform: scale(1); transform-origin: center;\"></img>\n                    </div>\n                    <div\n                        class=\"flex items-center gap-3 bg-white/10 border border-white/20 rounded-full px-5 py-3 text-white shadow-lg\">\n                        <button id=\"rosieZoomOut\"\n                            class=\"w-10 h-10 rounded-full bg-white/15 hover:bg-white/25 flex items-center justify-center transition\">\n                            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                    d=\"M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM13 10H7\"></path>\n                            </svg>\n                        </button>\n                        <button id=\"rosieZoomReset\"\n                            class=\"px-4 h-10 rounded-full bg-white/15 hover:bg-white/25 text-sm font-semibold tracking-wide transition\">\n                            Reset\n                        </button>\n                        <button id=\"rosieZoomIn\"\n                            class=\"w-10 h-10 rounded-full bg-white/15 hover:bg-white/25 flex items-center justify-center transition\">\n                            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                    d=\"M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM10 7v6m3-3H7\"></path>\n                            </svg>\n                        </button>\n                        <span id=\"rosieZoomLevel\" class=\"text-xs uppercase tracking-[0.25em] text-white/80\">100%</span>\n                    </div>\n                </div>\n            </div>\n\n            <script>\n                document.addEventListener(\'DOMContentLoaded\', () => {\n                    const lightbox = document.getElementById(\'rosieLightbox\');\n                    const lightboxImg = document.getElementById(\'rosieLightboxImage\');\n                    const closeBtn = document.getElementById(\'rosieClose\');\n                    const galleryImages = document.querySelectorAll(\'.rosie-gallery-item .gallery-image\');\n                    const zoomInBtn = document.getElementById(\'rosieZoomIn\');\n                    const zoomOutBtn = document.getElementById(\'rosieZoomOut\');\n                    const zoomResetBtn = document.getElementById(\'rosieZoomReset\');\n                    const zoomLevelDisplay = document.getElementById(\'rosieZoomLevel\');\n\n                    let currentZoom = 1;\n                    const zoomStep = 0.25;\n                    const minZoom = 0.75;\n                    const maxZoom = 4;\n\n                    const applyZoom = () => {\n                        if (!lightboxImg) return;\n                        lightboxImg.style.transform = `scale(${currentZoom})`;\n                        if (zoomLevelDisplay) {\n                            zoomLevelDisplay.textContent = `${Math.round(currentZoom * 100)}%`;\n                        }\n                    };\n\n                    const zoomIn = () => {\n                        currentZoom = Math.min(maxZoom, currentZoom + zoomStep);\n                        applyZoom();\n                    };\n\n                    const zoomOut = () => {\n                        currentZoom = Math.max(minZoom, currentZoom - zoomStep);\n                        applyZoom();\n                    };\n\n                    const resetZoom = () => {\n                        currentZoom = 1;\n                        applyZoom();\n                    };\n\n                    const openLightbox = (src, alt) => {\n                        if (!lightbox || !lightboxImg) return;\n                        lightboxImg.src = src;\n                        lightboxImg.alt = alt || \'Rosie Robot full view\';\n                        resetZoom();\n                        lightbox.classList.remove(\'hidden\');\n                        lightbox.classList.add(\'flex\');\n                        document.body.style.overflow = \'hidden\';\n                    };\n\n                    const closeLightbox = () => {\n                        if (!lightbox) return;\n                        lightbox.classList.add(\'hidden\');\n                        lightbox.classList.remove(\'flex\');\n                        if (lightboxImg) {\n                            lightboxImg.src = \'\';\n                        }\n                        document.body.style.overflow = \'\';\n                        resetZoom();\n                    };\n\n                    galleryImages.forEach(img => {\n                        img.addEventListener(\'click\', () => openLightbox(img.src, img.alt));\n                    });\n\n                    if (zoomInBtn) {\n                        zoomInBtn.addEventListener(\'click\', zoomIn);\n                    }\n\n                    if (zoomOutBtn) {\n                        zoomOutBtn.addEventListener(\'click\', zoomOut);\n                    }\n\n                    if (zoomResetBtn) {\n                        zoomResetBtn.addEventListener(\'click\', resetZoom);\n                    }\n\n                    if (closeBtn) {\n                        closeBtn.addEventListener(\'click\', closeLightbox);\n                    }\n\n                    if (lightbox) {\n                        lightbox.addEventListener(\'click\', (event) => {\n                            if (event.target === lightbox) {\n                                closeLightbox();\n                            }\n                        });\n\n                        lightbox.addEventListener(\'wheel\', (event) => {\n                            if (!lightbox.classList.contains(\'flex\')) return;\n                            event.preventDefault();\n                            if (event.deltaY < 0) {\n                                zoomIn();\n                            } else {\n                                zoomOut();\n                            }\n                        }, { passive: false });\n                    }\n\n                    document.addEventListener(\'keydown\', (event) => {\n                        if (event.key === \'Escape\') {\n                            closeLightbox();\n                        } else if (event.key === \'+\' || event.key === \'=\') {\n                            zoomIn();\n                        } else if (event.key === \'-\' || event.key === \'_\') {\n                            zoomOut();\n                        } else if (event.key === \'0\') {\n                            resetZoom();\n                        }\n                    });\n                });\n            </script>\n        </section>\n\n        <!-- Trade Show Features Section -->\n        <section class=\"section-padding bg-gradient-to-br from-slate-50 via-white to-slate-50 relative overflow-hidden\">\n            <!-- Circuit Board Background -->\n            <svg class=\"absolute inset-0 w-full h-full opacity-[0.08]\" xmlns=\"http://www.w3.org/2000/svg\">\n                <defs>\n                    <!-- Circuit Board Pattern -->\n                    <pattern id=\"circuit\" x=\"0\" y=\"0\" width=\"400\" height=\"400\" patternUnits=\"userSpaceOnUse\">\n                        <!-- Horizontal Traces -->\n                        <line x1=\"50\" y1=\"50\" x2=\"150\" y2=\"50\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n                        <line x1=\"200\" y1=\"50\" x2=\"350\" y2=\"50\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n                        <line x1=\"50\" y1=\"150\" x2=\"200\" y2=\"150\" stroke=\"#3b82f6\" stroke-width=\"3\" />\n                        <line x1=\"250\" y1=\"150\" x2=\"350\" y2=\"150\" stroke=\"#3b82f6\" stroke-width=\"3\" />\n                        <line x1=\"50\" y1=\"250\" x2=\"150\" y2=\"250\" stroke=\"#6366f1\" stroke-width=\"3\" />\n                        <line x1=\"200\" y1=\"250\" x2=\"300\" y2=\"250\" stroke=\"#6366f1\" stroke-width=\"3\" />\n                        <line x1=\"100\" y1=\"350\" x2=\"250\" y2=\"350\" stroke=\"#8b5cf6\" stroke-width=\"3\" />\n\n                        <!-- Vertical Traces -->\n                        <line x1=\"150\" y1=\"50\" x2=\"150\" y2=\"150\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n                        <line x1=\"150\" y1=\"200\" x2=\"150\" y2=\"350\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n                        <line x1=\"250\" y1=\"50\" x2=\"250\" y2=\"200\" stroke=\"#3b82f6\" stroke-width=\"3\" />\n                        <line x1=\"250\" y1=\"250\" x2=\"250\" y2=\"350\" stroke=\"#3b82f6\" stroke-width=\"3\" />\n                        <line x1=\"100\" y1=\"100\" x2=\"100\" y2=\"250\" stroke=\"#6366f1\" stroke-width=\"3\" />\n                        <line x1=\"300\" y1=\"150\" x2=\"300\" y2=\"300\" stroke=\"#8b5cf6\" stroke-width=\"3\" />\n\n                        <!-- Connection Pads (circles at intersections) -->\n                        <circle cx=\"150\" cy=\"50\" r=\"6\" fill=\"#06b6d4\" />\n                        <circle cx=\"150\" cy=\"150\" r=\"6\" fill=\"#06b6d4\" />\n                        <circle cx=\"150\" cy=\"250\" r=\"6\" fill=\"#3b82f6\" />\n                        <circle cx=\"250\" cy=\"50\" r=\"6\" fill=\"#3b82f6\" />\n                        <circle cx=\"250\" cy=\"150\" r=\"6\" fill=\"#6366f1\" />\n                        <circle cx=\"250\" cy=\"250\" r=\"6\" fill=\"#6366f1\" />\n                        <circle cx=\"100\" cy=\"150\" r=\"6\" fill=\"#8b5cf6\" />\n                        <circle cx=\"100\" cy=\"250\" r=\"6\" fill=\"#8b5cf6\" />\n                        <circle cx=\"300\" cy=\"250\" r=\"6\" fill=\"#a855f7\" />\n\n                        <!-- IC Chips (rectangles) -->\n                        <rect x=\"170\" y=\"70\" width=\"60\" height=\"40\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"2\"\n                            rx=\"2\" />\n                        <line x1=\"175\" y1=\"75\" x2=\"175\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n                        <line x1=\"185\" y1=\"75\" x2=\"185\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n                        <line x1=\"195\" y1=\"75\" x2=\"195\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n                        <line x1=\"205\" y1=\"75\" x2=\"205\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n                        <line x1=\"215\" y1=\"75\" x2=\"215\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n                        <line x1=\"225\" y1=\"75\" x2=\"225\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"1\" />\n\n                        <rect x=\"50\" y=\"170\" width=\"40\" height=\"60\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"\n                            rx=\"2\" />\n                        <line x1=\"55\" y1=\"175\" x2=\"85\" y2=\"175\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n                        <line x1=\"55\" y1=\"185\" x2=\"85\" y2=\"185\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n                        <line x1=\"55\" y1=\"195\" x2=\"85\" y2=\"195\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n                        <line x1=\"55\" y1=\"205\" x2=\"85\" y2=\"205\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n                        <line x1=\"55\" y1=\"215\" x2=\"85\" y2=\"215\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n                        <line x1=\"55\" y1=\"225\" x2=\"85\" y2=\"225\" stroke=\"#3b82f6\" stroke-width=\"1\" />\n\n                        <!-- Resistors (small rectangles) -->\n                        <rect x=\"175\" y=\"145\" width=\"20\" height=\"10\" fill=\"none\" stroke=\"#6366f1\" stroke-width=\"2\"\n                            rx=\"1\" />\n                        <rect x=\"270\" y=\"245\" width=\"20\" height=\"10\" fill=\"none\" stroke=\"#8b5cf6\" stroke-width=\"2\"\n                            rx=\"1\" />\n                        <rect x=\"120\" y=\"345\" width=\"20\" height=\"10\" fill=\"none\" stroke=\"#a855f7\" stroke-width=\"2\"\n                            rx=\"1\" />\n\n                        <!-- Capacitors (parallel lines) -->\n                        <line x1=\"195\" y1=\"245\" x2=\"195\" y2=\"255\" stroke=\"#6366f1\" stroke-width=\"2\" />\n                        <line x1=\"205\" y1=\"245\" x2=\"205\" y2=\"255\" stroke=\"#6366f1\" stroke-width=\"2\" />\n\n                        <!-- Via holes (small circles) -->\n                        <circle cx=\"200\" cy=\"50\" r=\"3\" fill=\"#06b6d4\" opacity=\"0.5\" />\n                        <circle cx=\"50\" cy=\"150\" r=\"3\" fill=\"#3b82f6\" opacity=\"0.5\" />\n                        <circle cx=\"200\" cy=\"250\" r=\"3\" fill=\"#6366f1\" opacity=\"0.5\" />\n                        <circle cx=\"300\" cy=\"150\" r=\"3\" fill=\"#8b5cf6\" opacity=\"0.5\" />\n                    </pattern>\n                </defs>\n                <rect width=\"100%\" height=\"100%\" fill=\"url(#circuit)\" />\n            </svg>\n\n            <!-- Glowing Circuit Nodes with Pulse -->\n            <div\n                class=\"absolute top-[15%] left-[20%] w-4 h-4 bg-cyan-400 rounded-full animate-pulse shadow-lg shadow-cyan-400/50\">\n            </div>\n            <div class=\"absolute top-[25%] right-[15%] w-3 h-3 bg-blue-400 rounded-full animate-pulse shadow-lg shadow-blue-400/50\"\n                style=\"animation-delay: 0.5s;\"></div>\n            <div class=\"absolute bottom-[30%] left-[30%] w-4 h-4 bg-indigo-400 rounded-full animate-pulse shadow-lg shadow-indigo-400/50\"\n                style=\"animation-delay: 1s;\"></div>\n            <div class=\"absolute bottom-[20%] right-[25%] w-3 h-3 bg-purple-400 rounded-full animate-pulse shadow-lg shadow-purple-400/50\"\n                style=\"animation-delay: 1.5s;\"></div>\n            <div class=\"absolute top-[50%] left-[50%] w-3 h-3 bg-pink-400 rounded-full animate-pulse shadow-lg shadow-pink-400/50\"\n                style=\"animation-delay: 2s;\"></div>\n            <div class=\"absolute top-[40%] right-[40%] w-3 h-3 bg-cyan-300 rounded-full animate-pulse shadow-lg shadow-cyan-300/50\"\n                style=\"animation-delay: 2.5s;\"></div>\n\n            <!-- Animated Data Flow Lines -->\n            <svg class=\"absolute inset-0 w-full h-full pointer-events-none opacity-20\">\n                <!-- Flowing circuit traces -->\n                <line x1=\"20%\" y1=\"15%\" x2=\"50%\" y2=\"50%\" stroke=\"#06b6d4\" stroke-width=\"2\" stroke-dasharray=\"10,5\">\n                    <animate attributeName=\"stroke-dashoffset\" from=\"0\" to=\"15\" dur=\"3s\" repeatCount=\"indefinite\" />\n                </line>\n                <line x1=\"85%\" y1=\"25%\" x2=\"50%\" y2=\"50%\" stroke=\"#3b82f6\" stroke-width=\"2\" stroke-dasharray=\"10,5\">\n                    <animate attributeName=\"stroke-dashoffset\" from=\"0\" to=\"15\" dur=\"3.5s\" repeatCount=\"indefinite\" />\n                </line>\n                <line x1=\"30%\" y1=\"70%\" x2=\"50%\" y2=\"50%\" stroke=\"#6366f1\" stroke-width=\"2\" stroke-dasharray=\"10,5\">\n                    <animate attributeName=\"stroke-dashoffset\" from=\"0\" to=\"15\" dur=\"4s\" repeatCount=\"indefinite\" />\n                </line>\n                <line x1=\"75%\" y1=\"80%\" x2=\"50%\" y2=\"50%\" stroke=\"#8b5cf6\" stroke-width=\"2\" stroke-dasharray=\"10,5\">\n                    <animate attributeName=\"stroke-dashoffset\" from=\"0\" to=\"15\" dur=\"4.5s\" repeatCount=\"indefinite\" />\n                </line>\n            </svg>\n\n            <div class=\"container mx-auto px-6 relative z-10\">\n                <div class=\"max-w-7xl mx-auto\">\n                    <!-- Section Header -->\n                    <div class=\"text-center mb-16\">\n                        <h2 class=\"text-4xl md:text-5xl lg:text-6xl font-black mb-6\" style=\"color: #FF4F4F;\">\n                            Interactive <span style=\"color: #FF4F4F;\">Features</span>\n                        </h2>\n                        <p class=\"text-xl text-[#1f1f1f] max-w-3xl mx-auto\">\n                            Transform your booth experience with next-generation engagement technology\n                        </p>\n                    </div>\n\n                    <!-- Features with Grid Layout (4 columns) -->\n                    <div class=\"grid grid-cols-1 md:grid-cols-4 gap-6 auto-rows-fr\">\n                        <!-- Row 1 -->\n                        <!-- Card 1: Top Left -->\n                        <div\n                            class=\"group bg-gradient-to-br from-[#FFFF] to-[#FFFF] rounded-2xl p-6 hover:shadow-xl transition-all hover:-translate-y-2 border-2 border-transparent hover:border-[#18F1E1]\">\n                            <div\n                                class=\"w-14 h-14 bg-gradient-to-br from-[#18F1E1] to-[#18F1E1] rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform\">\n                                <svg class=\"w-7 h-7 text-white\" fill=\"#18F1E1\" stroke=\"#1F1F1F\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                        d=\"M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z\">\n                                    </path>\n                                </svg>\n                            </div>\n                            <h4 class=\"text-lg mb-2 text-gray-900\" style=\"color: #FF4F4F;\">Custom Brand Messaging</h4>\n                            <p class=\"text-gray-600 text-sm\">Fully customizable branding and messaging</p>\n                        </div>\n\n                        <!-- Card 2: Top Left Second -->\n                        <div\n                            class=\"group bg-gradient-to-br from-[#FFFF] to-[#FFFF] rounded-2xl p-6 hover:shadow-xl transition-all hover:-translate-y-2 border-2 border-transparent hover:border-[#18F1E1]\">\n                            <div\n                                class=\"w-14 h-14 bg-gradient-to-br from-[#18F1E1] to-[#18F1E1] rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform\">\n                                <svg class=\"w-7 h-7 text-white\" fill=\"#18F1E1\" stroke=\"#1F1F1F\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                        d=\"M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z\">\n                                    </path>\n                                </svg>\n                            </div>\n                            <h4 class=\"text-lg mb-2 text-gray-900\" style=\"color: #FF4F4F;\">Social Media Integration</h4>\n                            <p class=\"text-gray-600 text-sm\">Instant sharing to all platforms</p>\n                        </div>\n\n                        <!-- Card 5: Top Right - Spans 2 columns, 2 rows -->\n                        <div class=\"md:col-span-2 md:row-span-2 cursor-pointer group relative overflow-hidden rounded-3xl shadow-2xl\"\n                            onclick=\"openLightbox(\'../assets/images/rosie-robot/rosie-robot-1.webp\')\">\n                            <img src=\"../assets/images/rosie-robot/rosie-robot-1.webp\"\n                                alt=\"Rosie Robot AI photo booth at trade show event\" width=\"800\" height=\"600\"\n                                class=\"w-full h-full object-cover group-hover:scale-110 transition-transform duration-500 min-h-[400px]\"\n                                loading=\"lazy\">\n                            <div\n                                class=\"absolute inset-0 bg-gradient-to-t from-cyan-900/70 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity\">\n                            </div>\n                        </div>\n\n                        <!-- Row 2 -->\n                        <!-- Card 3: Middle Left First -->\n                        <div\n                            class=\"group bg-gradient-to-br from-[#FFFF] to-[#FFFF] rounded-2xl p-6 hover:shadow-xl transition-all hover:-translate-y-2 border-2 border-transparent hover:border-[#18F1E1]\">\n                            <div\n                                class=\"w-14 h-14 bg-gradient-to-br from-[#18F1E1] to-[#18F1E1] rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform\">\n                                <svg class=\"w-7 h-7 text-white\" fill=\"#18F1E1\" stroke=\"#1F1F1F\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                        d=\"M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z\">\n                                    </path>\n                                </svg>\n                            </div>\n                            <h4 class=\"text-lg mb-2 text-gray-900\" style=\"color: #FF4F4F;\">Interactive Entertainment\n                            </h4>\n                            <p class=\"text-gray-600 text-sm\">Engaging AI conversations</p>\n                        </div>\n\n                        <!-- Card 4: Middle Left Second -->\n                        <div\n                            class=\"group bg-gradient-to-br from-[#FFFF] to-[#FFFF] rounded-2xl p-6 hover:shadow-xl transition-all hover:-translate-y-2 border-2 border-transparent hover:border-[#18F1E1]\">\n                            <div\n                                class=\"w-14 h-14 bg-gradient-to-br from-[#18F1E1] to-[#18F1E1] rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform\">\n                                <svg class=\"w-7 h-7 text-white\" fill=\"#18F1E1\" stroke=\"#1F1F1F\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                        d=\"M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z\">\n                                    </path>\n                                </svg>\n                            </div>\n                            <h4 class=\"text-lg mb-2 text-gray-900\" style=\"color: #FF4F4F;\">Lead Capture</h4>\n                            <p class=\"text-gray-600 text-sm\">Automated lead qualification</p>\n                        </div>\n\n                        <!-- Row 3 -->\n                        <!-- Card 6: Bottom Left - Spans 2 columns, 2 rows -->\n                        <div class=\"md:col-span-2 md:row-span-2 cursor-pointer group relative overflow-hidden rounded-3xl shadow-2xl\"\n                            onclick=\"openLightbox(\'../assets/images/rosie-robot/rosie-robot-hero.webp\')\">\n                            <img src=\"../assets/images/rosie-robot/rosie-robot-hero.webp\"\n                                alt=\"Rosie Robot AI-powered photo booth experience\" width=\"800\" height=\"600\"\n                                class=\"w-full h-full object-cover group-hover:scale-110 transition-transform duration-500 min-h-[400px]\"\n                                loading=\"lazy\">\n                            <div\n                                class=\"absolute inset-0 bg-gradient-to-t from-indigo-900/70 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity\">\n                            </div>\n                        </div>\n\n                        <!-- Card 7: Top Right of Right Column -->\n                        <div\n                            class=\"group bg-gradient-to-br from-[#FFFF] to-[#FFFF] rounded-2xl p-6 hover:shadow-xl transition-all hover:-translate-y-2 border-2 border-transparent hover:border-[#18F1E1]\">\n                            <div\n                                class=\"w-14 h-14 bg-gradient-to-br from-[#18F1E1] to-[#18F1E1] rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform\">\n                                <svg class=\"w-7 h-7 text-white\" fill=\"#18F1E1\" stroke=\"#1F1F1F\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                        d=\"M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z\">\n                                    </path>\n                                </svg>\n                            </div>\n                            <h4 class=\"text-lg mb-2 text-gray-900\" style=\"color: #FF4F4F;\">Crowd Engagement</h4>\n                            <p class=\"text-gray-600 text-sm\">Attract and entertain visitors</p>\n                        </div>\n\n                        <!-- Card 10: Top Right of Right Column Second -->\n                        <div\n                            class=\"group bg-gradient-to-br from-[#FFFF] to-[#FFFF] rounded-2xl p-6 hover:shadow-xl transition-all hover:-translate-y-2 border-2 border-transparent hover:border-[#18F1E1]\">\n                            <div\n                                class=\"w-14 h-14 bg-gradient-to-br from-[#18F1E1] to-[#18F1E1] rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform\">\n                                <svg class=\"w-7 h-7 text-white\" fill=\"#18F1E1\" stroke=\"#1F1F1F\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"\n                                        d=\"M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z\"></path>\n                                </svg>\n                            </div>\n                            <h4 class=\"text-lg mb-2 text-gray-900\" style=\"color: #FF4F4F;\">Multi-Day Recognition</h4>\n                            <p class=\"text-gray-600 text-sm\">Remembers returning attendees</p>\n                        </div>\n\n                        <!-- Row 4 -->\n                        <!-- Card 8: Bottom Right First -->\n                        <div\n                            class=\"group bg-gradient-to-br from-[#FFFF] to-[#FFFF] rounded-2xl p-6 hover:shadow-xl transition-all hover:-translate-y-2 border-2 border-transparent hover:border-[#18F1E1]\">\n                            <div\n                                class=\"w-14 h-14 bg-gradient-to-br from-[#18F1E1] to-[#18F1E1] rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform\">\n                                <svg class=\"w-7 h-7 text-white\" fill=\"#18F1E1\" stroke=\"#1F1F1F\" viewBox=\"0 0 24 24\">\n                                    <path stroke-linecap=\"round\" s